R:Segment({id="class/druid/aquatic-form",title="Aquatic Form",classes={"DRUID"},min=16,max=22,zone=1450,zoneName="Moonglade",why="Your water travel form: swim fast and breathe underwater, with a belt and an idol besides.",spells={1066},spellNames={"Aquatic Form"},items={263411,16608},folder="Druid"}, function() return {
  {t="Cenarion Enclave", lv=16, n="Mathrengyl Bearwalker stands upstairs in the druids' building of the Cenarion Enclave. Skyborne: cast Teleport: Moonglade and take Silva Fil'naveth's flight from the middle of Nighthaven (she flies druids to Rut'theran Village, no flight path needed), then the portal up.", f={r={"NightElf","Skyborne"},fa={"Alliance"}}, g={{"l",16,txt="Reach level 16"},{"g",0,txt="Cenarion Enclave",m=1457,x=35.8,y=11.6}}},
  {t="A Lesson to Learn", lv=16, n="Mathrengyl Bearwalker stands upstairs in the druids' building of the Cenarion Enclave. Skyborne: cast Teleport: Moonglade and take Silva Fil'naveth's flight from the middle of Nighthaven (she flies druids to Rut'theran Village, no flight path needed), then the portal up.", f={r={"NightElf","Skyborne"},fa={"Alliance"}}, g={{"l",16,txt="Reach level 16"},{"a",26,m=1457,x=35.4,y=8.4,ml=16}}},
  {t="Trial of the Lake", lv=16, n="Cast Teleport: Moonglade to get here: Dendrite Starblaze stands upstairs in the building beside where you land. Trial of the Lake runs on a 30-minute timer: once you accept it, no teleport or Hearthstone until Tajarri has it. Six Bauble Containers (vases) lie in narrow hollows deep on the floor of Lake Elune'ara below Nighthaven, often near the bubbling fissures (the Bubbly Fissure in the middle of the lake refills your breath); each comes back three minutes after it is opened, and other druids take them too. Check the Shrine Bauble is in your bags before you surface: it fades five minutes after you loot it. Swim it straight to the Shrine of Remulos on the north-west shore, use it inside the shrine grounds and speak to Tajarri by the tree.", f={r={"NightElf","Skyborne"},fa={"Alliance"}}, g={{"t",26,m=1450,x=56.2,y=30.6},{"a",29,m=1450,x=56.2,y=30.6,ml=16},{"h",15877,txt="Get Shrine Bauble",n2="Shrine Bauble, from a Bauble Container in the lake",m=1450,x=54.7,y=46.4,n=1},{"i",0,txt="Use Shrine Bauble",n2="At the Shrine of Remulos",m=1450,x=36,y=41.4},{"c",29,txt="Shrine Of Remulos",m=1450,x=36,y=41.4},{"t",29,m=1450,x=36.5,y=40.1},{"a",272,m=1450,x=36.5,y=40.1,ml=16}}},
  {t="Half Pendant of Aquatic Agility", lv=16, n="Fly from Nighthaven to Auberdine. The Strange Lockbox lies far out on the sea floor off the north coast, between tall rocks west of where the Cliffspring River reaches the sea: it cannot be seen from the east side of the rocks. Watch your breath and the Darkshore Threshers; fight above water.", f={r={"NightElf","Skyborne"},fa={"Alliance"}}, g={{"z",0,txt="Fly to Auberdine",at="Auberdine"},{"h",15883,txt="Get Half Pendant of Aquatic Agility",n2="Half Pendant of Aquatic Agility, from the Strange Lockbox",m=1439,x=48.9,y=11.3,n=1}}},
  {t="Half Pendant of Aquatic Endurance", lv=16, n="Take the boat from Auberdine to Stormwind and fly to Sentinel Hill. Head west to the coast: the Strange Lockbox lies far out on the sea floor beside a bubbling fissure (air), west of a sunken anchor. Sharks roam here; do not swim on past the wreck beyond it, the deep water brings fatigue.", f={r={"NightElf","Skyborne"},fa={"Alliance"}}, g={{"z",0,txt="Fly to Sentinel Hill",at="Sentinel Hill"},{"h",15882,txt="Get Half Pendant of Aquatic Endurance",n2="Half Pendant of Aquatic Endurance, from the Strange Lockbox",m=1436,x=17.9,y=33.2,n=1}}},
  {t="Pendant of the Sea Lion", lv=16, n="Cast Teleport: Moonglade. With both halves in your bags, stand by the Shrine of Remulos on the north-west shore and use the Half Pendant of Aquatic Agility to join them, then cast Teleport: Moonglade again (it works inside Moonglade) to land by Dendrite Starblaze. He stands upstairs in his building: go up inside, the arrow cannot tell the floors apart. Afterwards Silva Fil'naveth, in the middle of Nighthaven, flies druids straight to Rut'theran Village.", f={r={"NightElf","Skyborne"},fa={"Alliance"}}, g={{"o",272,i=1,txt="Pendant of the Sea Lion",n2="Pendant of the Sea Lion: join the halves at the shrine",m=1450,x=36,y=41.4},{"t",272,m=1450,x=56.2,y=30.6},{"a",5061,m=1450,x=56.2,y=30.6,ml=16},{"z",0,txt="Fly to Rut'theran Village",at="Rut'theran Village"}}},
  {t="Cenarion Enclave", lv=16, n="Take the portal up to Mathrengyl in the Cenarion Enclave. Aquatic Form: swim fast and breathe underwater.", f={r={"NightElf","Skyborne"},fa={"Alliance"}}, g={{"g",0,txt="Cenarion Enclave",m=1457,x=35.8,y=11.6}}},
  {t="Aquatic Form", lv=16, n="Take the portal up to Mathrengyl in the Cenarion Enclave. Aquatic Form: swim fast and breathe underwater.", f={r={"NightElf","Skyborne"},fa={"Alliance"}}, g={{"t",5061,n2="Mathrengyl Bearwalker: Aquatic Form",m=1457,x=35.4,y=8.4}}},
  {t="A Lesson to Learn", lv=16, n="Turak Runetotem stands in the druids' hut on Elder Rise.", f={r={"Tauren","Skyborne"},fa={"Horde"}}, g={{"l",16,txt="Reach level 16"},{"a",27,m=1456,x=76.5,y=27.2,ml=16}}},
  {t="Trial of the Lake", lv=16, n="Cast Teleport: Moonglade to get here: Dendrite Starblaze stands upstairs in the building beside where you land. Trial of the Lake runs on a 30-minute timer: once you accept it, no teleport or Hearthstone until Tajarri has it. Six Bauble Containers (vases) lie in narrow hollows deep on the floor of Lake Elune'ara below Nighthaven, often near the bubbling fissures (the Bubbly Fissure in the middle of the lake refills your breath); each comes back three minutes after it is opened, and other druids take them too. Check the Shrine Bauble is in your bags before you surface: it fades five minutes after you loot it. Swim it straight to the Shrine of Remulos on the north-west shore, use it inside the shrine grounds and speak to Tajarri by the tree.", f={r={"Tauren","Skyborne"},fa={"Horde"}}, g={{"t",27,m=1450,x=56.2,y=30.6},{"a",28,m=1450,x=56.2,y=30.6,ml=16},{"h",15877,txt="Get Shrine Bauble",n2="Shrine Bauble, from a Bauble Container in the lake",m=1450,x=54.7,y=46.4,n=1},{"i",0,txt="Use Shrine Bauble",n2="At the Shrine of Remulos",m=1450,x=36,y=41.4},{"c",28,txt="Shrine Of Remulos",m=1450,x=36,y=41.4},{"t",28,m=1450,x=36.5,y=40.1},{"a",30,m=1450,x=36.5,y=40.1,ml=16}}},
  {t="Half Pendant of Aquatic Agility", lv=16, n="Take Bunthen Plainswind's flight to Thunder Bluff and fly on to Orgrimmar. The Strange Lockbox lies underwater in the Sludge Fen pond, a short walk out of Orgrimmar's west gate, in front of a wooden wall. The Venture Co. there are quick to join a fight: come in from the west to avoid most of them.", f={r={"Tauren","Skyborne"},fa={"Horde"}}, g={{"z",0,txt="Fly to Thunder Bluff",at="Thunder Bluff"},{"z",0,txt="Fly to Orgrimmar",at="Orgrimmar"},{"h",15883,txt="Get Half Pendant of Aquatic Agility",n2="Half Pendant of Aquatic Agility, from the Strange Lockbox",m=1413,x=56.7,y=8.3,n=1}}},
  {t="Zeppelin to Undercity", lv=16, n="Back through Orgrimmar to the zeppelin towers outside its main gate: the zeppelin to the Undercity lands in Tirisfal Glades, and Silverpine Forest is south of the Undercity.", f={r={"Tauren","Skyborne"},fa={"Horde"}}, g={{"g",0,txt="Zeppelin to Undercity",m=1411,x=50.8,y=13.5}}},
  {t="Half Pendant of Aquatic Endurance", lv=16, n="The Strange Lockbox lies at the bottom of very deep water off the coast north-west of the Sepulcher, beside an air fissure where you can breathe: watch your breath on the way down. Then Teleport: Moonglade takes you straight back.", f={r={"Tauren","Skyborne"},fa={"Horde"}}, g={{"h",15882,txt="Get Half Pendant of Aquatic Endurance",n2="Half Pendant of Aquatic Endurance, from the Strange Lockbox",m=1421,x=29.6,y=29.2,n=1}}},
  {t="Pendant of the Sea Lion", lv=16, n="Cast Teleport: Moonglade. With both halves in your bags, stand by the Shrine of Remulos on the north-west shore and use the Half Pendant of Aquatic Agility to join them, then cast Teleport: Moonglade again (it works inside Moonglade) to land by Dendrite Starblaze. He stands upstairs in his building: go up inside, the arrow cannot tell the floors apart. Bunthen Plainswind flies druids to Thunder Bluff.", f={r={"Tauren","Skyborne"},fa={"Horde"}}, g={{"o",30,i=1,txt="Pendant of the Sea Lion",n2="Pendant of the Sea Lion: join the halves at the shrine",m=1450,x=36,y=41.4},{"t",30,m=1450,x=56.2,y=30.6},{"a",31,m=1450,x=56.2,y=30.6,ml=16},{"z",0,txt="Fly to Thunder Bluff",at="Thunder Bluff"}}},
  {t="Aquatic Form", lv=16, f={r={"Tauren","Skyborne"},fa={"Horde"}}, g={{"t",31,n2="Turak Runetotem: Aquatic Form",m=1456,x=76.5,y=27.2}}},
} end)

R:Segment({id="class/druid/bear-form",title="Bear Form and Moonglade",classes={"DRUID"},min=10,max=12,zone=1450,zoneName="Moonglade",why="Your tanking form: Forever no longer trains Bear Form, these quests give it. Opens Moonglade too.",spells={5487},spellNames={"Bear Form"},folder="Druid"}, function() return {
  {t="Heeding the Call", lv=10, n="At 10 a druid's call reaches you: Kal in Dolanaar, Denatharion in Darnassus or Theridran in Stormwind. Any one of them sends you to Mathrengyl Bearwalker in the Cenarion Enclave of Darnassus.", f={r={"NightElf"}}, g={{"l",10,txt="Reach level 10"},{"a",5925,n2="Kal, Dolanaar; Denatharion's and Theridran's letters lead to the same place",m=1438,x=56,y=61.6,opt=true,ml=10}}},
  {t="Cenarion Enclave", lv=10, n="Mathrengyl Bearwalker stands upstairs in the druids' building of the Cenarion Enclave. He teaches you Teleport: Moonglade with the quest (it stays in your spellbook, Balance tab).", f={r={"NightElf"}}, g={{"g",0,txt="Cenarion Enclave",m=1457,x=35.8,y=11.6}}},
  {t="Mathrengyl Bearwalker", lv=10, n="Mathrengyl Bearwalker stands upstairs in the druids' building of the Cenarion Enclave. He teaches you Teleport: Moonglade with the quest (it stays in your spellbook, Balance tab).", f={r={"NightElf"}}, g={{"t",5925,n2="or whichever of the three letters you carry",m=1457,x=35.4,y=8.4,opt=true},{"a",5921,m=1457,x=35.4,y=8.4,ml=10}}},
  {t="Moonglade", lv=10, n="Cast Teleport: Moonglade: it lands you beside the building where Dendrite Starblaze stands upstairs, past the armor vendor. The Great Bear Spirit sits in the woods to the north-west. Speak to it and go through all of its words (what it represents, the strength of the body, the strength of the heart, then ask for its blessing): the talk is the objective, there is no fight. It blends into the ground, has no quest mark and gives off a faint blue-grey glow by a group of three trees: from Nighthaven go west along the foot of the northern mountains, through the gap between the trees and the hills. If Dendrite is missing when you return, step outside and cast Teleport: Moonglade again. Learn the Moonglade flight path (Sindrayl, south of the lake) for later, then take Silva Fil'naveth's flight from the middle of Nighthaven: she flies druids straight to Rut'theran Village, no flight path needed. Take the portal up to Darnassus.", f={r={"NightElf"}}, g={{"t",5921,m=1450,x=56.2,y=30.6},{"a",5929,m=1450,x=56.2,y=30.6,ml=10},{"c",5929,txt="Seek out the Great Bear Spirit and learn what it has to share with you about the nature of the bear.",n2="Speak with the Great Bear Spirit",m=1450,x=39.1,y=27.5},{"t",5929,m=1450,x=56.2,y=30.6},{"a",5931,m=1450,x=56.2,y=30.6,ml=10},{"fp",49,txt="Get the Moonglade flight path (Sindrayl)",m=1450,x=48.1,y=67.3},{"z",0,txt="Fly to Rut'theran Village",at="Rut'theran Village"}}},
  {t="Cenarion Enclave", lv=10, f={r={"NightElf"}}, g={{"g",0,txt="Cenarion Enclave",m=1457,x=35.8,y=11.6}}},
  {t="Back to Darnassus", lv=10, f={r={"NightElf"}}, g={{"t",5931,m=1457,x=35.4,y=8.4},{"a",6001,m=1457,x=35.4,y=8.4,ml=10}}},
  {t="The Moonkin Stone", lv=10, n="Fly from Rut'theran Village to Auberdine. The Moonkin Stone stands inside the nearest moonkin cave east of the village: the northern of two small rock-pile caves where the Auberdine road meets the main north-south road. Moonkin (level 11-13) stand outside, the cave is empty: slip past them. Use the Cenarion Moondust by the stone: Lunaclaw (level 12-13) walks in towards you and stays three minutes. Kill her, then speak to the Lunaclaw Spirit that appears and ask for the strength of her body and heart: the talk is the credit. Another druid's Lunaclaw gives you the spirit too.", f={r={"NightElf"}}, g={{"z",0,txt="Fly to Auberdine",at="Auberdine"},{"i",0,txt="Use Cenarion Moondust",m=1439,x=43.5,y=46},{"c",6001,txt="Lunaclaw Spirit"}}},
  {t="Body and Heart", lv=10, n="Fly back to Rut'theran Village and take the portal up to Mathrengyl.", f={r={"NightElf"}}, g={{"z",0,txt="Fly to Rut'theran Village",at="Rut'theran Village"},{"g",0,txt="Cenarion Enclave",m=1457,x=35.8,y=11.6},{"t",6001,n2="Mathrengyl Bearwalker: Bear Form",m=1457,x=35.4,y=8.4}}},
  {t="Heeding the Call", lv=10, n="At 10 a druid's call reaches you: Gennia Runetotem in Bloodhoof Village or Innkeeper Pala in Thunder Bluff (Innkeeper Gryshka's letter in Orgrimmar works too). Any one of them sends you to Turak Runetotem on Elder Rise in Thunder Bluff.", f={r={"Tauren"}}, g={{"l",10,txt="Reach level 10"},{"a",5928,n2="Gennia Runetotem, Bloodhoof Village; Pala's and Gryshka's letters lead to the same place",m=1412,x=47.5,y=63,opt=true,ml=10}}},
  {t="Turak Runetotem", lv=10, n="Turak Runetotem stands in the druids' hut on Elder Rise, over the rope bridges east of the lifts. He teaches you Teleport: Moonglade with the quest (it stays in your spellbook, Balance tab).", f={r={"Tauren"}}, g={{"t",5928,n2="or whichever of the three letters you carry",m=1456,x=76.5,y=27.2,opt=true},{"a",5922,m=1456,x=76.5,y=27.2,ml=10}}},
  {t="Moonglade", lv=10, n="Cast Teleport: Moonglade: it lands you beside the building where Dendrite Starblaze stands upstairs. The Great Bear Spirit sits in the woods to the north-west. Speak to it and go through all of its words (what it represents, the strength of the body, the strength of the heart, then ask for its blessing): the talk is the objective, there is no fight. It blends into the ground, has no quest mark and gives off a faint blue-grey glow by a group of three trees: from Nighthaven go west along the foot of the northern mountains, through the gap between the trees and the hills. If Dendrite is missing when you return, step outside and cast Teleport: Moonglade again. Learn the Moonglade flight path (Faustron, south-west of the lake); Bunthen Plainswind in Nighthaven flies druids to Thunder Bluff.", f={r={"Tauren"}}, g={{"t",5922,m=1450,x=56.2,y=30.6},{"a",5930,m=1450,x=56.2,y=30.6,ml=10},{"c",5930,txt="Seek out the Great Bear Spirit and learn what it has to share with you about the nature of the bear.",n2="Speak with the Great Bear Spirit",m=1450,x=39.1,y=27.5},{"t",5930,m=1450,x=56.2,y=30.6},{"a",5932,m=1450,x=56.2,y=30.6,ml=10},{"z",0,txt="Fly to Thunder Bluff",at="Thunder Bluff"}}},
  {t="Back to Thunder Bluff", lv=10, f={r={"Tauren"}}, g={{"t",5932,m=1456,x=76.5,y=27.2},{"a",6002,m=1456,x=76.5,y=27.2,ml=10}}},
  {t="The Moonkin Stone", lv=10, n="The Moonkin Stone stands in the Barrens just south-west of Camp Taurajo, by the road out of Mulgore. Level 20 Thunderheads roam close by: clear the way first. Use the Cenarion Lunardust by the stone: Lunaclaw (level 12-13) appears for three minutes. Kill her, then speak to the Lunaclaw Spirit that appears and ask for the strength of her body and heart: the talk is the credit. Die in the fight? Lunaclaw stays by the stone: run back and finish her.", f={r={"Tauren"}}, g={{"i",0,txt="Use Cenarion Lunardust",m=1413,x=42,y=60.9},{"c",6002,txt="Lunaclaw Spirit"}}},
  {t="Body and Heart", lv=10, n="Back to Turak Runetotem on Elder Rise.", f={r={"Tauren"}}, g={{"t",6002,n2="Turak Runetotem: Bear Form",m=1456,x=76.5,y=27.2}}},
  {t="Skyboat from Dalaran", lv=10, n="Bear Form is taught on Zephras Isle. Skip this if you are still on the isle; otherwise take the skyboat from the north side of Dalaran.", f={r={"Skyborne"},fa={"Alliance"}}, g={{"g",0,txt="Skyboat to Zephras Isle",m=1416,x=12.5,y=51.8}}},
  {t="Skyboat from Thunder Bluff", lv=10, n="Bear Form is taught on Zephras Isle. Skip this if you are still on the isle; otherwise take the skyboat from the cliffs south of Skywatcher Plateau, north of Thunder Bluff.", f={r={"Skyborne"},fa={"Horde"}}, g={{"g",0,txt="Skyboat to Zephras Isle",m=1412,x=34.3,y=25.8}}},
  {t="Lotheluum Starbreeze", lv=10, n="Lotheluum Starbreeze stands in Valanaar.", f={r={"Skyborne"}}, g={{"l",10,txt="Reach level 10"},{"a",94006,m=2521,x=64,y=75.1,ml=10}}},
  {t="Urs'endris and Ur'endra", lv=10, n="Urs'endris waits by the waterfall below the Shrine of Akir, north-east of Valanaar. Ur'endra (the bear you must defeat) lairs in an unmarked cave high on the cliff face west of him, where the Shen'dar Highlands meet the Gustberry Lowlands: take the path west out of Valanaar (not north), cross the river on the log bridge and reach the cave from the cliff's upper, northern side. The cave at the foot of the cliffs and the foggy cave are the wrong ones.", f={r={"Skyborne"}}, g={{"t",94006,m=2521,x=69.8,y=61.7},{"a",94638,m=2521,x=69.8,y=61.7,ml=10},{"o",94638,i=1,txt="Kill Ur'endra",m=2521,x=53.9,y=64.7}}},
  {t="Strength and Mercy", lv=10, n="Back to Urs'endris by the falls.", f={r={"Skyborne"}}, g={{"t",94638,n2="Urs'endris: Bear Form",m=2521,x=69.8,y=61.7}}},
  {t="Child of Nature", lv=10, n="Muln Earthfury waits where the airship from Zephras Isle lands, in northern Mulgore beside Thunder Bluff.", f={r={"Skyborne"},fa={"Horde"}}, g={{"l",10,txt="Reach level 10"},{"a",94911,m=1412,x=33.4,y=22.6,ml=10}}},
  {t="Turak Runetotem", lv=10, n="Turak Runetotem trains druids in the druids' hut on Elder Rise, over the rope bridges east of the lifts. He teaches you Teleport: Moonglade with the next quest (it stays in your spellbook, Balance tab).", f={r={"Skyborne"},fa={"Horde"}}, g={{"t",94911,m=1456,x=76.5,y=27.2},{"a",94913,m=1456,x=76.5,y=27.2,ml=10}}},
  {t="Child of Nature", lv=10, n="Alfina Nightgaze stands beside Denaaris Stargale and the Skyborne Portal, west of Dalaran, where the skycutter from Zephras Isle lands. Archmage Ansirem Runeweaver offers the same quest.", f={r={"Skyborne"},fa={"Alliance"}}, g={{"l",10,txt="Reach level 10"},{"a",94912,m=1416,x=11.8,y=56.6,ml=10}}},
  {t="Sheldras Moontree", lv=10, n="The Skyborne Portal takes you to Stormwind. Sheldras Moontree is the city's druid trainer (the arrow points at him); he teaches you Teleport: Moonglade with the next quest (it stays in your spellbook, Balance tab).", f={r={"Skyborne"},fa={"Alliance"}}, g={{"t",94912,m=1453,x=35.8,y=67.4},{"a",94914,m=1453,x=35.8,y=67.4,ml=10}}},
  {t="Dendrite Starblaze", lv=10, n="Cast Teleport: Moonglade: it lands you beside the building where Dendrite Starblaze stands upstairs, in Nighthaven. Learn the Moonglade flight path while you are here (Faustron for the Horde, south-west of the lake; Sindrayl for the Alliance, south of it).", f={r={"Skyborne"}}, g={{"t",94913,m=1450,x=56.2,y=30.6,f={fa={"Horde"}}},{"t",94914,m=1450,x=56.2,y=30.6,f={fa={"Alliance"}}},{"fp",0,txt="Get the Moonglade flight path"}}},
} end)

R:Segment({id="class/druid/bloodpetal-poison",title="Bloodpetal Poison",classes={"DRUID"},min=50,max=54,zone=1449,zoneName="Un'Goro Crater",why="Experience in Un'Goro at 50 and two healing potions; the Classic item choice may be gone in Forever.",items={13446},folder="Druid"}, function() return {
  {t="Loganaar", lv=50, n="Cast Teleport: Moonglade. Loganaar stands in Nighthaven; your class trainer (Turak Runetotem, Mathrengyl Bearwalker or Theridran in Stormwind) offers the same quest.", g={{"l",50,txt="Reach level 50"},{"a",9063,m=1450,x=52.5,y=40.6,ml=50}}},
  {t="Torwa Pathfinder", lv=50, n="Fly to Gadgetzan, ride west to the long ramp down into Un'Goro Crater: Torwa camps at its foot, in the south-east corner of the crater.", g={{"t",9063,m=1449,x=71.6,y=76},{"a",9052,m=1449,x=71.6,y=76,ml=50}}},
  {t="Gorishi Stings and Bloodcap", lv=50, n="Eight of each. The Gorishi Wasps and Stingers (level 51-52) in and around the Slithering Scar, the hive in the south-west of the crater, drop a sting about one kill in seven; the wasps share spawn points with the other bugs, so kill whatever stands near you to make room for more wasps (respawn five minutes). The bugs' Silithid Pox makes you take more physical damage for 30 minutes; Workers call for help when hurt. The Bloodpetal Sprouts grow all over the crater (around Marshal's Refuge and the western half): open them, about every other one gives a Bloodcap, back in three to five minutes.", g={{"o",9052,i=1,txt="Gorishi Sting x8",m=1449,x=56.4,y=84.9},{"o",9052,i=2,txt="Bloodcap x8",m=1449,x=53.3,y=70.4}}},
  {t="Torwa Pathfinder", lv=50, g={{"t",9052,m=1449,x=71.6,y=76},{"a",9051,m=1449,x=71.6,y=76,ml=50}}},
  {t="Toxic Test", lv=50, n="Any Devilsaur counts, the Ironhide and Tyrant Devilsaurs too. They are elite (level 54-55), hit with Mighty Blow and outrun travel form. Grouping up is encouraged, but a druid can do it alone: Hibernate or Entangling Roots it from range, stab it with the Devilsaur Barb (the barb does not break Hibernate), then leave. The credit counts the moment the barb lands, even if you die after. The arrow points at the plain Devilsaurs of the west and north; an Ironhide Devilsaur roams the middle of the crater's south, nearer Torwa.", g={{"o",9051,i=1,txt="Stab a Devilsaur with the Devilsaur Barb",n2="Devilsaur: stab it with the Devilsaur Barb",m=1449,x=57.3,y=23.7,grp=true}}},
  {t="Torwa Pathfinder", lv=50, g={{"t",9051,m=1449,x=71.6,y=76},{"a",9053,m=1449,x=71.6,y=76,ml=50}}},
  {t="The Sunken Temple", lv=50, n="A five-player dungeon: needs a group of five, about level 50-55. Horde: fly to Stonard; Alliance: fly to Nethergarde Keep in the Blasted Lands and ride north. The Temple of Atal'Hakkar stands in the middle of the Pool of Tears in the Swamp of Sorrows: climb the stairs on the ruin's south side, dive into the flooded hall, swim down through it and follow the stairs and passages down to the portal. Atal'alarion (level 50 elite, Sweeping Slam and Ground Tremor) only appears when the six serpent statues on the balcony ring above the altar pit are clicked in order: South, North, South-west, South-east, North-west, North-east (each turns green when right; a wrong order fails). Clear the trash by each statue and the pit below first; jumping down into the water is the quick way down, but a knockback near the edge can kill. The Putrid Vine always drops.", g={{"g",0,txt="The Temple of Atal'Hakkar",m=1435,x=69.9,y=53.6},{"o",9053,i=1,txt="Putrid Vine",n2="Putrid Vine: Atal'alarion",m=1435,x=69.9,y=53.6,grp=true}}},
  {t="A Better Ingredient", lv=50, n="Back to Torwa in the south-east corner of Un'Goro Crater.", g={{"t",9053,n2="Torwa Pathfinder: the old item choice may be gone, count on the experience",m=1449,x=71.6,y=76}}},
} end)

R:Segment({id="class/druid/cat-form",title="Cat Form",classes={"DRUID"},min=20,max=22,zone=1450,zoneName="Moonglade",why="Your stealth and melee form: in Forever this chain gives Cat Form at 20, not the trainer.",spells={768},spellNames={"Cat Form"},folder="Druid"}, function() return {
  {t="Cenarion Enclave", lv=20, n="Mathrengyl Bearwalker stands in the Cenarion Enclave. Skyborne far from Darnassus: cast Teleport: Moonglade and take Silva Fil'naveth's flight from the middle of Nighthaven (she flies druids to Rut'theran Village, no flight path needed), then the portal up. No Aquatic Form yet? Take A Lesson to Learn from him too: it also goes to Dendrite, and its Trial of the Lake (the Aquatic Form guide) is in the same Moonglade.", f={r={"NightElf","Skyborne"},fa={"Alliance"}}, g={{"l",20,txt="Reach level 20"},{"g",0,txt="Cenarion Enclave",m=1457,x=35.8,y=11.6}}},
  {t="The Great Cat Spirit", lv=20, n="Mathrengyl Bearwalker stands in the Cenarion Enclave. Skyborne far from Darnassus: cast Teleport: Moonglade and take Silva Fil'naveth's flight from the middle of Nighthaven (she flies druids to Rut'theran Village, no flight path needed), then the portal up. No Aquatic Form yet? Take A Lesson to Learn from him too: it also goes to Dendrite, and its Trial of the Lake (the Aquatic Form guide) is in the same Moonglade.", f={r={"NightElf","Skyborne"},fa={"Alliance"}}, g={{"l",20,txt="Reach level 20"},{"a",98393,m=1457,x=35.4,y=8.4,ml=20}}},
  {t="Dendrite Starblaze", lv=20, n="Cast Teleport: Moonglade. Dendrite Starblaze stands upstairs in his building in Nighthaven: go up inside, the arrow cannot tell the floors apart. Learn the flight path there if you do not have it.", f={r={"NightElf","Skyborne"},fa={"Alliance"}}, g={{"t",98393,m=1450,x=56.2,y=30.6},{"a",98394,m=1450,x=56.2,y=30.6,f={r={"NightElf"}},ml=20},{"a",98341,m=1450,x=56.2,y=30.6,f={r={"Skyborne"}},ml=20},{"fp",49,txt="Get the Moonglade flight path (Sindrayl)",m=1450,x=48.1,y=67.3}}},
  {t="The relics of the Barrow Dens", lv=20, n="The Great Cat Spirit (Night Elves) waits on the hill above the bridge in southern Moonglade; the Avatar of Saeyleenan (Skyborne) stands on high ground past the twin bridges, south-west of Nighthaven: climb up to it. The relics lie in the Stormrage Barrow Dens east of the lake: leave your form and click the statue at the den's entrance for a short stealth (five minutes), then go deep into the cave and over the bridge. Enraged spirits guard the relics and attack anything they see: stay in the statue's stealth and keep moving. Each relic is a small orb beside a cat statue in an alcove: the Fang and the Claw have one spot each, the Silent Shadow two, and it is the one players camp. A relic shows as unusable while another player loots it: wait a moment and try again. Stealth gone? Walk back to the entrance statue for more.", f={r={"NightElf","Skyborne"},fa={"Alliance"}}, g={{"t",98394,m=1450,x=54.5,y=75,f={r={"NightElf"}}},{"a",98396,m=1450,x=54.5,y=75,f={r={"NightElf"}},ml=20},{"t",98341,m=1450,x=43.9,y=73.4,f={r={"Skyborne"}}},{"a",98404,m=1450,x=43.9,y=73.4,f={r={"Skyborne"}},ml=20},{"o",98396,i=1,txt="Relic of the Fang",m=1450,x=72.4,y=66,f={r={"NightElf"}}},{"o",98396,i=2,txt="Relic of the Claw",m=1450,x=75.2,y=67.2,f={r={"NightElf"}}},{"o",98396,i=3,txt="Relic of the Silent Shadow",m=1450,x=74.4,y=65.4,f={r={"NightElf"}}},{"o",98404,i=1,txt="Relic of the Fang",m=1450,x=72.4,y=66,f={r={"Skyborne"}}},{"o",98404,i=2,txt="Relic of the Claw",m=1450,x=75.2,y=67.2,f={r={"Skyborne"}}},{"o",98404,i=3,txt="Relic of the Silent Shadow",m=1450,x=74.4,y=65.4,f={r={"Skyborne"}}},{"t",98396,m=1450,x=54.5,y=75,f={r={"NightElf"}}},{"a",98731,m=1450,x=54.5,y=75,f={r={"NightElf"}},ml=20},{"t",98404,m=1450,x=43.9,y=73.4,f={r={"Skyborne"}}},{"a",98738,m=1450,x=43.9,y=73.4,f={r={"Skyborne"}},ml=20}}},
  {t="Back to Dendrite", lv=20, n="Cast Teleport: Moonglade to land by Dendrite Starblaze in Nighthaven (nobody on Zephras Isle takes the Skyborne quest), then take Silva Fil'naveth's flight to Rut'theran Village: she stands in the middle of Nighthaven and flies druids there, no flight path needed. Dendrite stands upstairs in his building: go up inside, the arrow cannot tell the floors apart.", f={r={"NightElf","Skyborne"},fa={"Alliance"}}, g={{"t",98731,m=1450,x=56.2,y=30.6,f={r={"NightElf"}}},{"t",98738,m=1450,x=56.2,y=30.6,f={r={"Skyborne"}}},{"a",98397,m=1450,x=56.2,y=30.6,ml=20},{"z",0,txt="Fly to Rut'theran Village",at="Rut'theran Village"}}},
  {t="Cenarion Enclave", lv=20, n="Take the portal up to Mathrengyl, upstairs in the Cenarion Enclave: he teaches you Cat Form.", f={r={"NightElf","Skyborne"},fa={"Alliance"}}, g={{"g",0,txt="Cenarion Enclave",m=1457,x=35.8,y=11.6}}},
  {t="To Darnassus", lv=20, n="Take the portal up to Mathrengyl, upstairs in the Cenarion Enclave: he teaches you Cat Form.", f={r={"NightElf","Skyborne"},fa={"Alliance"}}, g={{"t",98397,n2="Mathrengyl Bearwalker: Cat Form",m=1457,x=35.4,y=8.4}}},
  {t="The Great Cat Spirit", lv=20, n="Turak Runetotem stands in the druids' hut on Elder Rise. No Aquatic Form yet? Take A Lesson to Learn from him too: it also goes to Dendrite, and its Trial of the Lake (the Aquatic Form guide) is in the same Moonglade.", f={r={"Tauren","Skyborne"},fa={"Horde"}}, g={{"l",20,txt="Reach level 20"},{"a",98340,m=1456,x=76.5,y=27.2,ml=20}}},
  {t="Dendrite Starblaze", lv=20, n="Cast Teleport: Moonglade. Dendrite Starblaze stands upstairs in his building in Nighthaven: go up inside, the arrow cannot tell the floors apart.", f={r={"Tauren","Skyborne"},fa={"Horde"}}, g={{"t",98340,m=1450,x=56.2,y=30.6},{"a",98405,m=1450,x=56.2,y=30.6,f={r={"Tauren"}},ml=20},{"a",98341,m=1450,x=56.2,y=30.6,f={r={"Skyborne"}},ml=20}}},
  {t="The Stormrage Barrow Dens", lv=20, n="The Great Cat Spirit (Tauren) waits on the hill above the bridge in southern Moonglade; the Avatar of Saeyleenan (Skyborne) stands on high ground past the twin bridges, south-west of Nighthaven: climb up to it. The relics lie in the Stormrage Barrow Dens east of the lake: leave your form and click the statue at the den's entrance for a short stealth (five minutes), then go deep into the cave and over the bridge. Enraged spirits guard the relics and attack anything they see: stay in the statue's stealth and keep moving. Each relic is a small orb beside a cat statue in an alcove: the Fang and the Claw have one spot each, the Silent Shadow two, and it is the one players camp. A relic shows as unusable while another player loots it: wait a moment and try again. Stealth gone? Walk back to the entrance statue for more.", f={r={"Tauren","Skyborne"},fa={"Horde"}}, g={{"t",98405,m=1450,x=54.5,y=75,f={r={"Tauren"}}},{"a",98342,m=1450,x=54.5,y=75,f={r={"Tauren"}},ml=20},{"t",98341,m=1450,x=43.9,y=73.4,f={r={"Skyborne"}}},{"a",98404,m=1450,x=43.9,y=73.4,f={r={"Skyborne"}},ml=20},{"o",98342,i=1,txt="Relic of the Fang",m=1450,x=72.4,y=66,f={r={"Tauren"}}},{"o",98342,i=2,txt="Relic of the Claw",m=1450,x=75.2,y=67.2,f={r={"Tauren"}}},{"o",98342,i=3,txt="Relic of the Silent Shadow",m=1450,x=74.4,y=65.4,f={r={"Tauren"}}},{"o",98404,i=1,txt="Relic of the Fang",m=1450,x=72.4,y=66,f={r={"Skyborne"}}},{"o",98404,i=2,txt="Relic of the Claw",m=1450,x=75.2,y=67.2,f={r={"Skyborne"}}},{"o",98404,i=3,txt="Relic of the Silent Shadow",m=1450,x=74.4,y=65.4,f={r={"Skyborne"}}},{"t",98342,m=1450,x=54.5,y=75,f={r={"Tauren"}}},{"a",98739,m=1450,x=54.5,y=75,f={r={"Tauren"}},ml=20},{"t",98404,m=1450,x=43.9,y=73.4,f={r={"Skyborne"}}},{"a",98738,m=1450,x=43.9,y=73.4,f={r={"Skyborne"}},ml=20}}},
  {t="Back to Dendrite", lv=20, n="Cast Teleport: Moonglade to land by Dendrite Starblaze in Nighthaven (nobody on Zephras Isle takes the Skyborne quest), then take Bunthen Plainswind's flight to Thunder Bluff. Dendrite stands upstairs in his building: go up inside, the arrow cannot tell the floors apart.", f={r={"Tauren","Skyborne"},fa={"Horde"}}, g={{"t",98739,m=1450,x=56.2,y=30.6,f={r={"Tauren"}}},{"t",98738,m=1450,x=56.2,y=30.6,f={r={"Skyborne"}}},{"a",98362,m=1450,x=56.2,y=30.6,ml=20},{"z",0,txt="Fly to Thunder Bluff",at="Thunder Bluff"}}},
  {t="To Thunder Bluff", lv=20, n="Turak Runetotem on Elder Rise teaches you Cat Form.", f={r={"Tauren","Skyborne"},fa={"Horde"}}, g={{"t",98362,n2="Turak Runetotem: Cat Form",m=1456,x=76.5,y=27.2}}},
} end)

R:Segment({id="class/druid/cure-poison",title="Cure Poison",classes={"DRUID"},min=14,max=20,zone=1450,zoneName="Moonglade",why="Cure Poison is no longer trained in Forever: this chain teaches it, with a medicine bag on the way.",spells={8946},spellNames={"Cure Poison"},items={15866},folder="Druid"}, function() return {
  {t="Cenarion Enclave", lv=14, n="Mathrengyl Bearwalker stands upstairs in the druids' building of the Cenarion Enclave. No Herbalism? Buy five Earthroot on the Auction House first: you need them later.", f={r={"NightElf"}}, g={{"l",14,txt="Reach level 14"},{"g",0,txt="Cenarion Enclave",m=1457,x=35.8,y=11.6}}},
  {t="Lessons Anew", lv=14, n="Mathrengyl Bearwalker stands upstairs in the druids' building of the Cenarion Enclave. No Herbalism? Buy five Earthroot on the Auction House first: you need them later.", f={r={"NightElf"}}, g={{"l",14,txt="Reach level 14"},{"a",6121,m=1457,x=35.4,y=8.4,ml=14}}},
  {t="Cenarion Enclave", lv=14, n="Mathrengyl Bearwalker stands upstairs in the druids' building of the Cenarion Enclave; Alfina Nightgaze by the Skyborne Portal does not give this quest. Cast Teleport: Moonglade and take Silva Fil'naveth's flight from the middle of Nighthaven (she flies druids to Rut'theran Village, no flight path needed), then the portal up. No Herbalism? Buy five Earthroot on the Auction House first: you need them later.", f={r={"Skyborne"},fa={"Alliance"}}, g={{"l",14,txt="Reach level 14"},{"g",0,txt="Cenarion Enclave",m=1457,x=35.8,y=11.6}}},
  {t="Lessons Anew", lv=14, n="Mathrengyl Bearwalker stands upstairs in the druids' building of the Cenarion Enclave; Alfina Nightgaze by the Skyborne Portal does not give this quest. Cast Teleport: Moonglade and take Silva Fil'naveth's flight from the middle of Nighthaven (she flies druids to Rut'theran Village, no flight path needed), then the portal up. No Herbalism? Buy five Earthroot on the Auction House first: you need them later.", f={r={"Skyborne"},fa={"Alliance"}}, g={{"l",14,txt="Reach level 14"},{"a",6121,m=1457,x=35.4,y=8.4,ml=14}}},
  {t="Dendrite Starblaze", lv=14, n="Cast Teleport: Moonglade: Dendrite Starblaze stands upstairs in the building beside you. He hands you the Empty Cliffspring Falls Sampler. Then fly to Auberdine (learn the Moonglade flight path at Sindrayl first if you have not).", f={r={"NightElf","Skyborne"},fa={"Alliance"}}, g={{"t",6121,m=1450,x=56.2,y=30.6},{"a",6122,m=1450,x=56.2,y=30.6,ml=14},{"z",0,txt="Fly to Auberdine",at="Auberdine"}}},
  {t="Cliffspring Falls", lv=14, n="Head north-east from Auberdine to Cliffspring Falls. Stand at the cave mouth at the top of the waterfall, not in the river below, and use the Empty Cliffspring Falls Sampler (not the Empty Sampling Tube of another quest). Naga line the climb, a caster waits on the far bank, and filling the sampler calls two more (a Wave Rider and a Toxicologist, level 15): clear the way first and be ready to fight.", f={r={"NightElf","Skyborne"},fa={"Alliance"}}, g={{"o",6122,i=1,txt="Use Empty Cliffspring Falls Sampler",n2="Empty Cliffspring Falls Sampler, at the cave mouth",m=1439,x=54.9,y=33.3},{"o",6122,i=1,txt="Filled Cliffspring Falls Sampler",m=1439,x=54.9,y=33.3}}},
  {t="Alanndarian Nightsong", lv=14, n="Back in Auberdine, at the north end of the village.", f={r={"NightElf","Skyborne"},fa={"Alliance"}}, g={{"t",6122,m=1439,x=37.7,y=40.7},{"a",6123,m=1439,x=37.7,y=40.7,ml=14}}},
  {t="Lunar Fungus and Earthroot", lv=14, n="The Lunar Fungal Blooms are tiny white-spotted mushrooms on the floors and walls of the small moonkin caves in the hills just east and south-east of Auberdine; each gives one or two fungus, and each cave holds only a few, so go from cave to cave (they regrow in three minutes). The moonkin there are irritable. No Herbalism needed for the blooms. Earthroot needs Herbalism: herbalists pick it all over Darkshore, anyone else buys it (Maria Lumere or Bernard Gump in Stormwind, or the Auction House).", f={r={"NightElf","Skyborne"},fa={"Alliance"}}, g={{"o",6123,i=2,txt="Lunar Fungus x12",m=1439,x=43.2,y=45.8},{"o",6123,i=1,txt="Earthroot x5",m=1439,x=42.7,y=46.4}}},
  {t="Alanndarian Nightsong", lv=14, n="She hands you the Curative Animal Salve: ten doses, one per deer. Destroy any leftover Lunar Fungus.", f={r={"NightElf","Skyborne"},fa={"Alliance"}}, g={{"t",6123,m=1439,x=37.7,y=40.7},{"a",6124,m=1439,x=37.7,y=40.7,ml=14}}},
  {t="Sickly Deer", lv=14, n="Use the Curative Animal Salve on living Sickly Deer (level 5, a green cloud over them): they roam Darkshore from the Cliffspring River to the Ashenvale border, many around the Blackwood furbolg camp north-east of Auberdine. Druid trick: root a deer with Entangling Roots, apply the salve before the roots tick, and the root kill counts a second time. Lost a dose on a deer that did not count? Abandon the quest and take it again from Alanndarian for a fresh salve.", f={r={"NightElf","Skyborne"},fa={"Alliance"}}, g={{"o",6124,i=1,txt="Use the Curative Animal Salve on Sickly Deer x10",m=1439,x=38.6,y=36.1}}},
  {t="Curing the Sick", lv=14, n="Cast Teleport: Moonglade and see Dendrite Starblaze, then take Silva Fil'naveth's flight from the middle of Nighthaven (she flies druids to Rut'theran Village, no flight path needed) and the portal up to Darnassus. Dendrite stands upstairs in his building: go up inside, the arrow cannot tell the floors apart.", f={r={"NightElf","Skyborne"},fa={"Alliance"}}, g={{"t",6124,m=1450,x=56.2,y=30.6},{"a",6125,m=1450,x=56.2,y=30.6,ml=14},{"z",0,txt="Fly to Rut'theran Village",at="Rut'theran Village"}}},
  {t="Cenarion Enclave", lv=14, n="Mathrengyl Bearwalker, upstairs in the Cenarion Enclave, teaches you Cure Poison.", f={r={"NightElf","Skyborne"},fa={"Alliance"}}, g={{"g",0,txt="Cenarion Enclave",m=1457,x=35.8,y=11.6}}},
  {t="Power over Poison", lv=14, n="Mathrengyl Bearwalker, upstairs in the Cenarion Enclave, teaches you Cure Poison.", f={r={"NightElf","Skyborne"},fa={"Alliance"}}, g={{"t",6125,n2="Mathrengyl Bearwalker: Cure Poison",m=1457,x=35.4,y=8.4}}},
  {t="Lessons Anew", lv=14, n="Turak Runetotem stands in the druids' hut on Elder Rise; Hana Lighthoof, the Skyborne druid trainer where the airship from Zephras Isle lands in northern Mulgore, gives the same quest. No Herbalism? Hula'mahi at the Crossroads sells Earthroot later, or buy five on the Auction House now.", f={r={"Tauren","Skyborne"},fa={"Horde"}}, g={{"l",14,txt="Reach level 14"},{"a",6126,n2="Turak Runetotem, or Hana Lighthoof in northern Mulgore",m=1456,x=76.5,y=27.2,ml=14}}},
  {t="Dendrite Starblaze", lv=14, n="Cast Teleport: Moonglade: Dendrite Starblaze stands upstairs in the building beside you. He hands you the Empty Dreadmist Peak Sampler. Bunthen Plainswind flies druids to Thunder Bluff; fly on to the Crossroads from there.", f={r={"Tauren","Skyborne"},fa={"Horde"}}, g={{"t",6126,m=1450,x=56.2,y=30.6},{"a",6127,m=1450,x=56.2,y=30.6,ml=14},{"z",0,txt="Fly to Thunder Bluff",at="Thunder Bluff"}}},
  {t="Dreadmist Peak", lv=14, n="From the Crossroads head north to Dreadmist Peak and climb to the bubbling Dreadmist Peak Pool on its summit. Burning Blade cultists camp around it: pull them one or two at a time. Stand in the water and use the Empty Dreadmist Peak Sampler: three Burning Blade Toxicologists (level 13-14, curses and warlock spells) appear and attack. You need not kill them: once the sampler is full, run.", f={r={"Tauren","Skyborne"},fa={"Horde"}}, g={{"z",0,txt="Fly to Crossroads",at="Crossroads"},{"o",6127,i=1,txt="Use Empty Dreadmist Peak Sampler",n2="Empty Dreadmist Peak Sampler, standing in the pool",m=1413,x=48.4,y=18.9},{"o",6127,i=1,txt="Filled Dreadmist Peak Sampler",m=1413,x=48.4,y=18.9}}},
  {t="Tonga Runetotem", lv=14, n="Tonga Runetotem stands in the Crossroads. No Herbalism? Hula'mahi, a few steps away by the wind rider master, sells Earthroot for 80 copper each, three at a time until he restocks.", f={r={"Tauren","Skyborne"},fa={"Horde"}}, g={{"t",6127,m=1413,x=52.3,y=31.9},{"a",6128,m=1413,x=52.3,y=31.9,ml=14},{"h",2449,txt="Buy Earthroot x5 (Hula'mahi)",n2="Earthroot; herbalists pick it on the plains",m=1413,x=51.4,y=30.2,n=5,opt=true}}},
  {t="Earthroot and Kodo Horns", lv=14, n="Every Lost Barrens Kodo (level 14-15) drops a horn, but they are few and wander: search the far north near the Sludge Fen and the oases, above all the Stagnant Oasis south-east of the Crossroads. They charge from range and stomp. Herbalists find Earthroot all over the northern Barrens.", f={r={"Tauren","Skyborne"},fa={"Horde"}}, g={{"o",6128,i=2,txt="Kodo Horn x5",m=1413,x=54.8,y=40.1},{"o",6128,i=1,txt="Earthroot x5",m=1413,x=60.9,y=41.3}}},
  {t="Tonga Runetotem", lv=14, n="He hands you the Curative Animal Salve: ten doses, one per gazelle.", f={r={"Tauren","Skyborne"},fa={"Horde"}}, g={{"t",6128,m=1413,x=52.3,y=31.9},{"a",6129,m=1413,x=52.3,y=31.9,ml=14}}},
  {t="Sickly Gazelles", lv=14, n="Use the Curative Animal Salve on living Sickly Gazelles (level 3): they graze on both sides of the road north of the Crossroads up to the Ashenvale border, north-west of the Crossroads and west of Ratchet. Druid trick: root a gazelle with Entangling Roots, apply the salve before the roots tick, and the root kill counts a second time, so five gazelles can do. Lost a dose? Abandon and retake the quest from Tonga for a fresh salve.", f={r={"Tauren","Skyborne"},fa={"Horde"}}, g={{"o",6129,i=1,txt="Use the Curative Animal Salve on Sickly Gazelles x10",m=1413,x=54.5,y=32.1}}},
  {t="Curing the Sick", lv=14, n="Cast Teleport: Moonglade and see Dendrite Starblaze, then take Bunthen Plainswind's flight to Thunder Bluff. Dendrite stands upstairs in his building: go up inside, the arrow cannot tell the floors apart.", f={r={"Tauren","Skyborne"},fa={"Horde"}}, g={{"t",6129,m=1450,x=56.2,y=30.6},{"a",6130,m=1450,x=56.2,y=30.6,ml=14},{"z",0,txt="Fly to Thunder Bluff",at="Thunder Bluff"}}},
  {t="Power over Poison", lv=14, n="Turak Runetotem on Elder Rise teaches you Cure Poison.", f={r={"Tauren","Skyborne"},fa={"Horde"}}, g={{"t",6130,n2="Turak Runetotem: Cure Poison",m=1456,x=76.5,y=27.2}}},
} end)

R:Segment({id="class/hunter/rhokdelar",title="Rhok'delar and Lok'delar",classes={"HUNTER"},min=60,max=60,zone=1448,zoneName="Felwood",why="The hunter's epic bow chain: in Classic the stave and sinew became Rhok'delar and Lok'delar (unconfirmed in Forever).",items={18707,18724,18714},folder="Hunter"}, function() return {
  {t="The Ancient Petrified Leaf", lv=60, n="Molten Core is a 40-player raid inside Blackrock Mountain. When Majordomo Executus yields, the Cache of the Firelord appears; it holds the Ancient Petrified Leaf about half the time, one per kill, so it may take several weeks of raids. Right-click the leaf to start the quest.", g={{"a",7632,n2="from the Ancient Petrified Leaf",grp=true,ml=60}}},
  {t="Vartrus the Ancient", lv=60, n="Vartrus, Stoma and Hastat the Ancient are petrified trees on a small island in a ring-shaped lake in Irontree Woods, north Felwood. Their spirits only appear when someone carrying the leaf climbs the island's little hill to its east edge. Alliance: fly to Talonbranch Glade; Horde: fly to Bloodvenom Post. Vartrus gives Stave of the Ancients, Stoma A Proper String, Hastat the quiver; each can be handed in on its own.", g={{"t",7632,m=1448,x=47.8,y=24.1},{"a",7633,m=1448,x=47.8,y=24.1,ml=60},{"t",7633,m=1448,x=47.8,y=24.1},{"a",7636,m=1448,x=47.8,y=24.1,ml=60},{"a",7635,m=1448,x=48.4,y=22.3,ml=60},{"a",7634,n2="Hastat the Ancient: the quiver, last in this guide",m=1448,x=46.7,y=24.1,ml=60}}},
  {t="Before the demons", lv=60, n="The four demons are level 60 elites disguised as friendly travellers; talk to one and say you know what it is, and it turns into its demon form. Fight every one alone: no pet (dismiss it), no other player's heal, buff or attack once the fight starts, or the demon calls you a coward and vanishes, with a 3 hour wait for it to return (also after it dies). Buffs and potions you take before the pull are fine, and a friend may stand by to kill wandering monsters or enemy players, as long as they never touch the demon or you. Bring a Potion of Demon Slaying (Alchemy or the auction house), Major Mana Potions for the long kites, and a melee weapon with the Demonslaying enchant if you can. Track Demons, from your trainer, shows the disguised demons on the minimap. In a group, set loot to free for all so you can loot the head.", g={{"i",0,txt="Learn Track Demons and get demon-slaying potions",opt=true}}},
  {t="Simone the Inconspicuous", lv=60, n="Simone the Inconspicuous, a troll with a wolf, walks a long path that starts at the lake in western Un'Goro and can reach the south of the crater; use Track Demons. Talk to her and she becomes Simone the Seductress, and her wolf Precious a Felstalker. The hardest of the four: Freezing Trap Precious and pull Simone well away from it, or kite Precious away and kill it first, let Simone reset and come back for her alone. Her Chain Lightning hits hard, so drain her mana with Viper Sting (a 15-second cooldown on Forever) and keep her busy; her Temptress' Kiss cuts your ranged attack power, so finish her in melee. Loot her head before Precious breaks free.", g={{"tk",14527,txt="Talk to Simone the Inconspicuous",m=1449,x=34.3,y=40.8},{"o",7636,i=1,txt="Simone's Head",m=1449,x=34.3,y=40.8,grp=true}}},
  {t="Franklin the Friendly", lv=60, n="Franklin the Friendly, a human, wanders the western Burning Steppes south of Blackrock Mountain. Talk to him and he becomes Klinfran the Crazed, the easiest of the four. Keep Scorpid Sting on him the whole fight: while it lasts he barely hurts you. When he goes into Demonic Frenzy, remove it with Tranquilizing Shot and never stand in melee while it is up; between frenzies you can fight him in melee with Wing Clip and Raptor Strike. He cannot leave the Burning Steppes, so kite him around the trees if needed.", g={{"tk",14529,txt="Talk to Franklin the Friendly",m=1428,x=24.8,y=65.9},{"o",7636,i=2,txt="Klinfran's Head",m=1428,x=24.8,y=65.9,grp=true}}},
  {t="Nelson the Nice", lv=60, n="Nelson the Nice, a gnome, walks around the gates of Ahn'Qiraj in the far south-west of Silithus. Talk to him and he becomes Solenor the Slayer. He enrages with Soul Flame as he turns: drop a Frost Trap, Feign Death, and he resets without the enrage. Wing Clip roots him for a long time; while rooted he fears you and sends beetles (Creeping Doom): kill them fast with traps and Multi-Shot before they wear you down.", g={{"tk",14536,txt="Talk to Nelson the Nice",m=1451,x=24.7,y=76},{"o",7636,i=3,txt="Solenor's Head",m=1451,x=24.7,y=76,grp=true}}},
  {t="Artorius the Amiable", lv=60, n="Artorius the Amiable, a tauren, walks a loop in the rocks of northern Winterspring, north of Everlook. Talk to him and he becomes Artorius the Doombringer. Within 30 yards of him Demonic Doom hits hard: keep your distance and kite him the whole fight, Aspect of the Cheetah on, south down the road. Serpent Sting on him adds Stinging Trauma, extra Nature damage, so keep it ticking while you run; his Demonic Frenzy can be removed with Tranquilizing Shot, but distance matters more. It is a long fight: bring mana potions and plan your kiting path.", g={{"tk",14531,txt="Talk to Artorius the Amiable",m=1452,x=60.3,y=13.2},{"o",7636,i=4,txt="Artorius's Head",m=1452,x=60.3,y=13.2,grp=true}}},
  {t="Onyxia", lv=60, n="Onyxia is the 40-player raid boss of Onyxia's Lair, a cave in the Wyrmbog of southern Dustwallow Marsh; she returns once a week. She drops one Mature Black Dragon Sinew in about two kills of five, lootable without the quest, so only one hunter per kill gets it: settle who first.", g={{"o",7635,i=1,txt="Mature Black Dragon Sinew",n2="Mature Black Dragon Sinew, from Onyxia",m=1445,x=52.1,y=75.8,grp=true}}},
  {t="Back to the Ancients", lv=60, g={{"t",7636,m=1448,x=47.8,y=24.1},{"t",7635,m=1448,x=48.4,y=22.3}}},
  {t="Rhok'delar and Lok'delar", lv=60, n="Not confirmed in Forever. In Classic, using the Ancient Rune Etched Stave with the Enchanted Black Dragon Sinew in your bags made Rhok'delar, and talking to Vartrus once more then gave Lok'delar, Stave of the Ancient Keepers, at no extra cost.", g={{"i",0,txt="Use Ancient Rune Etched Stave",n2="Ancient Rune Etched Stave, by Vartrus",m=1448,x=47.8,y=24.1},{"tk",14524,txt="Talk to Vartrus the Ancient",n2="Vartrus the Ancient: Lok'delar in Classic",m=1448,x=47.8,y=24.1,opt=true}}},
  {t="Azuregos", lv=60, n="Hastat's quiver needs the Mature Blue Dragon Sinew. Azuregos, a world boss for a raid, stands in southern Azshara, returns only every two to four days and drops it nearly every kill. The elite Cobalt dragonkin in and around Mazthoril, the cave south of Everlook in Winterspring, drop it about once in 200 kills; Manaclaw there a little more often. Skip the rest of this guide if you do not want the quiver.", g={{"o",7634,i=1,txt="Mature Blue Dragon Sinew",n2="Mature Blue Dragon Sinew, from Azuregos",m=1447,x=53.3,y=80.4,grp=true}}},
  {t="Hastat the Ancient", lv=60, g={{"t",7634,m=1448,x=46.7,y=24.1}}},
} end)

R:Segment({id="class/hunter/taming-the-beast-alliance",title="Taming the Beast (Alliance)",faction="Alliance",races={"Human","Dwarf","NightElf","Skyborne"},classes={"HUNTER"},min=10,max=10,zone=1429,zoneName="Elwynn Forest",why="Your own pet at 10: three practice tames with a Taming Rod teach Tame Beast, then Beast Training.",spells={1515,5149},spellNames={"Tame Beast","Beast Training"},folder="Hunter"}, function() return {
  {t="Elayaa Easewind", lv=10, n="At 10, Elayaa Easewind, a hunter trainer on Zephras Isle, may send you on to Valanaar with Taming the Beast. It is only a pointer: skip it if you are already in Valanaar.", f={r={"Skyborne"}}, g={{"l",10,txt="Reach level 10"},{"a",94007,m=2521,x=45.3,y=44.2,opt=true,ml=10}}},
  {t="Quel'ana Quickgale in Valanaar", lv=10, n="Quel'ana Quickgale stands with the trainers by Valanaar's west gate, Quel'dora Quickgale beside her.", f={r={"Skyborne"}}, g={{"t",94007,m=2521,x=59.6,y=72.6,opt=true},{"a",94978,n2="Quel'ana Quickgale: the first Taming Rod",m=2521,x=59.6,y=72.6,ml=10}}},
  {t="Windsong Crawler", lv=10, n="Windsong Crawlers live only by water: the nearest scuttle along the shore south-west of Valanaar, among the crabs. How the rod works: target a living crawler, use the Taming Rod and stand still for the whole channel while it hits you; moving, fighting back or anyone else's help breaks it and costs one of the rod's few charges. Killing one does not count. Keep each rod: it goes back to Quel'ana.", f={r={"Skyborne"}}, g={{"o",94978,i=1,txt="Tame Windsong Crawler",n2="Use the Taming Rod on a living crawler",m=2521,x=53.8,y=77},{"t",94978,m=2521,x=59.6,y=72.6},{"a",94979,m=2521,x=59.6,y=72.6,ml=10}}},
  {t="Ornery Galestrider", lv=10, n="Dismiss the crawler first (right-click the pet portrait, Dismiss Pet). Ornery Galestriders graze in the Gustberry Lowlands, the fields a short walk west and south-west of Valanaar.", f={r={"Skyborne"}}, g={{"o",94979,i=1,txt="Tame Ornery Galestrider",n2="Use the Taming Rod on a living galestrider",m=2521,x=59.2,y=74},{"t",94979,m=2521,x=59.6,y=72.6},{"a",94013,m=2521,x=59.6,y=72.6,ml=10}}},
  {t="Vuldren Alpha", lv=10, n="Dismiss the galestrider. Vuldren Alphas hunt in the same Gustberry Lowlands, a little further south.", f={r={"Skyborne"}}, g={{"o",94013,i=1,txt="Tame Vuldren Alpha",n2="Use the Taming Rod on a living alpha",m=2521,x=59.7,y=72.7},{"t",94013,n2="Quel'ana Quickgale: Tame Beast",m=2521,x=59.6,y=72.6},{"a",94050,m=2521,x=59.6,y=72.6,ml=10},{"t",94050,n2="Quel'dora Quickgale, beside her: Beast Training",m=2521,x=59.9,y=72.9}}},
  {t="Grif Wildheart in Kharanos", lv=10, n="At 10 go to Grif Wildheart, the hunter trainer at the smithy in Kharanos. The Hunter's Path from Olmin Burningbeard in Ironforge, Tristane Shadowstone north-west of Kharanos or Einris Brightspear in Stormwind also leads here, for a little experience; it is only a pointer. In Elwynn at 10 instead? Josephine Carson's chain in Goldshire teaches the same.", w={{k="onquest",neg=true,q={94792,94863,94864,94793}},{k="turnedin",neg=true,q=94792}}, f={r={"Dwarf"}}, g={{"l",10,txt="Reach level 10"},{"a",6064,n2="Grif Wildheart: the first Taming Rod",m=1426,x=45.8,y=53,ml=10}}},
  {t="Large Crag Boar", lv=10, n="Large Crag Boars (level 6-7) root around the fields west, south and north-west of Kharanos and respawn every 3 minutes. How the rod works: target a living beast, use the Taming Rod and stand still for the whole channel while it hits you. Moving, fighting back, being out of range or anyone else's help breaks it and costs one of the rod's few charges; if they run out, destroy the rod, abandon the quest and take it again from Grif. The boars use Rushing Charge from 25 yards, so start with the rod, not Auto Shot. Keep each rod: it goes back to Grif.", w={{k="onquest",neg=true,q={94792,94863,94864,94793}},{k="turnedin",neg=true,q=94792}}, f={r={"Dwarf"}}, g={{"o",6064,i=1,txt="Tame Large Crag Boar",n2="Use the Taming Rod on a living boar",m=1426,x=49.2,y=54.8},{"t",6064,m=1426,x=45.8,y=53},{"a",6084,m=1426,x=45.8,y=53,ml=10}}},
  {t="Snow Leopard", lv=10, n="Dismiss the boar first (right-click the pet portrait, Dismiss Pet): a released practice pet can turn on you. Snow Leopards (level 7-8) prowl the slopes south-east of Kharanos, more north-west and west of it; the smaller Juvenile Snow Leopards do not count.", w={{k="onquest",neg=true,q={94792,94863,94864,94793}},{k="turnedin",neg=true,q=94792}}, f={r={"Dwarf"}}, g={{"o",6084,i=1,txt="Tame Snow Leopard",n2="Use the Taming Rod on a living leopard",m=1426,x=48.3,y=56.5},{"t",6084,m=1426,x=45.8,y=53},{"a",6085,m=1426,x=45.8,y=53,ml=10}}},
  {t="Ice Claw Bear", lv=10, n="Dismiss the leopard. Ice Claw Bears (level 7-8) roam the hills around Kharanos, many south-east of it and more north-west toward Anvilmar; their Ice Claw hits hard, so start at full health.", w={{k="onquest",neg=true,q={94792,94863,94864,94793}},{k="turnedin",neg=true,q=94792}}, f={r={"Dwarf"}}, g={{"o",6085,i=1,txt="Tame Ice Claw Bear",n2="Use the Taming Rod on a living bear",m=1426,x=50.3,y=53.8},{"t",6085,n2="Grif Wildheart: Tame Beast",m=1426,x=45.8,y=53},{"a",6086,m=1426,x=45.8,y=53,ml=10}}},
  {t="Belia Thundergranite in Ironforge", lv=10, n="Belia Thundergranite, the pet trainer, stands in the Hall of Arms in Ironforge's Military Ward, by the hunter trainers.", w={{k="onquest",neg=true,q={94792,94863,94864,94793}},{k="turnedin",neg=true,q=94792}}, f={r={"Dwarf"}}, g={{"t",6086,n2="Belia Thundergranite: Beast Training",m=1455,x=70.9,y=85.8}}},
  {t="Dazalar in Dolanaar", lv=10, n="At 10 go to Dazalar, the hunter trainer in Dolanaar. The Hunter's Path from Ayanna Everstride at Aldrassil, Jocaste in Darnassus, Einris Brightspear in Stormwind, Olmin Burningbeard in Ironforge or Grif Wildheart in Kharanos also leads here, for a little experience; it is only a pointer. In Elwynn at 10 instead? Josephine Carson's chain in Goldshire teaches the same.", w={{k="onquest",neg=true,q={94792,94863,94864,94793}},{k="turnedin",neg=true,q=94792}}, f={r={"NightElf"}}, g={{"l",10,txt="Reach level 10"},{"a",6063,n2="Dazalar: the first Taming Rod",m=1438,x=56.7,y=59.5,ml=10}}},
  {t="Webwood Lurker", lv=10, n="Webwood Lurkers (level 5-6) creep through the woods just north-east, south-west and east of Dolanaar. How the rod works: target a living beast, use the Taming Rod and stand still for the whole channel while it hits you; moving, attacking it or anyone else's help breaks it and costs one of the rod's few charges (out of charges: destroy the rod, abandon the quest, take it again). Their Web roots you but does not break the channel if you keep still. Keep each rod: it goes back to Dazalar.", w={{k="onquest",neg=true,q={94792,94863,94864,94793}},{k="turnedin",neg=true,q=94792}}, f={r={"NightElf"}}, g={{"o",6063,i=1,txt="Tame Webwood Lurker",n2="Use the Taming Rod on a living spider",m=1438,x=58.2,y=55.8},{"t",6063,m=1438,x=56.7,y=59.5},{"a",6101,m=1438,x=56.7,y=59.5,ml=10}}},
  {t="Nightsaber Stalker", lv=10, n="Dismiss the spider first (right-click the pet portrait, Dismiss Pet): a released practice pet can turn on you. Nightsaber Stalkers (level 7-8) lie on the hillside south of Lake Al'Ameth, south of Dolanaar; the plain Nightsabers by the village do not count.", w={{k="onquest",neg=true,q={94792,94863,94864,94793}},{k="turnedin",neg=true,q=94792}}, f={r={"NightElf"}}, g={{"o",6101,i=1,txt="Tame Nightsaber Stalker",n2="Use the Taming Rod on a living stalker",m=1438,x=55.8,y=72.3},{"t",6101,m=1438,x=56.7,y=59.5},{"a",6102,m=1438,x=56.7,y=59.5,ml=10}}},
  {t="Strigid Screecher", lv=10, n="Dismiss the cat. Strigid Screechers (level 7-8), owls, perch in the woods south, south-west and west of Dolanaar.", w={{k="onquest",neg=true,q={94792,94863,94864,94793}},{k="turnedin",neg=true,q=94792}}, f={r={"NightElf"}}, g={{"o",6102,i=1,txt="Tame Strigid Screecher",n2="Use the Taming Rod on a living owl",m=1438,x=64.2,y=67.2},{"t",6102,n2="Dazalar: Tame Beast",m=1438,x=56.7,y=59.5},{"a",6103,m=1438,x=56.7,y=59.5,ml=10}}},
  {t="Jocaste in Darnassus", lv=10, n="Take the road west from Dolanaar to Darnassus. Jocaste stands inside the Cenarion Enclave with the hunter trainers; Silvaria, the pet trainer, is up the ramp next to her.", w={{k="onquest",neg=true,q={94792,94863,94864,94793}},{k="turnedin",neg=true,q=94792}}, f={r={"NightElf"}}, g={{"t",6103,n2="Jocaste: Beast Training",m=1457,x=40.4,y=8.6}}},
  {t="Josephine Carson in Goldshire", lv=10, n="At 10 go to Josephine Carson, the hunter trainer who stands with the other trainers by the Lion's Pride Inn in Goldshire; Isaac Chan, the pet trainer, is beside her. Skyborne: this is for one who left Zephras Isle without taming; it teaches the same.", f={r={"Human","Skyborne"}}, lb="goldshire", g={{"l",10,txt="Reach level 10"},{"a",94792,n2="Josephine Carson: the first Taming Rod",m=1429,x=41.1,y=66.2,ml=10}}},
  {t="Rockhide Boar", lv=10, n="Rockhide Boars (level 7-8) graze in three herds south and south-east of Goldshire, toward the Maclure Vineyards. How the rod works: target a living beast, use the Taming Rod and stand still for the whole channel while it hits you. Moving, fighting back, a heal from someone else or anyone else hitting the beast breaks it and costs one of the rod's few charges; if they run out, destroy the rod, abandon the quest and take it again. The boars use Rushing Charge, so start with the rod, not Auto Shot. Killing a boar does not count. Keep each rod: it goes back to Josephine. A Dwarf or Night Elf who took Josephine's rod instead of their home trainer's is led through Goldshire from here.", w={{k="turnedin",neg=true,q=6064},{k="turnedin",neg=true,q=6063}}, g={{"o",94792,i=1,txt="Tame Rockhide Boar",n2="Use the Taming Rod on a living boar",m=1429,x=43.3,y=77.9},{"t",94792,m=1429,x=41.1,y=66.2},{"a",94863,m=1429,x=41.1,y=66.2,ml=10}}},
  {t="Gray Forest Wolf", lv=10, n="Dismiss the boar first (right-click the pet portrait, Dismiss Pet): a released practice pet can turn on you. Gray Forest Wolves (level 7-8) run in the woods east of Goldshire, east of Crystal Lake.", w={{k="turnedin",neg=true,q=6064},{k="turnedin",neg=true,q=6063}}, g={{"o",94863,i=1,txt="Tame Gray Forest Wolf",n2="Use the Taming Rod on a living wolf",m=1429,x=58.4,y=62.1},{"t",94863,m=1429,x=41.1,y=66.2},{"a",94864,m=1429,x=41.1,y=66.2,ml=10}}},
  {t="Young Forest Bear", lv=10, n="Dismiss the wolf. Young Forest Bears (level 8-9) roam the woods just south of Goldshire, with more south-west and south-east of town.", w={{k="turnedin",neg=true,q=6064},{k="turnedin",neg=true,q=6063}}, g={{"o",94864,i=1,txt="Tame Young Forest Bear",n2="Use the Taming Rod on a living bear",m=1429,x=43.4,y=80.4},{"t",94864,n2="Josephine Carson: Tame Beast",m=1429,x=41.1,y=66.2},{"a",94793,m=1429,x=41.1,y=66.2,ml=10},{"t",94793,n2="Isaac Chan, beside her: Beast Training",m=1429,x=41.8,y=66.4}}},
  {t="Your first pet", lv=10, n="Tame Beast works like the rod: a beast of your level or lower, a channel you must not move during, the beast hitting you all the while. A pet keeps the level you tame it at and levels up with you; it can never be above your level, so tame one close to yours. Each family has its own ability on Forever (a boar's Charge, for example). For levelling, a cat hits hardest (Claw and Bite) and a boar takes more punishment.", lb="pet", g={{"i",0,txt="Tame a beast of your level to keep",opt=true},{"i",0,txt="Near Goldshire there are no cats: Prowlers (wolves, level 9-10) roam eastern Elwynn, Longsnouts (boars, 10-11) its far south-west by the Westfall border; at 12-13, Young Goretusks (boars) graze the fields of northern Westfall.",f={r={"Human"}}},{"i",0,txt="Near Kharanos: Snow Leopards (cats, level 7-8) prowl all over Dun Morogh, Scarred Crag Boars (9-10) its east toward Loch Modan; at 10-11, Mountain Boars roam western Loch Modan.",f={r={"Dwarf"}}},{"i",0,txt="Near Dolanaar: Elder Nightsabers (cats, level 8-9) and Feral Nightsabers (cats, 10-11) prowl the woods of north-western Teldrassil.",f={r={"NightElf"}}},{"i",0,txt="Near Valanaar: Vuldren Alphas (level 10), the beast of your last practice tame, hunt the Gustberry Lowlands; Shriekling Matriarchs (raptors, level 9) nest just west of Valanaar; Shadowgale Urseras (bears, 10-11) roam the north of Zephras Isle.",f={r={"Skyborne"}}},{"i",0,txt="Feed Pet: open your spellbook, cast Feed Pet and click a food your pet's family eats (the pet's tooltip lists them: cats eat meat and fish, boars almost anything). Raw meat looted from beasts counts. To buy: Toddrick the butcher in Goldshire, Jaeana in Darnassus and the innkeepers on Zephras Isle sell meat; the innkeepers of Kharanos and Dolanaar sell bread. Food near the pet's level makes it happiest; much lower food gives about half. You cannot feed in combat."},{"i",0,txt="Happiness: the face on the pet frame. An unhappy pet does three quarters of its damage, a happy one a quarter more. Happiness drains slowly, faster when the pet dies; a pet left unhappy too long can run away."},{"i",0,txt="Loyalty grows with time and kills. Each loyalty rank raises the training points you spend in Beast Training (pet level times loyalty rank minus one)."},{"i",0,txt="Beast Training (spellbook, General tab) teaches your current pet the abilities you know. To learn a new ability or rank: leave your pet with a stable master (Erma in Goldshire, Shelby Stoneflint in Kharanos, Seriadne in Dolanaar, Genn Fairweather on Zephras Isle), tame a beast that has it (its pet spellbook tab shows what it knows), use the ability in fights until the game says you learned it, then take your own pet back and teach it with Beast Training. A pet holds four active abilities at most."},{"i",0,txt="Pet trainers sell Growl ranks and resistances. Alliance: Isaac Chan in Goldshire, Karrina Mekenda by the hunter trainers in Stormwind's Dwarven District, Peria Lamenur in Kharanos, Belia Thundergranite in Ironforge's Hall of Arms, Keldas in Dolanaar, Silvaria in Darnassus' Cenarion Enclave, Quel'dora Quickgale in Valanaar."},{"i",0,txt="Call Pet, Dismiss Pet and Revive Pet are in your spellbook now; Mend Pet comes from your trainer at 12. A dead pet needs Revive Pet; one that is away more than about 100 yards is dismissed and comes back with Call Pet."}}},
} end)

R:Segment({id="class/hunter/taming-the-beast-horde",title="Taming the Beast (Horde)",faction="Horde",races={"Orc","Troll","Tauren","Skyborne"},classes={"HUNTER"},min=10,max=10,zone=1411,zoneName="Durotar",why="Your own pet at 10: three practice tames with a Taming Rod teach Tame Beast, then Beast Training.",spells={1515,5149},spellNames={"Tame Beast","Beast Training"},folder="Hunter"}, function() return {
  {t="Thotar in Razor Hill", lv=10, n="At 10 go to Thotar, the hunter trainer inside the barracks in Razor Hill. If Sian'dur in Orgrimmar, Kali Remik in Sen'jin Village or Kary Thunderhorn in Thunder Bluff hands you The Hunter's Path, take it and hand it to Thotar for a little experience; it is only a pointer, and you can take the first rod without it.", f={r={"Orc","Troll"}}, g={{"l",10,txt="Reach level 10"},{"a",6062,n2="Thotar: the first Taming Rod",m=1411,x=51.9,y=43.5,ml=10}}},
  {t="Dire Mottled Boar", lv=10, n="Dire Mottled Boars (level 6-7) roam just north and west of Razor Hill. How the rod works: target a living beast, use the Taming Rod from inside its range and stand still for the whole channel while the beast hits you. Moving, fighting back, a heal from someone else or anyone else hitting the beast breaks it and costs one of the rod's few charges; if they run out, destroy the rod, abandon the quest and take it again from Thotar. The boars charge from 20 yards, so start with the rod, not Auto Shot. The tamed boar becomes your pet for practice. Keep each rod: it goes back to Thotar.", f={r={"Orc","Troll"}}, g={{"o",6062,i=1,txt="Tame Dire Mottled Boar",n2="Use the Taming Rod on a living boar",m=1411,x=53.4,y=46.2},{"t",6062,m=1411,x=51.9,y=43.5},{"a",6083,m=1411,x=51.9,y=43.5,ml=10}}},
  {t="Surf Crawler", lv=10, n="First dismiss the boar (right-click your pet's portrait, Dismiss Pet): a released practice pet can turn on you. Surf Crawlers (level 7-8) walk the beaches around Sen'jin Village and the Echo Isles; the small Pygmy Surf Crawlers do not count. A crawler runs for help at 15% health, so do not hurt it.", f={r={"Orc","Troll"}}, g={{"o",6083,i=1,txt="Tame Surf Crawler",n2="Use the Taming Rod on a living Surf Crawler",m=1411,x=58.9,y=28.3},{"t",6083,m=1411,x=51.9,y=43.5},{"a",6082,m=1411,x=51.9,y=43.5,ml=10}}},
  {t="Armored Scorpid", lv=10, n="Dismiss the crawler. Armored Scorpids (level 7-8) crawl the dry plains west and south-west of Razor Hill, some just south of the road west out of town; Track Beasts shows them. Their hits can break the channel: start at full health and keep still.", f={r={"Orc","Troll"}}, g={{"o",6082,i=1,txt="Tame Armored Scorpid",n2="Use the Taming Rod on a living scorpid",m=1411,x=51,y=37.7},{"t",6082,n2="Thotar: Tame Beast",m=1411,x=51.9,y=43.5},{"a",6081,m=1411,x=51.9,y=43.5,ml=10}}},
  {t="Ormak Grimshot in Orgrimmar", lv=10, n="Follow the road north to Orgrimmar's gate. Ormak Grimshot stands with the hunter trainers in the Valley of Honor, up the ramp at the city's east side; Xao'tsu, the pet trainer, is a few steps north of him.", f={r={"Orc","Troll"}}, g={{"t",6081,n2="Ormak Grimshot: Beast Training",m=1454,x=66,y=18.5}}},
  {t="Yaw Sharpmane at Bloodhoof", lv=10, n="At 10 go to Yaw Sharpmane, who stands at the north edge of Bloodhoof Village. The Hunter's Path from Kary Thunderhorn in Thunder Bluff, Sian'dur in Orgrimmar or Thotar in Razor Hill also leads here, for a little experience; it is only a pointer.", f={r={"Tauren"}}, g={{"l",10,txt="Reach level 10"},{"a",6061,n2="Yaw Sharpmane: the first Taming Rod",m=1412,x=46.9,y=59.6,ml=10}}},
  {t="Adult Plainstrider", lv=10, n="Adult Plainstriders (level 6-7) walk the plains south-west and north-west of Bloodhoof Village. How the rod works: target a living beast, use the Taming Rod and stand still for the whole channel while it hits you; moving, fighting back or anyone else's help breaks it and costs one of the rod's few charges (out of charges: destroy the rod, abandon the quest, take it again). A plainstrider flees at 25% health, so do not damage it first. Keep each rod: it goes back to Yaw.", f={r={"Tauren"}}, g={{"o",6061,i=1,txt="Tame Adult Plainstrider",n2="Use the Taming Rod on a living plainstrider",m=1412,x=42.9,y=59.1},{"t",6061,m=1412,x=46.9,y=59.6},{"a",6087,m=1412,x=46.9,y=59.6,ml=10}}},
  {t="Prairie Stalker", lv=10, n="Dismiss the plainstrider first (right-click the pet portrait, Dismiss Pet): a released practice pet may attack you. Prairie Stalkers (level 7-8) roam the grass north of Bloodhoof Village.", f={r={"Tauren"}}, g={{"o",6087,i=1,txt="Tame Prairie Stalker",n2="Use the Taming Rod on a living stalker",m=1412,x=44.6,y=54.1},{"t",6087,m=1412,x=46.9,y=59.6},{"a",6088,m=1412,x=46.9,y=59.6,ml=10}}},
  {t="Swoop", lv=10, n="Dismiss the stalker. Swoops (level 7-9) glide over the plains north-west and north-east of Bloodhoof; the Taloned Swoops do not count. A Swoop's knockdown breaks the channel, but it lands only once per channel: start the rod just after it has used it.", f={r={"Tauren"}}, g={{"o",6088,i=1,txt="Tame Swoop",n2="Use the Taming Rod on a living Swoop",m=1412,x=45.5,y=54.6},{"t",6088,n2="Yaw Sharpmane: Tame Beast",m=1412,x=46.9,y=59.6},{"a",6089,m=1412,x=46.9,y=59.6,ml=10}}},
  {t="Holt Thunderhorn in Thunder Bluff", lv=10, n="Head north to Thunder Bluff and take a lift up. Holt Thunderhorn stands with the hunter trainers on Hunter Rise; Hesuwa Thunderhorn, the pet trainer, is nearby.", f={r={"Tauren"}}, g={{"t",6089,n2="Holt Thunderhorn: Beast Training",m=1456,x=57.3,y=89.8}}},
  {t="Elayaa Easewind", lv=10, n="At 10, Elayaa Easewind, a hunter trainer on Zephras Isle, may send you on to Valanaar with Taming the Beast. It is only a pointer: skip it if you are already in Valanaar.", f={r={"Skyborne"}}, g={{"l",10,txt="Reach level 10"},{"a",94007,m=2521,x=45.3,y=44.2,opt=true,ml=10}}},
  {t="Quel'ana Quickgale in Valanaar", lv=10, n="Quel'ana Quickgale stands with the trainers by Valanaar's west gate, Quel'dora Quickgale beside her.", f={r={"Skyborne"}}, g={{"t",94007,m=2521,x=59.6,y=72.6,opt=true},{"a",94978,n2="Quel'ana Quickgale: the first Taming Rod",m=2521,x=59.6,y=72.6,ml=10}}},
  {t="Windsong Crawler", lv=10, n="Windsong Crawlers live only by water: the nearest scuttle along the shore south-west of Valanaar, among the crabs. How the rod works: target a living crawler, use the Taming Rod and stand still for the whole channel while it hits you; moving, fighting back or anyone else's help breaks it and costs a charge. Killing one does not count.", f={r={"Skyborne"}}, g={{"o",94978,i=1,txt="Tame Windsong Crawler",n2="Use the Taming Rod on a living crawler",m=2521,x=53.8,y=77},{"t",94978,m=2521,x=59.6,y=72.6},{"a",94979,m=2521,x=59.6,y=72.6,ml=10}}},
  {t="Ornery Galestrider", lv=10, n="Dismiss the crawler first (right-click the pet portrait, Dismiss Pet). Ornery Galestriders graze in the Gustberry Lowlands, the fields a short walk west and south-west of Valanaar.", f={r={"Skyborne"}}, g={{"o",94979,i=1,txt="Tame Ornery Galestrider",n2="Use the Taming Rod on a living galestrider",m=2521,x=59.2,y=74},{"t",94979,m=2521,x=59.6,y=72.6},{"a",94013,m=2521,x=59.6,y=72.6,ml=10}}},
  {t="Vuldren Alpha", lv=10, n="Dismiss the galestrider. Vuldren Alphas hunt in the same Gustberry Lowlands, a little further south.", f={r={"Skyborne"}}, g={{"o",94013,i=1,txt="Tame Vuldren Alpha",n2="Use the Taming Rod on a living alpha",m=2521,x=59.7,y=72.7},{"t",94013,n2="Quel'ana Quickgale: Tame Beast",m=2521,x=59.6,y=72.6},{"a",94050,m=2521,x=59.6,y=72.6,ml=10},{"t",94050,n2="Quel'dora Quickgale, beside her: Beast Training",m=2521,x=59.9,y=72.9}}},
  {t="Your first pet", lv=10, n="Tame Beast works like the rod: a beast of your level or lower, a channel you must not move during, the beast hitting you all the while. A pet keeps the level you tame it at and levels up with you; it can never be above your level, so tame one close to yours. Each family has its own ability on Forever (a boar's Charge, for example). For levelling, a cat hits hardest (Claw and Bite) and a boar takes more punishment.", g={{"i",0,txt="Tame a beast of your level to keep",opt=true},{"i",0,txt="Near Razor Hill: Durotar Tigers (cats, level 7-8) roam the south of Durotar, from Sen'jin Village down the coast; Venomtail Scorpids (9-10) the north-west toward Orgrimmar; at 11-12, Savannah Huntresses (cats) prowl the plains around the Crossroads in the Barrens.",f={r={"Orc","Troll"}}},{"i",0,txt="Near Bloodhoof: Flatland Prowlers (cats, level 9) and Prairie Wolf Alphas (wolves, 9-10) roam the plains of northern Mulgore; at 11-12, Savannah Huntresses (cats) prowl around the Crossroads in the Barrens.",f={r={"Tauren"}}},{"i",0,txt="Near Valanaar: Vuldren Alphas (level 10), the beast of your last practice tame, hunt the Gustberry Lowlands; Shriekling Matriarchs (raptors, level 9) nest just west of Valanaar; Shadowgale Urseras (bears, 10-11) roam the north of Zephras Isle.",f={r={"Skyborne"}}},{"i",0,txt="Feed Pet: open your spellbook, cast Feed Pet and click a food your pet's family eats (the pet's tooltip lists them: cats eat meat and fish, boars almost anything). Raw meat looted from beasts counts. To buy: Grimtak the butcher and Innkeeper Grosk in Razor Hill sell meat, Kaga Mistrunner in Thunder Bluff and the innkeepers on Zephras Isle too; Bloodhoof's innkeeper and bakers sell bread. Food near the pet's level makes it happiest; much lower food gives about half. You cannot feed in combat."},{"i",0,txt="Happiness: the face on the pet frame. An unhappy pet does three quarters of its damage, a happy one a quarter more. Happiness drains slowly, faster when the pet dies; a pet left unhappy too long can run away."},{"i",0,txt="Loyalty grows with time and kills. Each loyalty rank raises the training points you spend in Beast Training (pet level times loyalty rank minus one)."},{"i",0,txt="Beast Training (spellbook, General tab) teaches your current pet the abilities you know. To learn a new ability or rank: leave your pet with a stable master (Shoja'my in Razor Hill, Seikwa at Bloodhoof, Genn Fairweather on Zephras Isle, Xon'cha in Orgrimmar), tame a beast that has it (its pet spellbook tab shows what it knows), use the ability in fights until the game says you learned it, then take your own pet back and teach it with Beast Training. A pet holds four active abilities at most."},{"i",0,txt="Pet trainers sell Growl ranks and resistances. Horde: Harruk in Razor Hill, Reban Freerunner at Bloodhoof, Xao'tsu in Orgrimmar's Valley of Honor, Hesuwa Thunderhorn on Thunder Bluff's Hunter Rise, Quel'dora Quickgale in Valanaar, later Grokor in Stonard and Zudd at Grom'gol."},{"i",0,txt="Call Pet, Dismiss Pet and Revive Pet are in your spellbook now; Mend Pet comes from your trainer at 12. A dead pet needs Revive Pet; one that is away more than about 100 yards is dismissed and comes back with Call Pet."}}},
} end)

R:Segment({id="class/hunter/the-hunters-charm",title="The Hunter's Charm",classes={"HUNTER"},min=50,max=52,zone=1447,zoneName="Azshara",why="Experience at 50 through Azshara and the Sunken Temple; Classic's item choice may be gone on Forever.",folder="Hunter"}, function() return {
  {t="The Hunter's Charm (Alliance)", lv=50, n="At 50 any Alliance hunter trainer offers it: Ulfir Ironbeard in Stormwind's Dwarven District, Olmin Burningbeard in Ironforge's Hall of Arms or Dorion in Darnassus' Cenarion Enclave.", f={fa={"Alliance"}}, g={{"l",50,txt="Reach level 50"},{"a",8151,m=1453,x=67.6,y=35.8,ml=50}}},
  {t="The Hunter's Charm (Horde)", lv=50, n="At 50 any Horde hunter trainer offers it: Ormak Grimshot in Orgrimmar's Valley of Honor or Holt Thunderhorn on Hunter Rise in Thunder Bluff.", f={fa={"Horde"}}, g={{"l",50,txt="Reach level 50"},{"a",8151,m=1454,x=66,y=18.5,ml=50}}},
  {t="Ogtinc", lv=50, n="Ogtinc lives on a raised spot on the cliffs at the north-east rim of the Ruins of Eldarath, west-central Azshara. Keep to the high ridges around the ruins: the pit below does not lead up to him. Alliance: fly to Talrendis Point; Horde: fly to Valormok, a short ride west of him.", g={{"fp",64,txt="Get the Talrendis Point flight path (Jarrodenus)",m=1447,x=11.9,y=77.6,f={fa={"Alliance"}}},{"fp",44,txt="Get the Valormok flight path (Kroum)",m=1447,x=22,y=49.6,f={fa={"Horde"}}},{"t",8151,m=1447,x=42.4,y=42.6},{"a",8153,m=1447,x=42.4,y=42.6,ml=50}}},
  {t="Courser Antlers", lv=50, n="You need two Perfect Courser Antlers. Mosshoof Coursers (level 52-53, deer) graze all over Azshara and drop one about one kill in twelve, so expect two dozen kills. Good herds: north of the Thalassian Base Camp in the north, and the hills north-east and south-east of Valormok; the Lake Mennar area also has elite giants and dragonkin. They Enrage at 30% health. Coursers share spawn points with the Thunderhead hippogryphs: if none are around, kill the hippogryphs and coursers may spawn instead. Respawn is about five and a half minutes.", g={{"o",8153,i=1,txt="Perfect Courser Antler x2",n2="Perfect Courser Antler, from Mosshoof Coursers",m=1447,x=52.1,y=35.4}}},
  {t="Ogtinc", lv=50, g={{"t",8153,m=1447,x=42.4,y=42.6},{"a",8231,m=1447,x=42.4,y=42.6,ml=50}}},
  {t="Wavethrashing", lv=50, n="You need six Wavethrasher Scales. Wavethrashers (three-headed sea beasts) live along Azshara's coasts, mostly underwater: the Young Wavethrashers (level 51-52) of the north-east shore drop a scale about one kill in three, the Wavethrashers (52-53) of the east coast by the Tower of Eldara about as often (a few walk the beach there), the Great Wavethrashers (53-54) of the south-east shore about one in seven. Track Beasts does not show them; fight them where you can breathe, and bring water breathing if you can. Elite sharks swim the deeper water.", g={{"o",8231,i=1,txt="Wavethrasher Scales x6",m=1447,x=84.6,y=30.9}}},
  {t="Ogtinc", lv=50, g={{"t",8231,m=1447,x=42.4,y=42.6},{"a",8232,m=1447,x=42.4,y=42.6,ml=50}}},
  {t="Morphaz in the Sunken Temple", lv=50, n="Morphaz is an elite green drake (level 52) inside the Sunken Temple, a five-player dungeon: needs a group of five. The temple stands in the Pool of Tears in eastern Swamp of Sorrows: climb its outer steps, dive into the flooded hall and follow the stairs down to the entrance. Horde: fly to Stonard; Alliance: fly to Nethergarde Keep or Darkshire and ride on. He is not there when you arrive: first kill the six troll guardians on the platforms around the upper ring, which opens the way down to Jammal'an the Prophet in the Pit of Sacrifice. Jammal'an's death brings out two drakes, Weaver and Dreamscythe (pull them one at a time); when both are dead, Morphaz and Hazzas appear together and cannot be split. Clear the dragonkin around the pit first, because they call for help. Morphaz uses Acid Breath and Wing Flap. The tooth always drops. Warriors in the group may want the same run for the voodoo feathers of the balcony trolls.", g={{"o",8232,i=1,txt="Tooth of Morphaz",n2="Tooth of Morphaz, inside the Sunken Temple",m=1435,x=69,y=54,grp=true}}},
  {t="The Green Drake", lv=50, n="In Classic Ogtinc let you choose the Devilsaur Eye, the Devilsaur Tooth or the Hunting Spear here. Forever's change notes say the choice is gone, though its quest page still lists three unnamed rewards: look at the reward window before you hand in.", g={{"t",8232,m=1447,x=42.4,y=42.6}}},
} end)

R:Segment({id="class/mage/arcane-refreshment",title="Conjure Water (Arcane Refreshment)",classes={"MAGE"},min=60,max=60,zone=1444,zoneName="Feralas",why="The level 60 Conjure Water, from a Dire Maul library: drink for you and your group.",spells={10140},spellNames={"Conjure Water"},folder="Mage"}, function() return {
  {t="Lorekeeper Lydros", lv=60, n="Fly to Feathermoon (Alliance) or Camp Mojache (Horde) and ride to Dire Maul in central Feralas. Lorekeeper Lydros waits in the Athenaeum, the library, reached through the West wing, or through the North wing's courtyard doors with a Crescent Key (it drops from the imp Pusillin in the East wing; a Powerful Seaforium Charge also opens them; Blink no longer gets past). Other mages in your group can take it too: share it.", g={{"l",60,txt="Reach level 60"},{"a",7463,m=1444,x=58,y=44.5,ml=60}}},
  {t="Hydrospawn", lv=60, n="Hydrospawn, a level 57 elite water elemental, lives in the Warpwood Quarter (Dire Maul East): chase the imp Pusillin until he turns to fight, clear the satyr room, then take the spiral ramp down to the pool. A group of five. Frost does nothing to him, so frost mages switch to fire or arcane. Riptide hits everyone within 10 yards, so ranged stand back; at a quarter health he calls Hydrolings. The essence always drops; he does not come back until the instance resets.", g={{"o",7463,i=1,txt="Hydrospawn Essence",n2="Hydrospawn Essence: Hydrospawn",m=1444,x=58,y=44.5,grp=true}}},
  {t="Back to Lydros", lv=60, g={{"t",7463,n2="Lorekeeper Lydros: Conjure Water, and 200 Shen'dralar reputation",m=1444,x=58,y=44.5}}},
} end)

R:Segment({id="class/mage/astral-knot-garment",title="Astral Knot Garment",faction="Alliance",classes={"MAGE"},min=26,max=30,zone=1453,zoneName="Stormwind City",why="A robe or a blouse for Alliance mages in their late 20s.",items={7511,9516},folder="Mage"}, function() return {
  {t="Bink (Ironforge)", lv=26, n="Bink teaches mages in Ironforge's Mystic Ward. Take the Deeprun Tram from Tinker Town to Stormwind afterwards.", f={r={"Gnome"}}, g={{"l",26,txt="Reach level 26"},{"a",1939,m=1455,x=27.2,y=8.3,ml=26}}},
  {t="Jennea Cannon (Stormwind)", lv=26, n="Jennea Cannon stands at the top of the Wizard's Sanctum, the violet tower of the Mage Quarter; the portal near the top of the spiral ramp takes you to her.", f={r={"Human"}}, g={{"l",26,txt="Reach level 26"},{"a",1939,m=1453,x=49.6,y=85.8,ml=26}}},
  {t="High Sorcerer Andromath (Skyborne)", lv=26, n="You do not need a letter: at 26 climb the Wizard's Sanctum, the violet tower of Stormwind's Mage Quarter. High Sorcerer Andromath waits on the spiral walkway, just past the door of the portal room near the top, and has the quest for you. (Jennea Cannon may also offer you High Sorcerer Andromath, the pointer quest; it is only a pointer and you can skip it.)", f={r={"Skyborne"}}, g={{"l",26,txt="Reach level 26"},{"a",1938,m=1453,x=48.7,y=87.6,ml=26}}},
  {t="High Sorcerer Andromath", lv=26, n="High Sorcerer Andromath waits on the spiral walkway of the Wizard's Sanctum, just past the door of the portal room as you walk down from the trainers.", f={r={"Human","Gnome"}}, g={{"t",1939,m=1453,x=48.7,y=87.6},{"a",1938,m=1453,x=48.7,y=87.6,ml=26}}},
  {t="The Tower of Ilgalar", lv=26, n="Head east through Elwynn Forest into Redridge, or fly to Lakeshire. The Tower of Ilgalar stands alone in the east of the zone. Climb to the very top floor (not the one below): the treatise is the book sticking out of the shelf where the stairs come up. Two gnoll dogs and a gnoll caster guard the shelf; the dogs' Mana Burn interrupts the click, so fight them on the stairs out of their sight. Morganth (level 26 elite) stands across the top floor: you do not need him, keep to the left edge of the ramp so he stays put. The book is back two seconds after anyone takes it. If you die, your ghost can run up and come back to life beside it.", g={{"o",1938,i=1,txt="Ur's Treatise on Shadow Magic",m=1433,x=73.8,y=47.6}}},
  {t="Back to Andromath", lv=26, g={{"t",1938,m=1453,x=48.7,y=87.6},{"a",1940,m=1453,x=48.7,y=87.6,ml=26}}},
  {t="Carrion Recluses", lv=26, n="Raven Hill Cemetery in western Duskwood: the six Carrion Recluses (level 25-26, green, Paralyzing Poison) walk the graves, the central statue and the riverbank, and every one drops a silk; they come back after 5 minutes. The Black Widow Hatchlings (24-25) on the slopes east of the cemetery drop it about one time in six, so mix them in while you wait. Mor'Ladim, a level 35 elite skeleton, walks the cemetery: watch for him.", g={{"o",1940,i=1,txt="Pristine Spider Silk x8",m=1431,x=20,y=41.2}}},
  {t="Wynne Larson", lv=26, n="Wynne Larson works at Larson Clothiers in the Mage Quarter. The robe gives intellect, stamina and spirit; the blouse more intellect and stamina but no spirit.", g={{"t",1940,m=1453,x=51.8,y=83.5},{"a",1942,m=1453,x=51.8,y=83.5,ml=26},{"t",1942,n2="Astral Knot Garment",m=1453,x=51.8,y=83.5}}},
} end)

R:Segment({id="class/mage/atiesh",title="Atiesh, Greatstaff of the Guardian",classes={"PRIEST","MAGE","WARLOCK","DRUID"},min=60,max=60,zone=1446,zoneName="Tanaris",why="The legendary staff of the Guardian: forty splinters from Naxxramas, two raid bosses and a demon in Stratholme.",items={22589,22631,22630,22632},folder="Raid"}, function() return {
  {t="Splinters of Atiesh", lv=60, n="Forty Splinters of Atiesh drop in Naxxramas, the 40-player raid in the necropolis over the Plaguewood in Eastern Plaguelands: each of its twelve bosses before Sapphiron and Kel'Thuzad, and the Four Horsemen's chest, drops one about a third of the time, and the raid shares them out. It takes many weeks of clears. Keep every splinter in one stack.", g={{"l",60,txt="Reach level 60"},{"h",22726,txt="Get Splinter of Atiesh x40",n=40,grp=true},{"i",0,txt="Use Splinter of Atiesh",n2="Forming Frame of Atiesh: forty splinters become the Frame of Atiesh"}}},
  {t="Anachronos", lv=60, n="Right-click the Frame of Atiesh to start the quest, then take it to Anachronos, the bronze dragon in elf form who stands outside the Caverns of Time in eastern Tanaris. Fly to Gadgetzan and ride east.", g={{"a",9250,ml=60},{"t",9250,m=1446,x=65.3,y=50},{"a",9251,m=1446,x=65.3,y=50,ml=60}}},
  {t="The Staff Head and the Base", lv=60, n="Two more raid bosses, a full 40-player raid each, both pieces always drop: the Staff Head of Atiesh from Kel'Thuzad on his throne at the top of Naxxramas, the Base of Atiesh from C'Thun at the bottom of the Temple of Ahn'Qiraj, behind the Gates of Ahn'Qiraj in southern Silithus. Each boss comes back once a week.", g={{"o",9251,i=1,txt="Staff Head of Atiesh",n2="Staff Head of Atiesh: Kel'Thuzad, Naxxramas",grp=true},{"o",9251,i=2,txt="Base of Atiesh",n2="Base of Atiesh: C'Thun, Temple of Ahn'Qiraj, past the Gate of Ahn'Qiraj",m=1451,x=29.1,y=93.6,grp=true}}},
  {t="Back to Anachronos", lv=60, g={{"t",9251,m=1446,x=65.3,y=50},{"a",9270,n2="your class's Atiesh quest; he hands you the befouled staff",m=1446,x=65.3,y=50,f={c={"MAGE"}},ml=60},{"a",9257,m=1446,x=65.3,y=50,f={c={"PRIEST"}},ml=60},{"a",9271,m=1446,x=65.3,y=50,f={c={"WARLOCK"}},ml=60},{"a",9269,m=1446,x=65.3,y=50,f={c={"DRUID"}},ml=60}}},
  {t="Atiesh, Hand of Sargeras", lv=60, n="Take the befouled staff to Stratholme, the dungeon at the north end of Eastern Plaguelands, through the main gate. On Festival Lane find the patch of Consecrated Earth with a small white flame on it, stand on it and use the staff: Atiesh, Hand of Sargeras (level 63 boss) steps out. Bring a strong group: his Unholy Aura hurts everyone and cannot be dispelled (shadow resistance helps), his Breath of Sargeras curse must be removed at once, and a warrior's Disarm makes him drop his sword, which a melee player can pick up and use against him. He stays up to two and a half hours, so you can regroup.", g={{"i",0,txt="Use Atiesh, Greatstaff of the Guardian",n2="the befouled staff, on the Consecrated Earth inside Stratholme",m=1423,x=21.8,y=6.2},{"o",9270,i=1,txt="Kill Atiesh",n2="Atiesh, Hand of Sargeras",m=1423,x=21.8,y=6.2,grp=true,f={c={"MAGE"}}},{"o",9257,i=1,txt="Kill Atiesh",m=1423,x=21.8,y=6.2,grp=true,f={c={"PRIEST"}}},{"o",9271,i=1,txt="Kill Atiesh",m=1423,x=21.8,y=6.2,grp=true,f={c={"WARLOCK"}}},{"o",9269,i=1,txt="Kill Atiesh",m=1423,x=21.8,y=6.2,grp=true,f={c={"DRUID"}}}}},
  {t="The Greatstaff", lv=60, n="Back to Anachronos at the Caverns of Time.", g={{"t",9270,n2="Anachronos: Atiesh, Greatstaff of the Guardian",m=1446,x=65.3,y=50,f={c={"MAGE"}}},{"t",9257,m=1446,x=65.3,y=50,f={c={"PRIEST"}}},{"t",9271,m=1446,x=65.3,y=50,f={c={"WARLOCK"}}},{"t",9269,m=1446,x=65.3,y=50,f={c={"DRUID"}}}}},
} end)

R:Segment({id="class/mage/celestial-orb",title="Celestial Orb and Stave",classes={"MAGE"},min=35,max=40,zone=1445,zoneName="Dustwallow Marsh",why="An off-hand orb or a staff for the late 30s, your pick.",items={7515,9517},folder="Mage"}, function() return {
  {t="Return to the Marsh (Stormwind)", lv=35, n="Jennea Cannon at the top of the Wizard's Sanctum, Stormwind's Mage Quarter, sends you back to Tabetha; Bink in Ironforge gives the same quest.", f={fa={"Alliance"}}, g={{"l",35,txt="Reach level 35"},{"a",1953,m=1453,x=49.6,y=85.8,ml=35}}},
  {t="Return to the Marsh (Orgrimmar)", lv=35, n="Deino, one of Orgrimmar's mage trainers in Darkbriar Lodge, sends you back to Tabetha; Anastasia Hartwell in the Undercity and Ursyn Ghull in Thunder Bluff give the same quest.", f={fa={"Horde"}}, g={{"l",35,txt="Reach level 35"},{"a",1953,m=1454,x=38.5,y=86.1,ml=35}}},
  {t="Tabetha", lv=35, n="Tabetha's cottage is deep in the marsh west of Theramore, just north of the Stonemaul Ruins; come in from the west road, the elites roam its east side.", g={{"t",1953,m=1445,x=46.1,y=57.1},{"a",1954,m=1445,x=46.1,y=57.1,ml=35}}},
  {t="The Infernal Orb", lv=35, n="The Burning Blade Summoners (level 38-39, not elite) work the Mannoroc Coven in southern Desolace, east of Shadowprey Village, and every one carries an Infernal Orb. They cast Shadow Bolt from 40 yards, keep an imp at their side and run for help at low health; Nether Maidens patrol the pillared ruin beside them, so pull with care. Horde mages: one more summoner stands alone in western Mulgore, south-west of Thunder Bluff.", g={{"o",1954,i=1,txt="Infernal Orb",n2="Infernal Orb: Burning Blade Summoner",m=1443,x=66.5,y=77.9}}},
  {t="The Exorcism", lv=38, n="Back at Tabetha's. Hand in the orb now; The Exorcism waits for level 38. Kill the critters around the cottage first: they join the fight. Accepting The Exorcism starts a 3 minute timer, and Tabetha calls the Demon of the Orb out in her garden: a level 40 elite that resists many spells, roots and slows. Grouping up is encouraged: a mage of 40 may need help or potions, at about 45 it is soloable. You can pull it from range from the dock. The timer keeps running after it dies, so hand the quest in straight away. If time runs out, abandon the quest and take it again; she calls the demon again.", g={{"t",1954,m=1445,x=46.1,y=57.1},{"l",38,txt="Reach level 38"},{"a",1955,m=1445,x=46.1,y=57.1,ml=35},{"o",1955,i=1,txt="Kill Demon of the Orb",n2="Demon of the Orb (elite, 40)",m=1445,x=45.8,y=57,grp=true},{"t",1955,m=1445,x=46.1,y=57.1},{"a",1956,m=1445,x=46.1,y=57.1,ml=35}}},
  {t="Power in Uldaman", lv=40, n="Uldaman is a dungeon in the northern Badlands: a group of five, from level 40 here. Go in by the rear entrance, a cave in Dustwind Gulch south-east of the main entrance (elite dragons fly nearby): the Obsidian Sentinel (level 42 elite) stands just past the first door. At 80, 60, 40 and 20 percent it breaks off an Obsidian Shard, an elite too; while a shard lives, both reflect targeted spells, so use area spells and your wand on them. A solo trick: step out through the nearby zone line each time a shard appears; the Sentinel heals but keeps shrinking. It always drops the power source, and takes 2 hours to come back.", g={{"l",40,txt="Reach level 40"},{"o",1956,i=1,txt="Obsidian Power Source",n2="Obsidian Power Source: Obsidian Sentinel",m=1418,x=49.1,y=13.7,grp=true}}},
  {t="Mana Surges", lv=40, n="Back to Tabetha. Accepting Mana Surges opens a rift beside her cottage and starts a 10 minute timer: twelve Mana Surges (level 40, Shock and Lightning Bolt) come out about four at a time. Attacking one does not pull the rest. Standing at the edge of the field draws them all; the tree south-west of it is out of their reach but in your spell range. Kill twelve and hand in before the timer runs out.", g={{"t",1956,m=1445,x=46.1,y=57.1},{"a",1957,m=1445,x=46.1,y=57.1,ml=35},{"o",1957,i=1,txt="Kill Mana Surge x12",m=1445,x=45.8,y=56.9},{"t",1957,m=1445,x=46.1,y=57.1},{"a",1958,m=1445,x=46.1,y=57.1,ml=35},{"t",1958,n2="Celestial Power: the Celestial Orb (off-hand) or the Celestial Stave",m=1445,x=46.1,y=57.1}}},
  {t="Tabetha's Task (optional)", lv=40, n="At 40 the mage trainers who send you to Tabetha (Jennea Cannon, Bink, Anastasia Hartwell, Deino) also have Tabetha's Task, a quest any class can do. Tabetha then wants the Tiara of the Deep from Hydromancer Velratha, a level 46 elite naga in Zul'Farrak, the troll dungeon in north-western Tanaris: a group of five, level 44-54. The reward window shows the Spellshifter Rod and the Gemshale Pauldrons.", g={{"l",40,txt="Reach level 40"},{"a",2861,m=1454,x=38.5,y=86.1,opt=true,ml=40},{"t",2861,m=1445,x=46.1,y=57.1,opt=true},{"a",2846,m=1445,x=46.1,y=57.1,opt=true,grp=true,ml=40}}},
  {t="Tiara of the Deep in Zul'Farrak", lv=40, n="Zul'Farrak, the troll dungeon in north-western Tanaris, needs a group of five; the guide waits for level 44. Hydromancer Velratha is one of the bosses by the sacred pool, and the tiara always drops.", w={{k="onquest",q={2846}}}, g={{"l",44,txt="Reach level 44"},{"o",2846,i=1,txt="Tiara of the Deep",n2="Tiara of the Deep: Hydromancer Velratha, Zul'Farrak",m=1446,x=38.7,y=20,grp=true},{"t",2846,m=1445,x=46.1,y=57.1,grp=true}}},
} end)

R:Segment({id="class/mage/destroy-morphaz",title="Destroy Morphaz",classes={"MAGE"},min=50,max=54,zone=1447,zoneName="Azshara",why="Experience at 50 through Azshara and the Sunken Temple; Classic's item choice may be gone on Forever.",folder="Mage"}, function() return {
  {t="Magecraft (Stormwind)", lv=50, n="Maginor Dumas, the Master Mage, stands in the Wizard's Sanctum in Stormwind's Mage Quarter; Dink in Ironforge gives the same quest.", f={fa={"Alliance"}}, g={{"l",50,txt="Reach level 50"},{"a",8250,m=1453,x=49.2,y=87.8,ml=50}}},
  {t="Magecraft (Orgrimmar)", lv=50, n="Uthel'nay, one of Orgrimmar's mage trainers in Darkbriar Lodge, gives it; so do Pierce Shackleton in the Undercity and Archmage Shymm in Thunder Bluff.", f={fa={"Horde"}}, g={{"l",50,txt="Reach level 50"},{"a",8250,m=1454,x=39.2,y=86.3,ml=50}}},
  {t="Sanath Lim-yo", lv=50, n="Fly to Talrendis Point (Alliance) or Valormok (Horde). Sanath Lim-yo camps below his master's tower, a short way east of Valormok: from the fork of Azshara's main road at the Ruins of Eldarath, head straight north to the cliffs. Get off your mount before he teleports you up, or the teleport may not take you. A trail with no enemies climbs to Archmage Xylem at the top of the tower; an attendant at the top sends you back down, as often as you like.", g={{"t",8250,m=1447,x=28.1,y=50.1},{"a",8251,n2="Archmage Xylem, in the tower",m=1447,x=29.2,y=40.2,ml=50}}},
  {t="Glittering Dust", lv=50, n="The blood elves hold the Thalassian Base Camp on the hills of north-eastern Azshara. Blood Elf Surveyors (51-52, Fire Nova up close) and Reclaimers (52-53, Fireball, and they heal and Renew each other) each drop the dust about one time in four; they spot you from far off, so pull at the edges. They come back after 5 1/2 minutes.", g={{"o",8251,i=1,txt="Glittering Dust x10",m=1447,x=55.5,y=29.5}}},
  {t="Archmage Xylem", lv=50, n="Back to Sanath Lim-yo, who teleports you up to the tower.", g={{"t",8251,m=1447,x=29.2,y=40.2},{"a",8252,m=1447,x=29.2,y=40.2,ml=50}}},
  {t="Enchanted Coral", lv=50, n="The Spitelash Sirens (level 50-52) walk the ruins and beaches around the Ruins of Eldarath and the bay east of Valormok, often three together, and a few stand inside the Temple of Zin-Malor; each drops a coral about one time in four. The Spitelash Screamers look almost the same but never drop it. Killing the other naga there makes more Sirens appear in their spots. Lingering Highborne ghosts wander the ruins: watch your back.", g={{"o",8252,i=1,txt="Enchanted Coral x6",n2="Enchanted Coral: Spitelash Siren",m=1447,x=36.3,y=48}}},
  {t="Archmage Xylem again", lv=50, n="Back to Sanath Lim-yo and up to the tower.", g={{"t",8252,m=1447,x=29.2,y=40.2},{"a",8253,m=1447,x=29.2,y=40.2,ml=50}}},
  {t="Morphaz", lv=50, n="The Temple of Atal'Hakkar, the Sunken Temple, lies in the Pool of Tears: climb the steps into the sunken building, swim down through it and follow the passage down to the portal. A group of five, level 50-54. Morphaz is not waiting when you arrive. First kill the six troll guardians (elites of 50-52) on the platforms around the upper ring; that opens the way down (the left-hand ramp from the entrance) to Jammal'an the Prophet and Ogom the Wretched in the Pit of Sacrifice. Once Jammal'an dies, two green drakes, Weaver and Dreamscythe, come out and patrol the pit: pull them one at a time. When both are dead, Morphaz (level 52 elite, Acid Breath and Wing Flap) and Hazzas appear together and cannot be split, so fight both. The shard always drops. Hunters, Priests and Rogues of 50 need Morphaz too: a group of them shares one clear.", g={{"o",8253,i=1,txt="Arcane Shard",n2="Arcane Shard: Morphaz",m=1435,x=69.9,y=53.6,grp=true}}},
  {t="The Arcane Shard", lv=50, n="Back to Azshara, Sanath Lim-yo and the tower. Look at the reward window before you hand in: Classic offered the Arcane Crystal Pendant, the Fire Ruby or the Glacial Spike, and Forever's notes say the choice may be gone.", g={{"t",8253,m=1447,x=29.2,y=40.2}}},
} end)

R:Segment({id="class/mage/ju-ju-heaps",title="Ley or Arcane Staff or Orb (Horde)",faction="Horde",classes={"MAGE"},min=10,max=12,zone=1411,zoneName="Durotar",why="A staff or an off-hand orb at 10: Orcs and Trolls on the Echo Isles, the Undead at a Tirisfal farm.",items={7508,9513,7507,9514},folder="Mage"}, function() return {
  {t="Un'thuwa", lv=10, n="Un'thuwa, the troll mage trainer, stands in Sen'jin Village on the Durotar coast south of Razor Hill. Orcs coming from Orgrimmar can take Speak with Un'thuwa from Uthel'nay in the Valley of Spirits first; it is only a pointer and Un'thuwa gives Ju-Ju Heaps without it. Taking it shuts out the Undercity's Balnir Farmstead.", f={r={"Orc","Troll"}}, g={{"l",10,txt="Reach level 10"},{"a",1884,n2="Un'thuwa",m=1411,x=56.3,y=75.1,ml=10}}},
  {t="Cain Firesong (Brill)", lv=10, n="At 10 Cain Firesong, the Brill mage trainer upstairs in the Gallows' End Tavern, sends you to Anastasia Hartwell in the Undercity. Taking it shuts out Ju-Ju Heaps; if Speak with Un'thuwa (from Orgrimmar or Thunder Bluff) is in your log, abandon it first or Cain cannot give you this one. (A Troll who took this one in Brill follows the Balnir steps; an Undead who took Ju-Ju Heaps in Sen'jin, the Echo Isles steps.)", f={r={"Scourge"}}, g={{"l",10,txt="Reach level 10"},{"a",1881,m=1420,x=62,y=52.5,ml=10}}},
  {t="The Ju-Ju Heaps", lv=10, n="Wade across the shallows south-east of Sen'jin to the main Echo Isle, where Zalazane (level 10) holds his camp with Hexed and Voodoo Trolls (level 8). The heaps you can click are the skull piles inside the raised huts around his camp, one hut holding two, more in the huts to the north; the skulls lying on the ground outside cannot be clicked. Destroy four. There are seven and each comes back 30 seconds after it is destroyed.", w={{k="onquest",q={1884}}}, f={r={"Orc","Troll","Scourge"}}, g={{"o",1884,i=1,txt="Ju-Ju Heap",n2="Ju-Ju Heap, four of them",m=1411,x=67.8,y=84.3}}},
  {t="Back to Un'thuwa", lv=10, n="The orb is an off-hand for a one-hand weapon; the staff is a two-hander.", w={{k="onquest",q={1884}}}, f={r={"Orc","Troll","Scourge"}}, g={{"t",1884,n2="Un'thuwa: Ley Orb or Ley Staff",m=1411,x=56.3,y=75.1}}},
  {t="Anastasia Hartwell", lv=10, n="Walk south from Brill to the Ruins of Lordaeron and take the lift down into the Undercity. Anastasia stands in the Magic Quarter, the north-east ring of the city.", w={{k="onquest",q={1881}}}, f={r={"Scourge","Troll"}}, g={{"t",1881,m=1458,x=85.1,y=10},{"a",1882,m=1458,x=85.1,y=10,ml=10}}},
  {t="The Balnir Farmstead", lv=10, n="The Balnir Farmstead lies south-east of Brill, south of the road east to the Bulwark. The snapdragons grow in the farm's garden and look more like bushes than flowers; any of them will do and you need no Herbalism. They come back within seconds.", w={{k="onquest",q={1882}}}, f={r={"Scourge","Troll"}}, g={{"o",1882,i=1,txt="Balnir Snapdragons",m=1420,x=77.5,y=61.9}}},
  {t="Back to Anastasia", lv=10, w={{k="onquest",q={1882}}}, f={r={"Scourge","Troll"}}, g={{"t",1882,n2="Anastasia Hartwell: Arcane Orb or Arcane Staff",m=1458,x=85.1,y=10}}},
} end)

R:Segment({id="class/mage/mages-wand",title="Mage's Wand",classes={"MAGE"},min=30,max=40,zone=1445,zoneName="Dustwallow Marsh",why="A wand of your school for the 30s: frost, arcane or fire.",items={7514,11263,7513},folder="Mage"}, function() return {
  {t="Journey to the Marsh (Stormwind)", lv=30, n="Jennea Cannon at the top of the Wizard's Sanctum, Stormwind's Mage Quarter, sends you to Tabetha; Bink in Ironforge gives the same quest.", f={fa={"Alliance"}}, g={{"l",30,txt="Reach level 30"},{"a",1947,m=1453,x=49.6,y=85.8,ml=30}}},
  {t="Journey to the Marsh (Orgrimmar)", lv=30, n="Deino, one of Orgrimmar's mage trainers in Darkbriar Lodge, sends you to Tabetha; Anastasia Hartwell in the Undercity and Ursyn Ghull in Thunder Bluff give the same quest.", f={fa={"Horde"}}, g={{"l",30,txt="Reach level 30"},{"a",1947,m=1454,x=38.5,y=86.1,ml=30}}},
  {t="Tabetha", lv=30, n="Tabetha, a hermit, lives in a cottage deep in the marsh west of Theramore, just north of the Stonemaul Ruins. Level 38-41 elites roam the east side of her farm, and swimming in passes level 42 Muckshells: come in from the west along the road from the Barrens. Her cottage is no refuge: mobs follow you inside. Take both her quests.", g={{"t",1947,m=1445,x=46.1,y=57.1},{"a",1949,m=1445,x=46.1,y=57.1,ml=30},{"a",1948,m=1445,x=46.1,y=57.1,ml=30}}},
  {t="Magus Tirth", lv=30, n="Magus Tirth spends his days at the race track in the Shimmering Flats, south-east Thousand Needles.", g={{"t",1949,m=1441,x=78.3,y=75.7},{"a",1950,m=1441,x=78.3,y=75.7,ml=30}}},
  {t="\"Plucky\" Johnson", lv=30, n="Tirth's apprentice is \"Plucky\" Johnson, a small grey chicken pecking around the foot of the race track's lookout tower; at night type /target plucky. Target him and type /beckon (not /chicken or /wave): he turns human for a moment. Talk to him and ask for the phrase. Do not attack him. If he is gone, he is back within 5 minutes.", g={{"c",1950,txt="\"Plucky\" Johnson",n2="\"Plucky\" Johnson",m=1441,x=79.6,y=75.6},{"t",1950,m=1441,x=78.3,y=75.7},{"a",1951,m=1441,x=78.3,y=75.7,ml=30}}},
  {t="Witherbark trolls and the Bolt Charged Bramble", lv=30, n="The Witherbark trolls (level 30-36) hold the villages in south-eastern Arathi and south of Hammerfall; every kind of them drops a Witherbark Totem Stick about two times in five: you need ten. Then go to the Circle of Outer Binding (the outer one, not the Inner circle). Three elementals (level 33-39) stand around its middle stone: pull them one at a time and clear them first. Stand at the middle stone and use a totem stick; about ten seconds later the Bolt Charged Bramble forms on the stone: click it. If you die before you pick it up, the bramble and the sticks are lost and you need ten more.", g={{"h",7273,txt="Get Witherbark Totem Stick x10",m=1417,x=42.9,y=45.7,n=10},{"o",1948,i=2,txt="Use Witherbark Totem Stick",n2="at the middle stone of the Circle of Outer Binding",m=1417,x=52,y=50.7},{"o",1948,i=2,txt="Bolt Charged Bramble",m=1417,x=52,y=50.7}}},
  {t="Jade", lv=30, n="Tabetha also wants one Jade, a green gem. Miners sometimes find one in ore veins; the Auction House sells it; the Torn Fin Coastrunners on the coast south-west of Southshore drop one about every fifth kill. Do not sell it to a vendor by mistake.", g={{"o",1948,i=1,txt="Jade",m=1417,x=54.3,y=50.4}}},
  {t="Rituals of Power", lv=30, n="Tirth sold the book to the Scarlet Crusade. The Scarlet Monastery stands in north-eastern Tirisfal Glades; take the Library wing with a group of five. The book is in the last long hallway, the one that ends in Arcanist Doan's round room: on the left-hand shelf as you face his room, next to the Compendium of the Fallen. Take the thick, highlighted blue book sticking out of the shelf; a magnifying-glass cursor means a book you can only read.", g={{"o",1951,i=1,txt="Rituals of Power",n2="Rituals of Power: Scarlet Monastery Library",m=1420,x=82.6,y=33.8}}},
  {t="Tabetha's ritual", lv=30, n="Back to Tabetha. With both quests handed in she starts the ritual: wait a few seconds, then talk to her again and pick your wand: Icefury (frost), Nether Force (arcane) or Ragefire (fire).", g={{"t",1951,m=1445,x=46.1,y=57.1},{"t",1948,m=1445,x=46.1,y=57.1},{"a",1952,m=1445,x=46.1,y=57.1,ml=30},{"t",1952,n2="Mage's Wand",m=1445,x=46.1,y=57.1}}},
} end)

R:Segment({id="class/mage/manaweave-robe",title="Manaweave Robe",faction="Alliance",classes={"MAGE"},min=15,max=17,zone=1453,zoneName="Stormwind City",why="A robe at 15 for Alliance mages, from Stormwind and Loch Modan.",items={7509},folder="Mage"}, function() return {
  {t="Zaldimar Wefhellt (Goldshire)", lv=15, n="Zaldimar Wefhellt is the Goldshire mage trainer, upstairs in the Lion's Pride Inn.", f={r={"Human","Skyborne"}}, g={{"l",15,txt="Reach level 15"},{"a",1919,m=1429,x=43.2,y=66.2,ml=15}}},
  {t="Dink (Ironforge)", lv=15, n="Dink teaches mages in Ironforge's Mystic Ward. Take the Deeprun Tram from Tinker Town to Stormwind afterwards.", f={r={"Gnome"}}, g={{"l",15,txt="Reach level 15"},{"a",1919,m=1455,x=27.2,y=8.6,ml=15}}},
  {t="Jennea Cannon", lv=15, n="Jennea Cannon stands at the top of the Wizard's Sanctum, the violet tower of the Mage Quarter: climb the spiral ramp and take the portal near the top. The Chest of Containment Coffers and the Cantation of Manifestation lie on the table behind her (both come back 5 minutes after someone takes them). You hand both in at the end, so keep them.", g={{"t",1919,m=1453,x=49.6,y=85.8},{"a",1920,m=1453,x=49.6,y=85.8,ml=15},{"o",1920,i=2,txt="Chest of Containment Coffers",m=1453,x=49.5,y=85.5},{"o",1920,i=3,txt="Cantation of Manifestation",m=1453,x=49.6,y=85.4}}},
  {t="The Blue Recluse", lv=15, n="The Blue Recluse is the tavern in the Mage Quarter. Read the Cantation of Manifestation inside to make the invisible Rift Spawns (level 16-17) show: in the basement it brings out one, on the balcony or in the kitchen two, in the main room or by the door three, so read it downstairs. They hit hard and break out of Frost Nova fast. Beat one down: it does not die but sits stunned with a spiral over its head; use the Chest of Containment Coffers on it while it is stunned, then click the Filled Containment Coffer it leaves on the floor (clicking before it appears wastes a charge). You need three, and the cantation works only once every 5 minutes (logging out does not reset it), so plan on three rounds.", g={{"i",0,txt="Use Cantation of Manifestation",m=1453,x=51.3,y=93.3,opt=true},{"i",0,txt="Kill Rift Spawn",n2="Rift Spawn, down to the stun",m=1453,x=51.3,y=93.3,opt=true},{"i",0,txt="Use Chest of Containment Coffers",n2="Chest of Containment Coffers, on the stunned Rift Spawn",m=1453,x=51.3,y=93.3,opt=true},{"o",1920,i=1,txt="Filled Containment Coffer x3",m=1453,x=51.3,y=93.3}}},
  {t="Back to Jennea Cannon", lv=15, g={{"t",1920,m=1453,x=49.6,y=85.8},{"a",1921,m=1453,x=49.6,y=85.8,ml=15}}},
  {t="Linen Cloth", lv=15, n="Any humanoid drops Linen Cloth, and the Tunnel Rats in the Silver Stream Mine drop it while you gather the gems; the Auction House in the Trade District sells it. You hand in ten.", g={{"o",1921,i=1,txt="Linen Cloth x10",m=1453,x=49.8,y=85.8}}},
  {t="The Silver Stream Mine", lv=15, n="Take the Deeprun Tram to Ironforge, then the road east through the South Gate tunnel into Loch Modan. The Silver Stream Mine is at the north end of the loch, north of Thelsamar; Tunnel Rat kobolds hold it. The gems come only from the tall stacked Miners' League Crates (the cursor shows a cog over them; single boxes hold nothing): every crate gives one, there are fourteen and they come back after 3 to 5 minutes. You may have to go as deep as the end chamber for six. The same crates serve the dwarves' Filthy Paws quest.", g={{"o",1921,i=2,txt="Charged Rift Gem x6",n2="Charged Rift Gem: Miners' League Crates",m=1432,x=35.5,y=24.3}}},
  {t="Wynne Larson", lv=15, n="Back to Stormwind by the tram. Wynne Larson works at Larson Clothiers in the Mage Quarter.", g={{"t",1921,m=1453,x=51.8,y=83.5},{"a",1941,m=1453,x=51.8,y=83.5,ml=15},{"t",1941,n2="Wynne Larson: Manaweave Robe",m=1453,x=51.8,y=83.5}}},
} end)

R:Segment({id="class/mage/nether-lace-garment",title="Nether-lace Garment",faction="Horde",races={"Orc","Scourge","Troll"},classes={"MAGE"},min=26,max=30,zone=1454,zoneName="Orgrimmar",why="A robe or a tunic for Horde mages in their late 20s.",items={7512,9515},folder="Mage"}, function() return {
  {t="Anastasia Hartwell", lv=26, n="Anastasia Hartwell stands in the Undercity's Magic Quarter. Orcs and Trolls use Teleport: Undercity or take the zeppelin from Orgrimmar to Tirisfal Glades for her.", g={{"l",26,txt="Reach level 26"},{"a",1943,m=1458,x=85.1,y=10,ml=26}}},
  {t="Deino", lv=26, n="Take the zeppelin to Orgrimmar (or use Teleport: Orgrimmar, which lands you on the upper floor of Darkbriar Lodge). Deino stands with the mage trainers on the lower floor of Darkbriar Lodge in the Valley of Spirits. She hands you Deino's Flask.", g={{"t",1943,m=1454,x=38.5,y=86.1},{"a",1944,m=1454,x=38.5,y=86.1,ml=26}}},
  {t="The Xavian Waterfall", lv=26, n="Fly to Splintertree Post and swim north up the river past the big lake to its far northern end, where the zone text reads Xavian; satyrs hold the ruins around it and a few river beasts are in the way. Swim right in under the highest waterfall until you touch the rock wall, then use the flask (you can stay in the water). The waterfalls on the western Falfarren fork do not work.", g={{"o",1944,i=1,txt="Use Deino's Flask",n2="Deino's Flask, under the falls",m=1440,x=76.3,y=41.5},{"o",1944,i=1,txt="Xavian Water Sample",m=1440,x=76.3,y=41.5}}},
  {t="Back to Deino", lv=26, g={{"t",1944,m=1454,x=38.5,y=86.1},{"a",1945,m=1454,x=38.5,y=86.1,ml=26}}},
  {t="The Laughing Sisters", lv=26, n="The Laughing Sisters, dryads of level 24-25, roam around the Raynewood Retreat in central Ashenvale; every one drops a hair and they come back after 5 minutes. They often resist fire (and some frost and shadow): arcane spells land best. Each runs for help at low health. Keep clear of the guards by the white tower of the retreat, who hit hard.", g={{"o",1945,i=1,txt="Laughing Sister's Hair x12",m=1440,x=59.9,y=54.4}}},
  {t="Kil'hala", lv=26, n="Kil'hala, a troll tailor, works at the Crossroads. The robe gives intellect, stamina and spirit; the tunic more intellect and stamina but no spirit.", g={{"t",1945,m=1413,x=52.2,y=31.7},{"a",1946,m=1413,x=52.2,y=31.7,ml=26},{"t",1946,n2="Nether-lace Garment",m=1413,x=52.2,y=31.7}}},
} end)

R:Segment({id="class/mage/polymorph-pig",title="Polymorph: Pig",classes={"MAGE"},min=60,max=60,zone=1447,zoneName="Azshara",why="A new look for Polymorph: it turns the target into a pig rather than a sheep.",spells={28272},spellNames={"Polymorph: Pig"},folder="Mage"}, function() return {
  {t="Xylem's tower", lv=60, n="Fly to Talrendis Point (Alliance) or Valormok (Horde). Sanath Lim-yo camps below Archmage Xylem's tower, a short way east of Valormok: from the fork of Azshara's main road at the Ruins of Eldarath, head straight north to the cliffs. Dismount, and he teleports you up; a trail climbs to the Archmage at the top of the tower.", g={{"l",60,txt="Reach level 60"},{"a",9362,m=1447,x=29.2,y=40.2,ml=60}}},
  {t="Warlord Krellian", lv=60, n="Warlord Krellian (level 55, not elite, Strike and Demoralizing Roar) hides behind his Spitelash guards in the Temple of Zin-Malor, the biggest building in the middle of the Ruins of Eldarath. He always drops the Prismatic Shell and is back 5 1/2 minutes after a kill. Leave any raid group first: a raid gets no credit, a party is fine.", g={{"o",9362,i=1,txt="Prismatic Shell",n2="Prismatic Shell: Warlord Krellian",m=1447,x=41,y=53}}},
  {t="Archmage Xylem", lv=60, n="Back to Sanath Lim-yo and up to the tower. Xylem hands the shell back with the next quest: keep it in your bags.", g={{"t",9362,m=1447,x=29.2,y=40.2},{"a",9364,m=1447,x=29.2,y=40.2,ml=60}}},
  {t="Polymorph Clones", lv=60, n="Back to the Ruins of Eldarath, full of Spitelash naga. Cast your sheep Polymorph (the turtle one does nothing) on a naga and wait a few seconds: it splits into two to six Polymorph Clones of about 150 health that run off fast. Stand next to the sheep and hit them the moment they appear with Frost Nova and Arcane Explosion. Fifty clones are needed, so it takes a while; not in a raid group.", g={{"o",9364,i=1,txt="Kill Polymorph Clone x50",m=1447,x=29.9,y=53.5}}},
  {t="Fragmented Magic", lv=60, n="Back to Sanath Lim-yo and up to the tower.", g={{"t",9364,n2="Archmage Xylem: Polymorph (pig)",m=1447,x=29.2,y=40.2}}},
} end)

R:Segment({id="class/mage/spellfire-robes",title="Spellfire Robes",faction="Horde",classes={"MAGE"},min=15,max=18,zone=1458,zoneName="Undercity",why="A robe at 15 for Horde mages, from the Undercity and Silverpine Forest.",items={7510},folder="Mage"}, function() return {
  {t="Uthel'nay (Orgrimmar)", lv=15, n="Uthel'nay is one of Orgrimmar's mage trainers, in Darkbriar Lodge in the Valley of Spirits. Then take the zeppelin to Tirisfal Glades from the tower outside Orgrimmar's main gate.", f={r={"Orc","Troll"}}, g={{"l",15,txt="Reach level 15"},{"a",1959,m=1454,x=39.2,y=86.3,ml=15}}},
  {t="Cain Firesong (Brill)", lv=15, n="Cain Firesong is the Brill mage trainer, upstairs in the Gallows' End Tavern: take the stairs inside, the arrow cannot tell the floors apart.", f={r={"Scourge"}}, g={{"l",15,txt="Reach level 15"},{"a",1959,m=1420,x=62,y=52.5,ml=15}}},
  {t="Anastasia Hartwell", lv=15, n="Anastasia Hartwell stands in the Magic Quarter. The Chest of Containment Coffers and the Cantation of Manifestation lie on the ledge behind her (both come back 5 minutes after someone takes them). You hand both in at the end, so keep them.", g={{"t",1959,m=1458,x=85.1,y=10},{"a",1960,m=1458,x=85.1,y=10,ml=15},{"o",1960,i=2,txt="Chest of Containment Coffers",m=1458,x=85.5,y=9.9},{"o",1960,i=3,txt="Cantation of Manifestation",m=1458,x=85.7,y=10.2}}},
  {t="The alchemist shop", lv=15, n="Algernon's alchemist shop is in the Apothecarium. Stand on the steps or the bridge outside the shop and read the Cantation of Manifestation: up to four invisible Rift Spawns (level 16-17) appear and attack at once, and the city guards do not help. Hit one with a single-target spell and back off over the bridge: the others give up and fade, the one you hit follows. Beat it down on the shop's half of the bridge (past halfway the coffer will not work on it) until it stops fighting and sits stunned under a spiral, use the Chest of Containment Coffers on it, then click the Filled Containment Coffer once it appears on the floor (clicking too early wastes a charge). Three are needed.", g={{"i",0,txt="Use Cantation of Manifestation",m=1458,x=53.2,y=74.5,opt=true},{"i",0,txt="Kill Rift Spawn",n2="Rift Spawn, down to the stun",m=1458,x=53.3,y=74.6,opt=true},{"i",0,txt="Use Chest of Containment Coffers",n2="Chest of Containment Coffers, on the stunned Rift Spawn",m=1458,x=53.2,y=74.5,opt=true},{"o",1960,i=1,txt="Filled Containment Coffer x3",m=1458,x=53.2,y=74.5}}},
  {t="Back to Anastasia Hartwell", lv=15, g={{"t",1960,m=1458,x=85.1,y=10},{"a",1961,m=1458,x=85.1,y=10,ml=15}}},
  {t="Ambermill", lv=15, n="Leave the Undercity and follow the road south through Silverpine Forest. Every Dalaran human drops a Dalaran Mana Gem four times in five, and Linen Cloth too: the easiest are the Dalaran Apprentices (level 13-14, Frostbolt) on the hills south-east of the Sepulcher, either side of the road south; deeper in, the walled town of Ambermill in south-east Silverpine has Watchers (18-19, Fire Shield and Flamestrike) and Wizards (19-20, Frost Nova) that come back every 4 1/2 minutes and run for help at low health, so pull at the edge. Ten Linen Cloth also come from any humanoid or the Undercity Auction House.", g={{"o",1961,i=2,txt="Dalaran Mana Gem x6",m=1421,x=52.2,y=64.5},{"o",1961,i=1,txt="Linen Cloth x10",m=1421,x=51.6,y=64.3}}},
  {t="Josef Gregorian", lv=15, n="Back to the Undercity. Josef Gregorian, Victor Ward and Rhiannon Davis keep the tailor's shop in the Magic Quarter. Hand the gems and cloth to Josef and let the three of them talk for a moment; then Josef offers Spellfire Robes: take it and hand it straight back to him for the robe.", g={{"t",1961,m=1458,x=70.8,y=30.7},{"a",1962,m=1458,x=70.8,y=30.7,ml=15},{"t",1962,n2="Lesser Spellfire Robes",m=1458,x=70.8,y=30.7}}},
} end)

R:Segment({id="class/mage/staff-or-orb-alliance",title="Ley or Arcane Staff or Orb (Alliance)",faction="Alliance",classes={"MAGE"},min=10,max=15,zone=1429,zoneName="Elwynn Forest",why="A staff or an off-hand orb at 10 from your home town's mage trainer; Skyborne add a wand.",items={7508,9513,7507,9514,263430},folder="Mage"}, function() return {
  {t="Anathamaas Aetherwind (Valanaar)", lv=10, n="At 10 Anathamaas Aetherwind, the Valanaar mage trainer, sends you to Belann Windwood, the staff merchant a few steps away in the same town.", f={r={"Skyborne"}}, g={{"l",10,txt="Reach level 10"},{"a",93791,m=2521,x=65.9,y=80.6,ml=10},{"t",93791,m=2521,x=62.9,y=77.4},{"a",93797,m=2521,x=62.9,y=77.4,ml=10}}},
  {t="The Windstone Formations", lv=10, n="The bough lies on the ground among the Windstone Formations, the wind shrine on the rise west of Fillion's camp, south of Falaath Village. It does not sparkle, so look at the ground by the stones; there are two spots for it.", f={r={"Skyborne"}}, g={{"o",93797,i=1,txt="Wind-Infused Bough",m=2521,x=48.7,y=67.4}}},
  {t="Back to Belann", lv=10, f={r={"Skyborne"}}, g={{"t",93797,n2="Belann Windwood: Windbough Wand",m=2521,x=62.9,y=77.4},{"i",0,txt="Mirror Lake (the next steps) waits for you with Jennea Cannon in Stormwind, at about 15."}}},
  {t="Zaldimar Wefhellt (Goldshire)", lv=10, n="At 10 Zaldimar Wefhellt, the Goldshire mage trainer, upstairs in the Lion's Pride Inn, sends you to Jennea Cannon in Stormwind. Taking it shuts out Speak with Bink, the Kharanos trainer's errand; Mirror Lake and Bink's Gizmonitor shut out each other, so you get one staff or orb.", f={r={"Human"}}, g={{"l",10,txt="Reach level 10"},{"a",1860,m=1429,x=43.2,y=66.2,ml=10}}},
  {t="Magis Sparkmantle (Kharanos)", lv=10, n="At 10 Magis Sparkmantle, the Kharanos mage trainer in the Thunderbrew Distillery, sends you to Bink in Ironforge. Taking it shuts out Speak with Jennea, the Goldshire trainer's errand; Bink's Gizmonitor and Jennea's Mirror Lake shut out each other, so you get one staff or orb. (A Gnome who took Zaldimar's quest in Goldshire instead follows the Mirror Lake steps; a Human who took this one, the Gizmonitor steps.)", f={r={"Gnome"}}, g={{"l",10,txt="Reach level 10"},{"a",1879,m=1426,x=47.5,y=52.1,ml=10}}},
  {t="Jennea Cannon", lv=10, n="Follow the road north into Stormwind and west to the Mage Quarter. Jennea stands at the top of the Wizard's Sanctum, the tall violet tower: climb the spiral ramp and step into the portal near the top, which puts you beside her. She hands you Jennea's Flask. Skyborne mages take Mirror Lake from her when they first reach Stormwind, at about 15.", w={{k="onquest",neg=true,q={1879}}}, f={r={"Human","Gnome","Skyborne"}}, g={{"t",1860,m=1453,x=49.6,y=85.8,f={r={"Human","Gnome"}}},{"a",1861,m=1453,x=49.6,y=85.8,ml=10}}},
  {t="The Mirror Lake waterfall", lv=10, n="Leave Stormwind by the main gate and head south-west to the waterfall that feeds Mirror Lake. Wade in under the falling water to the rock behind it and use Jennea's Flask there (a 5 second cast); it fails anywhere else. Level 10 Defias casters stand on the rocks either side of the falls and shoot from range: pull them one at a time or fill the flask from the water.", w={{k="onquest",q={1861}}}, f={r={"Human","Gnome","Skyborne"}}, g={{"o",1861,i=1,txt="Use Jennea's Flask",n2="Jennea's Flask, under the falls",m=1429,x=28.6,y=61.4},{"o",1861,i=1,txt="Mirror Lake Water Sample",m=1429,x=28.6,y=61.4}}},
  {t="Back to Jennea", lv=10, n="Back up the Wizard's Sanctum and through the portal. The orb is an off-hand for a one-hand weapon; the staff is a two-hander.", w={{k="onquest",q={1861}}}, f={r={"Human","Gnome","Skyborne"}}, g={{"t",1861,n2="Jennea Cannon: Ley Orb or Ley Staff",m=1453,x=49.6,y=85.8}}},
  {t="Bink", lv=10, n="Bink teaches mages in the Mystic Ward, at the back of Ironforge past the Hall of Mysteries.", w={{k="onquest",q={1879}}}, f={r={"Human","Gnome"}}, g={{"t",1879,m=1455,x=27.2,y=8.3},{"a",1880,m=1455,x=27.2,y=8.3,ml=10}}},
  {t="Bink's Toolbox", lv=10, n="Head west along the road to Gnomeregan. Just north of its entrance stand two huts; the toolbox is in the taller, eastern one, the hut with the lift: a small grey box on the ground floor, half under the table beside the lift. Leper Gnomes (level 8) guard the huts: pull them singly. There is only one toolbox and it takes 15 minutes to come back after someone opens it, so wait nearby if it is gone.", w={{k="onquest",q={1880}}}, f={r={"Human","Gnome"}}, g={{"i",0,txt="Bink's Toolbox",m=1426,x=27.7,y=36.4},{"o",1880,i=1,txt="Mage-tastic Gizmonitor",m=1426,x=27.7,y=36.4}}},
  {t="Back to Bink", lv=10, w={{k="onquest",q={1880}}}, f={r={"Human","Gnome"}}, g={{"t",1880,n2="Bink: Arcane Orb or Arcane Staff",m=1455,x=27.2,y=8.3}}},
  {t="Belann's wand (optional)", lv=10, n="Belann's quest is open to Human and Gnome mages too, if you ever visit Valanaar on Zephras Isle, the Skyborne home: Anathamaas Aetherwind, the town's mage trainer, sends you to Belann Windwood next door, who wants a Wind-Infused Bough from the ground by the Windstone Formations south of Falaath Village, for the Windbough Wand. It does not shut out the staff or the orb.", f={r={"Human","Gnome"}}, g={{"a",93791,m=2521,x=65.9,y=80.6,opt=true,ml=10},{"t",93791,m=2521,x=62.9,y=77.4,opt=true},{"a",93797,m=2521,x=62.9,y=77.4,opt=true,ml=10},{"o",93797,i=1,txt="Wind-Infused Bough",m=2521,x=48.7,y=67.4,opt=true},{"t",93797,n2="Belann Windwood: Windbough Wand",m=2521,x=62.9,y=77.4,opt=true}}},
} end)

R:Segment({id="class/mage/teleports-alliance",title="Teleports and Portals (Alliance)",faction="Alliance",classes={"MAGE"},min=20,max=50,zone=1453,zoneName="Stormwind City",why="Your city teleports at 20 and 30 and the group portals at 40 and 50, from each city's portal trainer.",spells={3561,3562,3565,10059,11416,11419},spellNames={"Teleport: Stormwind","Teleport: Ironforge","Teleport: Darnassus","Portal: Stormwind","Portal: Ironforge","Portal: Darnassus"},folder="Mage"}, function() return {
  {t="Teleport: Stormwind", lv=20, n="At 20 go to the Wizard's Sanctum, the violet tower of Stormwind's Mage Quarter. Larimaine Purdue, the portal trainer, stands at the very top: climb the spiral ramp and take the portal near the top. She teaches Teleport: Stormwind for 20 silver. Every teleport burns one Rune of Teleportation (10 silver at any reagent vendor; Owen Vaughn sells them at the foot of the tower), so carry a few.", g={{"l",20,txt="Reach level 20"},{"i",0,txt="money"},{"tr",0,txt="Train with Larimaine Purdue",n2="Larimaine Purdue: Teleport: Stormwind",m=1453,x=50.4,y=86},{"h",17031,txt="Buy Rune of Teleportation x5",n2="Rune of Teleportation, 10s each",n=5}}},
  {t="Teleport: Ironforge", lv=20, n="Take the Deeprun Tram from Stormwind's Dwarven District to Ironforge. Milstaff Stormeye, the portal trainer, stands with the mage trainers in the Mystic Ward at the back of the city: Teleport: Ironforge, 20 silver.", g={{"i",0,txt="money"},{"tr",0,txt="Train with Milstaff Stormeye",n2="Milstaff Stormeye: Teleport: Ironforge",m=1455,x=25.5,y=7.1}}},
  {t="Teleport: Darnassus", lv=30, n="At 30. Take the boat from Stormwind Harbor to Auberdine in Darkshore, then the boat to Rut'theran Village and the pink portal up into Darnassus. Elissa Dumas, the portal trainer, teaches Teleport: Darnassus for 80 silver.", g={{"l",30,txt="Reach level 30"},{"i",0,txt="money"},{"tr",0,txt="Train with Elissa Dumas",n2="Elissa Dumas: Teleport: Darnassus",m=1457,x=40.6,y=82.1}}},
  {t="Portals to Stormwind and Ironforge", lv=40, n="At 40 the portal trainers teach the portals: a gateway your whole group can step through, for 1 gold 50 silver each. Each portal burns one Rune of Portals (20 silver at any reagent vendor). Larimaine Purdue has Portal: Stormwind at the top of the Wizard's Sanctum; then the tram to Milstaff Stormeye in Ironforge's Mystic Ward for Portal: Ironforge.", g={{"l",40,txt="Reach level 40"},{"i",0,txt="money"},{"tr",0,txt="Train with Larimaine Purdue",n2="Larimaine Purdue: Portal: Stormwind",m=1453,x=50.4,y=86},{"h",17032,txt="Buy Rune of Portals x5",n2="Rune of Portals, 20s each",n=5},{"tr",0,txt="Train with Milstaff Stormeye",n2="Milstaff Stormeye, Ironforge: Portal: Ironforge",m=1455,x=25.5,y=7.1}}},
  {t="Portal: Darnassus", lv=50, n="At 50 Elissa Dumas in Darnassus teaches the last one, Portal: Darnassus, for 3 gold 20 silver. Use your Teleport: Darnassus to get there.", g={{"l",50,txt="Reach level 50"},{"i",0,txt="money"},{"tr",0,txt="Train with Elissa Dumas",n2="Elissa Dumas: Portal: Darnassus",m=1457,x=40.6,y=82.1}}},
} end)

R:Segment({id="class/mage/teleports-horde",title="Teleports and Portals (Horde)",faction="Horde",classes={"MAGE"},min=20,max=50,zone=1454,zoneName="Orgrimmar",why="Your city teleports at 20 and 30 and the group portals at 40 and 50, from each city's portal trainer.",spells={3567,3563,3566,11417,11418,11420},spellNames={"Teleport: Orgrimmar","Teleport: Undercity","Teleport: Thunder Bluff","Portal: Orgrimmar","Portal: Undercity","Portal: Thunder Bluff"},folder="Mage"}, function() return {
  {t="Teleport: Orgrimmar", lv=20, n="At 20 go to Darkbriar Lodge in Orgrimmar's Valley of Spirits, where the mage trainers live. Thuul, the portal trainer, stands on the upper floor and teaches Teleport: Orgrimmar for 20 silver. Every teleport burns one Rune of Teleportation (10 silver at any reagent vendor), so carry a few.", g={{"l",20,txt="Reach level 20"},{"i",0,txt="money"},{"tr",0,txt="Train with Thuul",n2="Thuul: Teleport: Orgrimmar",m=1454,x=38.7,y=85.4},{"h",17031,txt="Buy Rune of Teleportation x5",n2="Rune of Teleportation, 10s each",n=5}}},
  {t="Teleport: Undercity", lv=20, n="Take the zeppelin from the tower outside Orgrimmar's gate to Tirisfal Glades and walk into the Undercity. Lexington Mortaim, the portal trainer, stands in the Magic Quarter with the mage trainers: Teleport: Undercity, 20 silver. Hannah Akeley beside him sells the runes.", g={{"i",0,txt="money"},{"tr",0,txt="Train with Lexington Mortaim",n2="Lexington Mortaim: Teleport: Undercity",m=1458,x=84.2,y=15.6}}},
  {t="Teleport: Thunder Bluff", lv=30, n="At 30. Thunder Bluff is in Mulgore: fly there from Orgrimmar or the Crossroads. Birgitte Cranston, the portal trainer, stands with the mage trainers in the Pools of Vision, the cave under Spirit Rise: go down inside, the arrow cannot tell the floors apart. She teaches Teleport: Thunder Bluff for 80 silver.", g={{"l",30,txt="Reach level 30"},{"i",0,txt="money"},{"tr",0,txt="Train with Birgitte Cranston",n2="Birgitte Cranston: Teleport: Thunder Bluff",m=1456,x=22.5,y=16.9}}},
  {t="Portals to Orgrimmar and the Undercity", lv=40, n="At 40 the portal trainers teach the portals: a gateway your whole group can step through, for 1 gold 50 silver each. Each portal burns one Rune of Portals (20 silver at any reagent vendor). Thuul in Darkbriar Lodge has Portal: Orgrimmar; teleport to the Undercity for Lexington Mortaim's Portal: Undercity.", g={{"l",40,txt="Reach level 40"},{"i",0,txt="money"},{"tr",0,txt="Train with Thuul",n2="Thuul: Portal: Orgrimmar",m=1454,x=38.7,y=85.4},{"h",17032,txt="Buy Rune of Portals x5",n2="Rune of Portals, 20s each",n=5},{"tr",0,txt="Train with Lexington Mortaim",n2="Lexington Mortaim, Undercity: Portal: Undercity",m=1458,x=84.2,y=15.6}}},
  {t="Portal: Thunder Bluff", lv=50, n="At 50 Birgitte Cranston, down in the Pools of Vision under Spirit Rise in Thunder Bluff, teaches the last one, Portal: Thunder Bluff, for 3 gold 20 silver. Use your Teleport: Thunder Bluff to get there.", g={{"l",50,txt="Reach level 50"},{"i",0,txt="money"},{"tr",0,txt="Train with Birgitte Cranston",n2="Birgitte Cranston: Portal: Thunder Bluff",m=1456,x=22.5,y=16.9}}},
} end)

R:Segment({id="class/paladin/cloak-of-the-divine-storm",title="Cloak of the Divine Storm",faction="Alliance",classes={"PALADIN"},min=22,max=30,zone=1439,zoneName="Darkshore",why="Starts now at 22 at the Tower of Althalaxx; its mobs are 28-30, so go nearer 30 or with a friend. Alliance only for now.",items={277205},folder="Paladin"}, function() return {
  {t="The Strange Orb", lv=22, n="Climb to the top of the Tower of Althalaxx in northern Darkshore. The Dark Strand Fanatics around it are easy (level 16-17), but four Dark Strand Voidcallers (level 28-29) stand in the tower on the way to the orb: each calls a voidwalker and casts Shadow Bolt from range. At 22-25 bring a friend or two, pull them one at a time and step behind a wall so they have to come to you. Loot the Strange Orb at the top: it gives you the Althalaxx Orb; right-click it to start the quest. Keep the orb in your bags until the Spear of Mannoroth: three later quests need it.", g={{"l",22,txt="Reach level 22"},{"a",78088,n2="Strange Orb atop the Tower of Althalaxx: right-click the Althalaxx Orb it gives",m=1439,x=56.2,y=26.5,ml=22}}},
  {t="Delgren the Purifier", lv=22, n="Delgren the Purifier stands at Maestra's Post in western Ashenvale, south of the Darkshore road. He sends you to Stormwind with the orb.", g={{"t",78088,m=1440,x=26.2,y=38.7},{"a",78089,m=1440,x=26.2,y=38.7,ml=22}}},
  {t="Katherine the Pure", lv=22, n="Katherine the Pure stands in the Cathedral of Light; she sends you to a warlock for a second opinion.", g={{"t",78089,m=1453,x=48.5,y=49.1},{"a",78090,m=1453,x=48.5,y=49.1,ml=22}}},
  {t="Ursula Deline", lv=22, n="Ursula Deline, the warlock trainer, is in the Mage Quarter's warlock sanctum, down in the Slaughtered Lamb's cellar. She wants 14 Summoner's Salt to read the orb.", g={{"t",78090,m=1453,x=39.9,y=84.2},{"a",78091,m=1453,x=39.9,y=84.2,ml=22}}},
  {t="Summoner's Salt", lv=22, n="The Blackrock Summoners, Champions and Trackers (level 22-25, not elite) camp in the north-west of Redridge and drop the Summoner's Salt; you need 14. Two elite Blackrock Shadowcasters (22-23) stand at the cave mouth at the camp's east end: pull around them. The Blackrock camps east of Lakeshire drop the salt too, but their Shadowcasters, Sentries and Hunters are elite (level 21-24), and so is Gath'Ilzogg (26): stay in the north-west.", g={{"o",78091,i=1,txt="Summoner's Salt x14",m=1433,x=23.5,y=12}}},
  {t="Back to Ursula", lv=22, g={{"t",78091,m=1453,x=39.9,y=84.2},{"a",78092,m=1453,x=39.9,y=84.2,ml=22}}},
  {t="Motes of Mannoroth", lv=22, n="Demon Fall Canyon is in south-east Ashenvale, east of Splintertree Post (a Horde camp: go round it). The Mannoroc Lashers, Searing Infernals, Felguards and Legion Hounds (level 29-30, not elite) drop the Motes of Mannoroth; you need 12. Below about 27 they are hard alone: come with a second player or later. Felguards knock you down, Lashers cast Shadow Bolt and Immolate, Infernals keep a fire shield up. They respawn in five minutes.", g={{"o",78092,i=1,txt="Mote of Mannoroth x12",m=1440,x=78.5,y=81.6}}},
  {t="The Spear of Mannoroth", lv=22, n="The Spear of Mannoroth stands at the east end of Demon Fall Canyon. Hand in the motes at the spear with the Althalaxx Orb in your bags: the orb shatters, and the Shattered Orb beside it starts the last quest.", g={{"t",78092,m=1440,x=89.4,y=77.1},{"a",78093,n2="from the Shattered Orb",m=1440,x=89.4,y=77,ml=22}}},
  {t="Return to Delgren", lv=22, n="Back to Delgren at Maestra's Post in western Ashenvale, across the whole zone.", g={{"t",78093,n2="Delgren the Purifier: Cloak of the Divine Storm",m=1440,x=26.2,y=38.7}}},
} end)

R:Segment({id="class/paladin/holy-mightstone",title="Holy Mightstone",faction="Alliance",races={"Human","Dwarf"},classes={"PALADIN"},min=50,max=56,zone=1453,zoneName="Stormwind City",why="A one-use stone that makes you much stronger against undead for 10 minutes; the old item choice may be gone in Forever.",items={20620},folder="Paladin"}, function() return {
  {t="Lord Grayson Shadowbreaker", lv=50, n="At 50 Lord Grayson Shadowbreaker, the paladin trainer in the Cathedral of Light, sends you to Chillwind Camp in the Western Plaguelands. Brandur Ironhammer in Ironforge gives the same quest.", f={r={"Human"}}, g={{"l",50,txt="Reach level 50"},{"a",8415,m=1453,x=48.4,y=50.2,ml=50}}},
  {t="Brandur Ironhammer", lv=50, n="At 50 Brandur Ironhammer, the paladin trainer in the Mystic Ward, sends you to Chillwind Camp in the Western Plaguelands. Lord Grayson Shadowbreaker in Stormwind gives the same quest.", f={r={"Dwarf"}}, g={{"l",50,txt="Reach level 50"},{"a",8415,m=1455,x=23.1,y=6.1,ml=50}}},
  {t="Chillwind Camp", lv=50, n="Chillwind Camp is the Alliance camp at the south end of the Western Plaguelands, north of the Alterac foothills. Commander Ashlam Valorfist commands it; Argent Officer Pureheart stands in the same camp.", g={{"t",8415,m=1422,x=42.7,y=84},{"a",8414,m=1422,x=42.7,y=84,ml=50}}},
  {t="The Argent Dawn Commission", lv=50, n="The Scourge drop no Scourgestones unless you wear an Argent Dawn Commission. Argent Officer Pureheart gives you one through her quest, Argent Dawn Commission, which you hand in straight away (if you already have one from Light's Hope Chapel, wear that). Equip it in a trinket slot: it shows as a buff that never runs out. Keep it on until you have 20 stones.", w={{k="has",neg=true,n=1,item=12846}}, g={{"a",5401,n2="Argent Officer Pureheart: Argent Dawn Commission",m=1422,x=43,y=83.5,ml=50},{"t",5401,n2="the Argent Dawn Commission trinket: equip it",m=1422,x=43,y=83.5}}},
  {t="Minion's Scourgestones", lv=50, n="Kill the Scourge of the Western Plaguelands with the Commission on: skeletons, ghouls and cultists (level 50-58) drop a Minion's Scourgestone about two kills in five. Sorrow Hill, just east of Chillwind Camp around Uther's Tomb, is the closest farm. Avoid the Flesh Golems that patrol the fields; Skeletal Guardians cast Cone of Cold and Arcane Explosion up close, Dark Summoners run for help at low health.", g={{"o",8414,i=1,txt="Minion's Scourgestone x20",n2="Minion's Scourgestone x20",m=1422,x=47.4,y=84.3}}},
  {t="High Priest Thel'danis", lv=50, n="High Priest Thel'danis keeps watch at Uther's Tomb on Sorrow Hill, east of the camp. He turns your 20 stones into one Inert Scourgestone: keep it.", g={{"t",8414,m=1422,x=52,y=83.3},{"a",8416,m=1422,x=52,y=83.3,ml=50}}},
  {t="Commander Ashlam Valorfist", lv=50, n="Back to Chillwind Camp. Ashlam needs the voodoo of the Sunken Temple's trolls for the stone.", g={{"t",8416,m=1422,x=42.7,y=84},{"a",8418,m=1422,x=42.7,y=84,ml=50}}},
  {t="The Sunken Temple", lv=50, n="The Temple of Atal'Hakkar, the Sunken Temple, lies in the Pool of Tears in eastern Swamp of Sorrows: go up the ruin's stairs, dive into the flooded hall and follow the stairs down to the portal. It is a dungeon for a group of five at about 50-55. Six elite troll minibosses (level 51-52) stand on the balconies around the temple's great round room, each behind a pack of elites on its side path. Each drops its feather every time: Gasher and Zul'Lor the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green; you need all six. Hukku calls guardians and throws Shadow Bolt Volleys, Mijan heals: kill them first.", g={{"g",0,txt="The Temple of Atal'Hakkar",m=1435,x=69.9,y=53.6},{"o",8418,i=1,txt="Amber Voodoo Feather x2",n2="Amber Voodoo Feather x2: Gasher, Zul'Lor",m=1435,x=69.9,y=53.6},{"o",8418,i=2,txt="Blue Voodoo Feather x2",n2="Blue Voodoo Feather x2: Hukku, Mijan",m=1435,x=69.9,y=53.6},{"o",8418,i=3,txt="Green Voodoo Feather x2",n2="Green Voodoo Feather x2: Zolo, Loro",m=1435,x=69.9,y=53.6}}},
  {t="Forging the Mightstone", lv=50, n="Back to Ashlam in Chillwind Camp: he forges the Holy Mightstone. Look at the reward window before you hand in: Classic also offered the Chivalrous Signet, the Lightforged Blade or the Sanctified Orb, and Forever's notes say that choice may be gone. Use the stone before a fight against undead (Stratholme, Scholomance): it lasts ten minutes and is gone after one use.", g={{"t",8418,n2="Commander Ashlam Valorfist: Holy Mightstone",m=1422,x=42.7,y=84}}},
} end)

R:Segment({id="class/paladin/lumina-windsinger",title="Moonsilver Blade and Wolfsbane (Forsaken)",faction="Horde",races={"Scourge"},classes={"PALADIN"},min=18,max=26,zone=1420,zoneName="Tirisfal Glades",why="The Forsaken paladin's two-handed sword: rescue Lumina Windsinger, gather three parts, slay Old Fire-Eye.",items={268484,267369},folder="Paladin"}, function() return {
  {t="Danitha Morr", lv=18, n="At 18 Danitha Morr, inside Bandarion Keep on the bluffs north-west of the Solliden Farmstead, sends you south to the Sepulcher in Silverpine Forest.", g={{"l",18,txt="Reach level 18"},{"a",91858,m=1420,x=22.1,y=44.7,ml=18}}},
  {t="The Sepulcher", lv=18, n="Trevan Rol stands in the lower part of the Sepulcher, below the surface; Deathguard Baldren keeps watch near the town's entrance.", g={{"t",91858,m=1421,x=43.4,y=41.1},{"a",91859,m=1421,x=43.4,y=41.1,ml=18},{"t",91859,m=1421,x=45.8,y=41.9},{"a",91860,m=1421,x=45.8,y=41.9,ml=18}}},
  {t="The pyre on Fenris Isle", lv=18, n="Fenris Isle lies in the lake north-east of the Sepulcher. The gnolls' pyre, with the Charred Remains, is on its shore: click the remains to hand in, and click them again for the next quest. The body is a tauren's, not the elf's.", g={{"t",91860,m=1421,x=65,y=34.1},{"a",91861,n2="from the Charred Remains",m=1421,x=65,y=34.1,ml=18}}},
  {t="Fenris Keep", lv=18, n="Lumina Windsinger is caged in the basement of Fenris Keep, at the north end of the isle. The Rot Hide gnolls (level 18-19) fill the keep: they pull in big groups across floors and players report very fast respawns, so clear a path and keep moving. Any of them can carry the Fenris Isle Key (often the first kill); the rare Rot Hide Bruiser (22) and Snarlmane (23) can too. If her cage is empty, another player is escorting her: wait for her to come back.", g={{"t",91861,m=1421,x=65.5,y=23.3},{"a",91862,m=1421,x=65.5,y=23.3,ml=18},{"o",91862,i=1,txt="Fenris Isle Key",n2="Fenris Isle Key, from the Rot Hide gnolls",m=1421,x=65.6,y=23.3}}},
  {t="Free Lumina", lv=18, n="Hand in the key first: starting the escort before that gives the key quest no credit. Then open the cage: Lumina walks out through the keep and its courtyard while the gnolls attack, then runs for the dock and makes her own way back to the Sepulcher. Stay close and keep her alive; if she dies, take the quest again when she is back in her cage.", g={{"t",91862,m=1421,x=65.5,y=23.3},{"a",96204,m=1421,x=65.5,y=23.3,ml=18}}},
  {t="Back to the Sepulcher", lv=18, n="Lumina waits beside Trevan Rol in the Sepulcher (a different Lumina from the one you escorted). For The Debt, click through every line of her story.", g={{"t",96204,n2="Lumina Windsinger, the Sepulcher",m=1421,x=43.4,y=41},{"a",95034,m=1421,x=43.4,y=41,ml=18},{"o",95034,i=1,txt="Talk to Lumina Windsinger",n2="Lumina Windsinger: hear her story to the end",m=1421,x=43.4,y=41},{"t",95034,m=1421,x=43.4,y=41}}},
  {t="A Moon-Kissed Blade", lv=20, n="At 20 Lumina asks for a blade that can kill Old Fire-Eye. Talk to Trevan Rol beside her for his Weapon Notes, which list the parts, and keep them: he wants them back with the parts. Three parts, in any order: two from dungeons (a group of five each) and a gem from elite naga outside a third.", g={{"l",20,txt="Reach level 20"},{"a",95036,m=1421,x=43.4,y=41,ml=20},{"h",267454,txt="Get Trevan's Weapon Notes",n2="Trevan's Weapon Notes: talk to Trevan Rol",m=1421,x=43.4,y=41.1,n=1}}},
  {t="The Enchanted Silver Ingot", lv=20, n="Shadowfang Keep is the dungeon in south Silverpine, for a group of five in the low to mid 20s. The ingot sits on the table next to Archmage Arugal at the very end. A friend's cleared instance works: walk in and run to the table.", g={{"g",0,txt="Shadowfang Keep",m=1421,x=44.8,y=67.8},{"o",95036,i=3,txt="Enchanted Silver Ingot",n2="Enchanted Silver Ingot, on Arugal's table",m=1421,x=44.8,y=67.8}}},
  {t="Whitestone Oak Lumber", lv=20, n="The Deadmines lies under Moonbrook in Westfall, Alliance land: a group of five at about 17-24. From the Undercity take the zeppelin to Grom'gol in Stranglethorn Vale and go north through Duskwood into Westfall. The way in is the Moonbrook mine. The Goblin Woodcarvers (elite, level 18-19) in Sneed's mast room drop the lumber every time.", g={{"g",0,txt="The Deadmines, in the Moonbrook mine",m=1436,x=42.5,y=71.7},{"o",95036,i=2,txt="Whitestone Oak Lumber",n2="Goblin Woodcarvers, inside",m=1436,x=42.5,y=71.7,grp=true}}},
  {t="Ulric Frostveil", lv=20, n="Ulric Frostveil waits at Zoram'gar Outpost on Ashenvale's west coast: take the zeppelin from Grom'gol (or the Undercity) to Orgrimmar, then go north through the Barrens into Ashenvale and west along the road. Andruk, the outpost's wind rider master, saves you the walk next time. Take Ulric's quest before you hunt the naga: the Kor Gem only drops while you have it.", g={{"a",95042,n2="Ulric Frostveil, Zoram'gar Outpost",m=1440,x=11.9,y=34.4,ml=20}}},
  {t="The Corrupted Kor Gem", lv=20, n="The naga stand in the flooded ruins and passages around the Blackfathom Deeps entrance, just north of Zoram'gar: you do not need to enter the instance (its first naga drop the gem too). Tide Priestesses (level 20-21), Oracles (21-22) and Sea Witches (23-24) drop the Corrupted Kor Gem, one in two. All are elite: grouping up is encouraged. Players solo them one at a time, with difficulty; a group of three makes it easy. They heal themselves, run for help at low health, and the Sea Witches cast Frost Nova up close. Some players report no drop while in a raid group.", g={{"o",95042,i=1,txt="Corrupted Kor Gem",m=1440,x=13.6,y=12.1,grp=true}}},
  {t="The Purified Kor Gem", lv=20, n="Back to Ulric at Zoram'gar: he cleanses the gem. Keep the Purified Kor Gem for Trevan.", g={{"t",95042,n2="Ulric Frostveil: Purified Kor Gem",m=1440,x=11.9,y=34.4}}},
  {t="Trevan Rol", lv=20, n="Bring the lumber, the ingot and the gem to Trevan in the Sepulcher. He gives you a Bundle of Blacksmithing Materials for a smith in Tarren Mill: keep it in your bags.", g={{"t",95036,m=1421,x=43.4,y=41.1},{"a",95111,m=1421,x=43.4,y=41.1,ml=20}}},
  {t="Ott", lv=20, n="Ott, the weaponsmith, stands just south of Tarren Mill in Hillsbrad Foothills. Accepting Ott's Masterwork starts the forging: step back and wait near him until he is done.", g={{"t",95111,n2="Ott, Tarren Mill",m=1424,x=60.4,y=26.2},{"a",95125,m=1424,x=60.4,y=26.2,ml=20},{"c",95125,txt="Watch Ott craft the blade",n2="Watch Ott forge the blade"},{"t",95125,m=1424,x=60.4,y=26.2},{"a",95126,n2="Ott gives you Ott's Masterwork",m=1424,x=60.4,y=26.2,ml=20}}},
  {t="The Moonsilver Blade", lv=20, n="Back to Trevan Rol in the Sepulcher's lower part: he hands you the Moonsilver Blade, a two-handed sword.", g={{"t",95126,n2="Trevan Rol: Moonsilver Blade",m=1421,x=43.4,y=41.1}}},
  {t="Two-Handed Swords", lv=20, n="The blade is a two-handed sword, and you need the skill to hit a level 25 elite with it. Archibald, the weapon master in the Undercity's War Quarter, teaches Two-Handed Swords for a small fee; then swing it on easy mobs until the skill is near its cap (five points per level).", g={{"tr",0,txt="Train with Archibald",n2="Archibald, War Quarter: Two-Handed Swords",m=1458,x=57.3,y=32.8,opt=true}}},
  {t="Old Fire-Eye", lv=22, n="Equip the Moonsilver Blade. Old Fire-Eye, the great worgen, roams the woods south of the Sepulcher toward the gates of Gilneas. He is elite (level 25): the guide waits for level 22 first, and grouping up is encouraged; players have killed him from 22 up, one needed a second, another soloed him at 25. A purple shield guards him until your first swing with the blade lands: a message tells you it broke.", g={{"a",95140,n2="Lumina Windsinger, the Sepulcher",m=1421,x=43.4,y=41,ml=20},{"l",22,txt="Reach level 22"},{"o",95140,i=1,txt="Kill Old Fire-Eye",n2="Old Fire-Eye, with the Moonsilver Blade equipped",m=1421,x=47.9,y=85.3,grp=true}}},
  {t="Wolfsbane", lv=22, n="Back to Lumina in the Sepulcher with the Moonsilver Blade (the quest asks for it): she takes it and blesses it with the magic of her people into Wolfsbane.", g={{"t",95140,n2="Lumina Windsinger: Wolfsbane",m=1421,x=43.4,y=41}}},
} end)

R:Segment({id="class/paladin/tome-of-divinity",title="Redemption (Alliance)",faction="Alliance",races={"Human","Dwarf"},classes={"PALADIN"},min=12,max=14,zone=1453,zoneName="Stormwind City",why="Redemption at 12, the paladin's resurrection: an easy chain through your capital and its home zone.",spells={7328},spellNames={"Redemption"},folder="Paladin"}, function() return {
  {t="The summons (Human)", lv=12, n="At 12 Brother Wilhelm, the paladin trainer in Goldshire, sends you to Duthorian Rall in Stormwind's Cathedral of Light. The errand is optional, a little XP: Brandur Ironhammer in Ironforge gives the same one (taking one closes the other), and Duthorian starts the chain without it.", f={r={"Human"}}, g={{"l",12,txt="Reach level 12"},{"a",2998,n2="Brother Wilhelm, Goldshire",m=1429,x=41.1,y=66,opt=true,ml=12}}},
  {t="The summons (Dwarf)", lv=12, n="At 12 Brandur Ironhammer, the paladin trainer in Ironforge's Mystic Ward, sends you upstairs to Tiza Battleforge. The errand is optional, a little XP: Azar Stronghammer in Kharanos and Lord Grayson Shadowbreaker in Stormwind give the same one (taking one closes the others), and Tiza starts the chain without it.", f={r={"Dwarf"}}, g={{"l",12,txt="Reach level 12"},{"a",2999,n2="Brandur Ironhammer, Ironforge",m=1455,x=23.1,y=6.1,opt=true,ml=12}}},
  {t="Duthorian Rall", lv=12, w={{k="onquest",q={2998}}}, f={r={"Human"}}, g={{"t",2998,n2="Duthorian Rall, Cathedral of Light",m=1453,x=50.5,y=47.5}}},
  {t="Duthorian Rall", lv=12, w={{k="onquest",q={3681}}}, f={r={"Human"}}, g={{"t",3681,n2="Duthorian Rall, Cathedral of Light",m=1453,x=50.5,y=47.5}}},
  {t="The Tome of Divinity", lv=12, n="Duthorian Rall stands inside the Cathedral of Light. He hands you the Tome of Divinity: right-click it in your bags to start the next quest. If the book says the quest is already done, destroy it and ask Duthorian for a new copy. Bring 10 Linen Cloth for the next step if you have it.", f={r={"Human"}}, g={{"t",1641,m=1453,x=50.5,y=47.5},{"a",1642,n2="Right-click the Tome of Divinity",ml=12},{"t",1642,m=1453,x=50.5,y=47.5},{"a",1643,m=1453,x=50.5,y=47.5,ml=12}}},
  {t="Stephanie Turner", lv=12, n="Stephanie Turner stands at a corner in the middle of the Trade District, outside a general goods store. She wants 10 Linen Cloth: humanoids drop it (Riverpaw gnolls in Westfall about every other kill, Defias and kobolds a little less), or buy it at the Auction House a few steps away in the Trade District.", f={r={"Human"}}, g={{"t",1643,m=1453,x=63.8,y=72.2},{"a",1644,m=1453,x=63.8,y=72.2,ml=12},{"o",1644,i=1,txt="Linen Cloth x10",n2="Linen Cloth x10",m=1453,x=49.8,y=85.8},{"t",1644,m=1453,x=63.8,y=72.2},{"a",1780,m=1453,x=63.8,y=72.2,ml=12}}},
  {t="The Symbol of Life", lv=12, n="Back to the Cathedral. Duthorian gives you the Symbol of Life; Gazin Tenorm lies wounded by the altar of the same hall. Keep the symbol: you need it on Henze Faulk. If you lose it, Duthorian gives you another (The Symbol of Life).", f={r={"Human"}}, g={{"t",1780,m=1453,x=50.5,y=47.5},{"a",1781,m=1453,x=50.5,y=47.5,ml=12},{"t",1781,m=1453,x=49.5,y=45},{"a",1786,m=1453,x=49.5,y=45,ml=12}}},
  {t="Henze Faulk", lv=12, n="Henze Faulk lies dead on Heroes' Vigil, the island in Stone Cairn Lake in eastern Elwynn, on top of one of the mounds around the stone circle. Target his body and use the Symbol of Life to raise him, then speak to him. If another paladin just raised him, his body is back within about three minutes. The Defias Rogue Wizards on the island (level 9-10) cast Frostbolt from far off: they stand apart, so pull one at a time.", f={r={"Human"}}, g={{"o",1786,i=1,txt="Use Symbol of Life",n2="Symbol of Life on Henze Faulk's body",m=1429,x=72.6,y=51.4},{"t",1786,m=1429,x=72.6,y=51.4},{"a",1787,m=1429,x=72.6,y=51.4,ml=12}}},
  {t="The Defias Script", lv=12, n="The Defias Rogue Wizards around the big stone tablet east of Henze carry the Defias Script: about one kill in two drops it, but some players need many kills. They respawn in three minutes.", f={r={"Human"}}, g={{"o",1787,i=1,txt="Defias Script",n2="Defias Script: Defias Rogue Wizards",m=1429,x=74.2,y=52}}},
  {t="Redemption", lv=12, n="Back to the Cathedral of Light: Gazin takes the script, Duthorian teaches you Redemption.", f={r={"Human"}}, g={{"t",1787,m=1453,x=49.5,y=45},{"a",1788,m=1453,x=49.5,y=45,ml=12},{"t",1788,n2="Duthorian Rall: Redemption",m=1453,x=50.5,y=47.5}}},
  {t="Tiza Battleforge", lv=12, w={{k="onquest",q={2997}}}, f={r={"Dwarf"}}, g={{"t",2997,n2="Tiza Battleforge, upstairs in the Hall of Mysteries",m=1455,x=27.6,y=12.2}}},
  {t="Tiza Battleforge", lv=12, w={{k="onquest",q={2999}}}, f={r={"Dwarf"}}, g={{"t",2999,n2="Tiza Battleforge, upstairs in the Hall of Mysteries",m=1455,x=27.6,y=12.2}}},
  {t="Tiza Battleforge", lv=12, w={{k="onquest",q={3000}}}, f={r={"Dwarf"}}, g={{"t",3000,n2="Tiza Battleforge, upstairs in the Hall of Mysteries",m=1455,x=27.6,y=12.2}}},
  {t="The Tome of Divinity", lv=12, n="Tiza Battleforge stands upstairs in the Hall of Mysteries, in the Mystic Ward: take the ramp at the back of the hall. She hands you the Tome of Divinity: right-click it in your bags to start the next quest. If the book says the quest is already done, destroy it and ask Tiza for a new copy. Bring 10 Linen Cloth for the next step if you have it.", f={r={"Dwarf"}}, g={{"t",1645,m=1455,x=27.6,y=12.2},{"a",1646,n2="Right-click the Tome of Divinity",ml=12},{"t",1646,m=1455,x=27.6,y=12.2},{"a",1647,m=1455,x=27.6,y=12.2,ml=12}}},
  {t="John Turner", lv=12, n="John Turner walks the outer ring of the Commons, past the front gate, the bank and the Auction House. He wants 10 Linen Cloth: humanoids drop it (Kogan Forgestone in Kharanos every time, Dark Iron Ambushers about two kills in five), or buy it at the Auction House on his ring.", f={r={"Dwarf"}}, g={{"t",1647,m=1455,x=23.3,y=61.9},{"a",1648,m=1455,x=23.3,y=61.9,ml=12},{"o",1648,i=1,txt="Linen Cloth x10",n2="Linen Cloth x10",m=1453,x=49.8,y=85.8},{"t",1648,m=1455,x=23.3,y=61.9},{"a",1778,m=1455,x=23.3,y=61.9,ml=12}}},
  {t="The Symbol of Life", lv=12, n="Back upstairs in the Hall of Mysteries. Tiza gives you the Symbol of Life; her husband Muiredon Battleforge rests on the same floor. Keep the symbol: you need it on Narm Faulk. If you lose it, Tiza gives you another (The Symbol of Life).", f={r={"Dwarf"}}, g={{"t",1778,m=1455,x=27.6,y=12.2},{"a",1779,m=1455,x=27.6,y=12.2,ml=12},{"t",1779,m=1455,x=23.5,y=8.3},{"a",1783,m=1455,x=23.5,y=8.3,ml=12}}},
  {t="Narm Faulk", lv=12, n="Narm Faulk lies dead in Dun Morogh, not Loch Modan: east past Kharanos, north-east of Ironband's compound, on the smallest of three little hills between Helm's Bed Lake and the Dark Iron camp. Target his body and use the Symbol of Life to raise him, then speak to him. If another paladin just raised him, his body is back within about three minutes.", f={r={"Dwarf"}}, g={{"o",1783,i=1,txt="Use Symbol of Life",n2="Symbol of Life on Narm Faulk's body",m=1426,x=78.3,y=58.1},{"t",1783,m=1426,x=78.3,y=58.1},{"a",1784,m=1426,x=78.3,y=58.1,ml=12}}},
  {t="The Dark Iron Script", lv=12, n="The Dark Iron Spies (level 9-11, twelve of them) sneak around the little house below the lake, just south of Narm; you see them from his hill. About one kill in two drops the Dark Iron Script. They run for help at low health: finish them or step back. They respawn in three minutes.", f={r={"Dwarf"}}, g={{"o",1784,i=1,txt="Dark Iron Script",n2="Dark Iron Script: Dark Iron Spies",m=1426,x=77.5,y=61.2}}},
  {t="Redemption", lv=12, n="Back up to the Hall of Mysteries: Muiredon takes the script, Tiza teaches you Redemption.", f={r={"Dwarf"}}, g={{"t",1784,m=1455,x=23.5,y=8.3},{"a",1785,m=1455,x=23.5,y=8.3,ml=12},{"t",1785,n2="Tiza Battleforge: Redemption",m=1455,x=27.6,y=12.2}}},
} end)

R:Segment({id="class/paladin/tyrs-watch",title="Tyr's Watch and Redemption (Forsaken)",faction="Horde",races={"Scourge"},classes={"PALADIN"},min=1,max=13,zone=1420,zoneName="Tirisfal Glades",why="Redemption to raise fallen allies, plus a weapon and a shield for a new Forsaken paladin.",spells={7328},spellNames={"Redemption"},items={246164,246165,246265},folder="Paladin"}, function() return {
  {t="Aramis Hammerhand", lv=2, n="Shadow Priest Sarvis gives you a Consecrated Scroll after The Mindless Ones: read it, then bring it to Aramis Hammerhand by the church. He asks you to heal five Injured Deathguard lying around Deathknell. Holy Light hurts a Forsaken paladin a little each time: watch your health.", w={{k="level",op="<",n=9}}, g={{"a",98601,m=1420,x=30.8,y=66.2,ml=1},{"t",98601,m=1420,x=31.1,y=66.4},{"l",2,txt="Reach level 2"},{"a",90902,m=1420,x=31.1,y=66.4,ml=2},{"c",90902,txt="Heal 5 Injured Deathguard",n2="Heal 5 Injured Deathguard with Holy Light",m=1420,x=31.6,y=65.8},{"t",90902,m=1420,x=31.1,y=66.4}}},
  {t="Coming to Terms", lv=4, n="At 4 Aramis sends you after a Frightened Paladin who fled into the hills west of the church, just south of the bat cave. Talk to her to offer aid: she turns on you, and you have to put her down (level 3, easy).", w={{k="level",op="<",n=9}}, g={{"l",4,txt="Reach level 4"},{"a",91208,m=1420,x=31.1,y=66.4,ml=4},{"a",91209,m=1420,x=31.1,y=66.4,ml=4},{"o",91208,i=1,txt="Kill Frightened Paladin",n2="Talk to the Frightened Paladin, then defeat her",m=1420,x=27.7,y=63.8},{"t",91208,m=1420,x=31.1,y=66.4}}},
  {t="Shari Stilwell", lv=4, n="Follow the road east out of Deathknell to Brill. Shari Stilwell, the paladin trainer, stands in town; she trains you from here on.", w={{k="level",op="<",n=9}}, g={{"t",91209,n2="Shari Stilwell, Brill",m=1420,x=60.2,y=52.7},{"tr",0,txt="Visit your class trainer"}}},
  {t="A Second Home", lv=8, n="At 8 Shari Stilwell in Brill sends you to the order's keep on the west coast. The Tarnished in Shadowvale and the crypt under it hit hard at 8-9: come at 10 or later.", g={{"l",8,txt="Reach level 8"},{"a",91282,n2="Shari Stilwell, Brill",m=1420,x=60.2,y=52.7,ml=8}}},
  {t="Bandarion Keep", lv=10, n="Bandarion Keep stands on the bluffs north-west of the Solliden Farmstead (the road west starts near 29,46). Breton Samuels waits at the gate. Hilda the Breaker, the keep's trainer, and Ephram Barbaro, its stable master, stand at the forest's edge just south of him. They only have work for you from level 10 and after A Righteous Cause from Leonid at the keep, the end of Hadric Harlson's chain that starts south-east of Brill; take their quests when you see them.", g={{"t",91282,m=1420,x=21.9,y=45.2},{"a",91285,m=1420,x=21.9,y=45.2,ml=7},{"a",99152,n2="Hilda the Breaker: As Above, So Below",m=1420,x=22,y=47.2,opt=true,ml=10},{"a",99153,n2="Ephram Barbaro: The One That Got Away",m=1420,x=20.2,y=46.5,opt=true,ml=10}}},
  {t="Murlocs at the Gates", lv=10, n="The Vile Fin murlocs (level 9-11) lurk on the bluffs along the road east of the keep and in the camps around the lake to the south-west, on the way down to Shadowvale.", g={{"o",91285,i=1,txt="Kill Vile Fin Attacker x8",n2="Vile Fin Attackers x8",m=1420,x=17.9,y=53.4},{"o",91285,i=2,txt="Kill Vile Fin Seer x8",n2="Vile Fin Seers x8",m=1420,x=17.7,y=54}}},
  {t="Touring the Grounds", lv=10, n="Breton gives you a weapon, then sends you round the keep to speak with four of its people: Hilda the Breaker just south of the gate, Ander Solliden, the lookout, who walks the road south-east of the keep, then Jorin Croge and Danitha Morr inside the keep. Pick the conversation option with each.", g={{"t",91285,n2="Breton Samuels: Skullthumper or Driftwood Smasher",m=1420,x=21.9,y=45.2},{"a",91294,m=1420,x=21.9,y=45.2,ml=8},{"o",91294,i=1,txt="Talk to Hilda the Breaker",m=1420,x=22,y=47.2},{"o",91294,i=3,txt="Talk to Ander Solliden",m=1420,x=22.3,y=49.6},{"o",91294,i=2,txt="Talk to Jorin Croge",m=1420,x=22.7,y=44.7},{"o",91294,i=4,txt="Talk to Danitha Morr",m=1420,x=22.1,y=44.7}}},
  {t="Danitha Morr", lv=10, n="Danitha Morr leads the order from inside the keep; Jorin Croge stands beside it. The Tarnished need level 9.", g={{"t",91294,m=1420,x=22.1,y=44.7},{"l",9,txt="Reach level 9"},{"a",91317,m=1420,x=22.1,y=44.7,ml=9},{"a",91316,m=1420,x=22.7,y=44.7,ml=8}}},
  {t="Shadowvale", lv=10, n="The Tarnished (level 8-9) hold the ruined village of Shadowvale in the Whispering Forest, south-west of the keep. Commander Rudolph Gelhardt (level 10) stands on the upper floor of a house, with Drudges below him: clear the ground floor first.", g={{"o",91317,i=2,txt="Kill Tarnished Drudge x8",n2="Tarnished Drudges x8",m=1420,x=20.2,y=61.5},{"o",91317,i=3,txt="Kill Tarnished Zealot x6",n2="Tarnished Zealots x6",m=1420,x=16.3,y=62.6},{"o",91317,i=1,txt="Rudolph Gelhardt's Head",m=1420,x=11.5,y=64.2}}},
  {t="The crypt under Shadowvale", lv=10, n="The cellar is under the village, not on the surface: the way down is inside a burned-out house, where the arrow points. Twelve Lumber Piles (stacked beams) lie in the cellar, each good for one Sturdy Lumber. Whispering Horror, an elite (level 11-13), sits at the far end: leave it alone.", g={{"o",91316,i=1,txt="Sturdy Lumber x12",n2="Lumber Piles, in the cellar: the way down is here",m=1420,x=12.9,y=65.7}}},
  {t="Hilda's bones", lv=10, n="The Shadowvale Lurchers and Mystics (level 8-10) in the crypt drop the Faintly Glowing Bones: about one in two from Lurchers, more from one kind of Mystic, less from the other.", w={{k="onquest",q={99152}}}, g={{"o",99152,i=1,txt="Faintly Glowing Bone x6",n2="Faintly Glowing Bones x6",m=1420,x=9.9,y=66.4}}},
  {t="Ephram's crystal", lv=10, n="The Glowing Crystal Fragment, a green crystal, lies on the floor in the left-hand part of the crypt.", w={{k="onquest",q={99153}}}, g={{"o",99153,i=1,txt="Glowing Crystal Fragment",m=1420,x=9.8,y=69.3}}},
  {t="Back to the keep", lv=10, n="Danitha hands you Rudolph Gelhardt's head for Sylvanas: keep it in your bags, it is what you hand in.", g={{"t",91316,n2="Jorin Croge: Salvaged Wooden Tower Shield",m=1420,x=22.7,y=44.7},{"t",91317,m=1420,x=22.1,y=44.7},{"a",95803,m=1420,x=22.1,y=44.7,ml=9}}},
  {t="Hilda the Breaker", lv=10, n="Hilda and Ephram wait at the forest's edge south of the gate.", w={{k="onquest",q={99152}}}, g={{"t",99152,m=1420,x=22,y=47.2}}},
  {t="Ephram Barbaro", lv=10, n="Ephram waits at the forest's edge south of the gate, a few steps west of Hilda.", w={{k="onquest",q={99153}}}, g={{"t",99153,m=1420,x=20.2,y=46.5}}},
  {t="A Lesson in Divinity", lv=12, n="Danitha offers the first Lesson in Divinity at level 12. Bring 10 Linen Cloth if you have it: the Undercity asks for it next.", g={{"l",12,txt="Reach level 12"},{"a",94427,m=1420,x=22.1,y=44.7,ml=12}}},
  {t="The Undercity", lv=12, n="Walk south from Brill to the Ruins of Lordaeron and down into the Undercity. Lady Sylvanas Windrunner holds court in the Royal Quarter; Tanis Alderwood begs in the Trade Quarter.", g={{"t",95803,m=1458,x=58,y=91.8},{"t",94427,m=1458,x=65.5,y=37.5},{"a",94434,m=1458,x=65.5,y=37.5,ml=12}}},
  {t="Linen Cloth", lv=12, n="Tanis needs 10 Linen Cloth. Humanoids drop it: the Scarlet Zealots and Friars of the glades about three kills in ten. The Undercity Auction House sells it too.", g={{"o",94434,i=1,txt="Linen Cloth x10",n2="Linen Cloth x10",m=1420,x=59.8,y=67.4}}},
  {t="Tanis Alderwood", lv=12, g={{"t",94434,m=1458,x=65.5,y=37.5},{"a",94435,m=1458,x=65.5,y=37.5,ml=12}}},
  {t="The Symbol of Life", lv=12, n="Back to Bandarion Keep. Danitha gives you the Symbol of Life; Deathguard Billmuth waits downstairs in the keep. If you lose the symbol, Danitha gives you another.", g={{"t",94435,m=1420,x=22.1,y=44.7},{"a",94436,m=1420,x=22.1,y=44.7,ml=12},{"t",94436,n2="Deathguard Billmuth, downstairs",m=1420,x=21.9,y=44.5},{"a",94438,m=1420,x=21.9,y=44.5,ml=12}}},
  {t="Deathguard Falgan", lv=12, n="Venomweb Vale is at the far east end of the glades, a long walk. Falgan lies dead among the Scarlet Crusaders there: target his body and use the Symbol of Life, then talk to him at once, as he does not stay alive long. If he is already up (another player), just talk to him; if he died again, raise him again.", g={{"t",94438,m=1420,x=86.7,y=47.7},{"a",94440,m=1420,x=86.7,y=47.7,ml=12}}},
  {t="The Scarlet attack plans", lv=12, n="The Scarlet Zealots (level 8-9), Friars (9-10) and Tarnished around Venomweb Vale carry the attack plans. They run for help at low health and respawn in five minutes.", g={{"o",94440,i=1,txt="Scarlet Crusade Attack Plans",m=1420,x=86.6,y=44.9}}},
  {t="Redemption", lv=12, n="Back to Bandarion Keep, across the whole glades: Billmuth downstairs takes the plans, then Danitha, back upstairs in the keep, teaches you Redemption.", g={{"t",94440,n2="Deathguard Billmuth, downstairs",m=1420,x=21.9,y=44.5},{"a",94441,m=1420,x=21.9,y=44.5,ml=12},{"t",94441,n2="Danitha Morr, back upstairs: Redemption",m=1420,x=22.1,y=44.7}}},
} end)

R:Segment({id="class/paladin/verigans-fist",title="Verigan's Fist",faction="Alliance",races={"Human","Dwarf"},classes={"PALADIN"},min=20,max=30,zone=1453,zoneName="Stormwind City",why="The Alliance paladin's rare two-handed mace for the 20s, with a shield and Sense Undead on the way.",spells={5502},spellNames={"Sense Undead"},items={6953,9607},folder="Paladin"}, function() return {
  {t="The Tome of Valor (Ironforge)", lv=20, n="At 20 Tiza Battleforge, upstairs in the Hall of Mysteries in the Mystic Ward, gives you the Tome of Valor. Right-click it: it sends you to Duthorian Rall in Stormwind's Cathedral of Light. Take the Deeprun Tram from Ironforge to Stormwind.", f={r={"Dwarf"}}, g={{"l",20,txt="Reach level 20"},{"t",1794,m=1455,x=27.6,y=12.2}}},
  {t="The Tome of Valor", lv=20, n="Duthorian Rall stands in the Cathedral of Light. Humans get the Tome of Valor from him. Right-click the book to start its quest and hand it straight back to him.", g={{"l",20,txt="Reach level 20"},{"t",1793,m=1453,x=50.5,y=47.5,f={r={"Human"}}},{"a",1649,n2="Right-click the Tome of Valor",ml=20},{"t",1649,m=1453,x=50.5,y=47.5},{"a",1650,m=1453,x=50.5,y=47.5,ml=20}}},
  {t="Daphne Stilwell", lv=20, n="Daphne Stilwell's farmhouse stands on the south-west coast of Westfall, south of Moonbrook: take the path that runs south beside the Deadmines' back exit. When you take her quest, she walks from her orchard to the house and three waves of Defias Raiders (level 17-18) attack: three, then four, then five. Fight close to her so they do not swarm her, and heal her when she drops. You get time to eat and drink between waves, and she heals to full. If you or Daphne die, the quest fails: abandon it and take it again from her (she is back five minutes after dying). Players find it hard alone before about 24.", g={{"t",1650,m=1436,x=41.7,y=89.2},{"a",1651,m=1436,x=41.7,y=89.2,ml=20},{"c",1651,txt="Protect Daphne Stilwell",n2="Protect Daphne Stilwell: three waves"},{"t",1651,m=1436,x=41.7,y=89.2},{"a",1652,m=1436,x=41.7,y=89.2,ml=20}}},
  {t="Duthorian Rall", lv=20, n="Back to the Cathedral of Light: Duthorian gives you the Bastion of Stormwind shield and teaches you Sense Undead.", g={{"t",1652,n2="Duthorian Rall: Bastion of Stormwind, Sense Undead",m=1453,x=50.5,y=47.5},{"a",1653,m=1453,x=50.5,y=47.5,ml=20}}},
  {t="Jordan Stilwell", lv=20, n="Jordan Stilwell works outside the gates of Ironforge, not inside. He gives you Jordan's Weapon Notes: four parts, in any order. Keep the notes.", g={{"t",1653,m=1426,x=52.5,y=36.9},{"a",1654,m=1426,x=52.5,y=36.9,ml=20}}},
  {t="Bailor Stonehand", lv=20, n="Bailor Stonehand is downstairs in the house of Thelsamar that has a tailoring merchant outside. His quest only opens once you hold Jordan's.", g={{"a",1655,m=1432,x=36,y=44.9,ml=20}}},
  {t="Bailor's Ore", lv=20, n="The crate of ore sits outdoors in the middle of the Mo'grosh ogre camp in north-east Loch Modan, beside a big tree and a broken wagon, between the caves. The camp holds about fifteen Mo'grosh ogres, elite (level 18-19), who knock you down and come back after five minutes: grouping up is encouraged; at 20-22 it needs a group of about three. The crate is back two seconds after each loot, so every paladin in the group gets one.", g={{"o",1655,i=1,txt="Jordan's Ore Shipment",n2="Bailor's Ore crate",m=1432,x=71.6,y=21.6}}},
  {t="Back to Bailor", lv=20, n="Bailor turns the ore into Jordan's Refined Ore Shipment, the part Jordan wants.", g={{"t",1655,m=1432,x=36,y=44.9},{"o",1654,i=2,txt="Jordan's Refined Ore Shipment",m=1432,x=36,y=44.9}}},
  {t="Whitestone Oak Lumber", lv=20, n="The Deadmines is a group of five under Moonbrook; the instance portal is at the bottom of the Moonbrook mine. The Goblin Woodcarvers (elite, level 18-19) in the mast room with Sneed drop the lumber every time.", g={{"g",0,txt="The Deadmines, in the Moonbrook mine",m=1436,x=42.5,y=71.7},{"o",1654,i=1,txt="Whitestone Oak Lumber",n2="Goblin Woodcarvers, inside",m=1436,x=42.5,y=71.7,grp=true}}},
  {t="Jordan's Smithing Hammer", lv=20, n="Shadowfang Keep is a dungeon for a group of five in the low to mid 20s, in southern Silverpine Forest, Horde land: a long trip for the Alliance, through the Wetlands, Arathi and Hillsbrad. The hammer lies on a crate across from the horses in the stables, early in the dungeon, at the far end of the courtyard before the ramp up; it is back five minutes after someone takes it.", g={{"g",0,txt="Shadowfang Keep",m=1421,x=44.8,y=67.8},{"o",1654,i=3,txt="Jordan's Smithing Hammer",n2="Jordan's Hammer, inside",m=1421,x=44.8,y=67.8}}},
  {t="Thundris Windweaver", lv=20, n="Thundris Windweaver is in Auberdine. Take his quest before you hunt naga: the Kor Gem never drops without it.", g={{"a",1442,m=1439,x=37.4,y=40.1,ml=20}}},
  {t="The Corrupted Kor Gem", lv=20, n="The Blackfathom naga in the flooded passages around the Blackfathom Deeps entrance, on Ashenvale's north-west coast, drop the Corrupted Kor Gem: Tide Priestesses (level 20-21), Oracles (21-22) and Sea Witches (23-24), one in two. You do not need to enter the instance. All are elite: grouping up is encouraged; players solo them one at a time, with difficulty. They heal themselves, run for help at low health, satyrs stand near some, and the Sea Witches cast Frost Nova up close. Some players report no drop while in a raid group.", g={{"o",1442,i=1,txt="Corrupted Kor Gem",m=1440,x=13.6,y=12.1,grp=true}}},
  {t="The Purified Kor Gem", lv=20, n="Back to Thundris in Auberdine: he purifies the gem.", g={{"t",1442,m=1439,x=37.4,y=40.1},{"o",1654,i=4,txt="Purified Kor Gem",m=1439,x=37.4,y=40.1}}},
  {t="Verigan's Fist", lv=20, n="Bring the four parts to Jordan Stilwell outside Ironforge. Accept his last quest and wait by him while he forges the mace at his anvil.", g={{"t",1654,m=1426,x=52.5,y=36.9},{"a",1806,m=1426,x=52.5,y=36.9,ml=20},{"t",1806,n2="Verigan's Fist",m=1426,x=52.5,y=36.9}}},
} end)

R:Segment({id="class/priest/benediction",title="Benediction and Anathema",classes={"PRIEST"},min=60,max=60,zone=1423,zoneName="Eastern Plaguelands",why="The epic priest staff: the Eye of Divinity from Molten Core, Eris's peasant rescue, then the Eye of Shadow.",items={18608,18659},folder="Priest"}, function() return {
  {t="The Eye of Divinity", lv=60, n="The Eye of Divinity comes from the Cache of the Firelord, the chest that appears when Majordomo Executus yields in Molten Core, a 40-player raid (it is in the cache about half the time). Molten Core's portal is at the bottom of Blackrock Depths; once you have done Attunement to the Core (a Core Fragment from beside that portal), Lothos Riftwaker inside Blackrock Mountain ports you straight in. Nothing in this chain starts without the Eye: Eris is invisible until you equip it.", g={{"tk",14387,txt="Talk to Lothos Riftwaker",n2="Lothos Riftwaker: the way into Molten Core once attuned",m=1428,x=26.4,y=24.5,opt=true},{"h",18646,txt="Get The Eye of Divinity",n2="The Eye of Divinity: Molten Core, through Blackrock Mountain",m=1428,x=26.4,y=24.5,n=1,grp=true}}},
  {t="Eris Havenfire", lv=60, n="Equip The Eye of Divinity, then find Eris Havenfire, a ghost on the hillside in the north-west of the Eastern Plaguelands, west of Stratholme's gate (if she does not show, take the Eye off and put it back on). A Warning is only talk; The Balance of Light and Shadow starts the moment you accept it, so prepare first: full mana, Major Mana Potions, Demonic or Dark Runes, mana food or Nightfin Soup, and a stack of Oil of Immolation or Stratholme Holy Water for the skeletons.", g={{"l",60,txt="Reach level 60"},{"a",7621,m=1423,x=17.2,y=12.8,ml=60},{"t",7621,m=1423,x=17.2,y=12.8},{"a",7622,m=1423,x=17.2,y=12.8,ml=60}}},
  {t="The Balance of Light and Shadow", lv=60, n="Save 50 peasants before 15 die (the Death Post by the path counts the dead). They walk from the cave towards Eris in waves, catch diseases and draw skeletons and skeleton archers. Cure the purple-glowing diseases first (Abolish Disease), keep Renew on the hurt ones, Flash Heal the nearly dead, and kill skeletons as they spawn: one Holy Nova of rank 3 or more kills them, oil takes two ticks while they hit you. Shield yourself at the start of each wave; friendly nameplates make the hurt peasants easy to pick out. Friends may buff you before you accept and may heal or cure peasants, but they must not heal or buff you, attack a skeleton or bring a pet once it starts, or a demon appears and kills everyone. Fail, and Eris is gone for a while (players report anything from 15 minutes to two hours); talk to her again when she is back.", g={{"c",7622,txt="The Balance of Light and Shadow"}}},
  {t="Benediction", lv=60, g={{"t",7622,n2="Eris Havenfire: Splinter of Nordrassil",m=1423,x=17.2,y=12.8}}},
  {t="The Eye of Shadow", lv=60, n="The splinter needs The Eye of Shadow as well. Lord Kazzak, a world boss in the Blasted Lands (a raid), always drops it; Manahounds and Doomguard Commanders there drop it rarely (about 3% and 2%), the Hederine of Winterspring hardly ever. It can be traded: check the Auction House first.", g={{"h",18665,txt="Get The Eye of Shadow",m=1419,x=35.5,y=75,n=1,grp=true}}},
  {t="Benediction", lv=60, n="With the Splinter of Nordrassil, The Eye of Divinity and The Eye of Shadow in your bags, use the splinter wherever you are: it becomes Benediction. Use Benediction to turn it into Anathema, the shadow staff, and back (a 30-minute cooldown).", g={{"i",0,txt="Use the Splinter of Nordrassil with both Eyes in your bags: Benediction"}}},
} end)

R:Segment({id="class/priest/blood-of-morphaz",title="Blood of Morphaz",classes={"PRIEST"},min=50,max=52,zone=1447,zoneName="Azshara",why="17,060 XP and 1g55s at 50: Azshara, then Morphaz in the Sunken Temple (group of 5). The item choice may be gone.",folder="Priest"}, function() return {
  {t="Cenarion Aid: High Priest Rohan", lv=50, n="At 50 in Ironforge, High Priest Rohan in the Hall of Mysteries (Mystic Ward) offers Cenarion Aid. Before you leave a city, buy an Ichor of Undeath at the Auction House (a few silver): the third quest asks for one and it drops rarely.", w={{k="zone",name="Ironforge",area=1537},{k="onquest",neg=true,q={8254}}}, f={fa={"Alliance"}}, g={{"l",50,txt="Reach level 50"},{"a",8254,m=1455,x=24.7,y=8.2,ml=50}}},
  {t="Cenarion Aid: Brother Joshua", lv=50, n="At 50, Brother Joshua at the altar of Stormwind's Cathedral of Light offers Cenarion Aid (High Priest Rohan in Ironforge has it too). Before you leave, buy an Ichor of Undeath at the Auction House in the Trade District (a few silver): the third quest asks for one and it drops rarely.", w={{k="onquest",neg=true,q={8254}}}, f={fa={"Alliance"}}, g={{"l",50,txt="Reach level 50"},{"a",8254,m=1453,x=49.5,y=45.2,ml=50}}},
  {t="Cenarion Aid: Ur'kyo", lv=50, n="At 50, Ur'kyo in Orgrimmar's Valley of Spirits offers Cenarion Aid. Before you leave, buy an Ichor of Undeath at the Auction House (a few silver): the third quest asks for one and it drops rarely.", f={fa={"Horde"}}, g={{"l",50,txt="Reach level 50"},{"a",8254,m=1454,x=35.6,y=87.8,ml=50}}},
  {t="Ogtinc", lv=50, n="Ogtinc, a furbolg, lives on the clifftop north-east of the Ruins of Eldarath. Alliance: fly to Talrendis Point; Horde: fly to Valormok. Ride east and leave the road at the fork before the ruins, then follow the northern cliff edge east to him: the naga ruins and the beach below are walled in by cliffs with no way up.", g={{"fp",64,txt="Get the Talrendis Point flight path (Jarrodenus)",m=1447,x=11.9,y=77.6,f={fa={"Alliance"}}},{"fp",44,txt="Get the Valormok flight path (Kroum)",m=1447,x=22,y=49.6,f={fa={"Horde"}}},{"t",8254,m=1447,x=42.4,y=42.6},{"a",8255,m=1447,x=42.4,y=42.6,ml=50}}},
  {t="Of Coursers We Know", lv=50, n="Mosshoof Coursers (level 52-53, not elite) graze all over Azshara, thickest north-east of Ogtinc and south of the mountains; about one in three drops a Healthy Courser Gland, so plan on a dozen kills for four. They enrage at 30% health: finish them fast. Killing them costs no Cenarion Circle reputation. Keep any Ichor of Undeath you loot.", g={{"o",8255,i=1,txt="Healthy Courser Gland x4",m=1447,x=52.1,y=35.4}}},
  {t="Ogtinc", lv=50, g={{"t",8255,m=1447,x=42.4,y=42.6},{"a",8256,m=1447,x=42.4,y=42.6,ml=50}}},
  {t="The Ichor of Undeath", lv=50, n="Carrying an Ichor of Undeath already? It counts at once. Otherwise any undead may drop one, rarely: the Lingering Highborne (level 48) in the Ruins of Eldarath below Ogtinc's cliff drop it about one kill in ten, the highborne ghosts on Azshara's border with Ashenvale (level 45-46) a little less, the Anguished and Suffering Highborne in Winterspring (54-55) about one in eight. The Auction House is usually quicker.", g={{"o",8256,i=1,txt="Ichor of Undeath",m=1447,x=40.3,y=46.1}}},
  {t="Ogtinc", lv=50, g={{"t",8256,m=1447,x=42.4,y=42.6},{"a",8257,m=1447,x=42.4,y=42.6,ml=50}}},
  {t="Morphaz in the Sunken Temple", lv=50, n="Morphaz is a level 52 elite green dragon inside the Sunken Temple, a five-player dungeon: bring a group of five (a level 60 group clears it with ease). Horde: fly to Stonard; Alliance: fly to Nethergarde Keep in the Blasted Lands and ride north. The temple stands in the middle of the Pool of Tears: climb the steps on its south side, swim down through the flooded hall and take the stairs to the portal. Inside, Morphaz only appears late: kill the six troll minibosses on the upper balconies, then Jammal'an the Prophet below them; that wakes the drakes Weaver and Dreamscythe in the Pit of Sacrifice, and killing both brings Morphaz and Hazzas. The pair patrols together and cannot be split: pull them into a hallway and have the tank face them away from the group (breath and a knockback). Loot him in a party, not a raid group: the blood always drops.", g={{"o",8257,i=1,txt="Blood of Morphaz",n2="Blood of Morphaz: the Sunken Temple entrance",m=1435,x=69,y=54,grp=true}}},
  {t="Greta Mosshoof", lv=50, n="Greta Mosshoof is at the Emerald Sanctuary in southern Felwood. Horde: fly to Bloodvenom Post and ride south-east; Alliance: fly to Astranaar in Ashenvale and ride north into Felwood. She takes the blood for experience and gold. Look at the reward window before you hand in: Classic let you pick Blessed Prayer Beads, Circle of Hope or Woestave, and Forever's notes say that choice may be gone.", g={{"t",8257,m=1448,x=51.2,y=82.1}}},
} end)

R:Segment({id="class/priest/confounding-flash-and-contingency-plan",title="Confounding Flash and Contingency Plan",faction="Alliance",races={"Gnome"},classes={"PRIEST"},min=10,max=20,zone=1455,zoneName="Ironforge",why="The Gnome priest spells, new in Forever: Confounding Flash at 10, Contingency Plan at 20. Free, no objectives.",spells={1277455,1277462},spellNames={"Confounding Flash","Contingency Plan"},folder="Priest"}, function() return {
  {t="Confounding Flash: Maxan Anvol", lv=10, n="At 10, Maxan Anvol, the priest trainer inside the Thunderbrew Distillery in Kharanos, hands you a Confounding Flash letter for High Priestess Mims in Ironforge. Kharanos is on the road up to the city.", w={{k="zone",name="Dun Morogh",area=1},{k="onquest",neg=true,q={94817,94821,94822,94823,94824,94825,94826}}}, g={{"l",10,txt="Reach level 10"},{"tk",1226,txt="Talk to Maxan Anvol",n2="Maxan Anvol: take his Confounding Flash letter",m=1426,x=47.3,y=52.2}}},
  {t="Confounding Flash: Priestess Josetta", lv=10, n="At 10 in Elwynn Forest, Priestess Josetta, upstairs in the Lion's Pride Inn in Goldshire, hands you a Confounding Flash letter for High Priestess Mims in Ironforge.", w={{k="zone",name="Elwynn Forest",area=12},{k="onquest",neg=true,q={94817,94821,94822,94823,94824,94825,94826}}}, g={{"l",10,txt="Reach level 10"},{"tk",377,txt="Talk to Priestess Josetta",n2="Priestess Josetta: take her Confounding Flash letter",m=1429,x=43.3,y=65.7}}},
  {t="Confounding Flash: High Priestess Laurena", lv=10, n="At 10 in Stormwind, High Priestess Laurena at the altar of the Cathedral of Light hands you a Confounding Flash letter for High Priestess Mims in Ironforge (the Deeprun Tram from the Dwarven District).", w={{k="zone",name="Stormwind City",area=1519},{k="onquest",neg=true,q={94817,94821,94822,94823,94824,94825,94826}}}, g={{"l",10,txt="Reach level 10"},{"tk",376,txt="Talk to High Priestess Laurena",n2="High Priestess Laurena: take her Confounding Flash letter",m=1453,x=49.5,y=44.6}}},
  {t="Confounding Flash: High Priestess Mims", lv=10, n="At 10, go to High Priestess Mims in the Hall of Mysteries, Ironforge's Mystic Ward (north-west of the city), right beside High Priest Rohan: she gives Confounding Flash and takes it back at once. No letter needed. Confounding Flash confuses up to five enemies around you for 3 seconds (any damage wakes them) on a 2-minute cooldown: time to step back and heal, or to run.", w={{k="onquest",neg=true,q={94817,94821,94822,94823,94824,94825,94826}}}, g={{"l",10,txt="Reach level 10"},{"a",94817,m=1455,x=24.6,y=10,ml=10},{"t",94817,n2="High Priestess Mims: Confounding Flash",m=1455,x=24.6,y=10}}},
  {t="Confounding Flash: Maxan's letter", lv=10, n="Follow the road up from Kharanos into Ironforge and to the Mystic Ward: High Priestess Mims in the Hall of Mysteries takes the letter and teaches Confounding Flash.", w={{k="onquest",q={94824}}}, g={{"t",94824,n2="High Priestess Mims: Confounding Flash",m=1455,x=24.6,y=10}}},
  {t="Confounding Flash: Josetta's letter", lv=10, n="Hand the letter to High Priestess Mims in the Hall of Mysteries, Ironforge's Mystic Ward: the Deeprun Tram from Stormwind's Dwarven District.", w={{k="onquest",q={94822}}}, g={{"t",94822,n2="High Priestess Mims: Confounding Flash",m=1455,x=24.6,y=10}}},
  {t="Confounding Flash: Laurena's letter", lv=10, n="Hand the letter to High Priestess Mims in the Hall of Mysteries, Ironforge's Mystic Ward: the Deeprun Tram from Stormwind's Dwarven District.", w={{k="onquest",q={94821}}}, g={{"t",94821,n2="High Priestess Mims: Confounding Flash",m=1455,x=24.6,y=10}}},
  {t="Confounding Flash: a letter from another trainer", lv=10, n="Any Confounding Flash letter goes to High Priestess Mims in the Hall of Mysteries, Ironforge's Mystic Ward.", w={{k="onquest",q={94823}}}, g={{"t",94823,n2="High Priestess Mims: Confounding Flash",m=1455,x=24.6,y=10}}},
  {t="Confounding Flash: a letter from another trainer", lv=10, n="Any Confounding Flash letter goes to High Priestess Mims in the Hall of Mysteries, Ironforge's Mystic Ward.", w={{k="onquest",q={94825}}}, g={{"t",94825,n2="High Priestess Mims: Confounding Flash",m=1455,x=24.6,y=10}}},
  {t="Confounding Flash: a letter from another trainer", lv=10, n="Any Confounding Flash letter goes to High Priestess Mims in the Hall of Mysteries, Ironforge's Mystic Ward.", w={{k="onquest",q={94826}}}, g={{"t",94826,n2="High Priestess Mims: Confounding Flash",m=1455,x=24.6,y=10}}},
  {t="Contingency Plan: High Priestess Laurena", lv=20, n="At 20 in Stormwind, High Priestess Laurena at the altar of the Cathedral of Light hands you a Contingency Plan letter for High Priestess Mims in Ironforge (the Deeprun Tram from the Dwarven District).", w={{k="zone",name="Stormwind City",area=1519},{k="onquest",neg=true,q={94818,94819,94820}}}, g={{"l",20,txt="Reach level 20"},{"tk",376,txt="Talk to High Priestess Laurena",n2="High Priestess Laurena: take her Contingency Plan letter",m=1453,x=49.5,y=44.6}}},
  {t="Contingency Plan: High Priestess Mims", lv=20, n="At 20, High Priestess Mims in the Hall of Mysteries teaches Contingency Plan with a quest she gives and takes back at once. Contingency Plan wards a friend for 30 seconds: if they drop below 35% health, they get a shield and a heal over time at once (it stacks with Renew and Power Word: Shield). 5-minute cooldown.", w={{k="onquest",neg=true,q={94818,94819,94820}}}, g={{"l",20,txt="Reach level 20"},{"a",94818,m=1455,x=24.6,y=10,ml=20},{"t",94818,n2="High Priestess Mims: Contingency Plan",m=1455,x=24.6,y=10}}},
  {t="Contingency Plan: Laurena's letter", lv=20, n="Hand Laurena's letter to High Priestess Mims in the Hall of Mysteries, Ironforge's Mystic Ward: the Deeprun Tram from Stormwind's Dwarven District.", w={{k="onquest",q={94819}}}, g={{"t",94819,n2="High Priestess Mims: Contingency Plan",m=1455,x=24.6,y=10}}},
  {t="Contingency Plan: a letter from another trainer", lv=20, n="Any Contingency Plan letter goes to High Priestess Mims in the Hall of Mysteries, Ironforge's Mystic Ward.", w={{k="onquest",q={94820}}}, g={{"t",94820,n2="High Priestess Mims: Contingency Plan",m=1455,x=24.6,y=10}}},
} end)

R:Segment({id="class/priest/desperate-prayer-and-chastise",title="Desperate Prayer and Chastise",faction="Alliance",races={"Dwarf"},classes={"PRIEST"},min=10,max=20,zone=1455,zoneName="Ironforge",why="The Dwarf priest spells: Desperate Prayer at 10, Chastise (new in Forever) at 20. Free, no objectives.",spells={13908,1277331},spellNames={"Desperate Prayer","Chastise (Dwarves)"},folder="Priest"}, function() return {
  {t="Desperate Prayer: Maxan Anvol", lv=10, n="At 10, Maxan Anvol, the priest trainer inside the Thunderbrew Distillery in Kharanos, hands you a Desperate Prayer letter for High Priest Rohan. Kharanos is on the road up to Ironforge.", w={{k="zone",name="Dun Morogh",area=1},{k="onquest",neg=true,q={5634,5635,5636,5637,5638,5639,5640}}}, g={{"l",10,txt="Reach level 10"},{"tk",1226,txt="Talk to Maxan Anvol",n2="Maxan Anvol: take his Desperate Prayer letter",m=1426,x=47.3,y=52.2}}},
  {t="Desperate Prayer: Priestess Josetta", lv=10, n="At 10 in Elwynn Forest, Priestess Josetta, upstairs in the Lion's Pride Inn in Goldshire, hands you a Desperate Prayer letter for High Priest Rohan in Ironforge (the Deeprun Tram from Stormwind's Dwarven District).", w={{k="zone",name="Elwynn Forest",area=12},{k="onquest",neg=true,q={5634,5635,5636,5637,5638,5639,5640}}}, g={{"l",10,txt="Reach level 10"},{"tk",377,txt="Talk to Priestess Josetta",n2="Priestess Josetta: take her Desperate Prayer letter",m=1429,x=43.3,y=65.7}}},
  {t="Desperate Prayer: Nara Meideros", lv=10, n="At 10 in Stormwind, Nara Meideros, the priest trainer in the Park (the night elf quarter on the city's west side), hands you a Desperate Prayer letter for High Priest Rohan in Ironforge. High Priestess Laurena in the Cathedral has none for Dwarves.", w={{k="zone",name="Stormwind City",area=1519},{k="onquest",neg=true,q={5634,5635,5636,5637,5638,5639,5640}}}, g={{"l",10,txt="Reach level 10"},{"tk",11397,txt="Talk to Nara Meideros",n2="Nara Meideros: take her Desperate Prayer letter",m=1453,x=35.7,y=63.2}}},
  {t="Desperate Prayer: Laurna Morninglight", lv=10, n="At 10 in Teldrassil, Laurna Morninglight, in the building at the north edge of Dolanaar, hands you a Desperate Prayer letter for High Priest Rohan in Ironforge.", w={{k="zone",name="Teldrassil",area=141},{k="onquest",neg=true,q={5634,5635,5636,5637,5638,5639,5640}}}, g={{"l",10,txt="Reach level 10"},{"tk",3600,txt="Talk to Laurna Morninglight",n2="Laurna Morninglight: take her Desperate Prayer letter",m=1438,x=55.6,y=56.8}}},
  {t="Desperate Prayer: Priestess Alathea", lv=10, n="At 10 in Darnassus, Priestess Alathea, on the upper balcony of the Temple of the Moon beside Tyrande Whisperwind, hands you a Desperate Prayer letter for High Priest Rohan in Ironforge.", w={{k="zone",name="Darnassus",area=1657},{k="onquest",neg=true,q={5634,5635,5636,5637,5638,5639,5640}}}, g={{"l",10,txt="Reach level 10"},{"tk",11401,txt="Talk to Priestess Alathea",n2="Priestess Alathea: take her Desperate Prayer letter",m=1457,x=39.5,y=81.2}}},
  {t="Desperate Prayer: High Priest Rohan", lv=10, n="At 10, go to High Priest Rohan in the Hall of Mysteries, in Ironforge's Mystic Ward (north-west of the city): he gives Desperate Prayer and takes it back at once. No letter needed. Desperate Prayer heals you instantly, costs no mana and has a long cooldown: keep it for emergencies.", w={{k="onquest",neg=true,q={5634,5635,5636,5637,5638,5639,5640}}}, g={{"l",10,txt="Reach level 10"},{"a",5639,m=1455,x=24.7,y=8.2,ml=10},{"t",5639,n2="High Priest Rohan: Desperate Prayer",m=1455,x=24.7,y=8.2}}},
  {t="Desperate Prayer: Maxan's letter", lv=10, n="Follow the road up from Kharanos into Ironforge and west to the Mystic Ward: High Priest Rohan in the Hall of Mysteries takes the letter and teaches Desperate Prayer. The letter tells you to head to Stormwind, but the one who wants you is Rohan in Ironforge.", w={{k="onquest",q={5637}}}, g={{"t",5637,n2="High Priest Rohan: Desperate Prayer",m=1455,x=24.7,y=8.2}}},
  {t="Desperate Prayer: Josetta's letter", lv=10, n="Hand the letter to High Priest Rohan in the Hall of Mysteries, Ironforge's Mystic Ward: the Deeprun Tram from Stormwind's Dwarven District.", w={{k="onquest",q={5635}}}, g={{"t",5635,n2="High Priest Rohan: Desperate Prayer",m=1455,x=24.7,y=8.2}}},
  {t="Desperate Prayer: Nara's letter", lv=10, n="Hand the letter to High Priest Rohan in the Hall of Mysteries, Ironforge's Mystic Ward: the Deeprun Tram from Stormwind's Dwarven District.", w={{k="onquest",q={5638}}}, g={{"t",5638,n2="High Priest Rohan: Desperate Prayer",m=1455,x=24.7,y=8.2}}},
  {t="Desperate Prayer: Laurna's letter", lv=10, n="Hand the letter to High Priest Rohan in the Hall of Mysteries, Ironforge's Mystic Ward: from Teldrassil, the boat from Rut'theran Village to Auberdine, the boat to Menethil Harbor and the road north through the Wetlands and Loch Modan (or the boat to Stormwind Harbor and the Deeprun Tram).", w={{k="onquest",q={5636}}}, g={{"t",5636,n2="High Priest Rohan: Desperate Prayer",m=1455,x=24.7,y=8.2}}},
  {t="Desperate Prayer: Alathea's letter", lv=10, n="Hand the letter to High Priest Rohan in the Hall of Mysteries, Ironforge's Mystic Ward: its text says Stormwind, but Rohan is in Ironforge. From Darnassus, the portal down to Rut'theran Village, the boat to Auberdine, then Menethil Harbor and the road north (or Stormwind Harbor and the Deeprun Tram).", w={{k="onquest",q={5640}}}, g={{"t",5640,n2="High Priest Rohan: Desperate Prayer",m=1455,x=24.7,y=8.2}}},
  {t="Desperate Prayer: an old letter", lv=10, n="This letter also goes to High Priest Rohan in the Hall of Mysteries, Ironforge's Mystic Ward.", w={{k="onquest",q={5634}}}, g={{"t",5634,n2="High Priest Rohan: Desperate Prayer",m=1455,x=24.7,y=8.2}}},
  {t="Chastise: High Priestess Laurena", lv=20, n="At 20 in Stormwind, High Priestess Laurena at the altar of the Cathedral of Light hands you a Chastise letter for High Priest Rohan in Ironforge (the Deeprun Tram from the Dwarven District).", w={{k="zone",name="Stormwind City",area=1519},{k="onquest",neg=true,q={5641,5645,5647}}}, g={{"l",20,txt="Reach level 20"},{"tk",376,txt="Talk to High Priestess Laurena",n2="High Priestess Laurena: take her Chastise letter",m=1453,x=49.5,y=44.6}}},
  {t="Chastise: Priestess Alathea", lv=20, n="At 20 in Darnassus, Priestess Alathea, on the upper balcony of the Temple of the Moon beside Tyrande Whisperwind, hands you a Chastise letter for High Priest Rohan in Ironforge.", w={{k="zone",name="Darnassus",area=1657},{k="onquest",neg=true,q={5641,5645,5647}}}, g={{"l",20,txt="Reach level 20"},{"tk",11401,txt="Talk to Priestess Alathea",n2="Priestess Alathea: take her Chastise letter",m=1457,x=39.5,y=81.2}}},
  {t="Chastise: High Priest Rohan", lv=20, n="At 20, High Priest Rohan in the Hall of Mysteries teaches Chastise with a quest he gives and takes back at once. Forever renamed it from A Lack of Fear: Chastise damages a humanoid and roots it for 2 seconds (instant, 2-minute cooldown), and every priest now trains Fear Ward.", w={{k="onquest",neg=true,q={5641,5645,5647}}}, g={{"l",20,txt="Reach level 20"},{"a",5641,m=1455,x=24.7,y=8.2,ml=20},{"t",5641,n2="High Priest Rohan: Chastise",m=1455,x=24.7,y=8.2}}},
  {t="Chastise: Laurena's letter", lv=20, n="Hand Laurena's letter to High Priest Rohan in the Hall of Mysteries, Ironforge's Mystic Ward: he teaches Chastise.", w={{k="onquest",q={5645}}}, g={{"t",5645,n2="High Priest Rohan: Chastise",m=1455,x=24.7,y=8.2}}},
  {t="Chastise: Alathea's letter", lv=20, n="Hand Alathea's letter to High Priest Rohan in the Hall of Mysteries, Ironforge's Mystic Ward: from Darnassus, the boats via Rut'theran Village and Auberdine to Menethil Harbor, then the road north through the Wetlands and Loch Modan (or the boat to Stormwind Harbor and the Deeprun Tram).", w={{k="onquest",q={5647}}}, g={{"t",5647,n2="High Priest Rohan: Chastise",m=1455,x=24.7,y=8.2}}},
} end)

R:Segment({id="class/priest/divine-grace-and-feedback",title="Divine Grace and Feedback",faction="Alliance",races={"Human"},classes={"PRIEST"},min=10,max=20,zone=1453,zoneName="Stormwind City",why="The Human priest spells: Divine Grace at 10 (new in Forever), Feedback at 20. Free, no objectives.",spells={1277370,13896},spellNames={"Divine Grace","Feedback"},folder="Priest"}, function() return {
  {t="Divine Grace: Priestess Josetta", lv=10, n="At 10, Priestess Josetta, upstairs in the Lion's Pride Inn in Goldshire, hands you a letter for High Priestess Laurena. Goldshire is on the road north to Stormwind, so it costs no detour.", w={{k="zone",name="Elwynn Forest",area=12},{k="onquest",neg=true,q={94773,94774,94775,94776,94777,94778,94779}}}, g={{"l",10,txt="Reach level 10"},{"tk",377,txt="Talk to Priestess Josetta",n2="Priestess Josetta: take her Divine Grace letter",m=1429,x=43.3,y=65.7}}},
