  {t="Divine Grace: Laurna's letter", lv=10, n="Hand Laurna's letter to High Priestess Laurena at the altar of Stormwind's Cathedral of Light (from Teldrassil: the boat from Rut'theran Village to Auberdine, then the boat to Stormwind Harbor): she teaches Divine Grace.", w={{k="onquest",q={94775}}}, g={{"t",94775,n2="High Priestess Laurena: Divine Grace",m=1453,x=49.5,y=44.6}}},
  {t="Divine Grace: a letter from another trainer", lv=10, n="Any Divine Grace letter goes to High Priestess Laurena at the altar of the Cathedral of Light.", w={{k="onquest",q={94776}}}, g={{"t",94776,n2="High Priestess Laurena: Divine Grace",m=1453,x=49.5,y=44.6}}},
  {t="Divine Grace: a letter from another trainer", lv=10, n="Any Divine Grace letter goes to High Priestess Laurena at the altar of the Cathedral of Light.", w={{k="onquest",q={94777}}}, g={{"t",94777,n2="High Priestess Laurena: Divine Grace",m=1453,x=49.5,y=44.6}}},
  {t="Divine Grace: a letter from another trainer", lv=10, n="Any Divine Grace letter goes to High Priestess Laurena at the altar of the Cathedral of Light.", w={{k="onquest",q={94778}}}, g={{"t",94778,n2="High Priestess Laurena: Divine Grace",m=1453,x=49.5,y=44.6}}},
  {t="Divine Grace: a letter from another trainer", lv=10, n="Any Divine Grace letter goes to High Priestess Laurena at the altar of the Cathedral of Light.", w={{k="onquest",q={94779}}}, g={{"t",94779,n2="High Priestess Laurena: Divine Grace",m=1453,x=49.5,y=44.6}}},
  {t="Feedback: High Priest Rohan", lv=20, n="At 20 in Ironforge, High Priest Rohan in the Hall of Mysteries (Mystic Ward) hands you a letter for High Priestess Laurena in Stormwind. The Deeprun Tram from Tinker Town takes you there.", w={{k="zone",name="Ironforge",area=1537},{k="onquest",neg=true,q={5676,5677,5678}}}, g={{"l",20,txt="Reach level 20"},{"tk",11406,txt="Talk to High Priest Rohan",n2="High Priest Rohan: take his Arcane Feedback letter",m=1455,x=24.7,y=8.2}}},
  {t="Feedback: Priestess Alathea", lv=20, n="At 20 in Darnassus, Priestess Alathea, on the upper balcony of the Temple of the Moon beside Tyrande Whisperwind, hands you a letter for High Priestess Laurena in Stormwind.", w={{k="zone",name="Darnassus",area=1657},{k="onquest",neg=true,q={5676,5677,5678}}}, g={{"l",20,txt="Reach level 20"},{"tk",11401,txt="Talk to Priestess Alathea",n2="Priestess Alathea: take her Arcane Feedback letter",m=1457,x=39.5,y=81.2}}},
  {t="Feedback: High Priestess Laurena", lv=20, n="At 20, High Priestess Laurena at the altar of the Cathedral of Light teaches Feedback with a quest she gives and takes back at once.", w={{k="onquest",neg=true,q={5676,5677,5678}}}, g={{"l",20,txt="Reach level 20"},{"a",5676,m=1453,x=49.5,y=44.6,ml=20},{"t",5676,n2="High Priestess Laurena: Feedback",m=1453,x=49.5,y=44.6}}},
  {t="Feedback: Rohan's letter", lv=20, n="Hand Rohan's letter to High Priestess Laurena at the altar of Stormwind's Cathedral of Light (the Deeprun Tram from Tinker Town in Ironforge): she teaches Feedback.", w={{k="onquest",q={5677}}}, g={{"t",5677,n2="High Priestess Laurena: Feedback",m=1453,x=49.5,y=44.6}}},
  {t="Feedback: Alathea's letter", lv=20, n="Hand Alathea's letter to High Priestess Laurena at the altar of Stormwind's Cathedral of Light (from Darnassus: the portal down to Rut'theran Village, the boat to Auberdine, then the boat to Stormwind Harbor): she teaches Feedback.", w={{k="onquest",q={5678}}}, g={{"t",5678,n2="High Priestess Laurena: Feedback",m=1453,x=49.5,y=44.6}}},
