R:Segment({id="class/priest/priest-robes-alliance",title="Priest Robes at 5 (Alliance)",faction="Alliance",races={"Human","Dwarf","Gnome","NightElf"},classes={"PRIEST"},min=5,max=6,zone=1429,zoneName="Elwynn Forest",why="A free uncommon robe at 5: heal and fortify a wounded guard near your first town.",items={16605,16604},folder="Priest"}, function() return {
  {t="In Favor of the Light", lv=5, n="At 5, Priestess Anetta, the priest trainer inside Northshire Abbey, sends you to Priestess Josetta in Goldshire. Train Lesser Heal (Rank 2) from Anetta while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank.", f={r={"Human"}}, g={{"l",5,txt="Reach level 5"},{"a",5623,m=1429,x=49.8,y=39.5,ml=5}}},
  {t="Priestess Josetta", lv=5, n="Follow the road south out of Northshire Valley to Goldshire. Priestess Josetta is upstairs in the Lion's Pride Inn.", f={r={"Human"}}, g={{"t",5623,m=1429,x=43.3,y=65.7},{"a",5624,m=1429,x=43.3,y=65.7,ml=5},{"tr",0,txt="Visit your class trainer",n2="Lesser Heal (Rank 2), if Anetta did not teach it yet"}}},
  {t="Guard Roberts", lv=5, n="Guard Roberts kneels by a tree on the lake shore east of Goldshire, off the road: walk along the shore, the minimap misses him from the road. Cast Lesser Heal (Rank 2) on him first, then Power Word: Fortitude. Rank 1 of Lesser Heal does not count; drag Rank 2 onto your bar from the spellbook (or cast both from the spellbook if an action bar addon gets in the way). He walks off once both land and is back in about 3 minutes.", f={r={"Human"}}, g={{"o",5624,i=1,txt="Heal and fortify Guard Roberts",m=1429,x=48.1,y=68}}},
  {t="Priestess Josetta", lv=5, n="Back upstairs in the Lion's Pride Inn: Josetta gives you Friar's Robes of the Light.", f={r={"Human"}}, g={{"t",5624,m=1429,x=43.3,y=65.7}}},
  {t="In Favor of the Light", lv=5, n="At 5, Branstock Khalder, the priest trainer inside Anvilmar in Coldridge Valley, sends you to Maxan Anvol in Kharanos. Train Lesser Heal (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank.", f={r={"Dwarf","Gnome"}}, g={{"l",5,txt="Reach level 5"},{"a",5626,m=1426,x=28.6,y=66.4,ml=5}}},
  {t="Maxan Anvol", lv=5, n="Take the tunnel north-east out of Coldridge Valley and follow the road east to Kharanos. Maxan Anvol is inside the Thunderbrew Distillery.", f={r={"Dwarf","Gnome"}}, g={{"t",5626,m=1426,x=47.3,y=52.2},{"a",5625,m=1426,x=47.3,y=52.2,ml=5},{"tr",0,txt="Visit your class trainer",n2="Lesser Heal (Rank 2), if Branstock did not teach it yet"}}},
  {t="Mountaineer Dolf", lv=5, n="Mountaineer Dolf kneels on a ridge between two low walls just south of Kharanos, across the road from the hunter pet trainer: if the road starts going downhill, you have passed him. Cast Lesser Heal (Rank 2) on him first, then Power Word: Fortitude; he speaks after each spell. Rank 1 of Lesser Heal does not count.", f={r={"Dwarf","Gnome"}}, g={{"o",5625,i=1,txt="Heal and fortify Mountaineer Dolf",m=1426,x=45.8,y=54.6}}},
  {t="Maxan Anvol", lv=5, n="Back inside the Thunderbrew Distillery: Maxan gives you Friar's Robes of the Light.", f={r={"Dwarf","Gnome"}}, g={{"t",5625,m=1426,x=47.3,y=52.2}}},
  {t="In Favor of Elune", lv=5, n="At 5, Shanda, the priest trainer on the second level of Aldrassil, the great tree in Shadowglen, sends you to Laurna Morninglight in Dolanaar. Train Lesser Heal (Rank 2) from her while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank.", f={r={"NightElf"}}, g={{"l",5,txt="Reach level 5"},{"a",5622,m=1438,x=59.2,y=40.4,ml=5}}},
  {t="Laurna Morninglight", lv=5, n="Leave Shadowglen by the ramp and follow the road south-west to Dolanaar. Laurna Morninglight is in the building at the north edge of the village.", f={r={"NightElf"}}, g={{"t",5622,m=1438,x=55.6,y=56.8},{"a",5621,m=1438,x=55.6,y=56.8,ml=5},{"tr",0,txt="Visit your class trainer",n2="Lesser Heal (Rank 2), if Shanda did not teach it yet"}}},
  {t="Sentinel Shaya", lv=5, n="Sentinel Shaya kneels on the rocks at the edge of Lake Al'Ameth, about 100 yards south of Dolanaar, with no quest mark over her. Cast Lesser Heal (Rank 2) on her first, then Power Word: Fortitude; she runs off toward the lake once both land and is back in about 5 minutes. Rank 1 of Lesser Heal does not count.", f={r={"NightElf"}}, g={{"o",5621,i=1,txt="Heal and fortify Sentinel Shaya",m=1438,x=57.2,y=63.5}}},
  {t="Laurna Morninglight", lv=5, n="Back at the north edge of Dolanaar: Laurna gives you the Moon Robes of Elune.", f={r={"NightElf"}}, g={{"t",5621,m=1438,x=55.6,y=56.8}}},
} end)

R:Segment({id="class/priest/priest-robes-horde",title="Priest Robes at 5 (Horde)",faction="Horde",races={"Troll","Scourge"},classes={"PRIEST"},min=5,max=6,zone=1411,zoneName="Durotar",why="A free uncommon robe at 5: heal and fortify a wounded guard near your first town.",items={16606,16607},folder="Priest"}, function() return {
  {t="In Favor of Spirituality", lv=5, n="At 5, Ken'jai, the priest trainer in the Den in the middle of the Valley of Trials, sends you to Tai'jin in Razor Hill. Train Lesser Heal (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank.", f={r={"Troll"}}, g={{"l",5,txt="Reach level 5"},{"a",5649,m=1411,x=42.4,y=68.8,ml=5}}},
