  {t="Grunt Kor'ja", lv=5, n="Grunt Kor'ja kneels behind a group of rocks just off the road, a short walk south of Razor Hill. Cast Lesser Heal (Rank 2) on her first, then Power Word: Fortitude. Rank 1 of Lesser Heal does not count; drag Rank 2 onto your bar from the spellbook. She leaves once both land and is back in about 5 minutes.", f={r={"Troll"}}, g={{"o",5648,i=1,txt="Heal and fortify Grunt Kor'ja",m=1411,x=53.1,y=46.5}}},
  {t="Tai'jin", lv=5, n="Back in the Razor Hill barracks: Tai'jin gives you the Juju Hex Robes.", f={r={"Troll"}}, g={{"t",5648,m=1411,x=54.3,y=42.9}}},
  {t="In Favor of Darkness", lv=5, n="At 5, Dark Cleric Duesten, the priest trainer in the chapel of Deathknell, sends you to Dark Cleric Beryl in Brill. Train Lesser Heal (Rank 2) from him while you are here: it opens at level 4 for 1 silver, and the next quest needs exactly that rank.", f={r={"Scourge"}}, g={{"l",5,txt="Reach level 5"},{"a",5651,m=1420,x=31.1,y=66,ml=5}}},
  {t="Dark Cleric Beryl", lv=5, n="Follow the road east out of Deathknell to Brill. Dark Cleric Beryl is upstairs in the inn, Gallows' End Tavern.", f={r={"Scourge"}}, g={{"t",5651,m=1420,x=61.6,y=52.2},{"a",5650,m=1420,x=61.6,y=52.2,ml=5},{"tr",0,txt="Visit your class trainer",n2="Lesser Heal (Rank 2), if Duesten did not teach it yet"}}},
  {t="Deathguard Kel", lv=5, n="Deathguard Kel kneels, half-dead, beside the north gate of Brill's graveyard, a short walk north of the inn. Cast Lesser Heal (Rank 2) on him first, then Power Word: Fortitude: Fortitude first does not count, nor does Rank 1 of Lesser Heal. If an addon gets in the way, cast both from the spellbook.", f={r={"Scourge"}}, g={{"o",5650,i=1,txt="Heal and fortify Deathguard Kel",m=1420,x=59.2,y=46.5}}},
  {t="Dark Cleric Beryl", lv=5, n="Back upstairs in the Brill inn: Beryl gives you the Acolyte's Sacrificial Robes.", f={r={"Scourge"}}, g={{"t",5650,m=1420,x=61.6,y=52.2}}},
} end)

