  {t="Starshards: Laurna Morninglight", lv=10, n="At 10, Laurna Morninglight, the priest trainer in the building at the north edge of Dolanaar, hands you Returning Home, a letter for Priestess Alathea in Darnassus. Dolanaar is on the road west to Darnassus.", w={{k="zone",name="Teldrassil",area=141},{k="onquest",neg=true,q={5627,5628,5629,5630,5631,5632,5633}}}, g={{"l",10,txt="Reach level 10"},{"tk",3600,txt="Talk to Laurna Morninglight",n2="Laurna Morninglight: take Returning Home",m=1438,x=55.6,y=56.8}}},
  {t="Starshards: Priestess Josetta", lv=10, n="At 10 in Elwynn Forest, Priestess Josetta, upstairs in the Lion's Pride Inn in Goldshire, hands you Returning Home, a letter for Priestess Alathea in Darnassus.", w={{k="zone",name="Elwynn Forest",area=12},{k="onquest",neg=true,q={5627,5628,5629,5630,5631,5632,5633}}}, g={{"l",10,txt="Reach level 10"},{"tk",377,txt="Talk to Priestess Josetta",n2="Priestess Josetta: take Returning Home",m=1429,x=43.3,y=65.7}}},
  {t="Starshards: Maxan Anvol", lv=10, n="At 10 in Dun Morogh, Maxan Anvol, the priest trainer inside the Thunderbrew Distillery in Kharanos, hands you Returning Home, a letter for Priestess Alathea in Darnassus.", w={{k="zone",name="Dun Morogh",area=1},{k="onquest",neg=true,q={5627,5628,5629,5630,5631,5632,5633}}}, g={{"l",10,txt="Reach level 10"},{"tk",1226,txt="Talk to Maxan Anvol",n2="Maxan Anvol: take Returning Home",m=1426,x=47.3,y=52.2}}},
  {t="Starshards: Brother Joshua", lv=10, n="At 10 in Stormwind, Brother Joshua at the altar of the Cathedral of Light hands you Returning Home, a letter for Priestess Alathea in Darnassus. Nara Meideros in the Park has the same letter.", w={{k="zone",name="Stormwind City",area=1519},{k="onquest",neg=true,q={5627,5628,5629,5630,5631,5632,5633}}}, g={{"l",10,txt="Reach level 10"},{"tk",5489,txt="Talk to Brother Joshua",n2="Brother Joshua: take Returning Home",m=1453,x=49.5,y=45.2}}},
  {t="Starshards: Braenna Flintcrag", lv=10, n="At 10 in Ironforge, Braenna Flintcrag in the Hall of Mysteries (Mystic Ward) hands you Returning Home, a letter for Priestess Alathea in Darnassus.", w={{k="zone",name="Ironforge",area=1537},{k="onquest",neg=true,q={5627,5628,5629,5630,5631,5632,5633}}}, g={{"l",10,txt="Reach level 10"},{"tk",5142,txt="Talk to Braenna Flintcrag",n2="Braenna Flintcrag: take Returning Home",m=1455,x=24.4,y=9.2}}},
  {t="Starshards: Priestess Alathea", lv=10, n="At 10, go to Priestess Alathea on the upper balcony of the Temple of the Moon, at the south end of Darnassus: take the ramp up from the temple floor; she stands beside Tyrande Whisperwind. Stars of Elune is given and taken back at once and teaches Starshards. No letter needed. Forever made Starshards hit much harder, on a 30-second cooldown.", w={{k="onquest",neg=true,q={5627,5628,5629,5630,5631,5632,5633}}}, g={{"l",10,txt="Reach level 10"},{"a",5627,m=1457,x=39.5,y=81.2,ml=10},{"t",5627,n2="Priestess Alathea: Starshards",m=1457,x=39.5,y=81.2}}},
  {t="Starshards: Laurna's letter", lv=10, n="Take the road west from Dolanaar into Darnassus and go up to the upper balcony of the Temple of the Moon, beside Tyrande Whisperwind: Priestess Alathea takes Returning Home and teaches Starshards.", w={{k="onquest",q={5629}}}, g={{"t",5629,n2="Priestess Alathea: Starshards",m=1457,x=39.5,y=81.2}}},
  {t="Starshards: Josetta's letter", lv=10, n="Returning Home goes to Priestess Alathea, on the upper balcony of the Temple of the Moon in Darnassus, beside Tyrande Whisperwind: take the boat from Stormwind Harbor (or Menethil Harbor) to Auberdine, the boat on to Rut'theran Village, then the portal up into Darnassus.", w={{k="onquest",q={5628}}}, g={{"t",5628,n2="Priestess Alathea: Starshards",m=1457,x=39.5,y=81.2}}},
  {t="Starshards: Maxan's letter", lv=10, n="Returning Home goes to Priestess Alathea, on the upper balcony of the Temple of the Moon in Darnassus, beside Tyrande Whisperwind: take the boat from Stormwind Harbor (or Menethil Harbor) to Auberdine, the boat on to Rut'theran Village, then the portal up into Darnassus.", w={{k="onquest",q={5630}}}, g={{"t",5630,n2="Priestess Alathea: Starshards",m=1457,x=39.5,y=81.2}}},
  {t="Starshards: Joshua's letter", lv=10, n="Returning Home goes to Priestess Alathea, on the upper balcony of the Temple of the Moon in Darnassus, beside Tyrande Whisperwind: take the boat from Stormwind Harbor (or Menethil Harbor) to Auberdine, the boat on to Rut'theran Village, then the portal up into Darnassus.", w={{k="onquest",q={5631}}}, g={{"t",5631,n2="Priestess Alathea: Starshards",m=1457,x=39.5,y=81.2}}},
