  {t="Starshards: Braenna's letter", lv=10, n="Returning Home goes to Priestess Alathea, on the upper balcony of the Temple of the Moon in Darnassus, beside Tyrande Whisperwind: take the boat from Stormwind Harbor (or Menethil Harbor) to Auberdine, the boat on to Rut'theran Village, then the portal up into Darnassus.", w={{k="onquest",q={5633}}}, g={{"t",5633,n2="Priestess Alathea: Starshards",m=1457,x=39.5,y=81.2}}},
  {t="Elune's Grace: High Priestess Laurena", lv=20, n="At 20 in Stormwind, High Priestess Laurena at the altar of the Cathedral of Light hands you an Elune's Grace letter for Priestess Alathea in Darnassus. Nara Meideros in the Park has the same letter.", w={{k="zone",name="Stormwind City",area=1519},{k="onquest",neg=true,q={5672,5673,5674,5675}}}, g={{"l",20,txt="Reach level 20"},{"tk",376,txt="Talk to High Priestess Laurena",n2="High Priestess Laurena: take her Elune's Grace letter",m=1453,x=49.5,y=44.6}}},
  {t="Elune's Grace: High Priest Rohan", lv=20, n="At 20 in Ironforge, High Priest Rohan in the Hall of Mysteries (Mystic Ward) hands you an Elune's Grace letter for Priestess Alathea in Darnassus.", w={{k="zone",name="Ironforge",area=1537},{k="onquest",neg=true,q={5672,5673,5674,5675}}}, g={{"l",20,txt="Reach level 20"},{"tk",11406,txt="Talk to High Priest Rohan",n2="High Priest Rohan: take his Elune's Grace letter",m=1455,x=24.7,y=8.2}}},
  {t="Elune's Grace: Priestess Alathea", lv=20, n="At 20, Priestess Alathea on the upper balcony of the Temple of the Moon, beside Tyrande Whisperwind, teaches Elune's Grace with a quest she gives and takes back at once. In Forever, Elune's Grace halves the chance for melee and ranged attacks to hit you for 15 seconds or until three attacks miss.", w={{k="onquest",neg=true,q={5672,5673,5674,5675}}}, g={{"l",20,txt="Reach level 20"},{"a",5672,m=1457,x=39.5,y=81.2,ml=20},{"t",5672,n2="Priestess Alathea: Elune's Grace",m=1457,x=39.5,y=81.2}}},
  {t="Elune's Grace: Laurena's letter", lv=20, n="Hand Laurena's letter to Priestess Alathea, on the upper balcony of the Temple of the Moon in Darnassus, beside Tyrande Whisperwind: the boat from Stormwind Harbor (or Menethil Harbor) to Auberdine, the boat on to Rut'theran Village, then the portal up into Darnassus.", w={{k="onquest",q={5673}}}, g={{"t",5673,n2="Priestess Alathea: Elune's Grace",m=1457,x=39.5,y=81.2}}},
  {t="Elune's Grace: Nara's letter", lv=20, n="Hand Nara's letter to Priestess Alathea, on the upper balcony of the Temple of the Moon in Darnassus, beside Tyrande Whisperwind: the boat from Stormwind Harbor (or Menethil Harbor) to Auberdine, the boat on to Rut'theran Village, then the portal up into Darnassus.", w={{k="onquest",q={5674}}}, g={{"t",5674,n2="Priestess Alathea: Elune's Grace",m=1457,x=39.5,y=81.2}}},
