} end)

R:Segment({id="class/priest/touch-of-weakness-and-dark-sacrifice",title="Touch of Weakness and Dark Sacrifice",faction="Horde",races={"Scourge"},classes={"PRIEST"},min=10,max=20,zone=1458,zoneName="Undercity",why="The Undead priest spells: Touch of Weakness at 10, Dark Sacrifice (new in Forever) at 20. Free, no objectives.",spells={2652,1277324},spellNames={"Touch of Weakness","Dark Sacrifice"},folder="Priest"}, function() return {
  {t="Touch of Weakness: Tai'jin", lv=10, n="At 10 in Durotar, Tai'jin, the priest trainer inside the barracks of Razor Hill, hands you a Touch of Weakness letter for Aelthalyste in the Undercity.", w={{k="zone",name="Durotar",area=14},{k="onquest",neg=true,q={5658,5660,5661,5662,5663}}}, g={{"l",10,txt="Reach level 10"},{"tk",3706,txt="Talk to Tai'jin",n2="Tai'jin: take his Touch of Weakness letter",m=1411,x=54.3,y=42.9}}},
  {t="Touch of Weakness: Ur'kyo", lv=10, n="At 10 in Orgrimmar, Ur'kyo in the Valley of Spirits hands you a Touch of Weakness letter for Aelthalyste in the Undercity. The zeppelin to Tirisfal Glades leaves from the tower outside Orgrimmar's front gate.", w={{k="zone",name="Orgrimmar",area=1637},{k="onquest",neg=true,q={5658,5660,5661,5662,5663}}}, g={{"l",10,txt="Reach level 10"},{"tk",6018,txt="Talk to Ur'kyo",n2="Ur'kyo: take his Touch of Weakness letter",m=1454,x=35.6,y=87.8}}},
  {t="Touch of Weakness: Var'jun", lv=10, n="At 10 in Mulgore, Var'jun, just south-west of Bloodhoof Village, hands you a Touch of Weakness letter for Aelthalyste in the Undercity.", w={{k="zone",name="Mulgore",area=215},{k="onquest",neg=true,q={5658,5660,5661,5662,5663}}}, g={{"l",10,txt="Reach level 10"},{"tk",11407,txt="Talk to Var'jun",n2="Var'jun: take the Touch of Weakness letter",m=1412,x=46.2,y=62.3}}},
  {t="Touch of Weakness: Miles Welsh", lv=10, n="At 10 in Thunder Bluff, Miles Welsh, the priest trainer in the cave under Spirit Rise, hands you a Touch of Weakness letter for Aelthalyste in the Undercity.", w={{k="zone",name="Thunder Bluff",area=1638},{k="onquest",neg=true,q={5658,5660,5661,5662,5663}}}, g={{"l",10,txt="Reach level 10"},{"tk",3044,txt="Talk to Miles Welsh",n2="Miles Welsh: take his Touch of Weakness letter",m=1456,x=25.3,y=15.3}}},
  {t="Touch of Weakness: Aelthalyste", lv=10, n="At 10, go to Aelthalyste, the priest trainer in the Undercity's War Quarter: she gives Touch of Weakness and takes it back at once. No letter needed. From Brill, follow the road south to the ruined city of Lordaeron; the Undercity's lifts are at the back of the throne room. Touch of Weakness strikes the next melee attacker for Shadow damage and lowers its melee attack power for 2 minutes.", w={{k="onquest",neg=true,q={5658,5660,5661,5662,5663}}}, g={{"l",10,txt="Reach level 10"},{"a",5658,m=1458,x=49.3,y=17.1,ml=10},{"t",5658,n2="Aelthalyste: Touch of Weakness",m=1458,x=49.3,y=17.1}}},
  {t="Touch of Weakness: Tai'jin's letter", lv=10, n="Hand the letter to Aelthalyste in the Undercity's War Quarter: the zeppelin from the tower outside Orgrimmar lands in Tirisfal Glades, a short walk from the Undercity.", w={{k="onquest",q={5660}}}, g={{"t",5660,n2="Aelthalyste: Touch of Weakness",m=1458,x=49.3,y=17.1}}},
  {t="Touch of Weakness: Var'jun's letter", lv=10, n="Hand the letter to Aelthalyste in the Undercity's War Quarter: travel to Orgrimmar and take the zeppelin to Tirisfal Glades.", w={{k="onquest",q={5661}}}, g={{"t",5661,n2="Aelthalyste: Touch of Weakness",m=1458,x=49.3,y=17.1}}},
  {t="Touch of Weakness: Ur'kyo's letter", lv=10, n="Hand the letter to Aelthalyste in the Undercity's War Quarter: the zeppelin from the tower outside Orgrimmar lands in Tirisfal Glades.", w={{k="onquest",q={5662}}}, g={{"t",5662,n2="Aelthalyste: Touch of Weakness",m=1458,x=49.3,y=17.1}}},
  {t="Touch of Weakness: Miles Welsh's letter", lv=10, n="Hand the letter to Aelthalyste in the Undercity's War Quarter: travel to Orgrimmar and take the zeppelin to Tirisfal Glades.", w={{k="onquest",q={5663}}}, g={{"t",5663,n2="Aelthalyste: Touch of Weakness",m=1458,x=49.3,y=17.1}}},
  {t="Dark Sacrifice: Ur'kyo", lv=20, n="At 20 in Orgrimmar, Ur'kyo in the Valley of Spirits hands you a Dark Sacrifice letter for Aelthalyste in the Undercity.", w={{k="zone",name="Orgrimmar",area=1637},{k="onquest",neg=true,q={5679,5644,5646}}}, g={{"l",20,txt="Reach level 20"},{"tk",6018,txt="Talk to Ur'kyo",n2="Ur'kyo: take his Dark Sacrifice letter",m=1454,x=35.6,y=87.8}}},
  {t="Dark Sacrifice: Miles Welsh", lv=20, n="At 20 in Thunder Bluff, Miles Welsh in the cave under Spirit Rise hands you a Dark Sacrifice letter for Aelthalyste in the Undercity.", w={{k="zone",name="Thunder Bluff",area=1638},{k="onquest",neg=true,q={5679,5644,5646}}}, g={{"l",20,txt="Reach level 20"},{"tk",3044,txt="Talk to Miles Welsh",n2="Miles Welsh: take his Dark Sacrifice letter",m=1456,x=25.3,y=15.3}}},
  {t="Dark Sacrifice: Aelthalyste", lv=20, n="At 20, Aelthalyste in the War Quarter teaches Dark Sacrifice with a quest she gives and takes back at once (its text still speaks of Devouring Plague, which every priest now learns from the trainer).", w={{k="onquest",neg=true,q={5679,5644,5646}}}, g={{"l",20,txt="Reach level 20"},{"a",5679,m=1458,x=49.3,y=17.1,ml=20},{"t",5679,n2="Aelthalyste: Dark Sacrifice",m=1458,x=49.3,y=17.1}}},
  {t="Dark Sacrifice: Ur'kyo's letter", lv=20, n="Hand the letter to Aelthalyste in the Undercity's War Quarter: the zeppelin from the tower outside Orgrimmar lands in Tirisfal Glades.", w={{k="onquest",q={5646}}}, g={{"t",5646,n2="Aelthalyste: Dark Sacrifice",m=1458,x=49.3,y=17.1}}},
  {t="Dark Sacrifice: Miles Welsh's letter", lv=20, n="Hand the letter to Aelthalyste in the Undercity's War Quarter: travel to Orgrimmar and take the zeppelin to Tirisfal Glades.", w={{k="onquest",q={5644}}}, g={{"t",5644,n2="Aelthalyste: Dark Sacrifice",m=1458,x=49.3,y=17.1}}},
} end)

R:Segment({id="class/rogue/blade-of-cunning-alliance",title="Blade of Cunning (Alliance)",faction="Alliance",classes={"ROGUE"},min=10,max=12,zone=1429,zoneName="Elwynn Forest",why="A dagger at 10 from your home town's rogue quests.",items={7298},folder="Rogue"}, function() return {
  {t="Seek out SI: 7", lv=10, n="At 10 Keryn Sylvius, the rogue trainer upstairs in the Lion's Pride Inn in Goldshire, gives you a package for Master Mathias Shaw in Stormwind. Train Pick Pocket if you lack it: this chain needs it.", f={r={"Human","Skyborne"}}, g={{"l",10,txt="Reach level 10"},{"a",2205,m=1429,x=43.9,y=65.9,ml=10}}},
  {t="Master Mathias Shaw", lv=10, n="Head north to Stormwind. Shaw stands upstairs in the SI:7 building in Old Town (the quest says the Barracks; it means SI:7).", f={r={"Human","Skyborne"}}, g={{"t",2205,m=1453,x=78.3,y=70.7},{"a",2206,m=1453,x=78.3,y=70.7,ml=10}}},
  {t="Defias Dockmaster", lv=10, n="The Defias Dockmaster (level 10, a goblin) works in the dock house at Jerod's Landing, on the river at Elwynn's southern edge, south of Goldshire. Stealth in and Pick Pocket him from behind: the schedule never drops from his corpse. Do not open with Sap or a fight: he calls in three waves of bodyguards. Keep away from the fireplaces in the house; they burn you out of stealth. He is back 2 to 5 minutes after a death.", f={r={"Human","Skyborne"}}, g={{"o",2206,i=1,txt="Pick Pocket the Defias Dockmaster for the Defias Shipping Schedule",m=1429,x=48.1,y=87}}},
  {t="Back to Mathias Shaw", lv=10, f={r={"Human","Skyborne"}}, g={{"t",2206,n2="Master Mathias Shaw, SI:7",m=1453,x=78.3,y=70.7}}},
  {t="Road to Salvation", lv=10, n="At 10 Hogral Bakkan, the rogue trainer in the Thunderbrew Distillery in Kharanos, sends you to Hulfdan Blackbeard in Ironforge.", f={r={"Dwarf","Gnome"}}, g={{"l",10,txt="Reach level 10"},{"a",2218,m=1426,x=47.6,y=52.6,ml=10}}},
  {t="Hulfdan Blackbeard", lv=10, n="Hulfdan Blackbeard is in the Forlorn Cavern, the rogue quarter in the north of Ironforge: go into the building with a shady dealer outside and down the stairs.", f={r={"Dwarf","Gnome"}}, g={{"t",2218,m=1455,x=52,y=14.8},{"a",2238,m=1455,x=52,y=14.8,ml=10}}},
  {t="Onin MacHammar", lv=10, n="Head west to Gnomeregan. Beside the road to its entrance stands a wooden spiral tower: Onin waits stealthed on the top platform, next to a level 10 Leper Gnome, so you only see him up close.", f={r={"Dwarf","Gnome"}}, g={{"t",2238,m=1426,x=25.2,y=44.5},{"a",2239,m=1426,x=25.2,y=44.5,ml=10}}},
  {t="Back to Hulfdan", lv=10, f={r={"Dwarf","Gnome"}}, g={{"t",2239,n2="Hulfdan Blackbeard, Ironforge",m=1455,x=52,y=14.8}}},
  {t="The Apple Falls", lv=10, n="At 10 Jannok Breezesong, the rogue trainer in the Dolanaar inn, gives you a rose for Syurna in Darnassus. If you lose the rose, abandon the quest and take it again.", f={r={"NightElf"}}, g={{"l",10,txt="Reach level 10"},{"a",2241,m=1438,x=56.4,y=60.1,ml=10}}},
  {t="Syurna", lv=10, n="Head west to Darnassus. Syurna is below ground in the Cenarion Enclave: the way down is the opening at the foot of the split tree left of the Arch Druid's tree, near the nightsaber trainer. Her map marker shows above ground.", f={r={"NightElf"}}, g={{"t",2241,m=1457,x=37,y=21.9},{"a",2242,m=1457,x=37,y=21.9,ml=10}}},
  {t="Sethir the Ancient", lv=10, n="Sethir the Ancient (level 12 satyr) lives out on a great branch north of the Oracle Glade: go through the V-shaped gap in the wall north of the glade and out along the branch. Pick his pocket for the journal; killing him does not give it, and a fight brings out three Minions of Sethir. He walks between the main branch and a side branch: wait stealthed at the far end of the main branch and pick him from behind when he comes back. Then Sprint away. He is back 8 1/2 minutes after a death.", f={r={"NightElf"}}, g={{"o",2242,i=1,txt="Pick Pocket Sethir the Ancient for Sethir's Journal",m=1438,x=37.1,y=22.8}}},
  {t="Back to Syurna", lv=10, f={r={"NightElf"}}, g={{"t",2242,n2="Syurna, Darnassus",m=1457,x=37,y=21.9}}},
} end)

R:Segment({id="class/rogue/blade-of-cunning-horde",title="Blade of Cunning (Horde)",faction="Horde",classes={"ROGUE"},min=10,max=13,zone=1411,zoneName="Durotar",why="A dagger at 10 from your home town's rogue quests.",items={7298},folder="Rogue"}, function() return {
  {t="Therzok", lv=10, n="At 10 Kaplak, the rogue trainer in Razor Hill, sends you to Therzok in Orgrimmar. It is only a pointer: an Orc already in Orgrimmar can skip it and take The Shattered Hand from Therzok straight away.", f={r={"Orc"}}, g={{"l",10,txt="Reach level 10"},{"a",1859,m=1411,x=52,y=43.7,ml=10}}},
  {t="The Shattered Hand", lv=10, n="Therzok stands in the Cleft of Shadow, the canyon under the Valley of Strength. Trolls: take The Shattered Hand from him at 10.", f={r={"Orc","Troll"}}, g={{"l",10,txt="Reach level 10"},{"t",1859,m=1454,x=42.7,y=53.5,f={r={"Orc"}}},{"a",1963,m=1454,x=42.7,y=53.5,ml=10}}},
  {t="Tazan", lv=10, n="Tazan (level 13, not elite) is a troll pirate on the Merchant Coast south of Ratchet: he walks the fenced hill path between the lower pirate camp by the beached ship and the upper camp by a big tree. Fight him at the foot of the hill, away from the camps. He always drops his satchel and is back 4 1/2 minutes after a death; one satchel per kill, so two rogues need two kills. Hand the satchel in unopened: picking its lock now destroys it and you must kill him again.", f={r={"Orc","Troll"}}, g={{"o",1963,i=1,txt="Tazan's Satchel",n2="Tazan's Satchel: Tazan",m=1413,x=63.1,y=44.3}}},
  {t="Back to Therzok", lv=10, f={r={"Orc","Troll"}}, g={{"t",1963,n2="Therzok, Cleft of Shadow",m=1454,x=42.7,y=53.5},{"a",1858,m=1454,x=42.7,y=53.5,ml=10}}},
  {t="Tazan's Key", lv=10, n="Therzok hands the satchel back: now open it. Gamon (level 12) kneels by the innkeeper in the inn in the Valley of Strength; stealth up and pick his pocket for Tazan's Key (do not kill him: the key almost never drops). Players often kill him, so you may wait up to 5 minutes for him. Then use the key on Tazan's Satchel in your bags. If you have trained Pick Lock, you can pick the satchel's lock instead.", f={r={"Orc","Troll"}}, g={{"h",7208,txt="Get Tazan's Key",m=1454,x=54,y=68,n=1},{"o",1858,i=1,txt="Use Tazan's Satchel",n2="Tazan's Satchel, once you have the key",m=1454,x=54,y=68},{"o",1858,i=1,txt="Tazan's Logbook",n2="Tazan's Logbook, from the satchel",m=1454,x=54,y=68}}},
  {t="Therzok's reward", lv=10, f={r={"Orc","Troll"}}, g={{"t",1858,n2="Therzok, Cleft of Shadow",m=1454,x=42.7,y=53.5}}},
  {t="Mennet Carkad", lv=10, n="At 10 Marion Call, the rogue trainer upstairs in the Gallows' End Tavern in Brill, sends you to Mennet Carkad in the Undercity.", f={r={"Scourge"}}, g={{"l",10,txt="Reach level 10"},{"a",1885,m=1420,x=61.8,y=52,ml=10}}},
  {t="The Rogues' Quarter", lv=10, n="Mennet Carkad stands in the Rogues' Quarter.", f={r={"Scourge"}}, g={{"t",1885,m=1458,x=83.5,y=69.1},{"a",1886,m=1458,x=83.5,y=69.1,ml=10}}},
  {t="Astor Hadren", lv=10, n="Astor Hadren (level 13) walks the road between the Sepulcher and the Undercity, north of the Sepulcher. He looks like a friendly traveller with no quest mark. Talk to him and pick both of his answers: he turns hostile. Kill him for the letter (it always drops). Fight him away from guards, who can take the kill and leave no loot; only one rogue per kill gets the letter. He is back 5 minutes after a death.", f={r={"Scourge"}}, g={{"o",1886,i=1,txt="Astor's Letter of Introduction",n2="Astor's Letter of Introduction: Astor Hadren",m=1421,x=49.7,y=32.2}}},
  {t="Back to Mennet Carkad", lv=10, f={r={"Scourge"}}, g={{"t",1886,n2="Mennet Carkad, Rogues' Quarter",m=1458,x=83.5,y=69.1},{"a",1898,m=1458,x=83.5,y=69.1,ml=10}}},
  {t="Andron Gant", lv=10, n="Andron Gant is in the Apothecarium, in its biggest room, where two huge guards watch a small bridge. His ledger is on the bookshelf in the back room behind him, not the shelf on the wall next to him.", f={r={"Scourge"}}, g={{"t",1898,m=1458,x=54.8,y=76.3},{"a",1899,m=1458,x=54.8,y=76.3,ml=10},{"o",1899,i=1,txt="Andron's Ledger",n2="Andron's Ledger: Andron's Bookshelf",m=1458,x=55.4,y=77}}},
  {t="Mennet and Varimathras", lv=10, n="Mennet sends the ledger on to Varimathras, the big demon in the middle of the Hall of the Dark Lady in the Royal Quarter, past its elite guards; the way in is the passage off the Apothecarium. If you lose the ledger, take another from Andron's bookshelf.", f={r={"Scourge"}}, g={{"t",1899,n2="Mennet Carkad, Rogues' Quarter",m=1458,x=83.5,y=69.1},{"a",1978,m=1458,x=83.5,y=69.1,ml=10},{"t",1978,n2="Varimathras, Royal Quarter",m=1458,x=56.2,y=92.2}}},
} end)

R:Segment({id="class/rogue/certificate-of-thievery",title="Certificate of Thievery",faction="Alliance",classes={"ROGUE"},min=16,max=20,zone=1453,zoneName="Stormwind City",why="Your first lockpicking job at 16: Lucius's lockbox at Alther's Mill, for SI:7.",items={7907},folder="Rogue"}, function() return {
  {t="SI:7 (Goldshire)", lv=16, n="At 16 Keryn Sylvius, the rogue trainer upstairs in the Lion's Pride Inn in Goldshire, sends you to Renzik \"The Shiv\" in Stormwind. Taking it shuts out the other towns' breadcrumbs.", f={r={"Human","Skyborne"}}, g={{"l",16,txt="Reach level 16"},{"a",2300,m=1429,x=43.9,y=65.9,ml=16}}},
  {t="To Hulfdan! (Kharanos)", lv=16, n="At 16 Hogral Bakkan in the Thunderbrew Distillery in Kharanos sends you to Hulfdan Blackbeard in Ironforge's Forlorn Cavern.", f={r={"Dwarf","Gnome"}}, g={{"l",16,txt="Reach level 16"},{"a",2299,m=1426,x=47.6,y=52.6,ml=16}}},
  {t="Hulfdan Blackbeard", lv=16, n="Hulfdan is in the house with a shady dealer outside, in the Forlorn Cavern, down the stairs. Then fly or take the Deeprun Tram to Stormwind.", f={r={"Dwarf","Gnome"}}, g={{"t",2299,m=1455,x=52,y=14.8},{"a",2298,m=1455,x=52,y=14.8,ml=16}}},
  {t="Erion Shadewhisper (Dolanaar)", lv=16, n="At 16 Jannok Breezesong in the Dolanaar inn sends you to Erion Shadewhisper in Darnassus.", f={r={"NightElf"}}, g={{"l",16,txt="Reach level 16"},{"a",2259,m=1438,x=56.4,y=60.1,ml=16}}},
  {t="Erion Shadewhisper", lv=16, n="Erion stands in the Cenarion Enclave. Then the boat from Rut'theran Village to Auberdine, and the boat from Auberdine to Stormwind Harbor.", f={r={"NightElf"}}, g={{"t",2259,n2="Erion Shadewhisper, Darnassus",m=1457,x=34.5,y=25.9},{"a",2260,m=1457,x=34.5,y=25.9,ml=16}}},
  {t="Renzik \"The Shiv\"", lv=16, n="Renzik stands upstairs in the SI:7 building in Old Town, behind the rogue trainers. Before you leave: if you lack Pick Lock, Lord Tony Romano in the SI:7 building teaches it; Lockpicking is the test of the next quest.", g={{"t",2300,m=1453,x=78.3,y=71.1,f={r={"Human","Skyborne"}}},{"t",2298,m=1453,x=78.3,y=71.1,f={r={"Dwarf","Gnome"}}},{"t",2260,m=1453,x=78.3,y=71.1,f={r={"NightElf"}}},{"a",2281,m=1453,x=78.3,y=71.1,ml=16}}},
  {t="Lucius", lv=16, n="Head east through Elwynn Forest into Redridge, or fly to Lakeshire. Lucius stands on a crate on one of the Lakeshire docks, south of town; he gives you Thieves' Tools with the job (Gerald Crawley in Lakeshire sells more). Pick Lock does not work without the tools in your bags.", g={{"t",2281,m=1433,x=23,y=52},{"a",2282,m=1433,x=23,y=52,ml=16}}},
  {t="Alther's Mill", lv=16, n="Alther's Mill stands east of Lakeshire, up off the road; Blackrock orcs roam near it. Inside, the Practice Lockboxes come back almost at once: pick them until Lucius's Lockbox opens for you (about 25 Lockpicking). Your Lockpicking cap rises 5 per level, so a low character may stall. Some boxes are trapped (a frost trap, for one); the skill still goes up. On Forever level 20 spiders wander near the boxes: clear them first or bring a friend. The lockbox always holds the token and is back two seconds after use. Practise on while it still gives skill: the next class quest needs about 75.", g={{"o",2282,i=1,txt="Token of Thievery",n2="Token of Thievery: Lucius's Lockbox",m=1433,x=47,y=44.7}}},
  {t="Back to Lucius", lv=16, g={{"t",2282,n2="Lucius: Certificate of Thievery",m=1433,x=23,y=52}}},
} end)

R:Segment({id="class/rogue/plundering-the-plunderers",title="Plundering the Plunderers",faction="Horde",classes={"ROGUE"},min=16,max=20,zone=1454,zoneName="Orgrimmar",why="Ten Thistle Tea, the rogue energy drink, from the Horde lockpicking jobs at 16.",items={7676},folder="Rogue"}, function() return {
  {t="To Orgrimmar!", lv=16, n="At 16 Kaplak, the rogue trainer in Razor Hill, sends you to Shenthul in Orgrimmar.", f={r={"Orc","Troll","Skyborne"}}, g={{"l",16,txt="Reach level 16"},{"a",2380,m=1411,x=52,y=43.7,ml=16}}},
  {t="Find the Shattered Hand", lv=16, n="At 16 Mennet Carkad in the Rogues' Quarter sends you to Shenthul in Orgrimmar. Take Fenwick Thatros from him too; it is done in Silverpine Forest at the end of this guide.", f={r={"Scourge"}}, g={{"l",16,txt="Reach level 16"},{"a",2378,m=1458,x=83.5,y=69.1,ml=16},{"a",1998,m=1458,x=83.5,y=69.1,ml=16}}},
  {t="Shenthul and Zando'zan", lv=16, n="Undead take the zeppelin from the towers outside the Undercity to Durotar. Shenthul and Zando'zan stand in the Cleft of Shadow, the canyon under the Valley of Strength. Train Pick Lock from Shenthul (or any rogue trainer) now if you lack it: this job is a lockpicking test.", g={{"t",2380,m=1454,x=43,y=53.7,f={r={"Orc","Troll","Skyborne"}}},{"t",2378,m=1454,x=43,y=53.7,f={r={"Scourge"}}},{"a",2379,m=1454,x=43,y=53.7,ml=16},{"t",2379,m=1454,x=42.7,y=53},{"a",2382,m=1454,x=42.7,y=53,ml=16}}},
  {t="Wrenix the Wretched", lv=16, n="Fly or walk to Ratchet on the Barrens coast. Wrenix stands in a small shed near the bank, up the hill to the left before the docks. His Gizmotronic Apparatus beside him hands out what the job needs: take an E.C.A.C. and Thieves' Tools (Pick Lock does not work without the tools in your bags).", g={{"fp",80,txt="Get the Ratchet flight path (Bragok)",m=1413,x=63.1,y=37.2,opt=true},{"t",2382,m=1413,x=63.1,y=36.3},{"a",2381,m=1413,x=63.1,y=36.3,ml=16},{"h",7970,txt="Buy E.C.A.C. (Wrenix's Gizmotronic Apparatus)",n2="E.C.A.C.: Wrenix's Gizmotronic Apparatus",m=1413,x=63.1,y=36.3,n=1},{"h",5060,txt="Buy Thieves' Tools (Wrenix's Gizmotronic Apparatus)",m=1413,x=63.1,y=36.3,n=1}}},
  {t="Southsea Treasure", lv=16, n="Follow the coast south from Ratchet to the first beached pirate ship, the Tide Razor, and climb aboard up its bow. On the middle deck the Buccaneer's Strongboxes come back fast: pick them until your Lockpicking is about 30 (a few are trapped with a frost nova or turn you into a rat; picking still works as a rat). Keep picking while they still give skill: the poisons job at 20 ends at a lockbox that needs about 75, and these boxes are the closest practice. Then go down to the bottom hold and pick the lock of The Jewel of the Southsea: it is empty, but opening it calls a giant level 50 Polly into the next room. Stay stealthed, put the E.C.A.C. on your action bar, target Polly and use it: the parrot shrinks to level 18. Kill it for the Southsea Treasure.", g={{"o",2381,i=1,txt="Southsea Treasure",n2="Southsea Treasure: Polly, after the E.C.A.C.",m=1413,x=64.8,y=45.5}}},
  {t="Back to Wrenix", lv=16, g={{"t",2381,n2="Wrenix the Wretched: ten Thistle Tea",m=1413,x=63.1,y=36.3}}},
  {t="Fenwick Thatros", lv=16, n="Take the zeppelin from Orgrimmar to the Undercity and head south into Silverpine. Fenwick Thatros (level 16) stands alone on the old ferry dock on Lordamere Lake, north-east of the Sepulcher. His Uppercut knocks you back, so do not fight him at the dock's edge. He always drops his head and is back 4 1/2 minutes after a death.", f={r={"Scourge"}}, g={{"o",1998,i=1,txt="Fenwick's Head",n2="Fenwick's Head: Fenwick Thatros",m=1421,x=59.6,y=33.9}}},
  {t="Mennet Carkad", lv=16, n="If you have no Thieves' Tools left, ask Estelle Gendry, the outfitter in the Rogues' Quarter.", f={r={"Scourge"}}, g={{"t",1998,n2="Mennet Carkad, Rogues' Quarter",m=1458,x=83.5,y=69.1},{"a",1999,m=1458,x=83.5,y=69.1,ml=16}}},
  {t="Ambermill", lv=16, n="The Kirin Tor keep their reports in walled Ambermill, in south-east Silverpine. Facing the town hall, take the building on the right: the Ambermill Strongbox is in a corner room upstairs (any Lockpicking opens it; the Thieves' Tools must be in your bags). Three casters of level 19-20 guard that floor and see through stealth, one walking in and out of the strongbox room: time it or fight them one at a time.", f={r={"Scourge"}}, g={{"o",1999,i=1,txt="Dalaran Status Report",n2="Dalaran Status Report: Ambermill Strongbox",m=1421,x=63.7,y=65.2}}},
  {t="Back to Mennet", lv=16, f={r={"Scourge"}}, g={{"t",1999,n2="Mennet Carkad, Rogues' Quarter",m=1458,x=83.5,y=69.1}}},
} end)

R:Segment({id="class/rogue/poisons-alliance",title="Poisons (Alliance)",faction="Alliance",classes={"ROGUE"},min=20,max=24,zone=1453,zoneName="Stormwind City",why="Forever teaches Poisons through this chain, not the trainer; the Thistle Tea recipe comes with it.",spells={2842},spellNames={"Poisons"},items={18160,8432},folder="Rogue"}, function() return {
  {t="Mathias and the Defias", lv=20, n="At 20 Master Mathias Shaw, upstairs in the SI:7 building in Old Town, sends you to Agent Kearnen in Westfall. This chain is how you learn Poisons on Forever, so do not skip it.", g={{"l",20,txt="Reach level 20"},{"a",2360,m=1453,x=78.3,y=70.7,ml=20}}},
  {t="Agent Kearnen", lv=20, n="Kearnen hides stealthed against the west side of a big tree with two small trees in front of it, just north of Klaven Mortwake's Defias tower in the far east of Westfall, by the Duskwood border. Read Kearnen's Journal for the tower's layout if you like.", g={{"t",2360,m=1436,x=68.5,y=70.1},{"a",2359,m=1436,x=68.5,y=70.1,ml=20}}},
  {t="The Defias Tower Key", lv=20, n="Get the key first. The Malformed Defias Drone (level 23, not elite) starts at the tower entrance and walks a loop around the outside; it is the spiky-haired one trailing yellow sparkles. Stealth up and Pick Pocket it from behind: it always has the key. It hits hard: if stealth breaks, Sprint away. Watch for the pair of Defias Drones that also patrol.", g={{"o",2359,i=2,txt="Pick Pocket the Malformed Defias Drone for the Defias Tower Key",m=1436,x=69.5,y=74}}},
  {t="Klaven's journal", lv=20, n="Sneak up the tower. Defias Tower Patrollers (23) and Sentries (24) guard the floors; an Ambush with a dagger kills them outright if you would rather clear them. Klaven Mortwake, a level 26 elite, waits on the top floor: Sap him, or bring a friend. The Duskwood Chest beside his desk needs Lockpicking of about 70-75 (practise on the boxes at Alther's Mill in Redridge first). A trick: while the Sentries are away, jump from the chair to the lamp to the bookshelf above the chest, step out of stealth and open the chest from there. Opening it poisons you with the Touch of Zanzil, which stops your stealth for a while and lets the drone see you; that is why the key comes first. Then get out.", g={{"o",2359,i=1,txt="Klaven Mortwake's Journal",n2="Klaven Mortwake's Journal: the Duskwood Chest, top floor",m=1436,x=70.4,y=74}}},
  {t="Master Mathias Shaw", lv=20, n="Head north through Elwynn to Stormwind; Mathias Shaw is upstairs in SI:7. He teaches Poisons and gives you the Thistle Tea recipe. Poisons are made, not bought: each batch of Instant Poison takes a Dust of Decay and an Empty Vial, which Jasper Fel and Sloan McCoy sell in Old Town next to SI:7. Buy a stack of each, open Poisons from your spellbook to make them, then use a poison on your weapon.", g={{"t",2359,n2="Master Mathias Shaw: Poisons",m=1453,x=78.3,y=70.7},{"a",2607,m=1453,x=78.3,y=70.7,ml=20}}},
  {t="Doc Mixilpixil", lv=20, n="The Touch of Zanzil still sits on you. Doc Mixilpixil works in the cellar of the SI:7 building: the stairs down are under the stairs to the upper floor, behind Jasper Fel. Target him and type /lay (nothing after it) to be examined, then wait. If he does nothing, abandon the quest, take it again and wait until he asks you to lie down.", g={{"t",2607,m=1453,x=80.1,y=69.9},{"a",2608,m=1453,x=80.1,y=69.9,ml=20},{"c",2608,txt="Diagnosis Complete",n2="/lay with the Doc targeted",m=1453,x=80.1,y=69.9},{"t",2608,m=1453,x=80.1,y=69.9},{"a",2609,m=1453,x=80.1,y=69.9,ml=20}}},
  {t="The cure's ingredients", lv=20, n="All four are in Stormwind. Simple Wildflowers: Bernard or Felicia Gump's flower shop by the Trade District canal. A Leaded Vial: many general goods and alchemy vendors (Keldric Boucher, Jasper Fel and others). A Bronze Tube: the Auction House in the Trade District; the engineering suppliers keep only one and are nearly always sold out, and an engineer can make one. The Spool of Light Chartreuse Silk Thread lies on the floor beside the left end of the counter in The Finest Thread, the tailor's shop on the canals; you can only pick it up with this quest. If you skip the cure, an Anti-Venom (First Aid) or a druid's Cure Poison also clears the Touch of Zanzil.", g={{"h",3421,txt="Buy Simple Wildflowers",n=1},{"h",3372,txt="Buy Leaded Vial",n=1},{"h",4371,txt="Get Bronze Tube",n2="Bronze Tube: the Auction House",m=1453,x=61.2,y=71.3,n=1},{"o",2609,i=4,txt="Spool of Light Chartreuse Silk Thread",m=1453,x=50.6,y=60.1}}},
  {t="Back to Doc Mixilpixil", lv=20, g={{"t",2609,n2="Doc Mixilpixil: Eau de Mixilpixil",m=1453,x=80.1,y=69.9}}},
} end)

R:Segment({id="class/rogue/poisons-horde",title="Poisons (Horde)",faction="Horde",classes={"ROGUE"},min=20,max=26,zone=1454,zoneName="Orgrimmar",why="Forever teaches Poisons through this chain, not the trainer; the Thistle Tea recipe comes with it.",spells={2842},spellNames={"Poisons"},items={18160,8066,8095},folder="Rogue"}, function() return {
  {t="Lockpicking practice", lv=20, n="Gallywix's Lockbox at the end of the tower job needs Lockpicking of about 70-75. Train Pick Lock from Gest or Shenthul in the Cleft of Shadow if you lack it, carry Thieves' Tools, and pick the Buccaneer's Strongboxes on the middle deck of the Tide Razor, the beached pirate ship south of Ratchet: they come back fast. Your cap rises 5 per level.", g={{"l",20,txt="Reach level 20"},{"g",0,txt="Tide Razor",m=1413,x=64.4,y=45.4},{"i",0,txt="Lockpicking about 75: pick the Buccaneer's Strongboxes on the Tide Razor",opt=true}}},
  {t="The Shattered Salute", lv=20, n="Shenthul stands in the Cleft of Shadow, the canyon under the Valley of Strength. Take the quest and wait: he speaks three lines and salutes you. After his third line, target him and type /salute. If it does not count, abandon the quest and take it again. The tower job ahead is built around Ambush, which needs a dagger: if you have none, Kareth, the blade merchant in the Cleft of Shadow, sells a Jambiya.", g={{"a",2460,m=1454,x=43,y=53.7,ml=20},{"c",2460,txt="Shenthul",n2="/salute Shenthul",m=1454,x=43,y=53.7},{"t",2460,m=1454,x=43,y=53.7},{"a",2458,n2="Deep Cover: keep the Flare Gun",m=1454,x=43,y=53.7,ml=20}}},
  {t="Taskmaster Fizzule", lv=20, n="Fly to the Crossroads and head north to the Venture Co. tower above the Sludge Fen. Fizzule stands under a tree east of the tower, outside it, and is hostile until signalled. Target him from about 50 yards and fire the Flare Gun twice, then walk up in front of him and /salute. In any other order he attacks. Lost the Flare Gun? Abandon and retake from Shenthul.", g={{"i",0,txt="Use Flare Gun",n2="Flare Gun, twice, at Fizzule",m=1413,x=55.4,y=5.6},{"t",2458,n2="Taskmaster Fizzule: Fizzule's Whistle",m=1413,x=55.4,y=5.6},{"a",2478,m=1413,x=55.4,y=5.6,ml=20}}},
  {t="Silixiz's Tower Key", lv=20, n="Keep Fizzule's Whistle in your bags and use it on him every time you come near, or he turns hostile. Foreman Silixiz (level 22) walks by the tower: hug the wall, stealth up behind him and Pick Pocket the key. Killing him does not give it; if his pockets are empty, kill him and wait 4 1/2 minutes for him to come back.", g={{"o",2478,i=5,txt="Pick Pocket Foreman Silixiz for Silixiz's Tower Key",m=1413,x=54.8,y=6}}},
  {t="The Venture Co. tower", lv=20, n="Inside, floor by floor (everything comes back after 4 1/2 minutes): the Mutated Venture Co. Drones (level 25) on the ground floor die to one Ambush with a dagger; the Patrollers on the second floor take half their health from a one-point Rupture; the Lookouts on the open third floor from a one-point Eviscerate. Grand Foreman Puzik Gallywix waits on the top floor: a level 23 elite, back 10 minutes after a kill. Open with Ambush (about half his health), then Gouge, Evasion, a healing potion and Thistle Tea; a friend makes it easy. One head per kill. Then pick Gallywix's Lockbox beside him for the cache: it poisons you with the Touch of Zanzil, which weakens your stealth and agility until Serge Hinott cures it.", g={{"o",2478,i=1,txt="Kill Mutated Venture Co. Drone x2",m=1413,x=54.7,y=5.7},{"o",2478,i=3,txt="Kill Venture Co. Patroller x2",m=1413,x=54.7,y=5.7},{"o",2478,i=2,txt="Kill Venture Co. Lookout x2",m=1413,x=54.6,y=5.8},{"o",2478,i=4,txt="Gallywix's Head",n2="Gallywix's Head: Grand Foreman Puzik Gallywix (elite)",m=1413,x=54.8,y=5.6,grp=true},{"o",2478,i=6,txt="Cache of Zanzil's Altered Mixture",n2="Cache of Zanzil's Altered Mixture: Gallywix's Lockbox",m=1413,x=54.8,y=5.6}}},
  {t="Back to Shenthul", lv=20, n="Fly back to Orgrimmar (Ratchet or the Crossroads; dying at the tower and taking the spirit healer's way back to the Crossroads is quicker). Keep Silixiz's Tower Key afterwards. Before you leave the Cleft, buy Dust of Decay and Empty Vials from Rekkul: once Hinott teaches Poisons, each batch of Instant Poison takes one of each.", g={{"t",2478,n2="Shenthul: Recipe: Thistle Tea",m=1454,x=43,y=53.7},{"a",2479,m=1454,x=43,y=53.7,ml=20}}},
  {t="Serge Hinott", lv=20, n="Take the zeppelin from Orgrimmar to the Undercity and follow the road south through Silverpine Forest into Hillsbrad, to Tarren Mill. Serge Hinott works in the building next to the flight path, beside Apothecary Lydon, a wagon outside. If you lost the Sample of Zanzil's Mixture, abandon and retake from Shenthul. Stay beside him for about a minute while he brews the cure; if it never finishes, abandon and retake from him. Then open Poisons from your spellbook to make Instant Poison from Rekkul's dust and vials, and use it on your weapon.", g={{"fp",13,txt="Get the Tarren Mill flight path (Zarise)",m=1424,x=60.1,y=18.6,opt=true},{"t",2479,m=1424,x=61.6,y=19.2},{"a",2480,m=1424,x=61.6,y=19.2,ml=20},{"c",2480,txt="Cure Completed",n2="Wait for the cure"},{"t",2480,n2="Serge Hinott: Poisons",m=1424,x=61.6,y=19.2},{"i",0,txt="Use Hinott's Oil",n2="Hinott's Oil: clears the Touch of Zanzil",m=1424,x=61.6,y=19.2,opt=true}}},
} end)

R:Segment({id="class/rogue/ravenholdt",title="Ravenholdt",classes={"ROGUE"},min=24,max=36,zone=1424,zoneName="Hillsbrad Foothills",why="Opens Ravenholdt Manor, the hidden rogue house in the Alterac hills, and Myrokos's jobs against the Syndicate.",folder="Rogue"}, function() return {
  {t="The Elegant Letter", lv=24, n="At 24 any capital's rogue trainer (Master Mathias Shaw or Osborne the Night Man in Stormwind, Gest or Ormok in Orgrimmar, and the others) has an Elegant Letter from Ravenholdt for you: ask for it in their talk window. Open it: the quest gives you the Seal of Ravenholdt for Fahrad. Learn Detect Traps from your trainer first if you have not; the way in is a test of it.", g={{"l",24,txt="Reach level 24"},{"a",6681,ml=24}}},
  {t="Ravenholdt Manor", lv=24, n="Horde fly to Tarren Mill, Alliance to Southshore. The trail to the manor is hard to see: it starts behind the plateau north of Durnholde Keep, east of Tarren Mill, climbs into the hills and bends twice to a small tunnel. A chest sits in the tunnel: do not open it. Cast Detect Traps near it and walk up close; that is the Rite of Cunning (it comes back after 5 minutes). Opening the chest calls Milton, an elite rogue of about level 32. Through the tunnel lies Ravenholdt Manor: Fahrad is upstairs inside. Do not attack anyone at the manor: it costs Ravenholdt reputation.", g={{"o",6681,i=1,txt="Kill Ravenholdt",n2="Rite of Cunning: Detect Traps beside the tunnel chest",m=1424,x=78.6,y=17.8},{"t",6681,m=1416,x=84.5,y=80.3},{"a",96779,m=1416,x=84.9,y=80.4,ml=24}}},
  {t="Lord Tomas", lv=24, n="Lord Tomas is inside Durnholde Keep, the Syndicate fortress south of the manor; he can stand in any of fifteen spots in the keep, so search. Quick and quiet, says Myrokos. Pick the pockets of the level 20-21 Syndicate Rogues, Shadow Mages and Watchmen on your way: they carry Syndicate Emblems for the guards' repeatable reputation quest.", g={{"o",96779,i=1,txt="Kill Lord Tomas",m=1424,x=79.3,y=46},{"h",17124,txt="Get Syndicate Emblem",m=1424,x=79.3,y=46.4,n=1,opt=true}}},
  {t="Myrokos Silentform", lv=24, g={{"t",96779,m=1416,x=84.9,y=80.4},{"t",6701,n2="Ravenholdt Guard: one emblem each time, 100 reputation",m=1416,x=85.3,y=79.6,opt=true}}},
  {t="What's the Big Idea?", lv=34, n="In your mid 30s Myrokos has two more jobs; take both. Barton leads a Syndicate scouting party at Strahnbrad, in the east of the Alterac Mountains, inside one of the houses with stealthed Syndicate around him. Pick his pocket for the report and do not kill him: he does not drop it. If you are lower than him he sees through stealth; Master of Deception helps, or Distract him, Vanish and come in from behind. Pick Pocket can miss several times in a row.", g={{"l",34,txt="Reach level 34"},{"a",96781,m=1416,x=84.9,y=80.4,ml=24},{"a",96783,m=1416,x=84.9,y=80.4,ml=24},{"o",96781,i=1,txt="Pick Pocket Barton for Barton's Scouting Report",m=1416,x=62.6,y=46.9}}},
  {t="Covert Extraction", lv=34, n="Back to Myrokos; the report sends you after the Perenolde heirlooms. Two towers stand among the Ruins of Alterac, in the middle of the Alterac Mountains, held by ogres: the shield lies in the northern tower, the sword in the southern one, which elite ogres ring and watch from far off. Stay stealthed; nothing guards the heirlooms inside.", g={{"t",96781,m=1416,x=84.9,y=80.4},{"a",96782,m=1416,x=84.9,y=80.4,ml=24},{"o",96782,i=2,txt="Royal Aegis of Perenolde",n2="Royal Aegis of Perenolde, in the northern tower",m=1416,x=41.4,y=40.2},{"o",96782,i=1,txt="Blade of House Perenolde",n2="Blade of House Perenolde, in the southern tower",m=1416,x=38.5,y=58},{"t",96782,m=1416,x=84.9,y=80.4}}},
  {t="A Way In", lv=34, n="Stromgarde Keep in western Arathi is a Syndicate stronghold; to get in you need a uniform. Northfold Manor, in north-western Arathi, is held by Syndicate Highwaymen, Pathstalkers and Mercenaries (level 30-32): find the Syndicate Footlocker there and take the uniform; that ends A Way In.", g={{"t",96783,n2="Syndicate Footlocker, Northfold Manor",m=1417,x=32.3,y=26.6},{"a",96784,n2="Master of Disguise: the Syndicate Uniform",m=1417,x=32.3,y=26.6,f={fa={"Horde"}},ml=24}}},
  {t="Anastasia Miller", lv=34, n="Stromgarde's Syndicate Prowlers and Conjurors are elite (level 35-36): a rogue of 36 can slip past them, but fighting one alone is hard, so stay hidden or bring a friend. Put on the Syndicate Uniform (Master of Disguise hands it to you at the footlocker) to pass as one of them; stealth or suspicious acts can break it. If the footlocker gave you no uniform, Anastasia hands you one with Ain't No Telling. Anastasia Miller is not inside the keep: she stands on a ledge on the outside of the castle wall. Jump across to it from the roof of the house beside the ledge.", g={{"t",96784,m=1417,x=26.8,y=64.4,f={fa={"Horde"}}},{"a",96785,n2="Ain't No Telling",m=1417,x=26.8,y=64.4,ml=24}}},
  {t="Ain't No Telling", lv=34, n="She will not talk without something to bargain with. Her stash is upstairs in a house close to the keep: take the Stolen Funds. If it is already open, wait for it to come back.", g={{"o",96785,i=1,txt="Stolen Funds",n2="Stolen Funds: Anastasia's Stash",m=1417,x=29.5,y=65.1},{"t",96785,m=1417,x=26.8,y=64.4},{"a",96786,n2="The Syndicate Sting",m=1417,x=26.8,y=64.4,ml=24}}},
  {t="The Syndicate Sting", lv=34, n="Falconcrest's men make the handoff at the southern end of Thoradin's Wall, the old wall between Arathi and Hillsbrad. Kill the two guarding the box and take the Intercepted Shipment. Keep the Syndicate Uniform: Myrokos wants it back with the shipment.", g={{"o",96786,i=1,txt="Intercepted Shipment",m=1417,x=15.5,y=43}}},
  {t="Back to Myrokos", lv=34, g={{"t",96786,n2="Myrokos Silentform: 70 silver, 300 Ravenholdt reputation",m=1416,x=84.9,y=80.4}}},
} end)

R:Segment({id="class/rogue/the-azure-key",title="The Azure Key",classes={"ROGUE"},min=50,max=52,zone=1416,zoneName="Alterac Mountains",why="Ravenholdt reputation and experience at 50; Classic's item choice may be gone on Forever.",folder="Rogue"}, function() return {
  {t="A Simple Request (Alliance)", lv=50, n="At 50 Osborne the Night Man in Stormwind's Old Town has it; so do Syurna in Darnassus and Hulfdan Blackbeard in Ironforge.", f={fa={"Alliance"}}, g={{"l",50,txt="Reach level 50"},{"a",8233,m=1453,x=77.4,y=65.3,ml=50}}},
  {t="A Simple Request (Horde)", lv=50, n="At 50 Ormok in the Cleft of Shadow has it; so does Miles Dexter in the Undercity's Rogues' Quarter.", f={fa={"Horde"}}, g={{"l",50,txt="Reach level 50"},{"a",8233,m=1454,x=43.9,y=54.6,ml=50}}},
  {t="Lord Jorach Ravenholdt", lv=50, n="Ravenholdt Manor hides in the hills east of Tarren Mill. Horde fly to Tarren Mill, Alliance to Southshore. The trail starts behind the plateau north of Durnholde Keep, climbs into the hills and runs through a small tunnel into the Alterac Mountains; Lord Jorach is inside the manor. Do not attack anyone at the manor: lost Ravenholdt reputation makes him refuse to speak to you.", g={{"t",8233,m=1416,x=86,y=78.9},{"a",8234,m=1416,x=86,y=78.9,ml=50}}},
  {t="Sealed Azure Bag", lv=50, n="Alliance fly to Talrendis Point, Horde to Valormok. Only the level 50-51 Timbermaw Shamans in the furbolg hills of northern Azshara carry the bag (the level 47-49 furbolgs further south do not): about one kill in thirty drops it. Pick Pocket them instead and you lose no Timbermaw reputation; if you are Unfriendly or better with Timbermaw Hold, mark them At War in your reputation panel first. They cast Lightning Bolt and Lightning Cloud, heal each other and run at low health.", g={{"fp",64,txt="Get the Talrendis Point flight path (Jarrodenus)",m=1447,x=11.9,y=77.6,f={fa={"Alliance"}}},{"fp",44,txt="Get the Valormok flight path (Kroum)",m=1447,x=22,y=49.6,f={fa={"Horde"}}},{"o",8234,i=1,txt="Sealed Azure Bag",n2="Sealed Azure Bag: Timbermaw Shaman",m=1447,x=44.2,y=26.6}}},
  {t="Archmage Xylem", lv=50, n="Sanath Lim-yo, camped below the cliffs just east of Valormok, teleports you up (dismount first); a trail leads to Xylem's tower.", g={{"t",8234,m=1447,x=29.2,y=40.2},{"a",8235,m=1447,x=29.2,y=40.2,ml=50}}},
  {t="Encoded Fragments", lv=50, n="The Forest Oozes (level 52-53, Diseased Slime up close) drop a fragment four times in five: the biggest group, seven of them, is in the Bitter Reaches hills of north-eastern Azshara, four more south-east of Valormok. Pick their pockets before the kill for an extra fragment or two. Killing the Mistwing Ravagers and hippogryphs that share their spots makes more oozes appear.", g={{"o",8235,i=1,txt="Encoded Fragment x10",n2="Encoded Fragment: Forest Ooze",m=1447,x=36.2,y=67.9}}},
  {t="Back to Xylem", lv=50, g={{"t",8235,m=1447,x=29.2,y=40.2},{"a",8236,m=1447,x=29.2,y=40.2,ml=50}}},
  {t="Morphaz in the Sunken Temple", lv=50, n="Morphaz, a level 52 elite green drake, lives deep in the Sunken Temple: a group of five, level 50-54. The temple stands in the Pool of Tears; climb into the sunken building, swim down through it and follow the passage to the portal. Horde: fly to Stonard; Alliance: fly to Nethergarde Keep and ride on. He is not there when you arrive: first kill the six troll guardians (elites of 50-52) on the platforms around the upper ring, which opens the way down (the left-hand ramp from the entrance) to Jammal'an the Prophet in the Pit of Sacrifice. Jammal'an's death brings out two drakes, Weaver and Dreamscythe; when both are dead, Morphaz and Hazzas appear together and fight as a pair. Their Acid Breath is nature damage: nature protection potions help; poisons and Blind do not work on them. The key always drops. Hunters, Priests and Mages of 50 need Morphaz too: one clear serves them all.", g={{"o",8236,i=1,txt="Azure Key",n2="Azure Key: Morphaz, inside the temple",m=1435,x=69.9,y=53.6,grp=true}}},
  {t="Lord Ravenholdt", lv=50, n="Look at the reward window before you hand in: Classic offered the Duskbat Drape, the Ebon Mask or the Whisperwalk Boots, and Forever's notes say the choice may be gone.", g={{"t",8236,m=1416,x=86,y=78.9}}},
} end)

R:Segment({id="class/rogue/the-eye-of-bhossca",title="The Eye of Bhossca",classes={"ROGUE"},min=30,max=35,zone=1421,zoneName="Silverpine Forest",why="The Ruby-Adorned Blade, C's payment for a solo job inside the Scarlet Monastery.",items={277246},folder="Rogue"}, function() return {
  {t="C's dead drop", lv=30, n="C's next job comes by letter: once you are level 30 and have done the horn job, visit any capital city and C's letter arrives in the mailbox; only then does the Dead Drop near Pyrewood Village, in southern Silverpine just south of Shadowfang Keep, offer it. The quest data lists a minimum of 25, but players get the letter, and the job, at 30.", g={{"l",30,txt="Reach level 30"},{"a",78676,m=1421,x=47.1,y=71,ml=30}}},
  {t="The Scarlet Monastery", lv=30, n="The monastery stands in the far north-east of Tirisfal Glades. Go in alone, out of any group. Before entering, take the Scarlet Initiate's Uniform from the Supply Locker in the stables behind the monastery and wear it; stealth and suspicious actions remove it, so put it back on after each wing change. In the Graveyard, in the Chamber of Atonement (the first big room), Pick Pocket a Scarlet Scryer or Scarlet Crier for the Scryer's Key. In the Library, open the Personal Letterbox in the Athenaeum with it and read the Confidential Message. It sends you back to sit on both benches between the two statues in the Graveyard. Watch for the mechanism's messages, then take the Reliquary Key from the stone coffer: an elite stands by the coffer with a patrol behind it, but from beside the northern mausoleum you can turn the camera until the box shows and click it through the wall (an interact key works too). An elite ghost walks near the mausoleum; the broken piece at its edge keeps you out of its path. Then return to the Library for the locked reliquary and the eye. Avoid fighting through the instance.", g={{"g",0,txt="Scarlet Monastery",m=1420,x=82.6,y=33.8},{"i",0,txt="Solo route: Graveyard key, Library letter, Graveyard benches and coffer, then Library reliquary for the eye. Read the letter before the bench puzzle; check the disguise each time you change wings."}}},
  {t="Back to the dead drop", lv=30, n="Place the eye in the Dead Drop near Pyrewood. Check a capital mailbox for C's payment letter on your next planned city visit, then return here for the reward quest. The payment may not be available immediately; do not repeat the infiltration just because the reward has not appeared.", g={{"t",78676,m=1421,x=47.1,y=71},{"a",78699,m=1421,x=47.1,y=71,ml=25},{"t",78699,n2="Ruby-Adorned Blade",m=1421,x=47.1,y=71}}},
} end)

R:Segment({id="class/rogue/the-horn-of-xelthos",title="The Horn of Xelthos",classes={"ROGUE"},min=23,max=26,zone=1421,zoneName="Silverpine Forest",why="The Pyrewood Signet Ring, C's payment for a solo job inside Shadowfang Keep.",items={277210},folder="Rogue"}, function() return {
  {t="C's dead drop", lv=23, n="The Dead Drop is a chest in a house just outside Pyrewood Village in southern Silverpine, south of Shadowfang Keep. Open it and read C's note: the job has to be done alone, out of any group.", g={{"l",23,txt="Reach level 23"},{"a",78261,m=1421,x=47.1,y=71,ml=1}}},
  {t="Veenix", lv=23, n="Veenix, a goblin friendly to both factions, stands among the Venture Co. in the Windshear Crag, east Stonetalon, a short way north-east of Sun Rock Retreat. Horde fly to Sun Rock Retreat; Alliance to Stonetalon Peak. He wants a Venture Co. Work Order before he hands over explosives: the Venture Co. Loggers (level 18) working around him carry them in their pockets. Stealth up behind one and Pick Pocket it; killing them does not give it.", g={{"tk",4086,txt="Talk to Veenix",m=1442,x=58.2,y=51.7},{"a",78270,m=1442,x=58.2,y=51.7,ml=1},{"h",210187,txt="Get Venture Co. Work Order",m=1442,x=59.4,y=52.3,n=1},{"t",78270,m=1442,x=58.2,y=51.7}}},
  {t="Shadowfang Keep", lv=23, n="Go in alone and use the Breaching Charge at the courtyard gate. Players also report a freed prisoner opening the courtyard door for you: if you die while he is opening it, stay dead until it is open; it stays open once you release. If you know Vanish, bring Flash Powder and check its cooldown before entering; keep it ready for a failed approach. Pickpocket the sister in the dining hall for the Sister's Half-Key, then the brother in the room reached by turning right at the top of the stairs for the Brother's Half-Key (a level 20 rogue without Vanish may need ranks in Master of Deception to reach the second one unseen). Combine them somewhere safe: this breaks stealth. Free a bag slot first: opening the chest with full bags can use up the key without giving the horn. Return to the courtyard stables and use the combined key on the chest for the horn. Stay clear of the nearby elites; the minimum quest level does not guarantee a safe approach.", g={{"o",78261,i=1,txt="Horn of Xelthos",n2="Horn of Xelthos, inside Shadowfang Keep",m=1421,x=44.8,y=67.8}}},
  {t="Back to the dead drop", lv=23, n="Place the horn in the Dead Drop near Pyrewood. The payment may not appear immediately: check a capital mailbox for C's follow-up letter on your next planned city visit, then return to this chest for the reward quest. Do not repeat the dungeon just because the payment is not yet offered.", g={{"t",78261,m=1421,x=47.1,y=71},{"a",78307,m=1421,x=47.1,y=71,ml=1},{"t",78307,n2="Pyrewood Signet Ring",m=1421,x=47.1,y=71}}},
} end)

R:Segment({id="class/shaman/call-of-air-alliance",title="Call of Air and the Tempest's Weapons (Alliance)",faction="Alliance",classes={"SHAMAN"},min=30,max=40,zone=1455,zoneName="Ironforge",why="The Air Totem that lets you place air totems, then a weapon of your choice at 40.",items={5178,280607,280605,280604,280696},folder="Shaman"}, function() return {
  {t="Eldrun Stormbreaker", lv=30, n="At 30 Eldrun Stormbreaker, the shaman trainer in Ironforge, sends you to Veyric Thunderhame in Arathi Highlands. Your level 30 air totems (Grounding, Nature Resistance) need the Air Totem he gives.", g={{"l",30,txt="Reach level 30"},{"a",94789,m=1455,x=47.1,y=13.8,ml=30}}},
  {t="Veyric Thunderhame", lv=30, n="Veyric Thunderhame camps in the hills just west of Hammerfall, the Horde town in the north-east of Arathi: mind its guards. Fly to Refuge Pointe and head north-east.", g={{"t",94789,n2="Veyric Thunderhame: your Air Totem",m=1417,x=59.8,y=27.6},{"a",96264,m=1417,x=59.8,y=27.6,ml=30}}},
  {t="Charlga Razorflank", lv=30, n="Razorfen Kraul is a five-player dungeon at the southern edge of the Barrens (the arrow points at its entrance); Charlga Razorflank (level 33 elite) is its last boss. She casts Chain Bolt, Renew on her allies and Purity; the Tattered Note drops only from her.", g={{"o",96264,i=1,txt="Tattered Note",n2="Tattered Note, from Charlga Razorflank",m=1413,x=42.9,y=90.2,grp=true}}},
  {t="Veyric Thunderhame", lv=30, g={{"t",96264,m=1417,x=59.8,y=27.6},{"a",79358,m=1417,x=59.8,y=27.6,ml=30}}},
  {t="Twisted Fire Totems", lv=36, n="Five Twisted Fire Totems. The Stonevault troggs (Skullthumpers, Bonesnappers and Shamans, level 37-41) south of Angor Fortress in the Badlands carry them; the Shamans drop Fire Nova Totems and a Healing Ward, the Bonesnappers run for help when hurt. Respawn about five minutes.", g={{"l",36,txt="Reach level 36"},{"o",79358,i=3,txt="Twisted Fire Totem x5",m=1418,x=50.5,y=68.4}}},
  {t="Twisted Earth Totems", lv=36, n="Five Twisted Earth Totems. The Lost Ones (murlocs, level 34-39) north and north-east of Stonard in the Swamp of Sorrows carry them; most run for help when hurt.", g={{"l",33,txt="Reach level 33"},{"o",79358,i=2,txt="Twisted Earth Totem x5",m=1435,x=48.5,y=31.1}}},
  {t="Twisted Water Totems", lv=36, n="Five Twisted Water Totems. The Mirefin murlocs (level 35-38) north-east of Brackenwall Village in northern Dustwallow Marsh carry them.", g={{"l",34,txt="Reach level 34"},{"o",79358,i=1,txt="Twisted Water Totem x5",m=1445,x=57.1,y=21.4}}},
  {t="Twisted Air Totems", lv=36, n="Five Twisted Air Totems. The Maraudine centaurs (level 36-40) north and north-east of Shadowprey Village in western Desolace carry them; the Scouts drop one nearly every other kill. Wranglers Net and Disarm, Windchasers heal, Stormers throw Jumping Lightning: pull one at a time. Respawn about five minutes.", g={{"l",36,txt="Reach level 36"},{"o",79358,i=4,txt="Twisted Air Totem x5",m=1443,x=32.6,y=59.8}}},
  {t="Veyric Thunderhame", lv=36, g={{"t",79358,m=1417,x=59.8,y=27.6},{"a",96135,m=1417,x=59.8,y=27.6,ml=30}}},
  {t="The steam pools", lv=38, n="Veyric hands you the Corrupted Totems. Thousand Needles is far: the boat to Theramore and the road west, or fly to Thalanaar on the Feralas border and head east into the canyon. Place the Corrupted Totems at the steam pools north-west of Freewind Post to call the corrupted elementals and then the Ravaging Tempest; Razormane quilboar join the fight while the ritual runs. A group quest: bring at least one or two friends. The Eye of the Tempest drops about every other kill, and every group member can loot it.", g={{"l",38,txt="Reach level 38"},{"o",96135,i=1,txt="Eye of the Tempest",n2="Eye of the Tempest, from the Ravaging Tempest",m=1441,x=36.7,y=39.2,grp=true}}},
  {t="Veyric Thunderhame", lv=38, g={{"t",96135,m=1417,x=59.8,y=27.6},{"a",96016,m=1417,x=59.8,y=27.6,ml=30}}},
  {t="Bath'rah the Windwatcher", lv=38, n="Bath'rah camps in the ruins in the east of Alterac Mountains: from Tarren Mill follow the river east of town north into the hills. Pick your weapon: Lightning's Grasp, Tidebringer's Claw or Rage of the Storm.", g={{"t",96016,n2="Bath'rah the Windwatcher: the Elementalist's Guard and your weapon",m=1416,x=80.5,y=66.9}}},
} end)

R:Segment({id="class/shaman/call-of-air-horde",title="Call of Air and the Tempest's Weapons (Horde)",faction="Horde",classes={"SHAMAN"},min=30,max=40,zone=1454,zoneName="Orgrimmar",why="The Air Totem that lets you place air totems, then a weapon of your choice at 40.",items={5178,280607,280605,280604,280696},folder="Shaman"}, function() return {
  {t="Searn Firewarder", lv=30, n="At 30 Searn Firewarder in the Valley of Wisdom sends you to Prate Cloudseer in Thousand Needles. Your level 30 air totems (Grounding, Nature Resistance) need the Air Totem she gives.", f={r={"Orc","Troll"}}, g={{"l",30,txt="Reach level 30"},{"a",1531,m=1454,x=38,y=37.7,ml=30}}},
  {t="Alaana Stormwalker", lv=30, n="At 30 Skyborne shamans get their own Call of Air. Alaana Stormwalker waits where the airship from Zephras Isle lands, in northern Mulgore beside Thunder Bluff. Your level 30 air totems need the Air Totem Prate Cloudseer gives. If she has nothing for you, head up to Xanis Flameweaver in Thunder Bluff (next step): the trainers' Call of Air is open to Skyborne and gives the same totem.", f={r={"Skyborne"}}, g={{"l",30,txt="Reach level 30"},{"a",96136,m=1412,x=33.4,y=22.6,opt=true,ml=30}}},
  {t="Xanis Flameweaver", lv=30, n="At 30 Xanis Flameweaver, a shaman trainer on Spirit Rise in Thunder Bluff, sends you to Prate Cloudseer in Thousand Needles. Your level 30 air totems (Grounding, Nature Resistance) need the Air Totem Prate gives. Already carry Searn Firewarder's Call of Air from Orgrimmar? It goes to Prate too: skip Xanis.", w={{k="onquest",neg=true,q={96136}},{k="onquest",neg=true,q={1531}}}, f={r={"Tauren","Skyborne"}}, g={{"l",30,txt="Reach level 30"},{"a",1532,m=1456,x=25.2,y=20.5,ml=30}}},
  {t="Prate Cloudseer", lv=30, n="Fly to Freewind Post. Prate Cloudseer stands on a ledge above a cave mouth in the canyon wall north-east of the post, not inside the cave: climb the slope beside it. She also gives you an hour of faster attacks and running.", g={{"g",0,txt="Prate Cloudseer",m=1441,x=53.5,y=42.6}}},
  {t="", lv=30, w={{k="onquest",q={1531}}}, g={{"t",1531,n2="Prate Cloudseer: your Air Totem",m=1441,x=53.5,y=42.6}}},
  {t="", lv=30, w={{k="onquest",q={1532}}}, g={{"t",1532,n2="Prate Cloudseer: your Air Totem",m=1441,x=53.5,y=42.6}}},
  {t="", lv=30, w={{k="onquest",q={96136}}}, g={{"t",96136,n2="Prate Cloudseer: your Air Totem",m=1441,x=53.5,y=42.6}}},
  {t="Prate Cloudseer", lv=30, g={{"a",79360,m=1441,x=53.5,y=42.6,ml=30}}},
  {t="Charlga Razorflank", lv=30, n="Razorfen Kraul is a five-player dungeon at the southern edge of the Barrens (the arrow points at its entrance); Charlga Razorflank (level 33 elite) is its last boss. She casts Chain Bolt, Renew on her allies and Purity; the Tattered Note drops only from her.", g={{"o",79360,i=1,txt="Tattered Note",n2="Tattered Note, from Charlga Razorflank",m=1413,x=42.9,y=90.2,grp=true}}},
  {t="Rau Cliffrunner", lv=30, n="Rau Cliffrunner stands at Freewind Post.", g={{"t",79360,m=1441,x=46.1,y=51.7},{"a",79364,m=1441,x=46.1,y=51.7,ml=30}}},
  {t="Prate Cloudseer", lv=30, g={{"t",79364,m=1441,x=53.5,y=42.6},{"a",79361,m=1441,x=53.5,y=42.6,ml=30}}},
  {t="Twisted Air Totems", lv=36, n="Five Twisted Air Totems. The Maraudine centaurs (level 36-40) north and north-east of Shadowprey Village in western Desolace carry them; the Scouts drop one nearly every other kill. Wranglers Net and Disarm, Windchasers heal, Stormers throw Jumping Lightning: pull one at a time. Respawn about five minutes.", g={{"l",36,txt="Reach level 36"},{"o",79361,i=4,txt="Twisted Air Totem x5",m=1443,x=32.6,y=59.8}}},
  {t="Twisted Water Totems", lv=36, n="Five Twisted Water Totems. The Mirefin murlocs (level 35-38) north-east of Brackenwall Village in northern Dustwallow Marsh carry them.", g={{"l",34,txt="Reach level 34"},{"o",79361,i=1,txt="Twisted Water Totem x5",m=1445,x=57.1,y=21.4}}},
  {t="Twisted Fire Totems", lv=36, n="Five Twisted Fire Totems. The Stonevault troggs (Skullthumpers, Bonesnappers and Shamans, level 37-41) south of Angor Fortress in the Badlands carry them; the Shamans drop Fire Nova Totems and a Healing Ward, the Bonesnappers run for help when hurt. Respawn about five minutes.", g={{"l",36,txt="Reach level 36"},{"o",79361,i=3,txt="Twisted Fire Totem x5",m=1418,x=50.5,y=68.4}}},
  {t="Twisted Earth Totems", lv=36, n="Five Twisted Earth Totems. The Lost Ones (murlocs, level 34-39) north and north-east of Stonard in the Swamp of Sorrows carry them; most run for help when hurt.", g={{"l",33,txt="Reach level 33"},{"o",79361,i=2,txt="Twisted Earth Totem x5",m=1435,x=48.5,y=31.1}}},
  {t="Prate Cloudseer", lv=36, g={{"t",79361,m=1441,x=53.5,y=42.6},{"a",79366,m=1441,x=53.5,y=42.6,ml=30}}},
  {t="The steam pools", lv=38, n="Prate hands you the Corrupted Totems. Place the Corrupted Totems at the steam pools north-west of Freewind Post to call the corrupted elementals and then the Ravaging Tempest; Razormane quilboar join the fight while the ritual runs. A group quest: bring at least one or two friends. The Eye of the Tempest drops about every other kill, and every group member can loot it.", g={{"l",38,txt="Reach level 38"},{"h",212792,txt="Get Eye of the Tempest",n2="Eye of the Tempest, from the Ravaging Tempest",m=1441,x=37.2,y=41.6,n=1,grp=true}}},
  {t="Rau Cliffrunner", lv=38, g={{"t",79366,m=1441,x=46.1,y=51.7},{"a",79442,m=1441,x=46.1,y=51.7,ml=30}}},
  {t="Bath'rah the Windwatcher", lv=38, n="Bath'rah camps in the ruins in the east of Alterac Mountains: from Tarren Mill follow the river east of town north into the hills. Pick your weapon: Lightning's Grasp, Tidebringer's Claw or Rage of the Storm; the Elementalist's Guard shield comes with it.", g={{"t",79442,n2="Bath'rah the Windwatcher: the Elementalist's Guard and your weapon",m=1416,x=80.5,y=66.9}}},
} end)

R:Segment({id="class/shaman/call-of-earth-alliance",title="Call of Earth (Alliance)",faction="Alliance",classes={"SHAMAN"},min=4,max=5,zone=1426,zoneName="Dun Morogh",why="Your Earth Totem: without it no earth totem can be cast. Stoneskin Totem comes with it at level 4.",spells={8071},spellNames={"Stoneskin Totem"},items={5175},folder="Shaman"}, function() return {
  {t="Archaic Rune", lv=4, n="Teo's Call of Earth needs the Archaic Rune handed in first: Sten Stoutarm, where you entered Coldridge Valley, gives it to Dwarf shamans after his Dwarven Outfitters. Bring it up the road to Teo Hammerstorm inside Anvilmar.", w={{k="turnedin",neg=true,q=98581}}, g={{"a",98581,m=1426,x=29.9,y=71.2,ml=1},{"t",98581,m=1426,x=28.8,y=66.2}}},
  {t="Teo Hammerstorm", lv=4, n="Teo Hammerstorm trains shamans inside Anvilmar, the hall at the south end of Coldridge Valley. The quest opens at level 4. Never took it and now 10 or more? Eldrun Stormbreaker in Ironforge or Ingrid Dunwald in Kharanos gives you Call of Earth, a pointer back to Teo: take it for the experience on the way.", g={{"l",4,txt="Reach level 4"},{"a",94373,m=1426,x=28.8,y=66.2,ml=4}}},
  {t="Iceclaw Bear Pendants", lv=4, n="The Frostmane Troll Whelps (level 3-4) hold the snowy slopes west and south-west of Anvilmar, and the Frostmane Novices (level 3-4, they throw Frostbolts from range) camp south of it. Both carry the pendants; they respawn in about three minutes.", g={{"o",94373,i=1,txt="Iceclaw Bear Pendant x2",m=1426,x=27.7,y=78.8}}},
  {t="Teo Hammerstorm", lv=4, n="Back to Teo inside Anvilmar. He hands you the Earth Sapta: do not drink it yet.", g={{"t",94373,m=1426,x=28.8,y=66.2},{"a",94374,m=1426,x=28.8,y=66.2,ml=4}}},
  {t="Lost the Earth Sapta?", lv=4, n="Only if the Earth Sapta is gone from your bags (drunk away from the stone, or sold): Teo gives you another.", w={{k="onquest",q={94374}},{k="has",neg=true,n=1,item=6635}}, g={{"t",94472,n2="Teo Hammerstorm: a new Earth Sapta",m=1426,x=28.8,y=66.2}}},
  {t="The Spirit Stone", lv=4, n="The Spirit Stone stands on a snowy ridge north-west of Anvilmar. The trail is easy to miss: it climbs the hill from the valley floor; at the small camp near the top turn left and the stone comes into view. Stand beside it, drink the Earth Sapta and speak to the Minor Manifestation of Earth before it fades.", g={{"i",0,txt="Use Earth Sapta",n2="Earth Sapta, beside the Spirit Stone",m=1426,x=24.8,y=61.8},{"t",94374,m=1426,x=24.8,y=61.8},{"a",94375,n2="it hands you the Rough Quartz: keep it",m=1426,x=24.8,y=61.8,ml=4}}},
  {t="Teo Hammerstorm", lv=4, n="Bring the Rough Quartz back to Teo inside Anvilmar. Keep the Earth Totem in your bags for good: every earth totem needs it.", g={{"t",94375,n2="Teo Hammerstorm: Stoneskin Totem and your Earth Totem",m=1426,x=28.8,y=66.2},{"tr",0,txt="Visit your class trainer",n2="the level 4 shaman spells"}}},
} end)

R:Segment({id="class/shaman/call-of-earth-horde",title="Call of Earth (Horde)",faction="Horde",classes={"SHAMAN"},min=4,max=5,zone=1411,zoneName="Durotar",why="Your Earth Totem: without it no earth totem can be cast. Stoneskin Totem comes with it at level 4.",spells={8071},spellNames={"Stoneskin Totem"},items={5175},folder="Shaman"}, function() return {
  {t="Canaga Earthcaller", lv=4, n="Canaga Earthcaller stands just outside the Den, the cave in the middle of the Valley of Trials. The quest opens at level 4.", f={r={"Orc","Troll"}}, g={{"l",4,txt="Reach level 4"},{"a",1516,m=1411,x=42.4,y=69.2,ml=4}}},
  {t="Felstalker Hooves", lv=4, n="Felstalkers (level 3-4) prowl the slope below the Burning Blade Coven, the cave in the north of the valley, and just inside its mouth among the Vile Familiars. Nearly every Felstalker drops a hoof (four kills in five); they respawn in a little over three minutes.", f={r={"Orc","Troll"}}, g={{"o",1516,i=1,txt="Felstalker Hoof x2",m=1411,x=43,y=55.3}}},
  {t="Canaga Earthcaller", lv=4, n="Back to Canaga outside the Den. She hands you the Earth Sapta: do not drink it yet.", f={r={"Orc","Troll"}}, g={{"t",1516,m=1411,x=42.4,y=69.2},{"a",1517,m=1411,x=42.4,y=69.2,ml=4}}},
  {t="Lost the Earth Sapta?", lv=4, n="Only if the Earth Sapta is gone from your bags (drunk away from the rock, or sold): Canaga gives you another.", w={{k="onquest",q={1517}},{k="has",neg=true,n=1,item=6635}}, f={r={"Orc","Troll"}}, g={{"t",1463,n2="Canaga Earthcaller: a new Earth Sapta",m=1411,x=42.4,y=69.2}}},
  {t="Spirit Rock", lv=4, n="Spirit Rock sits on a ledge in the hills just south of the Den. The Hidden Path up starts at the foot of the hills south-west of the Den, between two idle peons; it climbs south-west into the hills, then bends back east to the rock. Stand right beside the stone and drink the Earth Sapta: the Minor Manifestation of Earth appears for a short while, so speak to it at once (walk almost under it if it does not answer). Coming back, you can drop down the ledge towards the Den instead of walking the path.", f={r={"Orc","Troll"}}, g={{"i",0,txt="Use Earth Sapta",n2="Earth Sapta, beside Spirit Rock",m=1411,x=44.1,y=76.4},{"t",1517,m=1411,x=44,y=76.2},{"a",1518,n2="it hands you the Rough Quartz: keep it",m=1411,x=44,y=76.2,ml=4}}},
  {t="Canaga Earthcaller", lv=4, n="Bring the Rough Quartz back to Canaga outside the Den. Keep the Earth Totem she gives you in your bags for good: every earth totem needs it.", f={r={"Orc","Troll"}}, g={{"t",1518,n2="Canaga Earthcaller: Stoneskin Totem and your Earth Totem",m=1411,x=42.4,y=69.2},{"tr",0,txt="Visit your class trainer",n2="the level 4 shaman spells"}}},
  {t="Seer Ravenfeather", lv=4, n="Seer Ravenfeather stands in Camp Narache. She may show no quest mark over her head: speak to her anyway. The quest opens at level 4.", f={r={"Tauren"}}, g={{"l",4,txt="Reach level 4"},{"a",1519,m=1412,x=44.4,y=76.8,ml=4}}},
  {t="Ritual Salve", lv=4, n="The Bristleback Shamans (level 3-4) stand among the quilboar huts of Brambleblade Ravine, east of the camp, and throw the odd Lightning Bolt. Four kills in five drop a salve; they respawn in about four minutes.", f={r={"Tauren"}}, g={{"o",1519,i=1,txt="Ritual Salve x2",m=1412,x=56.6,y=78.3}}},
  {t="Seer Ravenfeather", lv=4, n="Back to the Seer in Camp Narache. She hands you the Earth Sapta: do not drink it yet.", f={r={"Tauren"}}, g={{"t",1519,m=1412,x=44.4,y=76.8},{"a",1520,m=1412,x=44.4,y=76.8,ml=4}}},
  {t="Lost the Earth Sapta?", lv=4, n="Only if the Earth Sapta is gone from your bags: the Seer gives you another.", w={{k="onquest",q={1520}},{k="has",neg=true,n=1,item=6635}}, f={r={"Tauren"}}, g={{"t",1462,n2="Seer Ravenfeather: a new Earth Sapta",m=1412,x=44.4,y=76.8}}},
  {t="Kodo Rock", lv=4, n="Kodo Rock is a small pillar on a low mound due east of Greatmother Hawkwind's well, east of the camp; it only shows from about fifteen yards away, and hostile boars graze around it. Stand beside it and drink the Earth Sapta, then speak to the Minor Manifestation of Earth before it fades (drink again if it does).", f={r={"Tauren"}}, g={{"i",0,txt="Use Earth Sapta",n2="Earth Sapta, beside Kodo Rock",m=1412,x=50.4,y=80},{"t",1520,m=1412,x=52,y=80.4},{"a",1521,n2="it hands you the Rough Quartz: keep it",m=1412,x=52,y=80.4,ml=4}}},
  {t="Seer Ravenfeather", lv=4, n="Bring the Rough Quartz back to the Seer. Keep the Earth Totem in your bags for good: every earth totem needs it.", f={r={"Tauren"}}, g={{"t",1521,n2="Seer Ravenfeather: Stoneskin Totem and your Earth Totem",m=1412,x=44.4,y=76.8},{"tr",0,txt="Visit your class trainer",n2="the level 4 shaman spells"}}},
  {t="Windshaper Boro", lv=4, n="Windshaper Boro, the shaman trainer, stands in Thendal Village. The quest opens at level 3.", f={r={"Skyborne"}}, g={{"l",3,txt="Reach level 3"},{"a",92466,m=2521,x=42.8,y=23.6,ml=3}}},
  {t="Signet of Akir", lv=4, n="Any Al'Aketh cultist can carry the Signet of Akir: the Converts (level 2-3) around the standing stones just east of the village, or the Brutes and Neophytes (level 4) in the camp beyond Hanaa Nightwind, south-west of the village. Keep killing until one drops it.", f={r={"Skyborne"}}, g={{"o",92466,i=1,txt="Signet of Akir",m=2521,x=45.4,y=19.4}}},
  {t="Windshaper Boro", lv=4, n="Back to Boro in Thendal Village. He hands you the Earth Sapta: do not drink it yet.", f={r={"Skyborne"}}, g={{"t",92466,m=2521,x=42.8,y=23.6},{"a",92467,m=2521,x=42.8,y=23.6,ml=3}}},
  {t="The Rise of Spirits", lv=4, n="The Rise of Spirits is the hilltop shrine north-east of Boro: the path up starts on the hill just above the clearing where the flies were. Drink the Earth Sapta beside the shrine and speak to the Minor Manifestation of Earth before it fades.", f={r={"Skyborne"}}, g={{"i",0,txt="Use Earth Sapta",n2="Earth Sapta, beside the shrine",m=2521,x=49.7,y=23.8},{"t",92467,m=2521,x=49.7,y=23.8},{"a",92468,n2="it hands you the Rough Quartz: keep it",m=2521,x=49.7,y=23.8,ml=3}}},
  {t="Windshaper Boro", lv=4, n="Bring the Rough Quartz back to Boro. Keep the Earth Totem in your bags for good: every earth totem needs it.", f={r={"Skyborne"}}, g={{"t",92468,n2="Windshaper Boro: Stoneskin Totem and your Earth Totem",m=2521,x=42.8,y=23.6},{"tr",0,txt="Visit your class trainer"}}},
} end)

R:Segment({id="class/shaman/call-of-fire-alliance",title="Call of Fire (Alliance)",faction="Alliance",classes={"SHAMAN"},min=10,max=14,zone=1426,zoneName="Dun Morogh",why="Your Fire Totem for every fire totem, Searing Totem with it, and Forever's Totem of Charged Flames.",spells={3599},spellNames={"Searing Totem"},items={5176,263412},folder="Shaman"}, function() return {
  {t="Call of Fire", lv=10, n="At 10 Ingrid Dunwald, the shaman trainer in Kharanos, or Eldrun Stormbreaker, the shaman trainer in Ironforge, sends you to Bruegs Kindleborn.", g={{"l",10,txt="Reach level 10"},{"a",94449,n2="Ingrid Dunwald, Kharanos; or Eldrun Stormbreaker, Ironforge",m=1426,x=47.6,y=52,ml=10}}},
  {t="Bruegs Kindleborn", lv=10, n="Follow the road east to the tunnel towards South Gate Outpost. Out of the first tunnel, keep left past Mountaineer Barleybrew and the tower: a slim trail, hard to see but shown on the minimap, winds up the mountain to Bruegs' cave above the farm. He hands you the Torch of the Dormant Flame: keep it until the end of the chain.", g={{"t",94449,m=1426,x=87.9,y=44.8},{"a",94465,m=1426,x=87.9,y=44.8,ml=10}}},
  {t="Braldir Ashmantle", lv=10, n="From Bruegs' ledge you can drop carefully down the mountain into Loch Modan, or walk back through the tunnel. Braldir Ashmantle keeps the shrine on the peak just south of Thelsamar: a hidden trail along a cliff ledge, marked by stone totems, climbs to it from the road north of the peak.", g={{"t",94465,m=1432,x=32.2,y=66},{"a",94466,m=1432,x=32.2,y=66,ml=10}}},
  {t="Reagent Pouch", lv=10, n="The Stonesplinter Seers (level 13-14) stand among the troggs of Stonesplinter Valley in the south of the loch, and in the trogg camps north-east of Thelsamar. They throw Lightning Bolts from 40 yards and run for help when hurt: pull one at a time. Respawn about five minutes.", g={{"o",94466,i=2,txt="Reagent Pouch",m=1432,x=36.8,y=77.8}}},
  {t="Fire Tar", lv=10, n="The Tunnel Rat Geomancers (level 12-13) work only inside the Silver Stream Mine at the north end of the loch, past Thelsamar. They cast Fire Blast behind a Fire Shield and run for help at low health.", g={{"o",94466,i=1,txt="Fire Tar",m=1432,x=35.5,y=27.9}}},
  {t="Braldir Ashmantle", lv=10, n="Back up the trail to Braldir. He makes the Fire Sapta from the tar and the pouch: keep it with the torch.", g={{"t",94466,m=1432,x=32.2,y=66},{"a",94467,m=1432,x=32.2,y=66,ml=10}}},
  {t="Lost the Fire Sapta?", lv=10, n="Only if the Fire Sapta is gone from your bags: Braldir gives you another.", w={{k="onquest",q={94467}},{k="has",neg=true,n=1,item=6636}}, g={{"t",94473,n2="Braldir Ashmantle: a new Fire Sapta",m=1432,x=32.2,y=66}}},
  {t="The Shrine of Eternal Flame", lv=10, n="Climb on past Braldir to the peak. Drink the Fire Sapta beside the rock statue there to see the Minor Manifestation of Fire (level 12): it waits until you strike, but grows stronger the longer it is left, and it is immune to fire. Open at once with Rockbiter Weapon and Earth Shock. Its Glowing Ember drops every time.", g={{"o",94467,i=1,txt="Use Fire Sapta",n2="Fire Sapta, beside the statue",m=1432,x=31.9,y=64.5},{"o",94467,i=1,txt="Glowing Ember",n2="Glowing Ember: Minor Manifestation of Fire",m=1432,x=32,y=64.4}}},
  {t="The Brazier of the Dormant Flame", lv=10, n="Click the Brazier of the Dormant Flame atop the shrine with the torch in your bags to place the ember, then click it again for the next quest: the lit Torch of Eternal Flame.", g={{"t",94467,m=1432,x=31.8,y=64.5},{"a",94468,m=1432,x=31.8,y=64.5,ml=10}}},
  {t="Bruegs Kindleborn", lv=10, n="Back through the South Gate tunnel and up the trail to Bruegs' cave. Keep the Fire Totem in your bags for good: every fire totem needs it.", g={{"t",94468,n2="Bruegs Kindleborn: Searing Totem, your Fire Totem and the Totem of Charged Flames",m=1426,x=87.9,y=44.8},{"tr",0,txt="Visit your class trainer"}}},
} end)

R:Segment({id="class/shaman/call-of-fire-horde",title="Call of Fire (Horde)",faction="Horde",classes={"SHAMAN"},min=10,max=13,zone=1413,zoneName="The Barrens",why="Your Fire Totem for every fire totem, Searing Totem with it, and Forever's Totem of Charged Flames.",spells={3599},spellNames={"Searing Totem"},items={5176,263412},folder="Shaman"}, function() return {
  {t="Swart", lv=10, n="At 10 Swart, the shaman trainer on the east side of Razor Hill, sends you to Kranal Fiss in the Barrens. Already carry Searn Firewarder's letter from Orgrimmar? It goes to Kranal too: skip Swart.", f={r={"Orc","Troll"}}, g={{"l",10,txt="Reach level 10"},{"a",2983,n2="Swart, Razor Hill",m=1411,x=54.4,y=42.6,opt=true,ml=10}}},
  {t="Narm Skychaser", lv=10, n="At 10 Narm Skychaser, the shaman trainer in Bloodhoof Village, sends you to Kranal Fiss in the Barrens. Already carry Xanis Flameweaver's letter from Thunder Bluff? It goes to Kranal too: skip Narm.", f={r={"Tauren"}}, g={{"l",10,txt="Reach level 10"},{"a",2984,n2="Narm Skychaser, Bloodhoof Village",m=1412,x=47.4,y=62.5,opt=true,ml=10}}},
  {t="Kranal Fiss", lv=10, n="Kranal Fiss is not in the Crossroads: take the road north from the Crossroads and fork east towards Durotar; past Grol'dom Farm he paces by a tall tower east of the road (from Durotar: over the Southfury bridge, past Far Watch Post). If you reach Ashenvale you went too far.", f={r={"Orc","Troll","Tauren"}}, g={{"g",0,txt="Kranal Fiss",m=1413,x=56,y=19.9}}},
  {t="", lv=10, w={{k="onquest",q={2983}}}, f={r={"Orc","Troll","Tauren"}}, g={{"t",2983,n2="Kranal Fiss: Swart's letter",m=1413,x=56,y=19.9}}},
  {t="", lv=10, w={{k="onquest",q={1522}}}, f={r={"Orc","Troll","Tauren"}}, g={{"t",1522,n2="Kranal Fiss: Searn Firewarder's letter",m=1413,x=56,y=19.9}}},
  {t="", lv=10, w={{k="onquest",q={2984}}}, f={r={"Orc","Troll","Tauren"}}, g={{"t",2984,n2="Kranal Fiss: Narm Skychaser's letter",m=1413,x=56,y=19.9}}},
  {t="", lv=10, w={{k="onquest",q={1523}}}, f={r={"Orc","Troll","Tauren"}}, g={{"t",1523,n2="Kranal Fiss: Xanis Flameweaver's letter",m=1413,x=56,y=19.9}}},
  {t="Kranal Fiss", lv=10, n="Kranal hands you the Torch of the Dormant Flame: keep it until the end of the chain.", f={r={"Orc","Troll","Tauren"}}, g={{"a",1524,m=1413,x=56,y=19.9,ml=10}}},
  {t="Telf Joolam", lv=10, n="Back east over the bridge, then south along the Durotar bank of the river to where the mountains meet the water. The trail up starts at the foot of the mountain beside a small dark stone carved with symbols, near the quilboar camp; it is narrow, and a slip costs fall damage. Telf Joolam keeps the shrine at the top.", f={r={"Orc","Troll","Tauren"}}, g={{"t",1524,m=1411,x=38.5,y=59},{"a",1525,m=1411,x=38.5,y=59,ml=10}}},
  {t="Fire Tar", lv=10, n="The Razormane casters north-east of the Crossroads drop the Fire Tar three times in four: Water Seekers and Thornweavers (level 10-11), Geomancers (level 12-13, they throw Fireballs and run for help when hurt) and Mystics (level 13-14, they heal themselves at low health). Pull them one at a time.", f={r={"Orc","Troll","Tauren"}}, g={{"o",1525,i=1,txt="Fire Tar",m=1413,x=54.6,y=25.9}}},
  {t="Reagent Pouch", lv=10, n="The Burning Blade Cultists (level 10-11, they call imps and cast Immolate) live deep in Dustwind Cave north of Razor Hill: climb the ramp just north-east of town and stay on the high ground above the ravines. The orcs at the cave mouth are not cultists; the cultists are further in, off to the left. Three kills in four drop a pouch. Skull Rock by Orgrimmar is the wrong cave.", f={r={"Orc","Troll","Tauren"}}, g={{"o",1525,i=2,txt="Reagent Pouch",m=1411,x=52.4,y=25.5}}},
  {t="Telf Joolam", lv=10, n="Back up the trail to Telf. He makes the Fire Sapta from the tar and the pouch and hands it to you with the torch: keep both.", f={r={"Orc","Troll","Tauren"}}, g={{"t",1525,m=1411,x=38.5,y=59},{"a",1526,m=1411,x=38.5,y=59,ml=10}}},
  {t="Lost the Fire Sapta?", lv=10, n="Only if the Fire Sapta is gone from your bags: Telf gives you another.", w={{k="onquest",q={1526}},{k="has",neg=true,n=1,item=6636}}, f={r={"Orc","Troll","Tauren"}}, g={{"t",1464,n2="Telf Joolam: a new Fire Sapta",m=1411,x=38.5,y=59}}},
  {t="The Minor Manifestation of Fire", lv=10, n="Drink the Fire Sapta beside the Shaman Shrine, the big grey stone just below the summit, then climb to the plateau. Of the fire elementals there only the one in the middle can be attacked: it is level 12, immune to fire and grows stronger the longer the fight lasts, so open at once with Rockbiter Weapon and Earth Shock and leave the others alone. Its Glowing Ember drops every time.", f={r={"Orc","Troll","Tauren"}}, g={{"o",1526,i=1,txt="Use Fire Sapta",n2="Fire Sapta, beside the Shaman Shrine",m=1411,x=38.1,y=58.5},{"o",1526,i=1,txt="Glowing Ember",n2="Glowing Ember: Minor Manifestation of Fire",m=1411,x=38.7,y=58.3}}},
  {t="The Brazier of the Dormant Flame", lv=10, n="Click the Brazier of the Dormant Flame on the plateau with the torch in your bags to place the ember, then click it a second time: the next quest does not open by itself. It gives you the lit Torch of Eternal Flame.", f={r={"Orc","Troll","Tauren"}}, g={{"t",1526,m=1411,x=39,y=58.2},{"a",1527,m=1411,x=39,y=58.2,ml=10}}},
  {t="Kranal Fiss", lv=10, n="Down the trail, back over the bridge to Kranal Fiss by his tower. Keep the Fire Totem in your bags for good: every fire totem needs it.", f={r={"Orc","Troll","Tauren"}}, g={{"t",1527,n2="Kranal Fiss: Searing Totem, your Fire Totem and the Totem of Charged Flames",m=1413,x=56,y=19.9}}},
  {t="Sessaria Skystride", lv=10, n="At 10 Sessaria Skystride, the shaman trainer beside Ayessa Dawnsinger in Valanaar, hands you the Torch of the Dormant Flame (Aarnor Galestrike offers the same quest). Already left the isle? A Call of Fire sends you back to them: take the skycutter from the cliffs south of Skywatcher Plateau, north of Thunder Bluff. Learn Flame Shock from her now: Kuramaa, later in the chain, only takes fire damage.", f={r={"Skyborne"}}, g={{"l",10,txt="Reach level 10"},{"a",97243,m=2521,x=58.3,y=78.5,ml=10},{"tr",0,txt="Visit your class trainer"}}},
  {t="Olariaan Swiftburn", lv=10, n="The Shrine of Flames hides on the island's outer rim south-west of Valanaar, just south-east of Windfield Orchard: Olariaan Swiftburn keeps it.", f={r={"Skyborne"}}, g={{"t",97243,m=2521,x=51.2,y=86.2},{"a",97244,m=2521,x=51.2,y=86.2,ml=10}}},
  {t="Skypriest Faladiel", lv=10, n="Skypriest Faladiel (level 10, a turncoat Windshaper with a single spawn) holds the farm north-east past Valanaar, just south of the Shrine of Akir, on the hill west of the falls north of the East Pylon Watchtower. Kill him and take his heart.", f={r={"Skyborne"}}, g={{"o",97244,i=1,txt="Faladiel's Heart",m=2521,x=64.4,y=63.7}}},
  {t="Olariaan Swiftburn", lv=10, n="Back to Olariaan at the Shrine of Flames.", f={r={"Skyborne"}}, g={{"t",97244,m=2521,x=51.2,y=86.2},{"a",97245,m=2521,x=51.2,y=86.2,ml=10}}},
  {t="Kuramaa", lv=10, n="Kuramaa's Stump is the twisted stump on the hilltop by the Shen'dar Highlands Anchor Pylon, west of Valanaar, in the hills south of the Windsong Crawlers' lakes. Knock on it to call Kuramaa (level 10). The spirit shrugs off most magic: only fire hurts it, so keep Flame Shock on it. Take its wooden mask.", f={r={"Skyborne"}}, g={{"i",0,txt="Kuramaa's Stump",n2="Kuramaa's Stump: knock on the bark",m=2521,x=42.4,y=68.8},{"o",97245,i=1,txt="Kuramaa's Mask",m=2521,x=42.4,y=68.8}}},
  {t="The Eternal Flame", lv=10, n="Back to Olariaan. Accept the last quest, then wait by the Brazier of Offering while he performs the ritual; when the fire spirits light the Eternal Flame, hold the torch to it. From then you have six minutes: carry the flame straight to the Brazier of Eternal Flame beside Sessaria in Valanaar, with no detours or fights. Timer out? Abandon the quest and take it again from Olariaan.", f={r={"Skyborne"}}, g={{"t",97245,m=2521,x=51.2,y=86.2},{"a",97257,m=2521,x=51.2,y=86.2,ml=10},{"g",0,txt="Brazier of Offering",m=2521,x=51.2,y=85.9},{"c",97257,txt="Brazier of Offering; Brazier of Eternal Flame",n2="the ritual, then the Brazier of Eternal Flame in Valanaar",m=2521,x=58.4,y=78.8}}},
  {t="Sessaria Skystride", lv=10, n="Keep the Fire Totem in your bags for good: every fire totem needs it.", f={r={"Skyborne"}}, g={{"t",97257,n2="Sessaria Skystride: Searing Totem, your Fire Totem and the Totem of Charged Flames",m=2521,x=58.3,y=78.5}}},
} end)

R:Segment({id="class/shaman/call-of-water-alliance",title="Call of Water (Alliance)",faction="Alliance",classes={"SHAMAN"},min=20,max=23,zone=1455,zoneName="Ironforge",why="The Water Totem that lets you place water totems, and Healing Stream Totem with it.",spells={5394},spellNames={"Healing Stream Totem"},items={5177,6637},folder="Shaman"}, function() return {
  {t="Eldrun Stormbreaker", lv=20, n="At 20 Eldrun Stormbreaker, the shaman trainer in Ironforge's Mystic Ward, sends you to Norric Lochthane in Loch Modan.", g={{"l",20,txt="Reach level 20"},{"a",94494,m=1455,x=47.1,y=13.8,ml=20}}},
  {t="Norric Lochthane", lv=20, n="Norric's burrow hut stands on the north-western shore of the loch, below Stonewrought Dam, north of Thelsamar.", g={{"t",94494,m=1432,x=41.8,y=19.1},{"a",94495,m=1432,x=41.8,y=19.1,ml=20}}},
  {t="Hervdana Saegrund", lv=20, n="Hervdana's family lives in a cave beneath the southern falls of the Wetlands, east of Dun Algaz: not in a town. Through the Algaz tunnel north of Loch Modan, then east off the road.", g={{"t",94495,m=1437,x=65.8,y=76.5},{"a",94497,m=1437,x=65.8,y=76.5,ml=20}}},
  {t="The brown waterskin", lv=20, n="Fill the Unfilled Brown Waterskin at the bottom of the waterfalls below Hervdana's cave, where the fresh water meets the brackish. Dark Iron dwarves roam near the falls.", g={{"o",94497,i=1,txt="Full Brown Waterskin",m=1437,x=65.8,y=76.5}}},
  {t="Hervdana Saegrund", lv=20, g={{"t",94497,m=1437,x=65.8,y=76.5},{"a",94499,m=1437,x=65.8,y=76.5,ml=20}}},
  {t="The red waterskin", lv=20, n="Stonewatch Falls pour out of Lake Everstill at the east end of Redridge (fly from Ironforge to Lakeshire). Fill the Unfilled Red Waterskin at their foot, where the Murloc Nightcrawlers gather; pull the murlocs off the spot first. If the skin vanishes without counting, abandon the quest and take it again from Hervdana for a new one.", g={{"o",94499,i=1,txt="Full Red Waterskin",m=1433,x=66.8,y=60.3}}},
  {t="Hervdana Saegrund", lv=20, g={{"t",94499,m=1437,x=65.8,y=76.5},{"a",94500,m=1437,x=65.8,y=76.5,ml=20}}},
  {t="The blue waterskin", lv=20, n="Take the boat from Menethil Harbor to Auberdine (it stops in Southshore on the way), then fly or walk south through Darkshore to Astranaar in Ashenvale. Fill the Unfilled Blue Waterskin in the lake around the town, then the boat back to Menethil.", g={{"o",94500,i=1,txt="Full Blue Waterskin",m=1440,x=34.5,y=48}}},
  {t="Hervdana Saegrund", lv=20, g={{"t",94500,m=1437,x=65.8,y=76.5},{"a",94501,n2="the Vial of Purest Water, for Norric",m=1437,x=65.8,y=76.5,ml=20}}},
  {t="Norric Lochthane", lv=20, n="Back to Norric by Stonewrought Dam with the Vial of Purest Water. He hands you the Water Sapta and the Remaining Drops of Purest Water: keep both for Westfall.", g={{"t",94501,n2="Norric Lochthane: your Water Sapta",m=1432,x=41.8,y=19.1},{"a",94502,m=1432,x=41.8,y=19.1,ml=20}}},
  {t="Lost the Water Sapta?", lv=20, n="Only if the Water Sapta is gone from your bags: Norric gives you another before you leave for Westfall.", w={{k="onquest",q={94502}},{k="has",neg=true,n=1,item=6637}}, g={{"a",94616,m=1432,x=41.8,y=19.1,ml=20},{"t",94616,n2="Norric Lochthane: a new Water Sapta",m=1432,x=41.8,y=19.1}}},
  {t="Stendel's Pond", lv=20, n="Fly to Sentinel Hill and head south to Moonbrook: Stendel's Pond and the Forgotten Shrine lie just north of it. Drink the Water Sapta by the shrine to see the Corrupt Minor Manifestation of Water (level 22, Frost Shock and Frost Nova; one spawn, back three minutes after a kill), defeat it for its bracers (always dropped), then place them and the Remaining Drops of Purest Water on the Forgotten Shrine (this, not Norric, ends the quest). Click the shrine again: the Minor Manifestation of Water rises beside it; speak to it before you walk off (if it is gone, abandon and take the quest again at the shrine). It gives you the Shard of Water.", g={{"o",94502,i=1,txt="Use Water Sapta",m=1436,x=45.6,y=59.9},{"o",94502,i=1,txt="Corrupt Manifestation's Bracers",m=1436,x=45.6,y=59.9},{"t",94502,m=1436,x=45.6,y=59.9},{"a",94503,m=1436,x=45.6,y=59.9,ml=20},{"t",94503,n2="Minor Manifestation of Water, beside the shrine",m=1436,x=46.4,y=59.2},{"a",94505,m=1436,x=46.4,y=59.2,ml=20}}},
  {t="Norric Lochthane", lv=20, n="Back to Norric with the Shard of Water. Keep the Water Totem in your bags for good: every water totem needs it.", g={{"t",94505,n2="Norric Lochthane: Healing Stream Totem and your Water Totem",m=1432,x=41.8,y=19.1}}},
} end)

R:Segment({id="class/shaman/call-of-water-horde",title="Call of Water (Horde)",faction="Horde",classes={"SHAMAN"},min=20,max=23,zone=1454,zoneName="Orgrimmar",why="The Water Totem that lets you place water totems, and Healing Stream Totem with it.",spells={5394},spellNames={"Healing Stream Totem"},items={5177,6637},folder="Shaman"}, function() return {
  {t="Searn Firewarder", lv=20, n="At 20 Searn Firewarder in the Valley of Wisdom sends you to Islen Waterseer in the Barrens. (Swart in Razor Hill gives the same letter: carry either.)", f={r={"Orc","Troll"}}, g={{"l",20,txt="Reach level 20"},{"a",1528,m=1454,x=38,y=37.7,opt=true,ml=20}}},
  {t="Xanis Flameweaver", lv=20, n="At 20 Xanis Flameweaver, a shaman trainer on Spirit Rise in Thunder Bluff, sends you to Islen Waterseer in the Barrens. (Narm Skychaser in Bloodhoof Village gives the same letter: carry either.)", f={r={"Tauren","Skyborne"}}, g={{"l",20,txt="Reach level 20"},{"a",1529,m=1456,x=25.2,y=20.5,opt=true,ml=20}}},
  {t="Islen Waterseer", lv=20, n="Islen is not in Ratchet: take the small coast road south from Ratchet past the pirate camp and over a low hill; her fishing hut, with a shark strung up outside, stands by the water before the pirate ship. If you reach the ship you went too far.", g={{"g",0,txt="Islen Waterseer",m=1413,x=65.8,y=43.8}}},
  {t="", lv=20, w={{k="onquest",q={1528}}}, g={{"t",1528,n2="Islen Waterseer: Searn's letter",m=1413,x=65.8,y=43.8}}},
  {t="", lv=20, w={{k="onquest",q={1529}}}, g={{"t",1529,n2="Islen Waterseer: Xanis' letter",m=1413,x=65.8,y=43.8}}},
  {t="", lv=20, w={{k="onquest",q={2985}}}, g={{"t",2985,n2="Islen Waterseer: Swart's letter",m=1413,x=65.8,y=43.8}}},
  {t="", lv=20, w={{k="onquest",q={2986}}}, g={{"t",2986,n2="Islen Waterseer: Narm's letter",m=1413,x=65.8,y=43.8}}},
  {t="Islen Waterseer", lv=20, g={{"a",1530,m=1413,x=65.8,y=43.8,ml=20}}},
  {t="Brine", lv=20, n="Brine lives in the southern Barrens, south of Camp Taurajo: her hut sits on a hilltop of Blackthorn Ridge with a spinning windmill beside it, and the way up is the ridge by the lone tree. Quilboar camp all around the hill; Stormhides, thunderhawks and hyenas roam the plains on the way.", g={{"t",1530,m=1413,x=43.4,y=77.4},{"a",1535,m=1413,x=43.4,y=77.4,ml=20}}},
  {t="The Quilboar Watering Hole", lv=20, n="The muddy pond below Brine's hut. Step right into the puddle before you use the Empty Brown Waterskin (too far away and it refuses). Filling it calls a hostile Razormane Pathfinder (level 20): kill it, and watch for the quilboar hunter by the pond, who may start shooting afterwards.", g={{"o",1535,i=1,txt="Use Empty Brown Waterskin",n2="Empty Brown Waterskin, standing in the puddle",m=1413,x=44.3,y=76.8},{"o",1535,i=1,txt="Filled Brown Waterskin",m=1413,x=44.3,y=76.8}}},
  {t="Brine", lv=20, g={{"t",1535,m=1413,x=43.4,y=77.4},{"a",1536,m=1413,x=43.4,y=77.4,ml=20}}},
  {t="The Spring Well", lv=20, n="The Spring Well stands in the middle of Tarren Mill, just outside the church. From the Barrens: the zeppelin from Orgrimmar to Tirisfal Glades, then south past the Undercity and through Silverpine Forest (or fly once you have the Tarren Mill flight path). Hillsbrad is contested: Alliance players may attack. Stand beside the well and use the Empty Red Waterskin.", g={{"o",1536,i=1,txt="Use Empty Red Waterskin",n2="Empty Red Waterskin, beside the well",m=1424,x=62.2,y=20.8},{"o",1536,i=1,txt="Filled Red Waterskin",m=1424,x=62.2,y=20.8}}},
  {t="Brine", lv=20, g={{"t",1536,m=1413,x=43.4,y=77.4},{"a",1534,m=1413,x=43.4,y=77.4,ml=20}}},
  {t="The Ruins of Stardust", lv=20, n="The right fountain stands in a ring of standing stones on the island of the small green lake south of Astranaar, west of Lake Mystral (not the island in Lake Mystral itself). From the Barrens take the road north through the Mor'shan Rampart and on west. Water elementals and walking treants guard the lake and root you in place; an elite Wandering Protector roams Ashenvale and can pass close by. Use the Empty Blue Waterskin beside the fountain.", g={{"o",1534,i=1,txt="Use Empty Blue Waterskin",n2="Empty Blue Waterskin, beside the fountain",m=1440,x=33.6,y=67.5},{"o",1534,i=1,txt="Filled Blue Waterskin",m=1440,x=33.5,y=67.5}}},
  {t="Brine", lv=20, n="Back to Brine. She gives you the Vial of Purest Water for Islen.", g={{"t",1534,m=1413,x=43.4,y=77.4},{"a",220,n2="the Vial of Purest Water, for Islen",m=1413,x=43.4,y=77.4,ml=20}}},
  {t="Islen Waterseer", lv=20, n="Islen hands you the Water Sapta and the Remaining Drops of Purest Water: take everything she offers before you leave for Silverpine, or you will be back for more.", g={{"t",220,n2="Islen Waterseer: your Water Sapta",m=1413,x=65.8,y=43.8},{"a",63,m=1413,x=65.8,y=43.8,ml=20}}},
  {t="Lost the Water Sapta?", lv=20, n="Only if the Water Sapta is gone from your bags: Islen gives you another.", w={{k="onquest",q={63}},{k="has",neg=true,n=1,item=6637}}, g={{"t",972,n2="Islen Waterseer: a new Water Sapta",m=1413,x=65.8,y=43.8}}},
  {t="The Brazier of Everfount", lv=20, n="Fly to the Sepulcher. The shrine lies in a hollow just south-west of it: go round the back of the crypt to the thick tree between the two hills, hop past it onto the rocks and drop west down the slope to the pool (each drop costs a little health). Drink the Water Sapta beside the tall standing stone by the pool: several water elementals appear, and only the corrupt one near the middle can be attacked (Tab picks it). The Corrupt Minor Manifestation of Water is level 22 and casts Frost Shock and Frost Nova; if someone just killed it, it is back in about three minutes. Its bracers always drop.", g={{"o",63,i=1,txt="Use Water Sapta",n2="Water Sapta, beside the standing stone",m=1421,x=38.3,y=44.6},{"o",63,i=1,txt="Corrupt Manifestation's Bracers",m=1421,x=38.8,y=44.3}}},
  {t="The Minor Manifestation of Water", lv=20, n="Click the Brazier of Everfount to place the bracers and the drops. A few seconds later the pure Minor Manifestation of Water rises on the stone in the middle of the pool: speak to it while the Sapta Sight lasts (drink again by the stone if it has worn off). It gives you the Shard of Water for Islen. Gone before you could speak to it? Back at Islen ask for Call of Water (a fresh Water Sapta for Tiev Mordune, who stands just west of the shrine): hand it to Tiev, stay close while he calls the spirit back, then speak to it.", g={{"t",63,m=1421,x=38.3,y=44.6},{"a",100,m=1421,x=38.3,y=44.6,ml=20},{"t",100,m=1421,x=38.6,y=44.6},{"a",96,m=1421,x=38.6,y=44.6,ml=20}}},
  {t="Islen Waterseer", lv=20, n="Back to Islen south of Ratchet. Keep the Water Totem in your bags for good: every water totem needs it.", g={{"t",96,n2="Islen Waterseer: Healing Stream Totem and your Water Totem",m=1413,x=65.8,y=43.8}}},
} end)

R:Segment({id="class/shaman/darkreaver",title="The Darkreaver Menace",faction="Horde",classes={"SHAMAN"},min=58,max=60,zone=1454,zoneName="Orgrimmar",why="A Scholomance fight at 60 for Horde reputation; the Skyfury Helm may be gone in Forever.",folder="Shaman"}, function() return {
  {t="Sagorne Creststrider", lv=58, n="At 58 Sagorne Creststrider, the shaman trainer in the Valley of Wisdom, asks for two rare diamonds; every Horde shaman goes to him. Skyborne: Forever's quest page lists this quest for Orcs, Tauren and Trolls only: ask before you buy the diamonds.", g={{"a",7667,m=1454,x=38.7,y=35.9,ml=58}}},
  {t="Two diamonds", lv=58, n="Both diamonds are rare: the auction house is the quick way. Miners find the Azerothian Diamond in about one Thorium vein in a hundred (the Small Thorium Veins north of Morgan's Vigil in the Burning Steppes respawn every five minutes). The Pristine Black Diamond drops from high-level elites at about one in a hundred, best from the rare elite Revanchion (about one in nine).", g={{"o",7667,i=1,txt="Azerothian Diamond",m=1422,x=54.2,y=41.4},{"o",7667,i=2,txt="Pristine Black Diamond",m=1422,x=51.9,y=23.8}}},
  {t="Sagorne Creststrider", lv=60, n="The Darkreaver Menace needs level 60.", g={{"t",7667,m=1454,x=38.7,y=35.9},{"l",60,txt="Reach level 60"},{"a",8258,n2="he hands you the Divination Scryer",m=1454,x=38.7,y=35.9,ml=58}}},
  {t="The Great Ossuary", lv=60, n="A five-player dungeon event: Scholomance lies under Caer Darrow, the island town in the south-east of the Western Plaguelands. In the Great Ossuary's basement, first clear every mob in the room, then use the Divination Scryer at its centre: four waves of spirits follow, each closing with an Aspect mini-boss (the first wave weak and slow, the rest elite). Fight in a corner so nothing else joins, and drink between waves: it is long. Then Death Knight Darkreaver (level 62 elite) appears: he Cleaves, casts Shadow Bolt and Blood Leech, and Dominates a player's mind against the group. His head always drops.", g={{"o",8258,i=1,txt="Darkreaver's Head",m=1422,x=68.9,y=75.2,grp=true}}},
  {t="Sagorne Creststrider", lv=60, g={{"t",8258,n2="Sagorne Creststrider: 200 Horde reputation; the Skyfury Helm may be gone",m=1454,x=38.7,y=35.9}}},
} end)

R:Segment({id="class/shaman/spirit-totem",title="Spirit Totem and Da Voodoo",faction="Horde",classes={"SHAMAN"},min=50,max=52,zone=1454,zoneName="Orgrimmar",why="Experience and gold at 50, ending in the Sunken Temple; the Classic item choice may be gone in Forever.",folder="Shaman"}, function() return {
  {t="Sagorne Creststrider", lv=50, n="At 50 Sagorne Creststrider, the shaman trainer in the Valley of Wisdom, asks for the four elements for Bath'rah the Windwatcher.", f={r={"Orc","Troll"}}, g={{"l",50,txt="Reach level 50"},{"a",8410,m=1454,x=38.7,y=35.9,ml=50}}},
  {t="Beram Skychaser", lv=50, n="At 50 Beram Skychaser, a shaman trainer on Spirit Rise in Thunder Bluff, asks for the four elements for Bath'rah the Windwatcher. Skyborne: Forever's quest page lists Elemental Mastery and Spirit Totem for Orcs, Tauren and Trolls only; if Beram has nothing for you, Bath'rah's own Mastering the Elements is open to every Horde race, but Spirit Totem after it may still turn you away.", f={r={"Tauren","Skyborne"}}, g={{"l",50,txt="Reach level 50"},{"a",8410,m=1456,x=22,y=18.8,ml=50}}},
  {t="The four elements", lv=50, n="One each of Elemental Air, Fire, Earth and Water; all four trade, so the auction house is quickest. To farm them, Arathi Highlands has the exiles near Refuge Pointe (level 38-39, about one kill in eight to ten, respawn under seven minutes): Thundering Exiles south-east of it (air), Rumbling Exiles south-west (earth), Burning Exiles far to the north-west (fire), and the Summoned Guardian far to the south-west (water, about one in seven). Water comes easier from the Patches of Elemental Water in Azshara (two in five) or Seeker Aqualon by Lakeshire in Redridge.", g={{"o",8410,i=1,txt="Elemental Air",n2="Elemental Air: Thundering Exiles",m=1417,x=51.9,y=50.6},{"o",8410,i=2,txt="Elemental Fire",n2="Elemental Fire: Burning Exiles",m=1417,x=27.4,y=31.4},{"o",8410,i=3,txt="Elemental Earth",n2="Elemental Earth: Rumbling Exiles",m=1417,x=34.9,y=55.9},{"o",8410,i=4,txt="Elemental Water",n2="Elemental Water: the Summoned Guardian, or Azshara's water patches",m=1417,x=18.6,y=68}}},
  {t="Bath'rah the Windwatcher", lv=50, n="Bath'rah camps in the ruins of the east of Alterac Mountains: from Tarren Mill follow the river east of town north into the hills.", g={{"t",8410,m=1416,x=80.5,y=66.9},{"a",8412,m=1416,x=80.5,y=66.9,ml=50}}},
  {t="Spider eye and bear claw", lv=50, n="Eight of each. Fly or ride to the Bulwark and on to the west edge of the Western Plaguelands, north-west of Chillwind Camp: the Venom Mist Lurkers (level 50-51, they poison) give the Bloodshot Spider Eye and the Diseased Black Bears (level 51-52, Infected Wound) the Thick Black Claw, one kill in five each; the two Carrion Vultures there drop either. The bigger Diseased Grizzlies and Plague Lurkers further east almost never drop them. A few bears and lurkers also roam south-east of Brill in Tirisfal.", g={{"o",8412,i=1,txt="Bloodshot Spider Eye x8",m=1422,x=31.1,y=58.5},{"o",8412,i=2,txt="Thick Black Claw x8",m=1422,x=31.3,y=60.1}}},
  {t="Bath'rah the Windwatcher", lv=50, g={{"t",8412,m=1416,x=80.5,y=66.9},{"a",8413,m=1416,x=80.5,y=66.9,ml=50}}},
  {t="The Sunken Temple", lv=50, n="A five-player dungeon: needs a group of five, about level 50-55. Fly to Stonard and ride east. The Sunken Temple (Temple of Atal'Hakkar) stands in the middle of the Pool of Tears: climb the stairs on the ruin's south side, dive into the flooded hall, swim down through it and follow the stairs and passages down to the portal. Two feathers of each colour, one from each of six elite troll mini-bosses (level 51-52) on the balconies around the temple's great round room, every kill, and each player on the quest loots their own: Gasher and Zul'Lor the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green. Mijan heals the others (Renew, a Healing Ward): kill him first; Hukku summons guardians and throws Shadow Bolt Volleys.", g={{"o",8413,i=1,txt="Amber Voodoo Feather x2",n2="Amber Voodoo Feather: Gasher, Zul'Lor",m=1435,x=69.9,y=53.6},{"o",8413,i=2,txt="Blue Voodoo Feather x2",n2="Blue Voodoo Feather: Hukku, Mijan",m=1435,x=69.9,y=53.6},{"o",8413,i=3,txt="Green Voodoo Feather x2",n2="Green Voodoo Feather: Zolo, Loro",m=1435,x=69.9,y=53.6}}},
  {t="Bath'rah the Windwatcher", lv=50, g={{"t",8413,n2="Bath'rah the Windwatcher: the old item choice may be gone, count on the experience",m=1416,x=80.5,y=66.9}}},
} end)

R:Segment({id="class/warlock/dread-mage-hat",title="Dread Mage Hat",faction="Alliance",races={"Human","Gnome"},classes={"WARLOCK"},min=25,max=30,zone=1453,zoneName="Stormwind City",why="A cloth hat in your late 20s: Zardeth's errand for any Alliance player pays warlocks this extra.",items={3556},folder="Warlock"}, function() return {
  {t="Zardeth of the Black Claw", lv=25, n="At 25 Zardeth of the Black Claw, in the cellar of the Slaughtered Lamb in the Mage Quarter (beside the warlock trainers), wants two ingredients for a brew. Do it when your leveling takes you to Duskwood and the Wetlands.", g={{"l",25,txt="Reach level 25"},{"a",335,m=1453,x=40.1,y=85.3,ml=25}}},
  {t="Tear of Tilloa", lv=25, n="Manor Mistmantle stands in the north-east of Duskwood, north of Darkshire. The Tear of Tilloa is a small white flower low in the grass of the fenced garden beside Stalvan's house: hard to see, so sweep the garden with your mouse. Fetid Corpses (level 29) wander the grounds and come quickly: at 25, send your voidwalker at the nearest one, grab the flower and leave. Stalvan Mistmantle (32) is inside the house; leave him alone.", g={{"o",335,i=1,txt="Tear of Tilloa",m=1431,x=78.3,y=36}}},
  {t="Musquash Root", lv=25, n="The root grows at the water's edge in the pool below the small falls east of Dun Algaz, beside the Dark Iron cave below the Stonewrought Dam: a tall, spiky wooden root, not at the foot of the dam itself.", g={{"o",335,i=2,txt="Musquash Root",m=1437,x=64.8,y=75.3}}},
  {t="A Noble Brew", lv=25, n="Back to Zardeth. He brews the Black Claw Stout and gives it to you for Lord Baurles K. Wishock in the Hall of Petitioners, the first hall on the right inside Stormwind Keep.", g={{"t",335,m=1453,x=40.1,y=85.3},{"a",336,m=1453,x=40.1,y=85.3,ml=25},{"t",336,n2="Lord Baurles K. Wishock, Stormwind Keep",m=1453,x=77.9,y=49}}},
  {t="You Have Served Us Well", lv=25, n="Back to Zardeth once more: he offers warlocks a reward, which his imp Zggi, standing beside him, hands over.", g={{"a",397,m=1453,x=40.1,y=85.3,ml=25},{"t",397,n2="Zggi: Dread Mage Hat",m=1453,x=40.2,y=85.3}}},
} end)

R:Segment({id="class/warlock/enchanted-gold-bloodrobe",title="Enchanted Gold Bloodrobe",classes={"WARLOCK"},min=31,max=38,zone=1413,zoneName="The Barrens",why="A rare cloth robe for your 30s from Menara Voidrender; its last parts wait for levels 35 and 37.",items={6900},folder="Warlock"}, function() return {
  {t="In Search of Menara Voidrender (Stormwind)", lv=31, n="At 31 Demisette Cloyce in the Slaughtered Lamb, in the Mage Quarter, sends you to Menara Voidrender in Ratchet. Buy a Robes of Arcana and a Gold Bar first (next steps) to save a trip.", f={r={"Human"}}, g={{"l",31,txt="Reach level 31"},{"a",4738,m=1453,x=39.2,y=85,ml=31}}},
  {t="In Search of Menara Voidrender (Ironforge)", lv=31, n="At 31 Briarthorn in Ironforge sends you to Menara Voidrender in Ratchet. Buy a Robes of Arcana and a Gold Bar first (next steps) to save a trip.", f={r={"Gnome"}}, g={{"l",31,txt="Reach level 31"},{"a",4736,m=1455,x=50.4,y=5.7,ml=31}}},
  {t="In Search of Menara Voidrender (Orgrimmar)", lv=31, n="At 31 Zevrost in the Cleft of Shadow sends you to Menara Voidrender in Ratchet. Buy a Robes of Arcana and a Gold Bar first (next steps) to save a trip.", f={r={"Orc","Troll"}}, g={{"l",31,txt="Reach level 31"},{"a",4737,m=1454,x=48.5,y=45.4,ml=31}}},
  {t="In Search of Menara Voidrender (Undercity)", lv=31, n="At 31 Kaal Soulreaper in the Magic Quarter sends you to Menara Voidrender in Ratchet; the zeppelin from Tirisfal Glades flies to Durotar. Buy a Robes of Arcana and a Gold Bar first (next steps) to save a trip.", f={r={"Scourge"}}, g={{"l",31,txt="Reach level 31"},{"a",4739,m=1458,x=86.2,y=15.9,ml=31}}},
  {t="Robes of Arcana and a Gold Bar", lv=31, n="Tailors sew the Robes of Arcana from a rare pattern; miners smelt Gold Bars from Gold Ore. Everyone else buys both at the Auction House. If you wear the robe, take it off: Menara keeps it.", g={{"h",5770,txt="Get Robes of Arcana",n2="Robes of Arcana: the Auction House",m=1453,x=61.2,y=71.3,n=1,f={fa={"Alliance"}}},{"h",5770,txt="Get Robes of Arcana",n2="Robes of Arcana: the Auction House",m=1454,x=55.9,y=62.7,n=1,f={fa={"Horde"}}},{"h",3577,txt="Get Gold Bar",n2="Gold Bar: the Auction House",m=1453,x=61.2,y=71.3,n=1,f={fa={"Alliance"}}},{"h",3577,txt="Get Gold Bar",n2="Gold Bar: the Auction House",m=1454,x=55.9,y=62.7,n=1,f={fa={"Horde"}}}}},
  {t="Menara Voidrender", lv=31, n="Menara Voidrender stands by Strahad Farsan's tower on the hill above Ratchet, behind the engineers' hut. She takes the robe, then sends the gold bar to Xizk Goodstitch in Booty Bay.", g={{"t",4738,m=1413,x=62.5,y=35.5,f={r={"Human"}}},{"t",4736,m=1413,x=62.5,y=35.5,f={r={"Gnome"}}},{"t",4737,m=1413,x=62.5,y=35.5,f={r={"Orc","Troll"}}},{"t",4739,m=1413,x=62.5,y=35.5,f={r={"Scourge"}}},{"a",1796,m=1413,x=62.5,y=35.5,ml=31},{"t",1796,m=1413,x=62.5,y=35.5},{"a",4781,m=1413,x=62.5,y=35.5,ml=31}}},
  {t="Xizk Goodstitch", lv=31, n="The boat from Ratchet sails to Booty Bay. Xizk Goodstitch runs A Tailor to Cities on an upper level of the town. Give him the Gold Bar; he will spin the thread later.", g={{"t",4781,m=1434,x=28.7,y=76.9},{"a",4782,m=1434,x=28.7,y=76.9,ml=31}}},
  {t="Back to Menara", lv=31, n="You need no thread yet: Menara wants demon parts from Desolace next.", g={{"t",4782,m=1413,x=62.5,y=35.5},{"a",4783,m=1413,x=62.5,y=35.5,ml=31}}},
  {t="Hatefury satyrs", lv=31, n="The Hatefury satyrs (level 31-32) hold Sargeron in the far north-east of Desolace, past Nijel's Point: two kills in five give a vial, so plan on about 25.", g={{"o",4783,i=1,txt="Vial of Hatefury Blood x10",n2="Vials of Hatefury Blood",m=1443,x=74.7,y=17.8}}},
  {t="Mannoroc Coven", lv=35, n="The Lesser Infernals (36-37) and Demon Portal Guardians (38) of Mannoroc Coven, in the south of Desolace, drop the stone half the time. The guide waits for level 35 first: at 31 they are too strong to solo. They resist fire, so use Shadow Bolt and Corruption.", g={{"l",35,txt="Reach level 35"},{"o",4783,i=2,txt="Lesser Infernal Stone",m=1443,x=56.8,y=71.1}}},
  {t="Menara again", lv=35, g={{"t",4783,m=1413,x=62.5,y=35.5},{"a",4784,m=1413,x=62.5,y=35.5,ml=31}}},
  {t="Fine Gold Thread", lv=35, n="Back to Xizk in Booty Bay: he offers Fine Gold Thread as a quest you hand straight back to him. He may show no quest marker; talk to him anyway.", g={{"t",4785,n2="Xizk Goodstitch: Fine Gold Thread, handed straight back",m=1434,x=28.7,y=76.9},{"o",4784,i=1,txt="Fine Gold Thread",m=1434,x=28.7,y=76.9}}},
  {t="Smoldering Coal", lv=37, n="The Burning Exiles (level 38-39), fire elementals at the Circle of West Binding in western Arathi Highlands, drop the coal about one time in three. The guide waits for level 37 first: below it they hit too hard to solo. They resist fire: Shadow Bolt and Corruption. The Cresting Charms from the Cresting Exiles near Hammerfall finish one off once you have hurt it. Make a Soul Shard with Drain Soul on the way.", g={{"l",37,txt="Reach level 37"},{"o",4784,i=2,txt="Smoldering Coal x2",m=1417,x=25.6,y=30.4},{"o",4784,i=3,txt="Soul Shard",n2="Soul Shard: Drain Soul on an Exile as it dies",m=1417,x=24.9,y=30.5}}},
  {t="The Completed Robe", lv=37, n="Back to Menara with the thread, the coals and a Soul Shard. Then wait beside her while she works the robe (do not attack her: the quest log calls it a kill), and speak to her again.", g={{"t",4784,m=1413,x=62.5,y=35.5},{"a",4786,m=1413,x=62.5,y=35.5,ml=31},{"c",4786,txt="Menara Voidrender",n2="Wait beside Menara while she finishes the robe",m=1413,x=62.5,y=35.4},{"t",4786,n2="Menara Voidrender: Enchanted Gold Bloodrobe",m=1413,x=62.5,y=35.5}}},
} end)

R:Segment({id="class/warlock/felhunter-alliance",title="Felhunter (Alliance)",faction="Alliance",classes={"WARLOCK"},min=30,max=33,zone=1413,zoneName="The Barrens",why="The felhunter, the demon to bring against spellcasters, and a Box of Souls for your shards.",spells={691},spellNames={"Summon Felhunter"},items={22244},folder="Warlock"}, function() return {
  {t="Seeking Strahad (Stormwind)", lv=30, n="At 30 Gakin the Darkbinder, in the cellar of the Slaughtered Lamb in the Mage Quarter, sends you to Strahad Farsan in Ratchet.", f={r={"Human"}}, g={{"l",30,txt="Reach level 30"},{"a",1798,m=1453,x=39.2,y=85.2,ml=30}}},
  {t="Seeking Strahad (Ironforge)", lv=30, n="At 30 Lago Blackwrench, in the Forlorn Cavern, sends you to Strahad Farsan in Ratchet.", f={r={"Gnome"}}, g={{"l",30,txt="Reach level 30"},{"a",1798,m=1455,x=47.6,y=9.3,ml=30}}},
  {t="Strahad Farsan", lv=30, n="Ratchet is a neutral goblin port on the Barrens coast: the boat from Booty Bay docks there. Strahad Farsan stands on the hill above the town, behind the engineers' hut, by his little tower; Menara Voidrender and two acolytes are with him. He sends you to Krom Stoutarm in Ironforge.", g={{"t",1798,m=1413,x=62.6,y=35.5},{"a",1758,m=1413,x=62.6,y=35.5,ml=30}}},
  {t="Krom Stoutarm", lv=30, n="Krom Stoutarm is in the library of the Hall of Explorers. He wants two lost pieces of the Tome of the Cabal: one on the Hillsbrad coast, one in Thousand Needles.", g={{"t",1758,m=1455,x=74.2,y=9.4},{"a",1802,m=1455,x=74.2,y=9.4,ml=30}}},
  {t="Moldy Tome", lv=30, n="The tome is a small grey-blue book lying in the sand of a murloc camp on the shore south-west of Southshore, near the water's edge. Six or seven murlocs guard it and more lurk underwater: they come in groups, so Fear one and keep your voidwalker on the rest. Walk down to the water to click it; from the hillside the crates block the cursor.", g={{"o",1802,i=1,txt="Moldy Tome",n2="Moldy Tome, from the Tome of the Cabal on the sand",m=1424,x=27.8,y=72.8}}},
  {t="Tattered Manuscript", lv=30, n="The centaur cave opens in the cliffs north of Freewind Post, a Horde town: keep clear of its guards. Inside, keep right at each fork, cross the pool by the small waterfall, and open the small dark box against the wall beside a larger chest: the larger one is the wrong one. You can open it only while on the quest. The centaurs respawn behind you on the way out.", g={{"o",1802,i=2,txt="Tattered Manuscript",n2="Tattered Manuscript, in the Damaged Chest",m=1441,x=43.4,y=32.7}}},
  {t="Back to Krom", lv=30, n="Krom pieces the tome together and gives you the Reconstructed Tome: keep it, Strahad takes it with the rods.", g={{"t",1802,m=1455,x=74.2,y=9.4},{"a",1804,m=1455,x=74.2,y=9.4,ml=30}}},
  {t="Rods of Channeling", lv=30, n="The Dragonmaw hold Angerfang Encampment in the hills east of the road from Menethil Harbor to Dun Algaz. Only the casters drop the rods, four kills in five: the Bonewarders (level 27, with skeleton pets) and Shadowwarders (28). A steep path north of the central spirit healer leads up into the camp past most of the warriors.", g={{"o",1804,i=1,txt="Rod of Channeling x3",n2="Rods of Channeling, from the Dragonmaw casters",m=1437,x=52.4,y=52.6}}},
  {t="The Binding", lv=30, n="Back to Strahad in Ratchet. When you accept, he draws the summoning circle and his acolytes channel a greater circle over it: wait inside the tower until both are done. Then use the Tome of the Cabal on the circle. The felhunter (level 30, not elite) silences and eats mana, and it vanishes after two minutes: have your voidwalker out, open with your damage over time at once and let the voidwalker tank. If you die or it wins, abandon The Binding and take it again from Strahad. Keep the tome: Strahad takes it back.", g={{"t",1804,m=1413,x=62.6,y=35.5},{"a",1795,m=1413,x=62.6,y=35.5,ml=30},{"i",0,txt="Use Tome of the Cabal",n2="Tome of the Cabal, on the circle",m=1413,x=62.6,y=35.3},{"o",1795,i=1,txt="Kill Summoned Felhunter",m=1413,x=62.6,y=35.3},{"t",1795,n2="Strahad Farsan: Summon Felhunter",m=1413,x=62.6,y=35.5}}},
} end)

R:Segment({id="class/warlock/felhunter-horde",title="Felhunter (Horde)",faction="Horde",classes={"WARLOCK"},min=30,max=33,zone=1413,zoneName="The Barrens",why="The felhunter, the demon to bring against spellcasters, and a Box of Souls for your shards.",spells={691},spellNames={"Summon Felhunter"},items={22244},folder="Warlock"}, function() return {
  {t="Seeking Strahad (Orgrimmar)", lv=30, n="At 30 Gan'rul Bloodeye, in the Cleft of Shadow under the Valley of Strength, sends you to Strahad Farsan in Ratchet.", f={r={"Orc","Troll"}}, g={{"l",30,txt="Reach level 30"},{"a",2996,m=1454,x=48.2,y=45.3,ml=30}}},
  {t="Seeking Strahad (Undercity)", lv=30, n="At 30 Carendin Halgar, in the Magic Quarter, sends you to Strahad Farsan in Ratchet. The zeppelin from Tirisfal Glades flies to Durotar. Take only one Seeking Strahad: if Strahad offers nothing, drop the duplicate from your log.", f={r={"Scourge"}}, g={{"l",30,txt="Reach level 30"},{"a",3001,m=1458,x=85.1,y=26,ml=30}}},
  {t="Strahad Farsan", lv=30, n="Ratchet's flight point is a short flight from Orgrimmar's. Strahad Farsan stands on the hill above the town, behind the engineers' hut, by his little tower; Menara Voidrender and two acolytes are with him. He sends you to Jorah Annison in the Undercity.", g={{"t",2996,m=1413,x=62.6,y=35.5,f={r={"Orc","Troll"}}},{"t",3001,m=1413,x=62.6,y=35.5,f={r={"Scourge"}}},{"a",1801,m=1413,x=62.6,y=35.5,ml=30}}},
  {t="Jorah Annison", lv=30, n="Jorah Annison is in the Magic Quarter of the Undercity. He wants two lost pieces of the Tome of the Cabal: one on the Hillsbrad coast, one in Thousand Needles.", g={{"t",1801,m=1458,x=75.9,y=37.9},{"a",1803,m=1458,x=75.9,y=37.9,ml=30}}},
  {t="Moldy Tome", lv=30, n="The tome is a small grey-blue book lying in the sand of a murloc camp on the shore south-west of Southshore, near the water's edge. Six or seven murlocs guard it and more lurk underwater: they come in groups, so Fear one and keep your voidwalker on the rest. Walk down to the water to click it; from the hillside the crates block the cursor.", g={{"o",1803,i=1,txt="Moldy Tome",n2="Moldy Tome, from the Tome of the Cabal on the sand",m=1424,x=27.8,y=72.8}}},
  {t="Tattered Manuscript", lv=30, n="The centaur cave opens in the cliffs north of Freewind Post. Inside, keep right at each fork, cross the pool by the small waterfall, and open the small dark box against the wall beside a larger chest: the larger one is the wrong one. You can open it only while on the quest. The centaurs respawn behind you on the way out.", g={{"o",1803,i=2,txt="Tattered Manuscript",n2="Tattered Manuscript, in the Damaged Chest",m=1441,x=43.4,y=32.7}}},
  {t="Back to Jorah", lv=30, n="Jorah pieces the tome together and gives you the Reconstructed Tome: keep it, Strahad takes it with the rods.", g={{"t",1803,m=1458,x=75.9,y=37.9},{"a",1805,m=1458,x=75.9,y=37.9,ml=30}}},
  {t="Rods of Channeling", lv=30, n="The Dragonmaw hold Angerfang Encampment in the hills east of the road through the Wetlands, south of the Thandol Span you cross from Arathi Highlands. Only the casters drop the rods, four kills in five: the Bonewarders (level 27, with skeleton pets) and Shadowwarders (28). A steep path north of the central spirit healer leads up into the camp past most of the warriors.", g={{"o",1805,i=1,txt="Rod of Channeling x3",n2="Rods of Channeling, from the Dragonmaw casters",m=1437,x=52.4,y=52.6}}},
  {t="The Binding", lv=30, n="Back to Strahad in Ratchet. When you accept, he draws the summoning circle and his acolytes channel a greater circle over it: wait inside the tower until both are done. Then use the Tome of the Cabal on the circle. The felhunter (level 30, not elite) silences and eats mana, and it vanishes after two minutes: have your voidwalker out, open with your damage over time at once and let the voidwalker tank. If you die or it wins, abandon The Binding and take it again from Strahad. Keep the tome: Strahad takes it back.", g={{"t",1805,m=1413,x=62.6,y=35.5},{"a",1795,m=1413,x=62.6,y=35.5,ml=30},{"i",0,txt="Use Tome of the Cabal",n2="Tome of the Cabal, on the circle",m=1413,x=62.6,y=35.3},{"o",1795,i=1,txt="Kill Summoned Felhunter",m=1413,x=62.6,y=35.3},{"t",1795,n2="Strahad Farsan: Summon Felhunter",m=1413,x=62.6,y=35.5}}},
} end)

R:Segment({id="class/warlock/imp-alliance",title="Imp (Alliance)",faction="Alliance",classes={"WARLOCK"},min=1,max=4,zone=1429,zoneName="Elwynn Forest",why="Your first demon at level 1-4: the imp, from your start zone's warlock trainer.",spells={688},spellNames={"Summon Imp"},folder="Warlock"}, function() return {
  {t="Drusilla La Salle (Humans)", lv=1, n="Your first letter (Tainted Letter, from Marshal McBride after Kobold Camp Cleanup) points you to Drusilla La Salle, the warlock trainer in the little graveyard beside Northshire Abbey. She asks for a book the Defias stole.", f={r={"Human"}}, g={{"a",1598,m=1429,x=49.9,y=42.6,ml=1}}},
  {t="The Stolen Books", lv=1, n="The Defias tent stands in the vineyard east of the Abbey. The book is small: it lies on the ground just right of the tent's opening, beside a blue jug. Three Defias Thugs (level 3-4) guard the tent; pull them one at a time, or step inside the tent and click the book, where they cannot reach you. The book respawns three minutes after someone takes it.", f={r={"Human"}}, g={{"o",1598,i=1,txt="Powers of the Void",n2="Powers of the Void, from the Stolen Books",m=1429,x=56.7,y=44}}},
  {t="Summon Imp", lv=1, n="Drusilla teaches you Summon Imp at the hand-in: summon it right away, it costs nothing and fights beside you.", f={r={"Human"}}, g={{"t",1598,n2="Drusilla La Salle: Summon Imp",m=1429,x=49.9,y=42.6}}},
  {t="Alamar Grimm (Gnomes)", lv=1, n="Your first letter (Tainted Memorandum, from Sten Stoutarm after Dwarven Outfitters) points you to Alamar Grimm, the warlock trainer upstairs inside Anvilmar. He asks for three Feather Charms.", f={r={"Gnome"}}, g={{"a",1599,m=1426,x=28.6,y=66.1,ml=1}}},
  {t="Feather Charms", lv=1, n="The Frostmane Novices (level 3-4) sit at the back of the troll cave south of Anvilmar, near Grek'nir the Cold by the icy pool: take the left tunnel past the entrance. Four kills in five drop a charm, but only two or three novices spawn, so you may wait out their three-minute respawn. They throw frostbolts from range; the Troll Whelps at the cave mouth jump anyone who passes. With the charms, your hearthstone takes you straight back: a new character's is set to Coldridge Valley.", f={r={"Gnome"}}, g={{"o",1599,i=1,txt="Feather Charm x3",n2="Feather Charms",m=1426,x=30.5,y=79.5}}},
  {t="Summon Imp", lv=1, n="Alamar teaches you Summon Imp at the hand-in: summon it right away, it costs nothing and fights beside you.", f={r={"Gnome"}}, g={{"t",1599,n2="Alamar Grimm: Summon Imp",m=1426,x=28.6,y=66.1}}},
} end)

R:Segment({id="class/warlock/imp-horde",title="Imp (Horde)",faction="Horde",classes={"WARLOCK"},min=1,max=4,zone=1411,zoneName="Durotar",why="Your first demon at level 1-4: the imp, with a starter blade or staff for Orcs and Trolls.",spells={688},spellNames={"Summon Imp"},items={4925,5778},folder="Warlock"}, function() return {
  {t="Ruzan (Orcs and Trolls)", lv=1, n="Your first letter (Tainted Parchment for Orcs, Tainted Tablet for Trolls, from Gornek after Cutting Teeth) points you to Nartok, the warlock trainer in the Den. Ruzan stands just outside the Den in the Valley of Trials and asks for six Vile Familiar Heads.", f={r={"Orc","Troll"}}, g={{"a",1485,m=1411,x=42.6,y=69,ml=1}}},
  {t="Vile Familiars", lv=1, n="The Vile Familiars (level 3-4) swarm the Burning Blade Coven, the cave north of the Den, inside and around its mouth. Almost every kill drops a head (80%), so about eight kills does it; they throw small fireballs, so pull them one at a time. They respawn in just over three minutes. Other classes hunt the same imps for their own Vile Familiars quest.", f={r={"Orc","Troll"}}, g={{"o",1485,i=1,txt="Vile Familiar Head x6",n2="Vile Familiar Heads",m=1411,x=43.8,y=58.3}}},
  {t="Summon Imp", lv=1, n="Ruzan teaches you Summon Imp when you hand in the heads: summon it right away, it costs nothing and fights beside you. Then speak with Zureetha Fargaze a few steps away for a starter weapon.", f={r={"Orc","Troll"}}, g={{"t",1485,n2="Ruzan: Summon Imp",m=1411,x=42.6,y=69},{"a",1499,m=1411,x=42.6,y=69,ml=1},{"t",1499,m=1411,x=42.9,y=69.2}}},
  {t="Venya Marthand (Undead)", lv=1, n="Your first letter (Tainted Scroll, from Shadow Priest Sarvis after The Mindless Ones) points you to Maximillion, the warlock trainer in Deathknell. Venya Marthand waits inside the building beside him and asks for three Rattlecage Skulls.", f={r={"Scourge"}}, g={{"a",1470,m=1420,x=31,y=66.4,ml=1}}},
  {t="Rattlecage Skulls", lv=1, n="The Rattlecage Skeletons (level 2-3) stand around the old smithy buildings just north of Deathknell, often right against the walls. Four kills in five drop a skull, so plan on about five; twenty of them spawn there and each comes back after five minutes.", f={r={"Scourge"}}, g={{"o",1470,i=1,txt="Rattlecage Skull x3",n2="Rattlecage Skulls",m=1420,x=33,y=63}}},
  {t="Summon Imp", lv=1, n="Venya teaches you Summon Imp when you hand in the skulls: summon it right away, it costs nothing and fights beside you.", f={r={"Scourge"}}, g={{"t",1470,n2="Venya Marthand: Summon Imp",m=1420,x=31,y=66.4}}},
} end)

R:Segment({id="class/warlock/impsys-request",title="An Imp's Request",classes={"WARLOCK"},min=50,max=54,zone=1448,zoneName="Felwood",why="A staff, off-hand or robe for your 50s; Impsy's own errand, not a step of the Dreadsteed chain.",items={20536,20534,20530},folder="Warlock"}, function() return {
  {t="An Imp's Request (Stormwind)", lv=50, n="At 50 Demisette Cloyce in the Slaughtered Lamb, in the Mage Quarter, sends you to Impsy in Felwood with a piece of Felcloth.", w={{k="zone",neg=true,name="Felwood",area=361}}, f={r={"Human"}}, g={{"l",50,txt="Reach level 50"},{"a",8419,m=1453,x=39.2,y=85,ml=50}}},
  {t="An Imp's Request (Ironforge)", lv=50, n="At 50 Briarthorn in Ironforge sends you to Impsy in Felwood with a piece of Felcloth.", w={{k="zone",neg=true,name="Felwood",area=361}}, f={r={"Gnome"}}, g={{"l",50,txt="Reach level 50"},{"a",8419,m=1455,x=50.4,y=5.7,ml=50}}},
  {t="An Imp's Request (Orgrimmar)", lv=50, n="At 50 Zevrost in the Cleft of Shadow sends you to Impsy in Felwood with a piece of Felcloth.", w={{k="zone",neg=true,name="Felwood",area=361}}, f={r={"Orc","Troll"}}, g={{"l",50,txt="Reach level 50"},{"a",8419,m=1454,x=48.5,y=45.4,ml=50}}},
  {t="An Imp's Request (Undercity)", lv=50, n="At 50 Kaal Soulreaper in the Magic Quarter sends you to Impsy in Felwood with a piece of Felcloth.", w={{k="zone",neg=true,name="Felwood",area=361}}, f={r={"Scourge"}}, g={{"l",50,txt="Reach level 50"},{"a",8419,m=1458,x=86.2,y=15.9,ml=50}}},
  {t="Felcloth", lv=50, n="One Felcloth: the Jadefire satyrs of Felwood drop it about one kill in fourteen, and so do the Legashi satyrs and the Felguard Sentries you hunt for Niby's essences. Quicker: buy one at the Auction House. You need it for the trainer's An Imp's Request or for Impsy's own Hot and Itchy, the same errand: whichever you hold.", g={{"h",14256,txt="Get Felcloth",m=1448,x=32.2,y=67.1,n=1}}},
  {t="Impsy", lv=50, n="Impsy waits beside Niby the Almighty on a rise just north-east of Bloodvenom Post: coming north over the Bloodvenom Falls bridge, they stand off the road to the east, past a few oozes. Hand him the trainer's An Imp's Request with the cloth. Next he wants ten Rotting Wood and four Bloodvenom Essence.", w={{k="onquest",q={8419}}}, g={{"t",8419,m=1448,x=41.4,y=45}}},
  {t="Impsy: Hot and Itchy", lv=50, n="Impsy waits beside Niby the Almighty on a rise just north-east of Bloodvenom Post: coming north over the Bloodvenom Falls bridge, they stand off the road to the east, past a few oozes. Take his own Hot and Itchy and hand him the cloth at once. Next he wants ten Rotting Wood and four Bloodvenom Essence.", w={{k="turnedin",neg=true,q=8419}}, g={{"a",8420,n2="Impsy: Hot and Itchy",m=1448,x=41.4,y=45,ml=50},{"t",8420,m=1448,x=41.4,y=45}}},
  {t="Rotting Wood and Bloodvenom", lv=50, n="The Irontree treants (level 52) of Irontree Woods, in northern Felwood west of Talonbranch Glade, drop Rotting Wood one time in four; the big Withered Protector (55) often drops three at once but hits hard and dazes. The Tainted Oozes (51) around Impsy and along the Bloodvenom drop the essence one time in five.", g={{"a",8421,n2="Impsy: The Wrong Stuff",m=1448,x=41.4,y=45,ml=50},{"o",8421,i=1,txt="Rotting Wood x10",m=1448,x=48.5,y=29.8},{"o",8421,i=2,txt="Bloodvenom Essence x4",m=1448,x=44,y=46.4}}},
  {t="Impsy again", lv=50, n="Impsy now wants six Voodoo Feathers from the Sunken Temple: a dungeon run.", g={{"t",8421,m=1448,x=41.4,y=45},{"a",8422,m=1448,x=41.4,y=45,ml=50}}},
  {t="The Sunken Temple", lv=50, n="The Sunken Temple (Temple of Atal'Hakkar, level 50-56, a group of five) stands in the middle of the Pool of Tears: swim down into the temple and take the stairs to the entrance. The six troll guardians (level 51-52, elite) stand on the balconies around the central pit, each with adds; each drops his feather every time: Gasher and Zul'Lor the Amber, Hukku and Mijan the Blue, Zolo and Loro the Green. Not soloable at 52.", g={{"o",8422,i=1,txt="Amber Voodoo Feather x2",n2="Amber Voodoo Feathers: Gasher, Zul'Lor",m=1435,x=69,y=54,grp=true},{"o",8422,i=2,txt="Blue Voodoo Feather x2",n2="Blue Voodoo Feathers: Hukku, Mijan",m=1435,x=69,y=54,grp=true},{"o",8422,i=3,txt="Green Voodoo Feather x2",n2="Green Voodoo Feathers: Zolo, Loro",m=1435,x=69,y=54,grp=true}}},
  {t="Trolls of a Feather", lv=50, n="Choose the Soul Harvester (staff), the Abyss Shard (off-hand) or the Robes of Servitude.", g={{"t",8422,m=1448,x=41.4,y=45}}},
} end)

R:Segment({id="class/warlock/incubus-alliance",title="Succubus and Incubus (Alliance)",faction="Alliance",classes={"WARLOCK"},min=20,max=25,zone=1453,zoneName="Stormwind City",why="At 20: the succubus and Forever's incubus, its male twin, each with a soul pouch for your shards.",spells={712,713},spellNames={"Summon Succubus","Summon Incubus"},items={22243},folder="Warlock"}, function() return {
  {t="Gakin's Summons (Gnomes)", lv=20, n="At 20 Lago Blackwrench, the warlock trainer in Ironforge's Forlorn Cavern, sends you to Gakin the Darkbinder in Stormwind. Take the Deeprun Tram.", f={r={"Gnome"}}, g={{"l",20,txt="Reach level 20"},{"a",1717,m=1455,x=47.6,y=9.3,ml=20}}},
  {t="Devourer of Souls", lv=20, n="At 20 Gakin the Darkbinder, in the cellar of the Slaughtered Lamb in the Mage Quarter, sends you to Takar the Seer in the Barrens: a long trip for the Alliance. Take the boat from Menethil Harbor to Theramore and head west through Dustwallow Marsh, or the boat from Booty Bay to Ratchet.", g={{"l",20,txt="Reach level 20"},{"t",1717,m=1453,x=39.2,y=85.2,f={r={"Gnome"}}},{"a",1716,m=1453,x=39.2,y=85.2,ml=20}}},
  {t="Takar the Seer", lv=20, n="Takar the Seer camps at a tent with a campfire just north-east of Camp Taurajo, by a fork in the road: Horde ground, so come in from the east and keep clear of the Taurajo guards. Doan Karhan beside him starts the Orb of Soran'ruk. Takar offers both branches: take both.", g={{"t",1716,m=1413,x=49.3,y=57.1},{"a",1738,n2="the succubus",m=1413,x=49.3,y=57.1,ml=20},{"a",65602,n2="the incubus",m=1413,x=49.3,y=57.1,ml=20}}},
  {t="Heartswood", lv=20, n="Ordil'Aran lies in north-west Ashenvale, north of Astranaar along the road toward Darkshore. About twenty Dark Strand cultists hold the ruins around the great tree: keep to the outer wall, and click the Heartswood from as far away as it lets you. It is turned in to Gakin, not to Takar.", g={{"o",1738,i=1,txt="Heartswood",m=1440,x=31.6,y=31.6}}},
  {t="The Wooden Figurine", lv=20, n="The house stands alone in the trees of north-western Ashenvale, north-west of Ordil'Aran and well north of Maestra's Post: do it on the same trip as the Heartswood. Take the Unlit Torch from the table outside, light it at a campfire (a Basic Campfire of your own, or Talen's fire on Zoram Strand), and go straight back: the Burning Torch burns out after five minutes, so a fire of your own beside the house is quickest. Without it the figure in the house stops you. The figurine is upstairs.", g={{"h",190307,txt="Get Unlit Torch",n2="Unlit Torch, on the table outside",m=1440,x=26.8,y=22.4,n=1,opt=true},{"o",65602,i=1,txt="Wooden Figurine",n2="Wooden Figurine, upstairs",m=1440,x=26.6,y=22}}},
  {t="The Binding: succubus", lv=20, n="Back to Gakin with the Heartswood. He hands you the Heartswood Core: take the stairs behind him down to the crypt; part way along the lowest corridor a side stair on the left leads to the room with the purple circle. Stand on it and use the core. Summon your voidwalker first and keep the succubus (level 20, not elite) on the circle, or the guards may kill her and the kill does not count. If she wins, use the core again; keep it, Gakin takes it back.", g={{"t",1738,m=1453,x=39.2,y=85.2},{"a",1739,m=1453,x=39.2,y=85.2,ml=20},{"i",0,txt="Use Heartswood Core",n2="Heartswood Core, on the circle in the crypt",m=1453,x=39.1,y=84.4},{"o",1739,i=1,txt="Kill Summoned Succubus",m=1453,x=39.1,y=84.3},{"t",1739,n2="Gakin the Darkbinder: Summon Succubus",m=1453,x=39.2,y=85.2}}},
  {t="The Binding: incubus", lv=20, n="Give Gakin the figurine, then use the Wooden Figurine at the middle of the same circle and defeat the incubus it calls (level 20, not elite; it can charm you) with your voidwalker tanking. Keep the figurine: Gakin takes it back.", g={{"t",65602,m=1453,x=39.2,y=85.2},{"a",65603,m=1453,x=39.2,y=85.2,ml=20},{"o",65603,i=1,txt="Kill Summoned Incubus",n2="Summoned Incubus, at the circle in the crypt",m=1453,x=39,y=84.6},{"t",65603,n2="Gakin the Darkbinder: Summon Incubus",m=1453,x=39.2,y=85.2}}},
} end)

R:Segment({id="class/warlock/incubus-horde",title="Succubus and Incubus (Horde)",faction="Horde",classes={"WARLOCK"},min=20,max=28,zone=1454,zoneName="Orgrimmar",why="At 20: the succubus and Forever's incubus, its male twin, each with a soul pouch for your shards.",spells={712,713},spellNames={"Summon Succubus","Summon Incubus"},items={22243},folder="Warlock"}, function() return {
  {t="Devourer of Souls (Orgrimmar)", lv=20, n="At 20 Gan'rul Bloodeye, in the Cleft of Shadow under the Valley of Strength, sends you to Cazul a few steps away. Two trainers start these demons, Gan'rul here and Carendin Halgar in the Undercity, and you can take only one; this guide follows whichever Devourer of Souls you took. Cazul offers both of Orgrimmar's branches: take both.", g={{"l",20,txt="Reach level 20"},{"a",1507,m=1454,x=48.2,y=45.3,ml=20},{"t",1507,m=1454,x=47.1,y=46.4},{"a",1508,n2="the succubus",m=1454,x=47.1,y=46.4,ml=20},{"a",65601,n2="the incubus",m=1454,x=47.1,y=46.4,ml=20}}},
  {t="Zankaja", lv=20, n="Zankaja lives in a hut up on the cliffs on the west side of the city, above the Valley of Strength: climb the wind rider tower, cross the bridge at its top to the west and turn right off it. She sends you to the Crossroads.", g={{"t",1508,m=1454,x=37,y=59.5},{"a",1509,m=1454,x=37,y=59.5,ml=20}}},
  {t="Magar", lv=20, n="Magar keeps Magar's Cloth Goods on the main street east of the Cleft of Shadow. He asks you to look for his mate Krilge in Ashenvale.", g={{"t",65601,m=1454,x=63.6,y=49.9},{"a",65610,m=1454,x=63.6,y=49.9,ml=20}}},
  {t="Gazrog", lv=20, n="Gazrog waits in front of the inn at the Crossroads. He sends you on to Ken'zigla at Malaka'jin, in Stonetalon Mountains.", g={{"t",1509,m=1413,x=51.9,y=30.3},{"a",1510,m=1413,x=51.9,y=30.3,ml=20}}},
  {t="Ken'zigla", lv=20, n="Take the road west from the Crossroads into Stonetalon Mountains and, just past the border, the faint trail up to the left (south): Malaka'jin cannot be reached from the main road. Ken'zigla hands you her draught for Grunt Logmar.", g={{"t",1510,n2="Ken'zigla, Malaka'jin",m=1442,x=73.2,y=95.1},{"a",1511,m=1442,x=73.2,y=95.1,ml=20}}},
  {t="Grunt Dogran", lv=20, n="Grunt Logmar stands at Camp Taurajo, south down the road from the Crossroads. He sends you north to the quilboar camp where Dogran is held: the camp with two huts side by side, north-west of a decoy camp whose huts stand apart. A rare level 22 elite quilboar sometimes guards the huts: send your voidwalker in, sacrifice it if you must, and talk to Dogran. He gives you a pendant for Gan'rul. Keep it.", g={{"t",1511,n2="Grunt Logmar, Camp Taurajo",m=1413,x=44.6,y=59.3},{"a",1515,m=1413,x=44.6,y=59.3,ml=20},{"t",1515,m=1413,x=43.3,y=47.9},{"a",1512,m=1413,x=43.3,y=47.9,ml=20}}},
  {t="The Binding: succubus (Orgrimmar)", lv=20, n="Back to Gan'rul with the pendant. He hands you Dogran's Pendant: take it across the Cleft of Shadow to Neeru Fireblade's tent, stand on the purple circle and use it. Summon your voidwalker first and let it tank: the succubus (level 20, not elite) charms and lashes; keep your damage over time on her. If she wins, use the pendant again. Keep the pendant: Gan'rul takes it back.", g={{"t",1512,m=1454,x=48.2,y=45.3},{"a",1513,m=1454,x=48.2,y=45.3,ml=20},{"i",0,txt="Use Dogran's Pendant",n2="Dogran's Pendant, on the circle in Neeru's tent",m=1454,x=49.4,y=50},{"o",1513,i=1,txt="Kill Summoned Succubus",m=1454,x=49.4,y=50},{"t",1513,n2="Gan'rul Bloodeye: Summon Succubus",m=1454,x=48.2,y=45.3}}},
  {t="Fallen Sky Lake", lv=24, n="Fallen Sky Lake lies in southern Ashenvale, south-west of Splintertree Post. The Shadethicket Stone Movers and Bark Rippers (level 25-27) around the lake drop the Withered Scarf about one time in twenty, and the lone Shadethicket Oracle (30) can drop it too: plan on a good number of kills, so the guide waits for level 24 first (Forever made this quest level 27); with the succubus already bound you can leave it for your 20s leveling in Ashenvale. They respawn in five minutes.", w={{k="onquest",q={65610}}}, g={{"l",24,txt="Reach level 24"},{"o",65610,i=1,txt="Withered Scarf",m=1440,x=72.4,y=68.1}}},
  {t="The Binding: incubus (Orgrimmar)", lv=24, n="Back to Gan'rul with the scarf, then use the Withered Scarf on the same circle in Neeru's tent and defeat the incubus it calls (level 20, not elite) with your voidwalker tanking. Keep the scarf: Gan'rul takes it back.", g={{"t",65610,m=1454,x=48.2,y=45.3},{"a",65604,m=1454,x=48.2,y=45.3,ml=20},{"o",65604,i=1,txt="Kill Summoned Incubus",n2="Summoned Incubus, at the circle in Neeru's tent",m=1454,x=49.8,y=50.5},{"t",65604,n2="Gan'rul Bloodeye: Summon Incubus",m=1454,x=48.2,y=45.3}}},
  {t="Devourer of Souls (Undercity)", lv=24, n="The Undercity's version, for warlocks who took Carendin Halgar's Devourer of Souls instead of Gan'rul's. At 20 Carendin, in the Magic Quarter, sends you to Godrick Farsan close by. Godrick shows you an image of each quarry and offers both branches: take both.", g={{"l",20,txt="Reach level 20"},{"a",1472,m=1458,x=85.1,y=26,ml=20},{"t",1472,m=1458,x=84.8,y=14.8},{"a",1476,n2="the succubus",m=1458,x=84.8,y=14.8,ml=20},{"a",65593,n2="the incubus",m=1458,x=84.8,y=14.8,ml=20}}},
  {t="Silverpine hearts", lv=24, n="Avelina Lilly (level 22) works as a tailor for the Dalaran wizards at Ambermill, in eastern Silverpine: the wizards around her are hostile. Dalin Forgewright (level 20, not elite) patrols near the Greymane Wall in the far south. Both are Alliance-friendly humans: attacking them can flag you for PvP. Each drops her or his heart.", g={{"o",65593,i=1,txt="Avelina's Heart",m=1421,x=63.1,y=65.3},{"o",1476,i=1,txt="Dalin's Heart",m=1421,x=47.6,y=85.7}}},
  {t="Corma Villard", lv=24, n="Corma Villard (level 22, not elite; Comar in older records) wanders the north of the Wetlands just past the Thandol Span, to the right as you come off the bridge. From the Undercity head through Hillsbrad and Arathi Highlands, where the mobs are 30 and up. Attacking her flags you for PvP.", g={{"o",1476,i=2,txt="Corma's Heart",m=1437,x=49.9,y=12.6}}},
  {t="The Binding: succubus (Undercity)", lv=24, n="Back to Carendin with Dalin's and Corma's hearts. He hands you the Pure Hearts: go down to the summoning circle below him, stand on it and use them. Summon your voidwalker first and keep the fight on the circle, or the guards may kill her and the kill does not count. If she wins, use the hearts again; keep them, Carendin takes them back.", g={{"t",1476,m=1458,x=85.1,y=26},{"a",1474,m=1458,x=85.1,y=26,ml=20},{"i",0,txt="Use Pure Hearts",n2="Pure Hearts, on the circle below Carendin",m=1458,x=86.6,y=27.1},{"o",1474,i=1,txt="Kill Summoned Succubus",m=1458,x=86.7,y=27.1},{"t",1474,n2="Carendin Halgar: Summon Succubus",m=1458,x=85.1,y=26}}},
  {t="Isaac Pearson", lv=24, n="Isaac Pearson (level 22) works in Ratchet, on the Barrens coast, at one of two spots in town: take the zeppelin to Durotar and head south, or fly from Orgrimmar. He is an Alliance-friendly human: attacking him can flag you for PvP.", g={{"o",65593,i=2,txt="Isaac's Heart",m=1413,x=62.1,y=38.4}}},
  {t="The Binding: incubus (Undercity)", lv=24, n="Back to Carendin with the lovers' hearts, then place the Lovers' Hearts on the same circle and defeat the incubus they call (level 20, not elite; it can charm you). Keep the hearts: Carendin takes them back.", g={{"t",65593,m=1458,x=85.1,y=26},{"a",65597,m=1458,x=85.1,y=26,ml=20},{"o",65597,i=1,txt="Kill Summoned Incubus",n2="Summoned Incubus, at the circle below Carendin",m=1458,x=85,y=25.2},{"t",65597,n2="Carendin Halgar: Summon Incubus",m=1458,x=85.1,y=26}}},
} end)

R:Segment({id="class/warlock/orb-of-orahil",title="Orb of Orahil",classes={"WARLOCK"},min=35,max=40,zone=1413,zoneName="The Barrens",why="An off-hand orb or a staff for your late 30s, down the felhound's or the infernal's path, your pick.",items={15108,15106,15107,15105},folder="Warlock"}, function() return {
  {t="Knowledge of the Orb of Orahil (Stormwind)", lv=35, n="At 35 Demisette Cloyce in the Slaughtered Lamb, in the Mage Quarter, sends you to Menara Voidrender in Ratchet.", f={r={"Human"}}, g={{"l",35,txt="Reach level 35"},{"a",4968,m=1453,x=39.2,y=85,ml=35}}},
  {t="Knowledge of the Orb of Orahil (Ironforge)", lv=35, n="At 35 Briarthorn in Ironforge sends you to Menara Voidrender in Ratchet.", f={r={"Gnome"}}, g={{"l",35,txt="Reach level 35"},{"a",4965,m=1455,x=50.4,y=5.7,ml=35}}},
  {t="Knowledge of the Orb of Orahil (Orgrimmar)", lv=35, n="At 35 Zevrost in the Cleft of Shadow sends you to Menara Voidrender in Ratchet.", f={r={"Orc","Troll"}}, g={{"l",35,txt="Reach level 35"},{"a",4967,m=1454,x=48.5,y=45.4,ml=35}}},
  {t="Knowledge of the Orb of Orahil (Undercity)", lv=35, n="At 35 Kaal Soulreaper in the Magic Quarter sends you to Menara Voidrender in Ratchet. The zeppelin from Tirisfal Glades flies to Durotar.", f={r={"Scourge"}}, g={{"l",35,txt="Reach level 35"},{"a",4969,m=1458,x=86.2,y=15.9,ml=35}}},
  {t="Menara Voidrender", lv=35, n="Menara Voidrender and her two acolytes stand in Strahad Farsan's tower on the hill above Ratchet.", g={{"t",4968,m=1413,x=62.5,y=35.5,f={r={"Human"}}},{"t",4965,m=1413,x=62.5,y=35.5,f={r={"Gnome"}}},{"t",4967,m=1413,x=62.5,y=35.5,f={r={"Orc","Troll"}}},{"t",4969,m=1413,x=62.5,y=35.5,f={r={"Scourge"}}},{"a",1799,m=1413,x=62.5,y=35.5,ml=35}}},
  {t="Choose an acolyte", lv=35, n="Pick one acolyte: you can take only one of their quests. Acolyte Wytula's felhound path ends with the Orb or Staff of Dar'Orahil, the shadow versions; Acolyte Magaz's infernal path with the Orb or Staff of Noh'Orahil, much the same items on the fire side. Most warlocks lean on shadow, but compare the four in their tooltips first. The guide follows the one you take. Keep the ruby or the emerald: it is handed back.", g={{"a",4962,n2="Acolyte Wytula: she gives you the Felhas Ruby",m=1413,x=62.6,y=35.3,ml=35},{"a",4963,n2="Acolyte Magaz: he gives you the Infus Emerald",m=1413,x=62.6,y=35.2,ml=35}}},
  {t="Mannoroc Coven", lv=35, n="Mannoroc Coven fills south-central Desolace, east of Shadowprey Village. The Burning Blade Summoners (level 38-39, warlocks with imps) carry the Infernal Orb every time. For the spirit, bring your demon to low health with your damage over time, then channel the ruby or the emerald on it and keep channelling while it dies, as with Drain Soul: the gem does no damage of its own. The ruby works on the coven's felhounds: the two Mana Eaters (37-38) in the north, and the Mage Hunters (38) and Ley Hunters (39) further south. The emerald works on the Lesser Infernals (36-37, sixteen of them, fire-resistant).", g={{"o",1799,i=1,txt="Infernal Orb",n2="Infernal Orb, from the Burning Blade Summoners",m=1443,x=66.5,y=77.9},{"o",4962,i=1,txt="Imprisoned Felhound Spirit",n2="Imprisoned Felhound Spirit, from a Mana Eater, Mage Hunter or Ley Hunter",m=1443,x=52.9,y=68.1},{"o",4963,i=1,txt="Imprisoned Infernal Spirit",n2="Imprisoned Infernal Spirit, from a Lesser Infernal",m=1443,x=54.3,y=71.1}}},
  {t="The demon's spirit", lv=35, n="Back to Menara in the tower above Ratchet with the spirit and the gem first: her orb follows from it.", g={{"t",4962,m=1413,x=62.5,y=35.5},{"t",4963,m=1413,x=62.5,y=35.5}}},
  {t="Tabetha", lv=38, n="Tabetha lives at her farm in the middle of Dustwallow Marsh, south of the road from the Barrens and south-west of Theramore; a spirit healer stands beside it. Deadmire, a level 45 crocolisk, patrols the creeks just north-east. Hand in the orb now; Cleansing waits for level 38. Before you accept it, clear the spiders and crocolisks around her paddock. Accepting starts a 3-minute timer: she walks to the paddock and lets the Demon of the Orb out. It is elite (level 40): grouping up is encouraged; a warlock of about 40 can solo it with Fear or Banish and damage over time, a level 38 one brings a friend. The timer keeps running after the kill, so hand in at once. If time runs out, abandon the quest and take it from Tabetha again.", g={{"t",1799,m=1445,x=46.1,y=57.1},{"l",38,txt="Reach level 38"},{"a",4961,m=1445,x=46.1,y=57.1,ml=35},{"o",4961,i=1,txt="Kill Demon of the Orb",m=1445,x=45.8,y=57,grp=true},{"t",4961,m=1445,x=46.1,y=57.1},{"a",4976,m=1445,x=46.1,y=57.1,ml=35}}},
  {t="The Orb of Dar'Orahil", lv=38, n="Back to Menara in the tower above Ratchet with the cleansed orb. On the felhound path, accept her last quest and wait beside her while she completes the Orb of Dar'Orahil (do not attack her: the quest log calls it a kill), then speak to her again and pick the off-hand orb or the staff.", g={{"t",4976,m=1413,x=62.5,y=35.5},{"a",4964,m=1413,x=62.5,y=35.5,ml=35},{"c",4964,txt="Menara Voidrender",n2="Wait beside Menara while she makes the orb",m=1413,x=62.5,y=35.4},{"t",4964,m=1413,x=62.5,y=35.5}}},
  {t="The Orb of Noh'Orahil", lv=38, n="On the infernal path, accept her last quest and wait beside Menara while she completes the Orb of Noh'Orahil, then speak to her again and pick the off-hand orb or the staff.", g={{"a",4975,m=1413,x=62.5,y=35.5,ml=35},{"c",4975,txt="Menara Voidrender",n2="Wait beside Menara while she makes the orb",m=1413,x=62.5,y=35.4},{"t",4975,m=1413,x=62.5,y=35.5}}},
} end)

R:Segment({id="class/warlock/orb-of-soranruk",title="Orb of Soran'ruk",classes={"WARLOCK"},min=22,max=30,zone=1413,zoneName="The Barrens",why="A rare off-hand orb or staff for your 20s, for fragments from two dungeons.",items={6898,15109},folder="Warlock"}, function() return {
  {t="Doan Karhan", lv=22, n="Doan Karhan camps beside Takar the Seer, at a tent just north-east of Camp Taurajo in the southern Barrens. Alliance warlocks reach him from Ratchet or Theramore; Horde ones head south from the Crossroads. He wants fragments from two dungeons: take the quest before your Blackfathom Deeps and Shadowfang Keep runs.", g={{"l",20,txt="Reach level 20"},{"a",1740,m=1413,x=49.3,y=57.2,ml=20}}},
  {t="Blackfathom Deeps", lv=22, n="Blackfathom Deeps (level 24-32, a group of five) opens in the ruins on the north-west coast of Ashenvale, under the water at Zoram Strand. The Twilight Acolytes (level 24-25, elite, healers) stand in the last halls, around Twilight Lord Kelris and the altar before Aku'mai; each one drops a fragment, but only three spawn in a run and they do not come back for two hours, so one run covers one warlock: kill them first, before they heal the rest.", g={{"o",1740,i=1,txt="Soran'ruk Fragment x3",n2="Soran'ruk Fragments, from the Twilight Acolytes inside",m=1440,x=14.5,y=14.2,grp=true}}},
  {t="Shadowfang Keep", lv=22, n="Shadowfang Keep (level 22-30, a group of five) stands on the hill south of the Sepulcher. Free the prisoner in the cells right of the entrance and he opens the way into the courtyard. The Shadowfang Darksouls (level 20-21, elite) are not in the courtyard: they walk the halls past it, up the ramp that curves left and in the building after. About twelve stand in a run and one in five drops the Large Fragment, so clear every Darksoul and run it again if it does not drop.", g={{"o",1740,i=2,txt="Large Soran'ruk Fragment",n2="Large Soran'ruk Fragment, from the Shadowfang Darksouls inside",m=1421,x=44.8,y=67.8,grp=true}}},
  {t="Back to Doan Karhan", lv=22, n="Choose the off-hand Orb of Soran'ruk or the two-handed Staff of Soran'ruk.", g={{"t",1740,m=1413,x=49.3,y=57.2}}},
} end)

R:Segment({id="class/warlock/shard-of-the-green-flame",title="Shard of the Green Flame",classes={"WARLOCK"},min=50,max=56,zone=1448,zoneName="Felwood",why="A rare off-hand for your 50s from Niby and Impsy in Felwood, the camp that also offers An Imp's Request.",items={18762},folder="Warlock"}, function() return {
  {t="Niby the Almighty", lv=50, n="At 50 Niby the Almighty and his imp Impsy wait on a rise in central Felwood just north-east of Bloodvenom Post: coming north over the Bloodvenom Falls bridge, they stand off the road to the east, past a few oozes. Niby sends you to Impsy, beside him, who wants three Flawless Fel Essences from three places.", g={{"l",50,txt="Reach level 50"},{"a",7601,m=1448,x=41.4,y=44.9,ml=50},{"t",7601,m=1448,x=41.4,y=45},{"a",7602,m=1448,x=41.4,y=45,ml=50}}},
  {t="Azshara", lv=50, n="The Legashi satyrs (level 51-53) hold the Legash Encampment on Azshara's northern coast. Every kind drops the essence three times in four; the satyrs burn mana and the Hellcallers rain fire, so pull them singly.", g={{"o",7602,i=1,txt="Flawless Fel Essence (Azshara)",m=1447,x=61.4,y=20.9}}},
  {t="Jaedenar", lv=53, n="Jaedenar lies just south of Bloodvenom Post, west of the road. The guide waits for level 53 first: its Legionnaires are 55. Of its two caves, Shadow Hold is the northern one, further up the hill; the other has no Legionnaires. Shadow Hold's tunnels run north under the hills, and the Jaedenar Legionnaires (level 55) stand in its deeper halls, from the first ramps on toward Lord Banehollow's chamber; they Uppercut anyone in melee. Three kills in four give the essence, but only about eleven spawn: clear your way in and wait out a five-minute respawn if you must. The cultists of Jaedenar and Shadow Hold are all hostile.", g={{"l",53,txt="Reach level 53"},{"o",7602,i=2,txt="Flawless Fel Essence (Jaedenar)",m=1448,x=37.6,y=50.2}}},
  {t="The Dark Portal", lv=53, n="The Felguard Sentries (level 54) walk around the Dark Portal in the south of the Blasted Lands, each with a felhunter. Leave the level 57 Servants of Razelikh alone: they cannot be killed without their own quest.", g={{"o",7602,i=3,txt="Flawless Fel Essence (Dark Portal)",m=1419,x=58.5,y=51.2}}},
  {t="Impsy", lv=53, n="Back to Impsy. He hands you the Fel Fire: keep it, it wakes the infernal Kroshius.", g={{"t",7602,m=1448,x=41.4,y=45},{"a",7603,m=1448,x=41.4,y=45,ml=50}}},
  {t="Kroshius", lv=53, n="Kroshius' remains lie in Shatter Scar Vale, the burnt crater north of Niby: follow the road north from his camp; the remains lie a little east of it. Use the Fel Fire beside them and wait for him to rise. Kroshius is elite (level 55): grouping up is encouraged; a warlock of 55 or more can solo him with Fear and damage over time, or with Enslave Demon, but fire spells do nothing to him and he knocks you back. If you die he heals to full; he rises again three minutes after he dies. An elite infernal patrols the pool south of the remains: pull Kroshius away from it. He always drops his core. Lost the Fel Fire? Abandon the quest and take it again from Impsy.", g={{"i",0,txt="Use Fel Fire",n2="Fel Fire, at Kroshius' Remains",m=1448,x=45.7,y=34.8},{"o",7603,i=1,txt="Kill Kroshius",m=1448,x=45.7,y=34.8,grp=true},{"o",7603,i=2,txt="Kroshius' Infernal Core",m=1448,x=45.7,y=34.8,grp=true}}},
  {t="Back to Niby", lv=53, g={{"t",7603,n2="Niby the Almighty: Shard of the Green Flame",m=1448,x=41.4,y=44.9}}},
} end)

R:Segment({id="class/warlock/tome-of-sacrifice",title="Tome of Sacrifice",classes={"WARLOCK"},min=60,max=60,zone=1419,zoneName="Blasted Lands",why="A rare off-hand at 60, Daio's payment for capturing a Doomguard Commander in the Blasted Lands.",items={18602},folder="Warlock"}, function() return {
  {t="Daio the Decrepit", lv=60, n="At 60 Daio the Decrepit waits in the Tainted Scar, the demon-filled hollow in the west of the Blasted Lands. The Scar is full of hard-hitting elites: Soulstone yourself first, then keep to the right-hand wall going in, or ride through mounted. Daio gives you two errands at once.", g={{"l",60,txt="Reach level 60"},{"a",7581,m=1419,x=34.1,y=50.1,ml=60},{"a",7582,m=1419,x=34.1,y=50.1,ml=60}}},
  {t="Satyr Blood", lv=60, n="The Wildspawn satyrs (level 55-57, elite) fill the Warpwood Quarter, Dire Maul's eastern wing: bring a group of five. Four in five drop a blood, but they do not come back for two hours and one full clear may come up short of fifteen; reset and run it again. The back door at Lariss Pavilion needs the Crescent Key, which drops inside this wing; until someone has it, go in by Dire Maul's main gate in central Feralas.", g={{"o",7581,i=1,txt="Satyr Blood x15",n2="Satyr Blood, from the Wildspawn inside",m=1444,x=59.2,y=45.1,grp=true}}},
  {t="Tears of the Hederine", lv=60, n="The Hederine demons (level 57-60, elite) hold Darkwhisper Gorge in the far south of Winterspring: grouping up is encouraged. Two Slayers guard the gorge past the bridge; the western tunnel leads to more Initiates, the easiest of them (watch for their Dominate Mind). A warlock can solo them one at a time with Fear or Banish and damage over time, but slowly. Any of them can drop the Tears, four kills in five.", g={{"o",7582,i=1,txt="Tears of the Hederine x5",m=1452,x=58.3,y=82.2,grp=true}}},
  {t="Suppression", lv=60, n="Hand both in to Daio and take the Glowing Crystal Prison. Find a Doomguard Commander (level 61, elite) standing alone in the Tainted Scar, open from about 30 yards with your voidwalker on him, and channel the prison on him for about 20 seconds: he attacks you to break free, and his War Stomp can interrupt the channel, so sacrifice the voidwalker for its shield if you must. Grouping up is encouraged: a second player to tank makes it easy. When the channel finishes he becomes the Imprisoned Doomguard: click it. If the channel breaks, kill him or run, and try another.", g={{"t",7581,m=1419,x=34.1,y=50.1},{"t",7582,m=1419,x=34.1,y=50.1},{"a",7583,m=1419,x=34.1,y=50.1,ml=60},{"o",7583,i=1,txt="Use Glowing Crystal Prison",n2="Glowing Crystal Prison, on a Doomguard Commander",m=1419,x=34.5,y=63.7},{"o",7583,i=1,txt="Imprisoned Doomguard",n2="Imprisoned Doomguard, click it",m=1419,x=34.5,y=63.7}}},
  {t="Back to Daio", lv=60, g={{"t",7583,n2="Daio the Decrepit: Tome of Sacrifice",m=1419,x=34.1,y=50.1}}},
} end)

R:Segment({id="class/warlock/voidwalker-alliance",title="Voidwalker (Alliance)",faction="Alliance",classes={"WARLOCK"},min=10,max=12,zone=1429,zoneName="Elwynn Forest",why="Your tank demon at 10: the voidwalker, after a dark sorceress's choker and a fight in Gakin's crypt.",spells={697},spellNames={"Summon Voidwalker"},folder="Warlock"}, function() return {
  {t="Gakin's Summons (Humans)", lv=10, n="At 10 Remen Marcot, in the cellar of the Lion's Pride Inn in Goldshire (the stairs down are in the back room past the butcher's table), sends you to Gakin the Darkbinder in Stormwind.", f={r={"Human"}}, g={{"l",10,txt="Reach level 10"},{"a",1685,n2="Remen Marcot, Lion's Pride Inn cellar",m=1429,x=44.5,y=66.3,ml=10}}},
  {t="The Slaughtered Lamb (Gnomes)", lv=10, n="At 10 Lago Blackwrench, the warlock trainer in Ironforge's Forlorn Cavern, sends you to Gakin the Darkbinder in Stormwind. Take the Deeprun Tram from Tinker Town. If Lago does not offer it, go to Gakin anyway: he still gives you the next quest.", f={r={"Gnome"}}, g={{"l",10,txt="Reach level 10"},{"a",1715,n2="Lago Blackwrench, Forlorn Cavern",m=1455,x=47.6,y=9.3,ml=10}}},
  {t="Gakin the Darkbinder", lv=10, n="The Slaughtered Lamb is the tavern in the Mage Quarter; Gakin is in its cellar, down the stairs inside.", g={{"t",1685,m=1453,x=39.2,y=85.2,f={r={"Human"}}},{"t",1715,m=1453,x=39.2,y=85.2,f={r={"Gnome"}}},{"a",1688,m=1453,x=39.2,y=85.2,ml=10}}},
  {t="Surena Caledon", lv=10, n="Surena Caledon (level 9) is inside the farmhouse at the Brackwell Pumpkin Patch, south-east Elwynn near the Redridge road. Morgan the Collector (level 10) and a warrior stand with her and join the fight; Morgan gouges and goes for your imp, so keep him Feared. Put your damage over time on Surena first, Fear the others, and loot her choker before you finish them: it stays yours even if you die after. She throws fireballs from range and is back three minutes after she dies. Have the quest before you kill her, or the choker does not drop.", g={{"i",0,txt="Kill Surena Caledon",m=1429,x=71,y=80.8,opt=true},{"o",1688,i=1,txt="Surena's Choker",m=1429,x=71,y=80.8}}},
  {t="The Binding", lv=10, n="Back to Gakin. He hands you the Bloodstone Choker. The circle is hard to find: take the stairs behind Gakin down; part way along the lowest corridor a side stair on the left leads into a room with a glowing purple circle in the middle. Stand on it and use the choker. The voidwalker (level 10, not elite) gets dangerous below 30% health: Curse of Agony, Corruption and Immolate with your imp on it, Fear when it gets close. If it beats you, use the choker again. Keep the choker: Gakin takes it back.", g={{"t",1688,m=1453,x=39.2,y=85.2},{"a",1689,m=1453,x=39.2,y=85.2,ml=10},{"i",0,txt="Use Bloodstone Choker",n2="Bloodstone Choker, on the circle in the crypt",m=1453,x=39.1,y=84.4},{"o",1689,i=1,txt="Kill Summoned Voidwalker",m=1453,x=39.1,y=84.3},{"t",1689,n2="Gakin the Darkbinder: Summon Voidwalker",m=1453,x=39.2,y=85.2}}},
} end)

R:Segment({id="class/warlock/voidwalker-horde",title="Voidwalker (Horde)",faction="Horde",classes={"WARLOCK"},min=10,max=12,zone=1411,zoneName="Durotar",why="Your tank demon at 10: the voidwalker, after a stolen book and a fight at a summoning circle.",spells={697},spellNames={"Summon Voidwalker"},folder="Warlock"}, function() return {
  {t="Gan'rul's Summons (Orcs and Trolls)", lv=10, n="At 10 Ophek sends you to Gan'rul Bloodeye. He stands outside at the back of Razor Hill's barracks, the big building on the east side of town (not the inn), a few steps from Dhugru Gorelust, the warlock trainer. Gan'rul stands with the senior warlocks in the Cleft of Shadow, the cavern under Orgrimmar's Valley of Strength. An Orc or Troll leveling in Tirisfal Glades can take the Undercity version from Ageron Kargal in Brill instead (the Undercity steps below): you can do only one of the two.", f={r={"Orc","Troll"}}, g={{"l",10,txt="Reach level 10"},{"a",1506,m=1411,x=54.4,y=41.3,ml=10},{"t",1506,n2="Gan'rul Bloodeye, Cleft of Shadow",m=1454,x=48.2,y=45.3},{"a",1501,m=1454,x=48.2,y=45.3,ml=10}}},
  {t="Skull Rock", lv=10, n="Skull Rock is the cave in the cliffs just east of Orgrimmar's gate. Inside, take the right-hand ramp up and follow it to the top: the Burning Blade Stash sits on that upper ledge, which cannot be reached from the lower floor. The cave is packed with Burning Blade Apprentices and Fanatics (level 9-11, many with voidwalkers) that respawn quickly, and Gazz'uz, a level 14 Burning Blade warlock, stands near the stash. Old notes call him elite; Forever's data lists him as normal. At 10 it is hard alone: pull one pack at a time and Fear the extra, wait for 11, or go with a friend. The stash always holds the tablet.", f={r={"Orc","Troll"}}, g={{"o",1501,i=1,txt="Tablet of Verga",n2="Tablet of Verga, in the Burning Blade Stash",m=1411,x=51.6,y=9.8}}},
  {t="The Binding (Orgrimmar)", lv=10, n="Back to Gan'rul. He hands you the Glyphs of Summoning: take them across the Cleft of Shadow to Neeru Fireblade's tent, stand on the purple circle on its floor and use them. The voidwalker (level 10, not elite) hits hard at 30% health and leaves after three minutes, so start at once: Curse of Agony, Corruption and Immolate, send your imp in, and Fear it when you need a breather. If it beats you or leaves, the glyphs are not used up: use them again on the circle. Keep the glyphs: Gan'rul takes them back.", f={r={"Orc","Troll"}}, g={{"t",1501,m=1454,x=48.2,y=45.3},{"a",1504,m=1454,x=48.2,y=45.3,ml=10},{"i",0,txt="Use Glyphs of Summoning",n2="Glyphs of Summoning, on the circle in Neeru's tent",m=1454,x=49.4,y=50},{"o",1504,i=1,txt="Kill Summoned Voidwalker",m=1454,x=49.3,y=50},{"t",1504,n2="Gan'rul Bloodeye: Summon Voidwalker",m=1454,x=48.2,y=45.3}}},
  {t="Halgar's Summons (Undercity)", lv=10, n="At 10 Ageron Kargal, upstairs in the Gallows' End Tavern in Brill, sends you to Carendin Halgar: the version for the Undead, and for Orcs and Trolls who level in Tirisfal Glades instead of taking Gan'rul's. Carendin stands in the Undercity's Magic Quarter, by the Temple of the Damned.", f={r={"Orc","Troll","Scourge"}}, g={{"l",10,txt="Reach level 10"},{"a",1478,n2="Ageron Kargal, upstairs in the Brill inn",m=1420,x=61.6,y=52.7,ml=10},{"t",1478,n2="Carendin Halgar, Magic Quarter",m=1458,x=85.1,y=26},{"a",1473,m=1458,x=85.1,y=26,ml=10}}},
  {t="Perrine's Chest", lv=10, n="The Scarlet tower stands in the fields west of the Undercity's ruins (not the tower near Deathknell). The grimoire is in the small chest on the ground floor, under the stairs; ignore the chest upstairs. Captain Perrine (level 9) and a Scarlet Zealot guard it: kill them, or Fear the zealot while you deal with Perrine. Scarlet Missionaries and Zealots (level 7-9) walk the fields around the tower. The chest is back three seconds after anyone opens it.", f={r={"Orc","Troll","Scourge"}}, g={{"o",1473,i=1,txt="Egalin's Grimoire",n2="Egalin's Grimoire, in Perrine's Chest",m=1420,x=51.1,y=67.6}}},
  {t="The Binding (Undercity)", lv=10, n="Back to Carendin. He hands you the Runes of Summoning: go down the stairs from him to the summoning circle and use them while standing on it. Fight the voidwalker (level 10, not elite) on the circle: if it wanders off, the city guards may kill it and the kill does not count. Curse of Agony, Corruption and Immolate with your imp tanking bring it down; it hits harder below 30%. If you lose, use the runes again. Keep the runes: Carendin takes them back.", f={r={"Orc","Troll","Scourge"}}, g={{"t",1473,m=1458,x=85.1,y=26},{"a",1471,m=1458,x=85.1,y=26,ml=10},{"i",0,txt="Use Runes of Summoning",n2="Runes of Summoning, on the circle below Carendin",m=1458,x=86.6,y=27.1},{"o",1471,i=1,txt="Kill Summoned Voidwalker",m=1458,x=86.6,y=27.1},{"t",1471,n2="Carendin Halgar: Summon Voidwalker",m=1458,x=85.1,y=26}}},
} end)

R:Segment({id="class/warrior/brutal-armor",title="Brutal Armor",faction="Horde",classes={"WARRIOR"},min=20,max=32,zone=1413,zoneName="The Barrens",why="Starts now at 20 at your trainer; four armor pieces at 30 (hauberk, helm, gauntlets, legguards), a shield on the way.",items={7133,7130,7129,7132,7120},folder="Warrior"}, function() return {
  {t="Speak with Ruga (Orgrimmar)", lv=20, n="At 20, Sorek in the Valley of Honor sends you to Ruga Ragetotem in Camp Taurajo.", f={r={"Orc","Troll","Skyborne"}}, g={{"l",20,txt="Reach level 20"},{"a",1823,m=1454,x=80.4,y=32.4,ml=20}}},
  {t="Speak with Ruga (Thunder Bluff)", lv=20, n="At 20, Torm Ragetotem, the warrior trainer of Thunder Bluff, sends you to Ruga Ragetotem in Camp Taurajo.", f={r={"Tauren"}}, g={{"l",20,txt="Reach level 20"},{"a",1823,m=1456,x=57.2,y=87.4,ml=20}}},
  {t="Speak with Ruga (Undercity)", lv=20, n="At 20, Baltus Fowler, a warrior trainer of the Undercity, sends you to Ruga Ragetotem in Camp Taurajo.", f={r={"Scourge"}}, g={{"l",20,txt="Reach level 20"},{"a",1823,m=1458,x=47.4,y=17.3,ml=20}}},
  {t="Ruga Ragetotem", lv=20, n="Fly to Camp Taurajo. Ruga stands in the hut with the leatherworking and tailoring trainers.", g={{"t",1823,m=1413,x=44.7,y=59.4},{"a",1824,m=1413,x=44.7,y=59.4,ml=20}}},
  {t="Trial at the Field of Giants", lv=20, n="You have 30 minutes, and each Twitching Antenna rots 15 minutes after you loot it, so take the quest only when ready (logging out does not stop the clock). The Silithid Mounds dot the Field of Giants south of Camp Taurajo; every silithid drops an antenna. Creepers (level 20-21) and Grubs are the easiest: Swarmers (21-22) call small swarms and Creepers lay eggs that hatch adds. The eastern part of the field has plenty of Creepers. Ruga's Bulwark, a shield, is the reward.", g={{"o",1824,i=1,txt="Twitching Antenna x5",n2="Twitching Antenna, from the silithid",m=1413,x=45.1,y=69},{"t",1824,n2="Ruga Ragetotem: Ruga's Bulwark",m=1413,x=44.7,y=59.4},{"a",1825,m=1413,x=44.7,y=59.4,ml=20}}},
  {t="Thun'grim Firegaze", lv=20, n="Thun'grim's hut sits on top of Thorn Hill, east of the Crossroads: climb the broad ridge on the north or east side. Brutal Armor is a level 30 quest; take it now and gather on the way. Thun'grim's Instructions list where each material comes from.", g={{"t",1825,m=1413,x=57.2,y=30.3},{"a",1838,m=1413,x=57.2,y=30.3,ml=20}}},
  {t="Windshear Mine", lv=20, n="You need 15 Smoky Iron Ingots. The Windshear Mine lies at the east end of Windshear Crag, east of Sun Rock Retreat; every Windshear kobold (level 19-23) drops an ingot four kills in five. Stonecutters, Geomancers and Overlords run for help when low; Geomancers cast Frostbolt.", g={{"o",1838,i=1,txt="Smoky Iron Ingot x15",n2="Smoky Iron Ingot, from the Windshear kobolds",m=1442,x=71.8,y=60.3}}},
  {t="Hillsbrad Miners", lv=25, n="You need 10 Powdered Azurite. The guide waits for level 25 first. The Hillsbrad Miners (level 26-27) work the mine in the hills west of Southshore and drop the azurite four kills in five; they fight in Defensive Stance, sunder your armor and run for help at 30% health. Fly to Tarren Mill and head south-west.", g={{"l",25,txt="Reach level 25"},{"o",1838,i=2,txt="Powdered Azurite x10",n2="Powdered Azurite, from the Hillsbrad Miners",m=1424,x=30,y=55}}},
  {t="Roogug in Razorfen Kraul", lv=26, n="Roogug is an elite quilboar (level 28) inside Razorfen Kraul, the dungeon at the south end of the Barrens; a five-player dungeon: needs a group of five, his guards come with him. The guide waits for level 26 first. Inside take the left path at the first fork, cross the vine bridge over the pig pens, go past the room with the big cauldron: he waits in the room on the right. He casts Lightning Bolt and calls Earth Rumblers. The vial always drops.", g={{"l",26,txt="Reach level 26"},{"o",1838,i=4,txt="Vial of Phlogiston",n2="Vial of Phlogiston, from Roogug",m=1413,x=42.9,y=90.2,grp=true}}},
  {t="Iron Bars", lv=26, n="You need 10 Iron Bars. Miners smelt them from Iron Ore (one ore a bar, Smelt Iron at Mining 125); everyone else buys them at the auction house in Orgrimmar.", g={{"o",1838,i=3,txt="Iron Bar x10",n2="Iron Bars: Auctioneer Thathung",m=1454,x=55.9,y=62.7}}},
  {t="Brutal Hauberk", lv=26, n="Back to Thun'grim on Thorn Hill. Brutal Hauberk is the first piece; he then sends you to three crafters, one per piece: take all three.", g={{"t",1838,m=1413,x=57.2,y=30.3},{"a",1848,m=1413,x=57.2,y=30.3,ml=20},{"t",1848,m=1413,x=57.2,y=30.3},{"a",1839,m=1413,x=57.2,y=30.3,ml=20},{"a",1840,m=1413,x=57.2,y=30.3,ml=20},{"a",1841,m=1413,x=57.2,y=30.3,ml=20}}},
  {t="Ula'elek", lv=26, n="Ula'elek is in Sen'jin Village on the Durotar coast. He wants 7 Uncloven Satyr Hooves.", g={{"t",1839,m=1411,x=56.3,y=74.3},{"a",1842,m=1411,x=56.3,y=74.3,ml=20}}},
  {t="Satyr Hooves", lv=26, n="The satyrs of Satyrnaar, north-east of Splintertree Post (Xavian, level 28-30), and the Felmusk satyrs north-west of the post (25-27) drop a hoof four kills in five. A Xavian satyr at 15% health may cast Gift of the Xavian and heal to full: finish it fast or stun it. Hellcallers throw Fireballs from 40 yards; Felmusk satyrs reek in melee and run for help at 15%.", g={{"o",1842,i=1,txt="Uncloven Satyr Hoof x7",m=1440,x=78.3,y=45.3}}},
  {t="Brutal Gauntlets", lv=26, g={{"t",1842,n2="Ula'elek, Sen'jin Village",m=1411,x=56.3,y=74.3},{"a",1843,m=1411,x=56.3,y=74.3,ml=20},{"t",1843,m=1411,x=56.3,y=74.3}}},
  {t="Orm Stonehoof", lv=26, n="Orm Stonehoof works on Thunder Bluff's lowest level, close to the blacksmith.", g={{"t",1840,m=1456,x=39,y=56},{"a",1844,m=1456,x=39,y=56,ml=20}}},
  {t="Chimaeric Horn", lv=26, n="The Chimaera Matriarch (level 28, not elite, larger than the young ones around her) roams the south edge of the Charred Vale in south-west Stonetalon, near the road to Desolace. She is the only one: she returns 5 minutes after dying and drops the Galvanized Horn four kills in five. She spits Corrosive Poison from 30 yards.", g={{"o",1844,i=1,txt="Galvanized Horn",n2="Galvanized Horn, from the Chimaera Matriarch",m=1442,x=33.6,y=74.7}}},
  {t="Brutal Helm", lv=26, g={{"t",1844,m=1456,x=39,y=56},{"a",1845,m=1456,x=39,y=56,ml=20},{"t",1845,m=1456,x=39,y=56}}},
  {t="Velora Nitely", lv=26, n="Take the zeppelin from Orgrimmar to Tirisfal Glades; Velora Nitely works in the Undercity's Trade Quarter. She wants 8 Sturdy Dragonmaw Shinbones.", g={{"t",1841,m=1458,x=62.1,y=39.1},{"a",1846,m=1458,x=62.1,y=39.1,ml=20}}},
  {t="Dragonmaw Shinbones", lv=26, n="The Dragonmaw orcs (level 26-30) camp in the middle of the Wetlands; from Hammerfall in Arathi head south over the Thandol Span (Menethil Harbor is Alliance). With Dragonmaw Shinbones from Velora in your log, every Raider, Swamprunner, Centurion, Shadowwarder and Bonewarder drops a Dragonmaw Shinbone (without the quest they drop none): right-click it to test it, and about one in four comes out sturdy, the rest break, so expect 30 or more kills for 8. You can test while moving or fighting. The orcs run for help at 15%; Raiders net you, Centurions shield-bash, Shadowwarders cast Shadow Bolt, Bonewarders raise skeletons.", w={{k="onquest",q={1846}}}, g={{"h",7131,txt="Get Dragonmaw Shinbone",n2="from the Dragonmaw orcs: right-click to test it",m=1437,x=45.7,y=44.8,n=1,opt=true},{"o",1846,i=1,txt="Sturdy Dragonmaw Shinbone x8",m=1437,x=45.8,y=45.1}}},
  {t="Brutal Legguards", lv=26, g={{"t",1846,m=1458,x=62.1,y=39.1},{"a",1847,m=1458,x=62.1,y=39.1,ml=20},{"t",1847,m=1458,x=62.1,y=39.1}}},
} end)

R:Segment({id="class/warrior/fire-hardened-armor",title="Fire Hardened Armor",faction="Alliance",classes={"WARRIOR"},min=20,max=30,zone=1433,zoneName="Redridge Mountains",why="Starts now at 20 with a shield; a hauberk at 28, then a coif, leggings and gauntlets from three smiths.",items={6972,6971,6973,6974,6970},folder="Warrior"}, function() return {
  {t="Yorus Barleybrew (Stormwind)", lv=20, n="At 20, Wu Shen, beside Ilsa Corbin in the warrior trainers' building of Old Town, sends you to Yorus Barleybrew in Redridge.", f={r={"Human","Skyborne"}}, g={{"l",20,txt="Reach level 20"},{"a",1698,m=1453,x=80.5,y=59.9,ml=20}}},
  {t="Yorus Barleybrew (Ironforge)", lv=20, n="At 20, Kelv Sternhammer, the warrior trainer of Ironforge, sends you to Yorus Barleybrew in Redridge.", f={r={"Dwarf","Gnome"}}, g={{"l",20,txt="Reach level 20"},{"a",1698,m=1455,x=70.3,y=90.7,ml=20}}},
  {t="Yorus Barleybrew (Darnassus)", lv=20, n="At 20, Darnath Bladesinger, the warrior trainer of Darnassus, sends you to Yorus Barleybrew in Redridge.", f={r={"NightElf"}}, g={{"l",20,txt="Reach level 20"},{"a",1698,m=1457,x=58.9,y=35.4,ml=20}}},
  {t="Yorus Barleybrew", lv=20, n="Yorus Barleybrew sits in the inn at Lakeshire. His test is timed: before you take it, clear the Redridge gnolls on the path to the Rethban Caverns in the hills north-west of Lakeshire, including the two on the rock by the cave mouth (climb it from its right side).", g={{"t",1698,m=1433,x=21.5,y=44.7},{"a",1699,m=1433,x=21.5,y=44.7,ml=20}}},
  {t="The Rethban Gauntlet", lv=20, n="You have one hour, and Yorus's Barleybrew Scalder leaves you drunk for 8-10 minutes. Run north-west into the Rethban Caverns, keeping close to the cliff wall to miss most gnoll packs, and go in as far as the first fork; then come back to Yorus (from the ridge you can jump down into Lakeshire). Dying and releasing your spirit fails the quest: abandon it and Yorus gives it again.", g={{"c",1699,txt="Enter the Rethban Caverns",n2="Enter the Rethban Caverns and come back"},{"t",1699,m=1433,x=21.5,y=44.7},{"a",1702,m=1433,x=21.5,y=44.7,ml=20}}},
  {t="The Shieldsmith", lv=20, n="Furen Longbeard works in the Dwarven District of Stormwind. He takes the Cask of Scalder (lost it? abandon the quest and Yorus gives a new one) and gives you Furen's Favor, a shield; Fire Hardened Mail is a level 28 quest, with Furen's Instructions listing what it needs.", g={{"t",1702,m=1453,x=64.6,y=37.2},{"a",1701,m=1453,x=64.6,y=37.2,ml=20}}},
  {t="Scorched Spider Fangs", lv=20, n="You need 50 fangs. The Leech Stalkers and Cave Stalkers (level 21-22) crawl in the middle of the Wetlands, north of Dun Algaz; every one drops a fang. They poison; back in 5 minutes.", g={{"o",1701,i=1,txt="Scorched Spider Fang x50",m=1437,x=52.6,y=63.1}}},
  {t="Charred and Galvanized Horns", lv=26, n="The chimaeras live south-west of Sun Rock Retreat in the Charred Vale; the guide waits for level 26 first. You need 12 Charred Horns from the Fledgling (level 25-27) and Young Chimaeras (23-25), four kills in five, and the Galvanized Horn from the Chimaera Matriarch (28, the big one), also four in five. Only three Fledglings, two Young and one Matriarch live there, each back in 5 minutes, so expect to wait. Fledglings and the Matriarch spit Corrosive Poison, the Young cast Lightning Bolt. Alliance: fly to Stonetalon Peak and head south.", g={{"l",26,txt="Reach level 26"},{"o",1701,i=2,txt="Charred Horn x12",n2="Charred Horn, from the young chimaeras",m=1442,x=33,y=72.1},{"o",1701,i=3,txt="Galvanized Horn",n2="Galvanized Horn, from the Chimaera Matriarch",m=1442,x=33.6,y=74.7}}},
  {t="Roogug in Razorfen Kraul", lv=26, n="Roogug is an elite quilboar (level 28) inside Razorfen Kraul, the dungeon at the south end of the Barrens; a five-player dungeon: needs a group of five, and his guards come with him. Inside take the left path at the first fork, cross the root bridge, go past the big empty cauldron: he is in a dead end on the right, with about ten elites on the way. He casts Lightning Bolt and calls Earth Rumblers. The vial always drops.", g={{"o",1701,i=4,txt="Vial of Phlogiston",n2="Vial of Phlogiston, from Roogug",m=1413,x=42.9,y=90.2,grp=true}}},
  {t="Furen's Armor", lv=26, n="Back to Furen Longbeard in the Dwarven District for the hauberk. He then sends you to the smith of your race; the other two smiths' pieces are open to you as well: talk to them directly.", g={{"t",1701,m=1453,x=64.6,y=37.2},{"a",1782,m=1453,x=64.6,y=37.2,ml=20},{"t",1782,m=1453,x=64.6,y=37.2},{"a",1700,m=1453,x=64.6,y=37.2,f={r={"Human"}},ml=20},{"a",1703,m=1453,x=64.6,y=37.2,f={r={"NightElf"}},ml=20},{"a",1704,m=1453,x=64.6,y=37.2,f={r={"Dwarf","Gnome"}},ml=20}}},
  {t="Grimand Elmore", lv=26, n="Grimand Elmore keeps the weapon shop in the north-west of the Dwarven District, a short walk from Furen. He wants 20 Burning Blood and the Burning Rock.", f={r={"Human","Skyborne"}}, g={{"t",1700,m=1453,x=59.7,y=33.8,f={r={"Human"}}},{"a",1705,m=1453,x=59.7,y=33.8,ml=20}}},
  {t="Burning Blood", lv=26, n="The Nightbane worgen of Duskwood (Dark Runners, Vile Fangs, Shadow Weavers, Worgen and Tainted Ones, level 26-31) south and west of Darkshire drop the Burning Blood four kills in five. The Tainted Ones poison and howl; Vile Fangs cause Infected Wound.", f={r={"Human","Skyborne"}}, g={{"o",1705,i=1,txt="Burning Blood x20",n2="Burning Blood, from the Nightbane worgen",m=1431,x=64,y=58.9}}},
  {t="Gutspill", lv=30, n="Gutspill (level 32, not elite) carries the Burning Rock, four kills in five; the guide waits for level 30 first. He walks between the inside and the mouth of the Roland's Doom mine south-east of Darkshire, so wait at the entrance and pull him outside. He poisons and howls.", f={r={"Human","Skyborne"}}, g={{"l",30,txt="Reach level 30"},{"o",1705,i=2,txt="Burning Rock",n2="Burning Rock, from Gutspill",m=1431,x=73.9,y=77.2}}},
  {t="Grimand's Armor", lv=30, f={r={"Human","Skyborne"}}, g={{"t",1705,m=1453,x=59.7,y=33.8},{"a",1706,m=1453,x=59.7,y=33.8,ml=20},{"t",1706,m=1453,x=59.7,y=33.8}}},
  {t="Mathiel", lv=30, n="Mathiel works on the south side of the Warrior's Terrace in Darnassus. He wants 20 Sunscorched Shells.", f={r={"NightElf"}}, g={{"t",1703,m=1457,x=59.5,y=45.4},{"a",1710,m=1457,x=59.5,y=45.4,ml=20}}},
  {t="Sunscorched Shells", lv=30, n="The shells lie on the ground under the wyvern nests at Highperch in western Thousand Needles, deeper into the gorge. Only nine exist and each returns 3 minutes after you pick it, so you will wait; some shell-like things there cannot be looted. Highperch Wyverns (level 28-31) guard them and sometimes come several at once.", f={r={"NightElf"}}, g={{"o",1710,i=1,txt="Sunscorched Shell x20",m=1441,x=12.1,y=37.1}}},
  {t="Mathiel's Armor", lv=30, f={r={"NightElf"}}, g={{"t",1710,m=1457,x=59.5,y=45.4},{"a",1711,m=1457,x=59.5,y=45.4,ml=20},{"t",1711,m=1457,x=59.5,y=45.4}}},
  {t="Klockmort Spannerspan", lv=30, n="Ride the Deeprun Tram from Stormwind to Ironforge. Klockmort Spannerspan, a gnome smith, works in Tinker Town near the engineering trainers. He wants 20 Searing Coral.", f={r={"Dwarf","Gnome"}}, g={{"t",1704,m=1455,x=67.9,y=46.1},{"a",1708,m=1455,x=67.9,y=46.1,ml=20}}},
  {t="Iron Coral", lv=30, n="The Iron Coral grows on the sea floor just south of Menethil Harbor, by the murloc huts and a wrecked boat: eight there and two south-east of the harbor, each back in 3 minutes, so you will wait for respawns to reach 20. The murlocs can net you underwater: watch your breath, and a Draught of Water Breathing removes the risk.", f={r={"Dwarf","Gnome"}}, g={{"o",1708,i=1,txt="Searing Coral x20",n2="Searing Coral, from Iron Coral",m=1437,x=9.3,y=69.1}}},
  {t="Klockmort's Creation", lv=30, f={r={"Dwarf","Gnome"}}, g={{"t",1708,m=1455,x=67.9,y=46.1},{"a",1709,m=1455,x=67.9,y=46.1,ml=20},{"t",1709,m=1455,x=67.9,y=46.1}}},
} end)

R:Segment({id="class/warrior/haggards-weapons",title="Defensive Stance and a Weapon (Alliance)",faction="Alliance",classes={"WARRIOR"},min=10,max=11,zone=1429,zoneName="Elwynn Forest",why="Defensive Stance at 10 and a one-hand weapon of your choice from Stormwind, Ironforge or Darnassus.",spells={71},spellNames={"Defensive Stance"},items={6979,6983,6980,6985,6978,6982,6981,6984,6966,6968,6969,6967,275290},folder="Warrior"}, function() return {
  {t="Seena Skybreaker in Valanaar", lv=10, n="At 10, Seena Skybreaker stands with the trainers by Valanaar's west gate. A cultist, Zaal Stormshield, holds her family's shield at the Shrine of Akir.", f={r={"Skyborne"}}, g={{"l",10,txt="Reach level 10"},{"a",94003,m=2521,x=59.9,y=72.9,ml=10}}},
  {t="Zaal Stormshield", lv=10, n="Head north-west from Valanaar to the Shrine of Akir. Zaal Stormshield stands west of the shrine's approach, among the cult's Guardians, Spiritcallers and Blademasters: pull them one at a time before you take him. He drops the Skybreaker Bulwark.", f={r={"Skyborne"}}, g={{"i",0,txt="Kill Zaal Stormshield",m=2521,x=56.7,y=50.4},{"o",94003,i=1,txt="Skybreaker Bulwark",n2="Skybreaker Bulwark, from Zaal Stormshield",m=2521,x=56.7,y=50.4}}},
  {t="The Skybreaker Bulwark", lv=10, n="Back to Seena in Valanaar. She teaches Defensive Stance and gives you the Stormforged Protector, a shield to use it with. Bartleby's road below still gives a weapon, once you reach Stormwind.", f={r={"Skyborne"}}, g={{"t",94003,n2="Seena Skybreaker: Defensive Stance",m=2521,x=59.9,y=72.9}}},
  {t="Muren Stormpike", lv=10, n="At 10, Granis Swiftaxe, the warrior trainer in Kharanos, sends you to Muren Stormpike in Ironforge. Any Alliance warrior may take one of the three roads, never two: in Stormwind at 10 anyway? Ilsa Corbin's A Warrior's Training is the quickest stance (one fight in a tavern), with a Haggard's weapon after it.", f={r={"Dwarf","Gnome"}}, g={{"l",10,txt="Reach level 10"},{"a",1679,m=1426,x=47.4,y=52.6,ml=10}}},
  {t="Muren Stormpike in Ironforge", lv=10, n="Muren Stormpike stands in the Hall of Arms in the Military Ward.", f={r={"Dwarf","Gnome"}}, g={{"t",1679,m=1455,x=70.8,y=90.3},{"a",1678,m=1455,x=70.8,y=90.3,ml=10}}},
  {t="Vejrek", lv=10, n="Vejrek (level 11, a lone troll) waits at his hut on a hill south of Frostmane Hold, near the mountains at the top of a short ramp, with no other trolls around; the hut at the front of Frostmane Hold is the wrong one. He fights in Defensive Stance and sunders your armor; Thunder Clap slows him. His head always drops; he returns about 8 minutes after dying.", f={r={"Dwarf","Gnome"}}, g={{"o",1678,i=1,txt="Vejrek's Head",m=1426,x=27.8,y=58}}},
  {t="Tormus Deepforge", lv=10, n="Back to Muren for Defensive Stance, then to Tormus Deepforge at the Great Forge in the middle of Ironforge.", f={r={"Dwarf","Gnome"}}, g={{"t",1678,n2="Muren Stormpike: Defensive Stance",m=1455,x=70.8,y=90.3},{"a",1680,m=1455,x=70.8,y=90.3,ml=10},{"t",1680,m=1455,x=48.6,y=42.5},{"a",1681,m=1455,x=48.6,y=42.5,ml=10}}},
  {t="Ironband's Compound", lv=10, n="Ironband's Compound lies in eastern Dun Morogh, below Helm's Bed Lake on its south side. Dark Iron Spies (level 8-10) stand along the way, far enough apart to pull one at a time. Ironband's Strongbox is in the basement of the southernmost house; Captain Beld (level 11) stands by it and charges on sight. The box always holds the ore and refills 15 minutes after opening.", f={r={"Dwarf","Gnome"}}, g={{"o",1681,i=1,txt="Umbral Ore",n2="Umbral Ore, from Ironband's Strongbox",m=1426,x=78,y=62.2}}},
  {t="Grey Iron Weapons", lv=10, f={r={"Dwarf","Gnome"}}, g={{"t",1681,m=1455,x=48.6,y=42.5},{"a",1682,m=1455,x=48.6,y=42.5,ml=10},{"t",1682,m=1455,x=48.6,y=42.5}}},
  {t="Elanaria", lv=10, n="At 10, Kyra Windblade, the warrior trainer in Dolanaar, or Moon Priestess Amara, who patrols the road west of Dolanaar, sends you to Elanaria on the Warrior's Terrace in Darnassus. Any Alliance warrior may take one of the three roads, never two: in Stormwind at 10 anyway? Ilsa Corbin's A Warrior's Training teaches the same stance after one fight in a tavern.", f={r={"NightElf"}}, g={{"l",10,txt="Reach level 10"},{"a",1684,m=1438,x=56.2,y=59.2,ml=10}}},
  {t="Elanaria in Darnassus", lv=10, n="Elanaria stands on the Warrior's Terrace.", f={r={"NightElf"}}, g={{"t",1684,m=1457,x=57.3,y=34.6},{"a",1683,m=1457,x=57.3,y=34.6,ml=10}}},
  {t="Vorlus Vilehoof", lv=10, n="Vorlus Vilehoof (level 10, a satyr) stands at a hidden moonwell up a hillside west of Dolanaar. The trail is hard to spot: it starts behind a Gnarlpine camp and climbs in switchbacks lined with lamp posts. The furbolgs below can come in groups. His horn always drops; he returns 5 minutes after dying.", f={r={"NightElf"}}, g={{"o",1683,i=1,txt="Horn of Vorlus",m=1438,x=47.2,y=63.6}}},
  {t="The Shade of Elura", lv=10, f={r={"NightElf"}}, g={{"t",1683,n2="Elanaria: Defensive Stance",m=1457,x=57.3,y=34.6},{"a",1686,m=1457,x=57.3,y=34.6,ml=10}}},
  {t="Elunite under Auberdine", lv=10, n="Take the boat from Rut'theran Village to Auberdine. The wreck lies underwater just south of Auberdine's southern pier, where the Menethil boat docks. Open Crates of Elunite on the sea floor around the wreck, by a huge sunken turtle, toward the beach and under the pier until you have eight; every crate holds ore and comes back in 3-5 minutes. The grey Shade of Elura (level 11) drifts around the middle of the wreck and always drops the medallion: target it when you see it, so you can find it after surfacing for air. Watch your breath; Threshers can join in.", f={r={"NightElf"}}, g={{"o",1686,i=1,txt="Elunite Ore x8",n2="Elunite Ore, from Crates of Elunite",m=1439,x=32.5,y=44.5},{"o",1686,i=2,txt="Elura's Medallion",n2="Elura's Medallion, from the Shade of Elura",m=1439,x=31.6,y=44.9}}},
  {t="Smith Mathiel", lv=10, n="Back on the Warrior's Terrace: Elanaria hands you the Case of Elunite; Mathiel works on the far, south side of the same terrace, easy to miss.", f={r={"NightElf"}}, g={{"t",1686,m=1457,x=57.3,y=34.6},{"a",1692,m=1457,x=57.3,y=34.6,ml=10},{"t",1692,m=1457,x=59.5,y=45.4},{"a",1693,m=1457,x=59.5,y=45.4,ml=10},{"t",1693,m=1457,x=59.5,y=45.4}}},
  {t="A Warrior's Training", lv=10, n="At 10, Lyria Du Lac, the warrior trainer by the inn in Goldshire, sends you to Harry Burlguard in Stormwind; Ilsa Corbin, the warrior trainer in Stormwind's Old Town, offers it too.", f={r={"Human","Skyborne"}}, g={{"l",10,txt="Reach level 10"},{"a",1638,m=1429,x=41.1,y=65.8,ml=10}}},
  {t="Bartleby", lv=10, n="Harry Burlguard and Bartleby are in the Pig and Whistle tavern in Old Town; Bartleby is the drunk at the far end of the bar. Bartleby (level 10) hits harder than his level, so start at full health; he gives up at low health instead of dying. If he wins, he disappears for about three minutes: keep the quest and talk to him again when he is back. A Dwarf, Gnome or Night Elf who took A Warrior's Training from Ilsa Corbin instead of their home road is led through Stormwind from here.", w={{k="turnedin",neg=true,q=1679},{k="turnedin",neg=true,q=1684}}, g={{"t",1638,m=1453,x=77.1,y=53.3},{"a",1639,m=1453,x=77.1,y=53.3,ml=10},{"t",1639,m=1453,x=76.8,y=52.5},{"a",1640,m=1453,x=76.8,y=52.5,ml=10},{"o",1640,i=1,txt="Kill Bartleby",n2="Beat Bartleby",m=1453,x=76.8,y=52.5},{"t",1640,m=1453,x=76.8,y=52.5},{"a",1665,m=1453,x=76.8,y=52.5,ml=10},{"t",1665,n2="Harry Burlguard: Defensive Stance",m=1453,x=77.1,y=53.3},{"a",1666,m=1453,x=77.1,y=53.3,ml=10}}},
  {t="Marshal Haggard", lv=10, n="Marshal Haggard's manor stands at the south-east edge of the Eastvale Logging Camp in eastern Elwynn, at the end of a short road that does not join the main one.", w={{k="turnedin",neg=true,q=1679},{k="turnedin",neg=true,q=1684}}, g={{"t",1666,m=1429,x=84.6,y=69.4},{"a",1667,m=1429,x=84.6,y=69.4,ml=10}}},
  {t="Dead-tooth Jack", lv=10, n="Dead-Tooth Jack (level 11) camps in the far south-east of Elwynn. A guard stands beside him and Defias and wolves are spread around the camp (now and then a rarer guard too): clear them one at a time, then kill Jack. He always drops Dead-tooth's Key; open Dead-tooth's Strongbox in the crates by him for Marshal Haggard's Badge. Jack returns 3 minutes after dying, the box 1 minute after opening.", w={{k="turnedin",neg=true,q=1679},{k="turnedin",neg=true,q=1684}}, g={{"h",6783,txt="Get Dead-tooth's Key",n2="from Dead-Tooth Jack",m=1429,x=89.4,y=79,n=1},{"o",1667,i=1,txt="Marshal Haggard's Badge",n2="Marshal Haggard's Badge, from Dead-tooth's Strongbox",m=1429,x=89.3,y=78.9}}},
  {t="Back to Marshal Haggard", lv=10, w={{k="turnedin",neg=true,q=1679},{k="turnedin",neg=true,q=1684}}, g={{"t",1667,m=1429,x=84.6,y=69.4}}},
} end)

R:Segment({id="class/warrior/heirloom-weapon",title="Defensive Stance and a Weapon (Horde)",faction="Horde",classes={"WARRIOR"},min=10,max=11,zone=1413,zoneName="The Barrens",why="Defensive Stance at 10 and a one-hand weapon of your choice: Uzzek's road, Brill's crypt, or the Skybreaker shield.",spells={71},spellNames={"Defensive Stance"},items={7326,7328,7327,7329,7115,7117,7116,7118,275290},folder="Warrior"}, function() return {
  {t="Seena Skybreaker in Valanaar", lv=10, n="At 10, Seena Skybreaker stands with the trainers by Valanaar's west gate. A cultist, Zaal Stormshield, holds her family's shield at the Shrine of Akir.", f={r={"Skyborne"}}, g={{"l",10,txt="Reach level 10"},{"a",94003,m=2521,x=59.9,y=72.9,ml=10}}},
  {t="Zaal Stormshield", lv=10, n="Head north-west from Valanaar to the Shrine of Akir. Zaal Stormshield stands west of the shrine's approach, among the cult's Guardians, Spiritcallers and Blademasters: pull them one at a time before you take him. He drops the Skybreaker Bulwark.", f={r={"Skyborne"}}, g={{"i",0,txt="Kill Zaal Stormshield",m=2521,x=56.7,y=50.4},{"o",94003,i=1,txt="Skybreaker Bulwark",n2="Skybreaker Bulwark, from Zaal Stormshield",m=2521,x=56.7,y=50.4}}},
  {t="The Skybreaker Bulwark", lv=10, n="Back to Seena in Valanaar. She teaches Defensive Stance and gives you the Stormforged Protector, a shield to use it with. Uzzek's road below still gives a weapon later, once you reach Kalimdor.", f={r={"Skyborne"}}, g={{"t",94003,n2="Seena Skybreaker: Defensive Stance",m=2521,x=59.9,y=72.9}}},
  {t="Veteran Uzzek (Razor Hill)", lv=10, n="At 10, Tarshaw Jaggedscar, the warrior trainer in the barracks of Razor Hill, sends you to Uzzek in the Barrens. Sorek in Orgrimmar's Valley of Honor offers it too. Any Horde warrior may take one of the two roads, never both: heading to Tirisfal Glades at 10 anyway? Austil de Mon in Brill's inn offers the other: one fight by Brill's graveyard for the same stance, then the Agamand crypt for an heirloom weapon.", f={r={"Orc","Troll","Skyborne"}}, g={{"l",10,txt="Reach level 10"},{"a",1505,m=1411,x=54.2,y=42.5,ml=10}}},
  {t="Veteran Uzzek (Mulgore)", lv=10, n="At 10, Krang Stonehoof, the warrior trainer of Bloodhoof Village, sends you to Uzzek in the Barrens. Torm Ragetotem in Thunder Bluff offers it too.", f={r={"Tauren"}}, g={{"l",10,txt="Reach level 10"},{"a",1505,m=1412,x=48.4,y=63.7,ml=10}}},
  {t="Uzzek at Far Watch Post", lv=10, n="Uzzek is easy to miss: he stands under a small canopy by a large tree just west of Far Watch Post, below the road's south side, with the post in sight to his east. Going straight south from the post does not lead to him. From Durotar cross the bridge west; from Mulgore head north past the Crossroads.", f={r={"Orc","Troll","Tauren","Skyborne"}}, g={{"t",1505,m=1413,x=61.4,y=21.1},{"a",1498,m=1413,x=61.4,y=21.1,ml=10}}},
  {t="Singed Scales in Thunder Ridge", lv=10, n="You need five Singed Scales. Thunder Lizards (level 9-10) and Lightning Hides (10-11) live down in the Thunder Ridge crevasse in north-west Durotar, south of Orgrimmar: from the Barrens bridge turn left and follow the river north into it. Both drop a scale about four kills in five; both cast Lizard Bolt.", f={r={"Orc","Troll","Tauren","Skyborne"}}, g={{"o",1498,i=1,txt="Singed Scale x5",n2="Singed Scale, from the lizards",m=1411,x=39.7,y=29.2}}},
  {t="Path of Defense", lv=10, n="Back to Uzzek under his tree west of Far Watch Post.", f={r={"Orc","Troll","Tauren","Skyborne"}}, g={{"t",1498,n2="Uzzek: Defensive Stance",m=1413,x=61.4,y=21.1},{"a",1502,m=1413,x=61.4,y=21.1,ml=10}}},
  {t="Thun'grim Firegaze", lv=10, n="Thun'grim's hut sits on top of Thorn Hill, east of the Crossroads. Most slopes are too steep: climb the broad ridge on the north or east side.", f={r={"Orc","Troll","Tauren","Skyborne"}}, g={{"t",1502,m=1413,x=57.2,y=30.3},{"a",1503,m=1413,x=57.2,y=30.3,ml=10}}},
  {t="Forged Steel", lv=10, n="The Stolen Iron Chest stands by a broken wagon in the Razormane camp north-west of Thun'grim, north-east of the Crossroads. Two Razormanes guard it and their hunters pull more quilboar: clear them one at a time, then open the chest (it refills within seconds, so a friend can loot it too).", f={r={"Orc","Troll","Tauren","Skyborne"}}, g={{"o",1503,i=1,txt="Forged Steel Bars",n2="Forged Steel Bars, from the Stolen Iron Chest",m=1413,x=55,y=26.6},{"t",1503,m=1413,x=57.2,y=30.3}}},
  {t="Speak with Dillinger", lv=10, n="At 10, Austil de Mon, the warrior trainer inside the inn of Brill, sends you to Deathguard Dillinger by the graveyard on Brill's west edge. This road and Uzzek's exclude each other: drop Veteran Uzzek or Path of Defense from your log if you hold one.", f={r={"Scourge"}}, g={{"l",10,txt="Reach level 10"},{"a",1818,m=1420,x=61.9,y=52.5,ml=10}}},
  {t="Deathguard Dillinger", lv=10, n="Dillinger stands by the graveyard on Brill's west edge. An Orc, Troll, Tauren or Skyborne who took Speak with Dillinger from Austil de Mon instead of Uzzek's road is led through Brill from here.", w={{k="turnedin",neg=true,q=1505}}, g={{"t",1818,m=1420,x=58.2,y=51.5},{"a",1819,m=1420,x=58.2,y=51.5,ml=10}}},
  {t="Ulag the Cleaver", lv=10, n="Ulag sleeps in the mausoleum in the graveyard just north of Dillinger. To wake him, click the flat skull plaque on the ground, left of the path to the mausoleum door; the seal lifts and Ulag (level 11, not elite) walks out. Start at full health.", w={{k="turnedin",neg=true,q=1505}}, g={{"o",1819,i=1,txt="Kill Ulag the Cleaver",m=1420,x=59.5,y=48.3},{"t",1819,n2="Deathguard Dillinger: Defensive Stance",m=1420,x=58.2,y=51.5},{"a",1820,m=1420,x=58.2,y=51.5,ml=10}}},
  {t="Coleman Farthing", lv=10, n="Coleman Farthing is in the Gallows' End Tavern, the inn on Brill's east side.", w={{k="turnedin",neg=true,q=1505}}, g={{"t",1820,m=1420,x=61.7,y=52.3},{"a",1821,m=1420,x=61.7,y=52.3,ml=10}}},
  {t="The Agamand Family Crypt", lv=10, n="The four Agamand Weapon Racks are inside the Agamand Family Crypt at the north end of Agamand Mills, north of Brill, one rack per room: one in the lowest room, two in the pair of rooms up the stairs, one in the room above those. The axe rack stands in a dark corner. The crypt's undead come in packs of three or more and return quickly; the ones in the top room are not linked. The axe, dagger and mace racks take 15 minutes to refill after someone loots them.", w={{k="turnedin",neg=true,q=1505}}, g={{"o",1821,i=1,txt="Agamand Family Axe",m=1420,x=51.7,y=25.7},{"o",1821,i=2,txt="Agamand Family Dagger",m=1420,x=51.9,y=27.1},{"o",1821,i=3,txt="Agamand Family Mace",m=1420,x=51.9,y=27.1},{"o",1821,i=4,txt="Agamand Family Sword",m=1420,x=52.7,y=25.9}}},
  {t="Back to Coleman Farthing", lv=10, w={{k="turnedin",neg=true,q=1505}}, g={{"t",1821,m=1420,x=61.7,y=52.3},{"a",1822,m=1420,x=61.7,y=52.3,ml=10},{"t",1822,m=1420,x=61.7,y=52.3}}},
} end)

R:Segment({id="class/warrior/quelserrar",title="Quel'Serrar",classes={"WARRIOR","PALADIN"},min=60,max=60,zone=1444,zoneName="Feralas",why="A tank sword at 60: a Dire Maul book, then Onyxia's breath tempers the blade (the sword is not in Forever's items yet).",items={18348},folder="Raid"}, function() return {
  {t="Nostro's Compendium of Dragon Slaying", lv=60, n="The book is a rare random drop from the bosses of all three Dire Maul wings (Alzzin, Hydrospawn and the rest of the East, Tendris, Illyanna, Kalendris, Immol'thar and the West, King Gordok and the North's guards) and very rarely from the tribute chest; it can be traded, so the auction house may have one. Dire Maul is a five-player dungeon in the ruins of central Feralas: needs a group of five. Right-click the book to start the quest; it stays in your bags.", g={{"a",7507,n2="from Nostro's Compendium of Dragon Slaying",grp=true,ml=60}}},
  {t="Lorekeeper Lydros", lv=60, n="Lorekeeper Lydros stands in the Athenaeum, the library at the far end of Dire Maul West, past the Court of the Highborne and the Prison of Immol'thar. The West door needs the Crescent Key, which Pusillin drops in Dire Maul East (he runs; chase him), or a rogue to pick it. Clearing to the library needs your group of five. He takes the book, hands you A Dull and Flat Elven Blade to give straight back, then the Unfired Ancient Blade. Keep that blade: lose it, and you must abandon the quest and take it again.", g={{"t",7507,n2="Lorekeeper Lydros, in the Athenaeum",m=1444,x=59.2,y=45.1,grp=true},{"a",7508,m=1444,x=59.2,y=45.1,grp=true,ml=60},{"t",7508,n2="Lorekeeper Lydros: hand back the Dull and Flat Elven Blade",m=1444,x=59.2,y=45.1,grp=true},{"a",7509,m=1444,x=59.2,y=45.1,grp=true,ml=60}}},
  {t="Onyxia's breath", lv=60, n="Onyxia is the 40-player raid boss of Onyxia's Lair, a cave in the Wyrmbog of southern Dustwallow Marsh; she returns once a week. Tell the raid first. Late in the fight (around 10-15% health, when she has landed again) use the Unfired Ancient Blade to plant it in the path of her fire breath, usually by the main tank's feet. When her breath has heated it, click the Ancient Heated Blade to take the Heated Ancient Blade: from then you have 20 minutes. Her breath can kill you while you plant or pick up the blade; if you die and nobody brings you back before she dies, wait for next week. Planted in the wrong place? Abandon the quest, take it again from Lydros for a new blade.", g={{"i",0,txt="Use Unfired Ancient Blade",n2="Unfired Ancient Blade: plant it in her breath",m=1445,x=52.1,y=75.8,grp=true},{"h",18488,txt="Get Heated Ancient Blade",n2="click the heated blade on the ground",m=1445,x=52.1,y=75.8,n=1}}},
  {t="Onyxia's corpse", lv=60, n="Kill Onyxia, then target her corpse and use the Heated Ancient Blade on it before the 20 minutes run out. It becomes the Treated Ancient Blade, with no time limit.", g={{"i",0,txt="Kill Onyxia",m=1445,x=52.1,y=75.8,grp=true},{"o",7509,i=1,txt="Use Heated Ancient Blade",n2="Heated Ancient Blade, on her corpse",m=1445,x=52.1,y=75.8,grp=true},{"o",7509,i=1,txt="Treated Ancient Blade",m=1445,x=52.1,y=75.8,grp=true}}},
  {t="The Forging of Quel'Serrar", lv=60, n="Back to Lorekeeper Lydros in the Athenaeum of Dire Maul West: through the West door with the Crescent Key again, and a group to reach the library.", g={{"t",7509,n2="Lorekeeper Lydros: Quel'Serrar",m=1444,x=59.2,y=45.1,grp=true}}},
} end)

R:Segment({id="class/warrior/voodoo-feathers",title="Voodoo Feathers",classes={"WARRIOR"},min=50,max=52,zone=1435,zoneName="Swamp of Sorrows",why="Experience at 50, ending in the Sunken Temple; Classic's item choice may be gone on Forever.",folder="Warrior"}, function() return {
  {t="A Troubled Spirit (Stormwind)", lv=50, n="At 50, Wu Shen, beside Ilsa Corbin in the warrior trainers' building of Old Town, sends you to the Fallen Hero of the Horde in the Swamp of Sorrows.", f={r={"Human","Skyborne"},fa={"Alliance"}}, g={{"l",50,txt="Reach level 50"},{"a",8417,m=1453,x=80.5,y=59.9,ml=50}}},
  {t="A Troubled Spirit (Ironforge)", lv=50, n="At 50, Kelv Sternhammer, the warrior trainer of Ironforge, sends you to the Fallen Hero of the Horde in the Swamp of Sorrows.", f={r={"Dwarf","Gnome"}}, g={{"l",50,txt="Reach level 50"},{"a",8417,m=1455,x=70.3,y=90.7,ml=50}}},
  {t="A Troubled Spirit (Darnassus)", lv=50, n="At 50, Darnath Bladesinger, the warrior trainer of Darnassus, sends you to the Fallen Hero of the Horde in the Swamp of Sorrows.", f={r={"NightElf"}}, g={{"l",50,txt="Reach level 50"},{"a",8417,m=1457,x=58.9,y=35.4,ml=50}}},
  {t="A Troubled Spirit (Orgrimmar)", lv=50, n="At 50, Sorek in the Valley of Honor sends you to the Fallen Hero of the Horde in the Swamp of Sorrows.", f={r={"Orc","Troll","Skyborne"},fa={"Horde"}}, g={{"l",50,txt="Reach level 50"},{"a",8417,m=1454,x=80.4,y=32.4,ml=50}}},
  {t="A Troubled Spirit (Thunder Bluff)", lv=50, n="At 50, Torm Ragetotem, the warrior trainer of Thunder Bluff, sends you to the Fallen Hero of the Horde in the Swamp of Sorrows.", f={r={"Tauren"}}, g={{"l",50,txt="Reach level 50"},{"a",8417,m=1456,x=57.2,y=87.4,ml=50}}},
  {t="A Troubled Spirit (Undercity)", lv=50, n="At 50, Christoph Walker, a warrior trainer of the Undercity, sends you to the Fallen Hero of the Horde in the Swamp of Sorrows.", f={r={"Scourge"}}, g={{"l",50,txt="Reach level 50"},{"a",8417,m=1458,x=46.9,y=15.2,ml=50}}},
  {t="The Fallen Hero of the Horde", lv=50, n="The Fallen Hero of the Horde, a ghost, stands in the south-west of the Swamp of Sorrows, at the pass into the Blasted Lands, a short ride south-west of Stonard. Horde: fly to Stonard. Alliance: fly to Nethergarde Keep in the Blasted Lands and ride north through the pass. High-level beasts roam the way.", g={{"t",8417,m=1435,x=34.3,y=66.1},{"a",8423,m=1435,x=34.3,y=66.1,ml=50}}},
  {t="Helboars", lv=50, n="Seven Helboars (level 52-53, not elite) roam the north-west of the Blasted Lands, south-west of Nethergarde Keep; some stand near the ogres on the mountainside by the road. They charge from 25 yards and cast Fire Nova. They share spawn points with the Felbeasts and scorpids: if no boars are around, kill those and boars may appear instead. Back in 5 minutes.", g={{"o",8423,i=1,txt="Kill Helboar x7",m=1419,x=49.8,y=42.7}}},
  {t="War on the Shadowsworn", lv=50, g={{"t",8423,m=1435,x=34.3,y=66.1},{"a",8424,m=1435,x=34.3,y=66.1,ml=50}}},
  {t="Shadowsworn camps", lv=50, n="The Shadowsworn camp around the mouth of the Serpent's Coil cave, south of Nethergarde Keep on the way to the Dark Portal. You need 20 Adepts (level 52-53, they leech blood and heal hurt allies: kill them first), 10 Cultists (51-52, they throw from range, so close in) and 20 Thugs (52-53, Thrash and Kick). Thugs can run short before the others: kill every Shadowsworn you pass.", g={{"o",8424,i=1,txt="Kill Shadowsworn Adept x20",m=1419,x=65,y=38.2},{"o",8424,i=2,txt="Kill Shadowsworn Cultist x10",m=1419,x=63.9,y=40.9},{"o",8424,i=3,txt="Kill Shadowsworn Thug x20",m=1419,x=63.9,y=42.3}}},
  {t="Voodoo Feathers", lv=50, g={{"t",8424,m=1435,x=34.3,y=66.1},{"a",8425,m=1435,x=34.3,y=66.1,ml=50}}},
  {t="The Sunken Temple", lv=50, n="You need two feathers of each colour from the six Atal'ai troll guardians (level 51-52, elite) on the Sunken Temple's balcony, who hold the barrier in front of Jammal'an the Prophet: Gasher and Zul'Lor drop the amber, Hukku and Mijan the blue, Zolo and Loro the green, every kill; each player on the quest loots their own set. The Sunken Temple is a five-player dungeon: needs a group of five. It lies in the Pool of Tears in eastern Swamp of Sorrows: climb the temple's outer steps, dive into the flooded hall and follow the stairs down to the entrance. Inside, reach the balcony by the stairs or the path on the right, not the spiral stairs. Hukku calls guardians and casts Shadow Bolt Volley and Curse of Blood; Mijan heals the others (Renew, a Healing Ward, Healing Wave below half health): kill her or her ward fast; Zul'Lor cleaves.", g={{"o",8425,i=1,txt="Amber Voodoo Feather x2",n2="Amber Voodoo Feather, from Gasher and Zul'Lor",m=1435,x=69.9,y=53.6},{"o",8425,i=2,txt="Blue Voodoo Feather x2",n2="Blue Voodoo Feather, from Hukku and Mijan",m=1435,x=69.9,y=53.6},{"o",8425,i=3,txt="Green Voodoo Feather x2",n2="Green Voodoo Feather, from Zolo and Loro",m=1435,x=69.9,y=53.6}}},
  {t="Back to the Fallen Hero", lv=50, n="In Classic the Fallen Hero let you choose the Diamond Flask, the Fury Visor or the Razorsteel Shoulders here. Forever's change notes say the choice is gone, though its quest page still lists three unnamed rewards: look at the reward window before you hand in.", g={{"t",8425,m=1435,x=34.3,y=66.1}}},
} end)

R:Segment({id="class/warrior/whirlwind-weapon",title="Whirlwind Weapon",classes={"WARRIOR"},min=30,max=40,zone=1413,zoneName="The Barrens",why="Berserker Stance at 30 and a Whirlwind axe, sword or warhammer at 40.",spells={2458},spellNames={"Berserker Stance"},items={6975,6977,6976},folder="Warrior"}, function() return {
  {t="The Islander (Stormwind)", lv=30, n="At 30, Wu Shen, beside Ilsa Corbin in the warrior trainers' building of Old Town, sends you to Klannoc Macleod on Fray Island in the Barrens.", f={r={"Human","NightElf","Skyborne"},fa={"Alliance"}}, g={{"l",30,txt="Reach level 30"},{"a",1718,m=1453,x=80.5,y=59.9,ml=30}}},
  {t="The Islander (Ironforge)", lv=30, n="At 30, Kelv Sternhammer, the warrior trainer of Ironforge, sends you to Klannoc Macleod on Fray Island in the Barrens.", f={r={"Dwarf","Gnome"}}, g={{"l",30,txt="Reach level 30"},{"a",1718,m=1455,x=70.3,y=90.7,ml=30}}},
  {t="The Islander (Orgrimmar)", lv=30, n="At 30, Sorek in the Valley of Honor sends you to Klannoc Macleod on Fray Island in the Barrens.", f={r={"Orc","Troll","Skyborne"},fa={"Horde"}}, g={{"l",30,txt="Reach level 30"},{"a",1718,m=1454,x=80.4,y=32.4,ml=30}}},
  {t="The Islander (Thunder Bluff)", lv=30, n="At 30, Torm Ragetotem, the warrior trainer of Thunder Bluff, sends you to Klannoc Macleod on Fray Island in the Barrens.", f={r={"Tauren"}}, g={{"l",30,txt="Reach level 30"},{"a",1718,m=1456,x=57.2,y=87.4,ml=30}}},
  {t="The Islander (Undercity)", lv=30, n="At 30, Baltus Fowler, a warrior trainer of the Undercity, sends you to Klannoc Macleod on Fray Island in the Barrens.", f={r={"Scourge"}}, g={{"l",30,txt="Reach level 30"},{"a",1718,m=1458,x=47.4,y=17.3,ml=30}}},
  {t="Fray Island", lv=30, n="Fly to Ratchet and go south along the Merchant Coast. Fray Island lies offshore to the south-east: wade across on the shallow sand bar; off it the water is deep and fatigue sets in. Klannoc Macleod stands by the arena.", g={{"t",1718,m=1413,x=68.6,y=49.2},{"a",1719,m=1413,x=68.6,y=49.2,ml=30}}},
  {t="The Affray", lv=30, n="You have 10 minutes. Eat and drink to full, then step onto the grate in the middle of the crowd: Twiggy Flathead announces the challengers (level 26-27), who come one at a time, 15-20 seconds apart, and only while you stand near the grate. After each kill, step off the grate to eat or bandage; step back on when ready for the next. Six of them, then Big Will (level 33, not elite) walks out; he stays neutral until you attack him, so bandage or eat first. Do not use Demoralizing Shout: it sends the challengers running and more of them pile in at once. If nothing starts, step off and on the grate again, or abandon the quest and take it again.", g={{"o",1719,i=1,txt="Kill Big Will",m=1413,x=68.6,y=48.7},{"t",1719,n2="Klannoc Macleod: Berserker Stance",m=1413,x=68.6,y=49.2},{"a",1791,m=1413,x=68.6,y=49.2,ml=30}}},
  {t="Bath'rah the Windwatcher", lv=30, n="Bath'rah the Windwatcher camps by ruins on the east bank of the river that runs past Tarren Mill, a short walk north-east of the town, just over the border in Alterac Mountains; his cauldron stands beside him. Horde: fly to Tarren Mill. Alliance: fly to Southshore and go north along the river; Tarren Mill's guards are level 42 elites, so keep away from the town. Accepting Cyclonian gives you Bath'rah's Parchment, the list of what he needs: 8 Liferoot, 30 Bloodscalp Tusks and the Essence of the Exile from his cauldron. The cauldron's Essence of the Exile is not a quest you take: it never shows in your quest log. Come back with its charms and hand them in at the cauldron.", g={{"t",1791,m=1416,x=80.5,y=66.9},{"a",1712,m=1416,x=80.5,y=66.9,ml=30}}},
  {t="Liferoot", lv=30, n="You need 8 Liferoot. Herbalists pick it by rivers and lakes in the Wetlands, Arathi Highlands and Stranglethorn Vale; otherwise the auction house. Herb vendors keep only one at a time and restock every two hours: Bernard Gump and Maria Lumere in Stormwind, Antonio Perelli on the road in eastern Elwynn, Jeeda at Sun Rock Retreat in Stonetalon, Montarr in Thousand Needles. Kurzen Medicine Men in northern Stranglethorn drop one about one kill in twelve.", g={{"o",1712,i=1,txt="Liferoot x8",m=1416,x=77.2,y=64.4}}},
  {t="Bloodscalp Tusks", lv=30, n="You need 30 tusks. Every Bloodscalp troll (level 33-37) of north-west Stranglethorn drops one about one kill in three, so plan on some 80 kills: the camps and ruins north and north-west of Grom'gol Base Camp and around the Bal'lal Ruins on the coast. They enrage below 30% health and the Warriors disarm; back in 5 minutes.", g={{"o",1712,i=2,txt="Bloodscalp Tusk x30",m=1434,x=32.3,y=17.2}}},
  {t="The exiles of Arathi", lv=37, n="The cauldron wants 8 of each charm, 24 in all, and each exile drops its charm about one kill in three, so plan on some 70 kills. All are level 38-39, not elite: the guide waits for level 37 first, and a friend helps. Burning Exiles (fire) by the Circle of West Binding in the north-west, north-west of Refuge Pointe; Thundering Exiles (air) by the Circle of Outer Binding south-east of Refuge Pointe, casting Lightning Bolt from 40 yards; Cresting Exiles (water) by the Circle of East Binding, north-west of Hammerfall, with Frost Nova. About a dozen of each, back in under 7 minutes. The charms trade and sell on the auction house; using one banishes another kind of exile for a while (Burning on Thundering, Thundering on Cresting, Cresting on Burning).", g={{"l",37,txt="Reach level 37"},{"h",4479,txt="Get Burning Charm x8",n2="Burning Charm, from Burning Exiles",m=1417,x=25.6,y=30.4,n=8},{"h",4480,txt="Get Thundering Charm x8",n2="Thundering Charm, from Thundering Exiles",m=1417,x=50.4,y=50.8,n=8},{"h",4481,txt="Get Cresting Charm x8",n2="Cresting Charm, from Cresting Exiles",m=1417,x=65.4,y=31,n=8}}},
  {t="Essence of the Exile", lv=37, n="Click Bath'rah's Cauldron with the 24 charms in your bags and Cyclonian in your log. Its window asks for the charms straight away, with nothing to accept: Continue, then Complete, and it hands you the Essence of the Exile.", g={{"t",1714,n2="Bath'rah's Cauldron: Essence of the Exile",m=1416,x=79.3,y=66.8},{"o",1712,i=3,txt="Essence of the Exile",n2="Essence of the Exile, from the cauldron by Bath'rah",m=1416,x=80.5,y=66.9}}},
  {t="The Summoning", lv=38, n="Back to Bath'rah. Accepting The Summoning starts his ritual, and Cyclonian appears just north of his camp. Cyclonian is elite (level 40): grouping up is encouraged; it needs a group of two or three around level 40. It deals nature damage (a Nature Protection Potion soaks it), whirls, and Knock Away throws you far while it heals itself as you run back: fight with your back to a slope or rock. The Whirlwind Heart always drops. If the fight fails Bath'rah stops answering: abandon The Summoning and take it again for a new summon; the earlier items are not needed again.", g={{"t",1712,m=1416,x=80.5,y=66.9},{"l",38,txt="Reach level 38"},{"a",1713,m=1416,x=80.5,y=66.9,ml=30},{"i",0,txt="Kill Cyclonian",m=1416,x=80.3,y=62.1,grp=true},{"o",1713,i=1,txt="Whirlwind Heart",n2="Whirlwind Heart, from Cyclonian",m=1416,x=80.3,y=62.1,grp=true},{"t",1713,m=1416,x=80.5,y=66.9},{"a",1792,m=1416,x=80.5,y=66.9,ml=30},{"t",1792,n2="Bath'rah the Windwatcher: Whirlwind Axe, Sword or Warhammer",m=1416,x=80.5,y=66.9}}},
} end)

R:Segment({id="collectibles/mounts/alliance/paladin-charger",title="Paladin Charger",faction="Alliance",races={"Human","Dwarf"},classes={"PALADIN"},min=60,max=60,zone=1453,zoneName="Stormwind City",why="Your epic mount at 60, summoned at will: the faster step up from the Warhorse.",spells={23214},spellNames={"Summon Charger"},folder="Paladin"}, function() return {
  {t="Lord Grayson Shadowbreaker (Ironforge)", lv=60, n="At 60 Brandur Ironhammer in the Mystic Ward sends you to Lord Grayson Shadowbreaker in Stormwind's Cathedral of Light.", f={r={"Dwarf"}}, g={{"l",60,txt="Reach level 60"},{"a",7670,m=1455,x=23.1,y=6.1,ml=60}}},
  {t="Lord Grayson Shadowbreaker", lv=60, n="The Summon Charger chain is long: Stratholme, Dire Maul West and Scholomance with a group, 350 gold in donations, and materials worth several hundred more (6 Arcanite Bars, 40 Runecloth, 10 Arthas' Tears, two diamonds). Start saving early. Lord Grayson stands in the Cathedral of Light, Duthorian Rall nearby.", g={{"l",60,txt="Reach level 60"},{"a",7638,n2="Duthorian Rall, Cathedral of Light",m=1453,x=50.5,y=47.5,f={r={"Human"}},ml=60},{"t",7638,m=1453,x=48.4,y=50.2,f={r={"Human"}}},{"t",7670,m=1453,x=48.4,y=50.2,f={r={"Dwarf"}}},{"a",7637,m=1453,x=48.4,y=50.2,ml=60}}},
  {t="High Priest Rohan", lv=60, n="High Priest Rohan, the priest trainer, walks about the Hall of Mysteries in Ironforge's Mystic Ward. He gives you his censer for a donation of 150 gold, taken at the hand-in. Keep the censer.", g={{"i",0,txt="money"},{"t",7637,n2="High Priest Rohan: 150 gold",m=1455,x=24.7,y=8.2},{"a",7639,m=1455,x=24.7,y=8.2,ml=60}}},
  {t="Back to Lord Grayson", lv=60, n="Lord Grayson blesses the censer into the Exorcism Censer for Terrordale.", g={{"t",7639,m=1453,x=48.4,y=50.2},{"a",7640,m=1453,x=48.4,y=50.2,ml=60}}},
  {t="Exorcising Terrordale", lv=60, n="Terrordale lies in the far north-west of the Eastern Plaguelands, west of the Stratholme gates. Stand inside a green glowing patch on the ground (a Terrordale Haunting Spirit; some are inside the ruined houses) and use the Exorcism Censer: up to three Terrordale Spirits (level 59-60) rise and attack. Their Wailing Dead lowers all your stats by 30%: fight them one at a time and use Turn Undead. The patches come back quickly; several paladins can work side by side.", g={{"i",0,txt="Use Exorcism Censer",n2="Exorcism Censer, inside a green patch",m=1423,x=11.4,y=19.2},{"o",7640,i=1,txt="Kill Terrordale Spirit x25",n2="Terrordale Spirits x25",m=1423,x=14.6,y=25.6}}},
  {t="Lord Grayson Shadowbreaker", lv=60, n="Lord Grayson takes the censer back.", g={{"t",7640,m=1453,x=48.4,y=50.2},{"a",7641,m=1453,x=48.4,y=50.2,ml=60}}},
  {t="Grimand Elmore", lv=60, n="Grimand Elmore works in Stormwind's Dwarven District. He forges the Arcanite Barding from your materials and 150 gold.", g={{"t",7641,m=1453,x=59.7,y=33.8},{"a",7642,m=1453,x=59.7,y=33.8,ml=60}}},
  {t="Grimand's materials", lv=60, n="Runecloth drops from humanoids of level 50 and up (Everlook's Bruisers, the Scarlet Crusade in the Plaguelands, the Dire Maul ogres). Arthas' Tears is a Plaguelands herb (Herbalism 220), common around Chillwind Camp. An Arcanite Bar is an alchemist's transmute from a Thorium Bar and an Arcane Crystal, once every two days per alchemist: ask a guild alchemist early, or buy the bars. The Auction House sells all three.", g={{"o",7642,i=3,txt="Runecloth x40",n2="Runecloth x40",m=1453,x=61.2,y=71.3},{"o",7642,i=2,txt="Arthas' Tears x10",n2="Arthas' Tears x10",m=1423,x=45.1,y=45.6},{"o",7642,i=4,txt="Arcanite Bar x6",n2="Arcanite Bars x6: an alchemist, or the Trade District Auction House",m=1453,x=61.2,y=71.3}}},
  {t="Stratholme Holy Water", lv=60, n="Stratholme is a dungeon for a group of five at 58-60, at the north end of the Eastern Plaguelands. Stratholme Supply Crates along the streets of both halves hold the Holy Water, one to three each; they come back after three minutes. Some crates let out a swarm of plagued rats or maggots: be ready. The main gate (the Scarlet half) needs no key.", g={{"g",0,txt="Stratholme",m=1423,x=26.5,y=10.4},{"o",7642,i=1,txt="Stratholme Holy Water x5",n2="Stratholme Supply Crates, inside",m=1423,x=26.5,y=10.4}}},
  {t="Grimand Elmore", lv=60, n="Bring the materials and 150 gold, taken at the hand-in. Grimand walks to his forge and hands you the Arcanite Barding.", g={{"i",0,txt="money"},{"t",7642,n2="Grimand Elmore: 150 gold",m=1453,x=59.7,y=33.8},{"a",7648,m=1453,x=59.7,y=33.8,ml=60}}},
  {t="Lord Grayson Shadowbreaker", lv=60, n="Lord Grayson keeps the barding for now: you get it back with the next quest.", g={{"t",7648,n2="Lord Grayson Shadowbreaker: the Arcanite Barding",m=1453,x=48.4,y=50.2},{"a",7643,m=1453,x=48.4,y=50.2,ml=60}}},
  {t="Enriched Manna Biscuits", lv=60, n="The Argent Dawn quartermasters sell Enriched Manna Biscuits, five for 60 silver, once the Argent Dawn is Friendly with you: Argent Quartermaster Lightspark at Chillwind Camp or Quartermaster Miranda Breechlock at Light's Hope Chapel. Scourgestones and the Plaguelands quests raise the standing.", g={{"h",13724,txt="Buy Enriched Manna Biscuit x20 (Argent Quartermaster Lightspark)",n2="Enriched Manna Biscuits: Argent Quartermaster Lightspark, Chillwind Camp",m=1422,x=42.8,y=83.7,n=20}}},
  {t="Merideth Carlson", lv=60, n="Merideth Carlson breeds horses in Southshore's stable. She makes the Manna-Enriched Horse Feed from the 20 biscuits and 50 gold, taken at the hand-in.", g={{"i",0,txt="money"},{"a",7645,m=1424,x=52.2,y=55.5,ml=60},{"h",13724,txt="Buy Enriched Manna Biscuit x20 (Argent Quartermaster Lightspark)",n2="Enriched Manna Biscuits: Argent Quartermaster Lightspark, Chillwind Camp",m=1422,x=42.8,y=83.7,n=20},{"t",7645,n2="Manna-Enriched Horse Feed",m=1424,x=52.2,y=55.5}}},
  {t="Dire Maul: Tendris Warpwood", lv=60, n="Dire Maul lies in central Feralas. From the gate at the foot of the ruins, walk up through the outer courtyards to the West wing's door at their north end; it needs a Crescent Key (from Pusillin in Dire Maul East) or a rogue's lockpicking. Tendris Warpwood (level 60 elite) stands at the far end of the West wing's first courtyard. Once attacked he calls every Ironbark Protector still alive in the courtyard: kill them first. His death frees the Ancient Equine Spirit: talk to it to give it the horse feed and the Arcanite Barding, and it blesses the barding. A group of five at 60.", g={{"g",0,txt="Dire Maul West's door",m=1444,x=60.3,y=30.2},{"i",0,txt="Kill Tendris Warpwood",n2="Tendris Warpwood, inside the West wing",m=1444,x=60.3,y=30.2,grp=true},{"t",7643,m=1444,x=60.3,y=30.2},{"a",7644,m=1444,x=60.3,y=30.2,ml=60}}},
  {t="Lord Grayson Shadowbreaker", lv=60, g={{"t",7644,m=1453,x=48.4,y=50.2},{"a",7646,m=1453,x=48.4,y=50.2,ml=60}}},
  {t="Two diamonds", lv=60, n="An Azerothian Diamond comes from Thorium veins and obsidian, about one vein in a hundred; a Pristine Black Diamond drops rarely from elites of level 59 and up (Revanchion and Lord Blackwood about one kill in nine and one in a hundred). The Auction House is the usual source of both.", g={{"o",7646,i=1,txt="Azerothian Diamond",m=1444,x=54.4,y=66.4},{"o",7646,i=2,txt="Pristine Black Diamond",m=1424,x=15.5,y=82.5}}},
  {t="Lord Grayson Shadowbreaker", lv=60, n="Lord Grayson hands you Lord Grayson's Satchel: open it for the Divination Scryer and the Blessed Arcanite Barding. Keep both.", g={{"t",7646,m=1453,x=48.4,y=50.2},{"a",7647,m=1453,x=48.4,y=50.2,ml=60},{"o",7647,i=2,txt="Use Lord Grayson's Satchel",m=1453,x=48.4,y=50.2},{"o",7647,i=2,txt="Blessed Arcanite Barding",n2="Blessed Arcanite Barding, from the satchel",m=1453,x=48.4,y=50.2,grp=true}}},
  {t="The Great Ossuary", lv=60, n="Scholomance lies under Caer Darrow, the island town in the south-east of the Western Plaguelands; the door needs the Skeleton Key (The Key to Scholomance). Clear the Great Ossuary, Rattlegore's room in the basement, then use the Divination Scryer at its centre. Four waves of spirits come, each ending with an Aspect: players judge them with Seal of Wisdom, Justice, Righteousness and then Light, which stuns them. Death Knight Darkreaver (level 62 elite) comes after the last; he mind-controls players. Loot the Charger's Lost Soul, use it inside the Ossuary to redeem it, and give it and the Blessed Arcanite Barding to Darkreaver's Fallen Charger. If the group wipes, the gates lock and the scryer is gone: abandon the quest and take it again from Lord Grayson for a new satchel. A group of five at 60. Again Into the Great Ossuary, after the mount, lets you fight him again.", g={{"g",0,txt="Scholomance",m=1422,x=69.7,y=73.2},{"h",18749,txt="Get Charger's Lost Soul",n2="Charger's Lost Soul: Death Knight Darkreaver",m=1422,x=69.7,y=73.2,n=1,grp=true},{"o",7647,i=1,txt="Use Charger's Lost Soul",n2="Charger's Lost Soul, inside the Great Ossuary",m=1422,x=69.7,y=73.2},{"o",7647,i=1,txt="Charger's Redeemed Soul",m=1422,x=69.7,y=73.2},{"t",7647,n2="Darkreaver's Fallen Charger: Summon Charger",m=1422,x=69.7,y=73.2}}},
} end)

R:Segment({id="collectibles/mounts/alliance/paladin-warhorse",title="Paladin Warhorse",faction="Alliance",races={"Human","Dwarf"},classes={"PALADIN"},min=40,max=60,zone=1453,zoneName="Stormwind City",why="Your first mount at 40, summoned at will: a paladin buys no horse.",spells={13819},spellNames={"Summon Warhorse"},folder="Paladin"}, function() return {
  {t="The Tome of Nobility (Ironforge)", lv=40, n="At 40 Tiza Battleforge, upstairs in the Hall of Mysteries, sends you to Duthorian Rall in Stormwind (Brandur Ironhammer downstairs gives the same errand; take one). Take the Deeprun Tram to Stormwind.", w={{k="available",q=4485,minLevel=40,closedBy={4486}}}, f={r={"Dwarf"}}, g={{"l",40,txt="Reach level 40"},{"a",4485,m=1455,x=27.6,y=12.2,ml=40}}},
  {t="Duthorian Rall", lv=40, w={{k="onquest",q={4485}}}, g={{"t",4485,m=1453,x=50.5,y=47.5}}},
  {t="Duthorian Rall", lv=40, w={{k="onquest",q={4486}}}, g={{"t",4486,m=1453,x=50.5,y=47.5}}},
  {t="Summon Warhorse", lv=40, n="Duthorian Rall stands in the Cathedral of Light. At 40 he offers The Tome of Nobility: accept it and hand it straight back to learn Summon Warhorse. Paladins do not buy a horse.", g={{"l",40,txt="Reach level 40"},{"a",1661,m=1453,x=50.5,y=47.5,ml=40},{"t",1661,n2="Duthorian Rall: Summon Warhorse",m=1453,x=50.5,y=47.5}}},
} end)

R:Segment({id="collectibles/mounts/neutral/warlock-dreadsteed",title="Warlock Dreadsteed",classes={"WARLOCK"},min=60,max=60,zone=1428,zoneName="Burning Steppes",why="Your epic mount at 60, summoned anywhere: no epic horse to buy and no 1,000g Journeyman Riding needed.",spells={23161},spellNames={"Summon Dreadsteed"},folder="Warlock"}, function() return {
  {t="Mor'zul Bloodbringer (Stormwind)", lv=60, n="At 60 Spackle Thornberry, the demon trainer in the Slaughtered Lamb, sends you to Mor'zul Bloodbringer in the Burning Steppes.", f={r={"Human"}}, g={{"l",60,txt="Reach level 60"},{"a",7562,m=1453,x=39.5,y=84.5,ml=60}}},
  {t="Mor'zul Bloodbringer (Ironforge)", lv=60, n="At 60 Jubahl Corpseseeker, the demon trainer in Ironforge, sends you to Mor'zul Bloodbringer in the Burning Steppes.", f={r={"Gnome"}}, g={{"l",60,txt="Reach level 60"},{"a",7562,m=1455,x=52.7,y=6.1,ml=60}}},
  {t="Mor'zul Bloodbringer (Orgrimmar)", lv=60, n="At 60 Kurgul, the demon trainer in the Cleft of Shadow, sends you to Mor'zul Bloodbringer in the Burning Steppes.", f={r={"Orc","Troll"}}, g={{"l",60,txt="Reach level 60"},{"a",7562,m=1454,x=47.5,y=46.7,ml=60}}},
  {t="Mor'zul Bloodbringer (Undercity)", lv=60, n="At 60 Martha Strain, the demon trainer in the Magic Quarter, sends you to Mor'zul Bloodbringer in the Burning Steppes.", f={r={"Scourge"}}, g={{"l",60,txt="Reach level 60"},{"a",7562,m=1458,x=85.7,y=16.1,ml=60}}},
  {t="Mor'zul Bloodbringer", lv=60, n="Mor'zul Bloodbringer and his goblin Gorzeeki Wildeyes camp on the hill across the road from the Altar of Storms, in the far north-west of the Burning Steppes, west of Blackrock Mountain. The chain is long: about 420 gold in Gorzeeki's and Ur'dan's goods, a pile of crafted materials, the Scholomance and Dire Maul. Start buying or gathering the materials of the next steps now.", g={{"t",7562,m=1428,x=12.7,y=31.6},{"a",7563,m=1428,x=12.7,y=31.6,ml=60}}},
  {t="Raging Beast's Blood", lv=60, n="Every owlbeast of Winterspring (level 53-58, none elite) drops the blood about one time in three: about ninety kills for thirty. Owl Wing Thicket, in the north-east, and the Hidden Grove's surroundings are packed with them, and they respawn in five and a half minutes.", g={{"o",7563,i=1,txt="Raging Beast's Blood x30",m=1452,x=43.2,y=39.4}}},
  {t="Wildeyes", lv=60, n="Back to Mor'zul: he gives you the Case of Blood for Gorzeeki beside him. Then Mor'zul asks for the bell, the wheel and the candle, and Gorzeeki sends you to Lord Banehollow in Jaedenar: buy three Shadowy Potions from him for that trip (6 gold each: one to walk in, one after Ulathek, and a spare in case one runs out) and bring 150 gold for the stardust.", g={{"t",7563,m=1428,x=12.7,y=31.6},{"a",7564,n2="he gives you the Case of Blood",m=1428,x=12.7,y=31.6,ml=60},{"t",7564,m=1428,x=12.4,y=31.6},{"a",7626,n2="Mor'zul Bloodbringer: Bell of Dethmoora",m=1428,x=12.7,y=31.6,ml=60},{"a",7627,n2="Mor'zul Bloodbringer: Wheel of the Black March",m=1428,x=12.7,y=31.6,ml=60},{"a",7628,n2="Mor'zul Bloodbringer: Doomsday Candle",m=1428,x=12.7,y=31.6,ml=60},{"a",7623,n2="Gorzeeki Wildeyes: Lord Banehollow",m=1428,x=12.4,y=31.6,ml=60},{"h",18802,txt="Buy Shadowy Potion x3 (Gorzeeki Wildeyes)",n2="Shadowy Potion, from Gorzeeki",m=1428,x=12.4,y=31.6,n=3}}},
  {t="The ritual pieces", lv=60, n="Gorzeeki wants 10 Elixirs of Shadow Power (Alchemy: 3 Ghost Mushrooms and a Crystal Vial each), 6 Large Brilliant Shards (Enchanting: disenchant level 51+ blue items), 25 Dark Iron Ore (Mining 230: the Dark Iron Deposits of the Burning Steppes and Blackrock Depths) and 35 Black Dragonscales (Skinning: the black dragonkin of the Burning Steppes, a few percent a kill, best from the Flamescale Wyrmkin). Make or gather what your professions allow and buy the rest at the Auction House; it can take a while to find 35 scales.", g={{"o",7626,i=1,txt="Elixir of Shadow Power x10",n2="Elixir of Shadow Power: the Auction House",m=1453,x=61.2,y=71.3,f={fa={"Alliance"}}},{"o",7626,i=1,txt="Elixir of Shadow Power x10",n2="Elixir of Shadow Power: the Auction House",m=1454,x=55.9,y=62.7,f={fa={"Horde"}}},{"o",7627,i=1,txt="Large Brilliant Shard x6",n2="Large Brilliant Shard: the Auction House",m=1453,x=61.2,y=71.3,f={fa={"Alliance"}}},{"o",7627,i=1,txt="Large Brilliant Shard x6",n2="Large Brilliant Shard: the Auction House",m=1454,x=55.9,y=62.7,f={fa={"Horde"}}},{"o",7627,i=2,txt="Dark Iron Ore x25",m=1428,x=56,y=47.8},{"o",7628,i=1,txt="Black Dragonscale x35",m=1428,x=56.3,y=60.6}}},
  {t="Arcanite", lv=60, n="Hand the three pieces to Gorzeeki. He then wants 3 Arcanite Bars for the Black Lodestone: alchemists transmute them (an Arcane Crystal and a Thorium Bar each, on a long cooldown); everyone else buys them.", g={{"t",7626,m=1428,x=12.4,y=31.6},{"t",7627,m=1428,x=12.4,y=31.6},{"t",7628,m=1428,x=12.4,y=31.6},{"a",7630,m=1428,x=12.4,y=31.6,ml=60},{"o",7630,i=1,txt="Arcanite Bar x3",n2="Arcanite Bar: the Auction House",m=1453,x=61.2,y=71.3,f={fa={"Alliance"}}},{"o",7630,i=1,txt="Arcanite Bar x3",n2="Arcanite Bar: the Auction House",m=1454,x=55.9,y=62.7,f={fa={"Horde"}}},{"t",7630,m=1428,x=12.4,y=31.6}}},
  {t="Lord Banehollow", lv=60, n="Jaedenar lies just south of Bloodvenom Post in western Felwood, west of the road; of its two caves, Shadow Hold is the northern one, further up the hill. Drink a Shadowy Potion at its mouth: for 20 minutes the Shadow Council there treat you as one of their own (Taint of Shadow). The oozes in the red pool and the succubus Rakaiah beyond them still attack: hug the wall past them. Go down past the second, red pool, up the ramp and across two bridges to Lord Banehollow, a great winged dreadlord at the back. He talks to you only while the potion lasts.", g={{"g",0,txt="Shadow Hold",m=1448,x=35.4,y=58.6},{"t",7623,m=1448,x=35.9,y=44.4},{"a",7624,m=1448,x=35.9,y=44.4,ml=60}}},
  {t="Ulathek the Traitor", lv=60, n="Ulathek waits in a small side room up a bridge you passed on the way down. Speak to him and he and four guards attack (all level 57, none elite): let your voidwalker hold the guards and burn Ulathek, sacrificing it if you must. Or click off your Taint of Shadow aura to start the fight, kill Ulathek, then drink another potion: the guards stop at once. Take his heart back to Lord Banehollow with a potion active.", g={{"i",0,txt="Kill Ulathek",m=1448,x=40.8,y=48.4,opt=true},{"o",7624,i=1,txt="The Traitor's Heart",m=1448,x=40.8,y=48.4},{"t",7624,m=1448,x=35.9,y=44.4},{"a",7625,m=1448,x=35.9,y=44.4,ml=60}}},
  {t="Xorothian Stardust", lv=60, n="Ur'dan, beside Lord Banehollow, sells the Xorothian Stardust for 150 gold. He deals with you only while a Shadowy Potion is active.", g={{"h",18687,txt="Buy Xorothian Stardust (Ur'dan)",n2="Xorothian Stardust, from Ur'dan",m=1448,x=36.2,y=44.5,n=1}}},
  {t="Imp Delivery", lv=60, n="Back to Gorzeeki with the stardust; with the Arcanite also done he gives you the Imp in a Jar for the Scholomance. Put a group of five together now: a party, not a raid group.", g={{"h",18687,txt="Buy Xorothian Stardust (Ur'dan)",n2="Xorothian Stardust, from Ur'dan",m=1448,x=36.2,y=44.5,n=1},{"t",7625,m=1428,x=12.4,y=31.6},{"a",7629,m=1428,x=12.4,y=31.6,ml=60}}},
  {t="The Scholomance", lv=60, n="The Scholomance (level 58-60, a group of five) lies under Caer Darrow, the island town in the south-east of the Western Plaguelands: someone needs the Skeleton Key or a rogue to open the door. Fight down to Ras Frostwhisper's room and use the Imp in a Jar at the alchemy lab tables to the right: J'eevee makes the parchment. You need not kill Ras, but it only counts at this lab and only in a party.", g={{"c",7629,txt="J'eevee",n2="Use the Imp in a Jar at the alchemy lab inside",m=1422,x=69.7,y=73.2,grp=true}}},
  {t="Dreadsteed of Xoroth", lv=60, n="Back to Gorzeeki, then Mor'zul hands you his instructions. Buy J'eevee's Jar (150 gold), the Black Lodestone (50) and the Xorothian Glyphs (50) from Gorzeeki; a warlock friend who owns them can bring theirs instead. Every other warlock who will recharge the nodes needs a Lodestone of their own. Carry 15 or more Soul Shards.", g={{"t",7629,m=1428,x=12.4,y=31.6},{"a",7631,m=1428,x=12.7,y=31.6,ml=60},{"h",18663,txt="Buy J'eevee's Jar (Gorzeeki Wildeyes)",n2="J'eevee's Jar, 150 gold",m=1428,x=12.4,y=31.6,n=1},{"h",18629,txt="Buy Black Lodestone (Gorzeeki Wildeyes)",n2="Black Lodestone, 50 gold",m=1428,x=12.4,y=31.6,n=1},{"h",18670,txt="Buy Xorothian Glyphs (Gorzeeki Wildeyes)",n2="Xorothian Glyphs, 50 gold",m=1428,x=12.4,y=31.6,n=1}}},
  {t="Into Dire Maul West", lv=60, n="Dire Maul stands in the ruins of central Feralas: from the gate at the foot of the ruins, walk up through the outer courtyards to the west wing's door at the north end. That door and an inner door need the Crescent Key (it drops from Pusillin in Dire Maul East) or a rogue with 300 Lockpicking. Bring a party of five. Lower Immol'thar's shield by killing the guardians of the five pylons (two stand in his own room), then kill Immol'thar: his dais is the summoning circle. Rest and rebuff before you start.", g={{"i",0,txt="Kill Immol'thar",n2="Immol'thar, inside the west wing",m=1444,x=60.3,y=30.2,grp=true}}},
  {t="The ritual", lv=60, n="Stand on the dais and use J'eevee's Jar: J'eevee sets out the Bell, the Wheel and the Candle. The Bell heals warlocks, the Wheel shields the party, the Candle burns the imps: ignore the imps and kill the Dread Guards (elite felguards, about ten, sometimes two at once); Banish or Enslave helps. Give one player each node to watch: when one sags, tilts and sounds, a warlock with a Lodestone recharges it, a 3-second cast that any hit breaks (a Soul Shard each), so keep attackers off them. If all three fail, the ritual ends and you start again; while one stands it survives even a wipe. After about six minutes nine symbols glow and a red vortex closes the circle: walk out and the remaining demons vanish at its edge. Rest, then use the Xorothian Glyphs. Kill the Xorothian Dreadsteed (level 62, elite); at half health Lord Hel'nurath joins, a hard hitter who knocks you back. Speak to the Dreadsteed Spirit: every warlock in the party who is on this quest can bind it.", g={{"i",0,txt="Use J'eevee's Jar",n2="J'eevee's Jar, on Immol'thar's dais",m=1444,x=60.3,y=30.2},{"i",0,txt="Use Xorothian Glyphs",n2="Xorothian Glyphs, once the circle is complete",m=1444,x=60.3,y=30.2},{"o",7631,i=1,txt="Kill Xorothian Dreadsteed",m=1444,x=60.3,y=30.2,grp=true},{"t",7631,n2="Dreadsteed Spirit: Summon Dreadsteed",m=1444,x=60.3,y=30.2}}},
} end)

R:Segment({id="collectibles/mounts/neutral/warlock-felsteed",title="Warlock Felsteed",classes={"WARLOCK"},min=40,max=60,zone=1413,zoneName="The Barrens",why="Your own mount at 40, summoned anywhere: no 100g riding training needed.",spells={5784},spellNames={"Summon Felsteed"},folder="Warlock"}, function() return {
  {t="Summon Felsteed (Stormwind)", lv=40, n="At 40 Demisette Cloyce, in the cellar of the Slaughtered Lamb in the Mage Quarter, sends you to Strahad Farsan in Ratchet. No quest offered? Finish the felhunter chain first: players report the mount comes after it.", f={r={"Human"}}, g={{"l",40,txt="Reach level 40"},{"a",4488,m=1453,x=39.2,y=85,ml=40}}},
  {t="Summon Felsteed (Ironforge)", lv=40, n="At 40 Briarthorn, by the warlock trainers in Ironforge, sends you to Strahad Farsan in Ratchet. No quest offered? Finish the felhunter chain first: players report the mount comes after it.", f={r={"Gnome"}}, g={{"l",40,txt="Reach level 40"},{"a",4487,m=1455,x=50.4,y=5.7,ml=40}}},
  {t="Summon Felsteed (Orgrimmar)", lv=40, n="At 40 Zevrost, in the Cleft of Shadow, sends you to Strahad Farsan in Ratchet. No quest offered? Finish the felhunter chain first: players report the mount comes after it.", f={r={"Orc","Troll"}}, g={{"l",40,txt="Reach level 40"},{"a",3631,m=1454,x=48.5,y=45.4,ml=40}}},
  {t="Summon Felsteed (Undercity)", lv=40, n="At 40 Kaal Soulreaper, in the Magic Quarter, sends you to Strahad Farsan in Ratchet. The zeppelin from Tirisfal Glades flies to Durotar; Ratchet is a short flight from Orgrimmar. No quest offered? Finish the felhunter chain first: players report the mount comes after it.", f={r={"Scourge"}}, g={{"l",40,txt="Reach level 40"},{"a",4489,m=1458,x=86.2,y=15.9,ml=40}}},
  {t="Strahad Farsan in Ratchet", lv=40, n="Ratchet is the goblin port on the Barrens coast, east of the Crossroads; from the Alliance side take the boat from Booty Bay. Strahad Farsan stands by his small tower on the hill above the town, not down at the docks. Hand in, then take his own Summon Felsteed and hand it straight back: that teaches you the mount. No fight, and the quests ask for nothing.", g={{"t",4488,m=1413,x=62.6,y=35.5,f={r={"Human"}}},{"t",4487,m=1413,x=62.6,y=35.5,f={r={"Gnome"}}},{"t",3631,m=1413,x=62.6,y=35.5,f={r={"Orc","Troll"}}},{"t",4489,m=1413,x=62.6,y=35.5,f={r={"Scourge"}}},{"a",4490,m=1413,x=62.6,y=35.5,ml=40},{"t",4490,n2="Strahad Farsan: Summon Felsteed",m=1413,x=62.6,y=35.5}}},
} end)
